-- ============================================================================
-- BILIMYO'L SMART EDU - WAVE 1 · BATCH W1-B2
-- Migration: 20261127000100_w1_b2_cefr_sql_seeding_and_9mode_grading.sql
-- Scope:
--   * FIX-P0-01: Seed all 33 canonical CEFR A1-B1 English lessons (with
--                deterministic SEED_LESSONS option permutation) and 31 CEFR
--                roadmap_nodes; add CEFR/RU/rich columns to public.lessons and
--                public.roadmap_nodes; strip acceptedAnswers, explanationRu,
--                and mistakeFeedbackByOption while deterministically scrambling
--                orderedTokens and deranging matchPairs right values in
--                public.sanitize_learner_content; grade all 9 question modes +
--                alternate_exercise in bilimyol_private.submit_answer_attempt.
--   * Coupling #2: Rewrite public.learner_lessons to use a single
--                  bilimyol_private.math_progression(auth.uid()) CTE without
--                  OFFSET 0 or per-row can_open_math_lesson lateral loops.
--   * FIX-P1-40: Multi-skill step & alternate_exercise support in
--                public.complete_lesson; non-MCQ wrong-answer feedback in
--                public.tutor_mistake_context; and >=50% floor for <28% skills
--                in public.complete_reinforcement.
-- ============================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS bilimyol_private;
REVOKE ALL ON SCHEMA bilimyol_private FROM PUBLIC, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 1. Extend public.lessons & public.roadmap_nodes with CEFR, RU & rich columns
-- ----------------------------------------------------------------------------
ALTER TABLE public.lessons
  ADD COLUMN IF NOT EXISTS title_ru TEXT,
  ADD COLUMN IF NOT EXISTS summary_ru TEXT,
  ADD COLUMN IF NOT EXISTS skill_domain TEXT,
  ADD COLUMN IF NOT EXISTS communicative_focus TEXT,
  ADD COLUMN IF NOT EXISTS cefr_level TEXT,
  ADD COLUMN IF NOT EXISTS module_id TEXT,
  ADD COLUMN IF NOT EXISTS unit_id TEXT,
  ADD COLUMN IF NOT EXISTS can_do_objective TEXT,
  ADD COLUMN IF NOT EXISTS can_do_objective_ru TEXT,
  ADD COLUMN IF NOT EXISTS prerequisites JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS official_cefr_disclaimer_uz TEXT,
  ADD COLUMN IF NOT EXISTS official_cefr_disclaimer_ru TEXT,
  ADD COLUMN IF NOT EXISTS pedagogy17 JSONB,
  ADD COLUMN IF NOT EXISTS alternate_exercise JSONB,
  ADD COLUMN IF NOT EXISTS requires_mastery BOOLEAN NOT NULL DEFAULT false;

ALTER TABLE public.roadmap_nodes
  ADD COLUMN IF NOT EXISTS title_ru TEXT,
  ADD COLUMN IF NOT EXISTS description_ru TEXT,
  ADD COLUMN IF NOT EXISTS skill_domain TEXT,
  ADD COLUMN IF NOT EXISTS cefr_level TEXT,
  ADD COLUMN IF NOT EXISTS module_id TEXT,
  ADD COLUMN IF NOT EXISTS module_title TEXT,
  ADD COLUMN IF NOT EXISTS module_title_ru TEXT,
  ADD COLUMN IF NOT EXISTS unit_id TEXT,
  ADD COLUMN IF NOT EXISTS can_do_objective TEXT,
  ADD COLUMN IF NOT EXISTS can_do_objective_ru TEXT,
  ADD COLUMN IF NOT EXISTS node_kind TEXT NOT NULL DEFAULT 'lesson',
  ADD COLUMN IF NOT EXISTS is_checkpoint BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS has_rich_exercise BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS task_kind TEXT;

UPDATE public.lessons
SET requires_mastery = true
WHERE pg_catalog.jsonb_typeof(steps) = 'array'
  AND pg_catalog.jsonb_path_exists(steps, '$[*].masteryCheckpoint')
  AND NOT requires_mastery;

-- Maintain least-privilege column grants on public.lessons & public.roadmap_nodes
REVOKE ALL ON TABLE public.lessons FROM PUBLIC, anon, authenticated;
GRANT SELECT (id) ON TABLE public.lessons TO authenticated;
GRANT UPDATE (is_published, is_archived, updated_at), DELETE ON TABLE public.lessons TO authenticated;
GRANT ALL ON TABLE public.lessons TO service_role;

REVOKE ALL ON TABLE public.roadmap_nodes FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.roadmap_nodes TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 2. Upsert all 33 canonical CEFR A1-B1 English lessons & 31 roadmap_nodes
-- ----------------------------------------------------------------------------
INSERT INTO public.lessons (
  id, course_id, skill_id, skill_domain, communicative_focus, cefr_level,
  module_id, unit_id, can_do_objective, can_do_objective_ru, prerequisites,
  title, title_ru, estimated_minutes, summary, summary_ru,
  official_cefr_disclaimer_uz, official_cefr_disclaimer_ru, pedagogy17,
  steps, reinforcement_exercise, alternate_exercise, requires_mastery,
  is_published, is_archived
)
VALUES
  ('lesson_eng_starter', 'course_eng_01', 'skill_eng_vocab', 'vocabulary', 'vocabulary', 'A1', 'mod_eng_a1_m1', 'unit_eng_a1_u1', 'Ikki kishilik tanishuv suhbatini tinglab tushunadi va o‘zini ingliz tilida tanishtiradi.', 'Понимает на слух диалог знакомства и представляет себя на английском языке.', '[]'::jsonb, 'Birinchi inglizcha so‘zlar', 'Первые английские слова', 5, 'Aziza va Benning tanishuv suhbatini tinglab, ingliz tilida salomlashish, ism so‘rash va o‘zingizni tanishtirishni o‘rganasiz.', 'Прослушав диалог Азизы и Бена, вы научитесь здороваться, спрашивать имя и представляться по-английски.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Ingliz tilida birinchi suhbat salomlashish va ism aytishdan boshlanadi.","ru":"Первый разговор на английском начинается с приветствия и знакомства."},"learningObjective":{"uz":"O‘quvchi «What''s your name?» savolini tushunadi va «I''m ... / My name is ...» deb javob beradi.","ru":"Ученик понимает вопрос «What''s your name?» и отвечает «I''m ... / My name is ...»."},"warmUp":{"uz":"Yangi sinfdosh bilan tanishganda avval nima deysiz?","ru":"Что вы говорите сначала при знакомстве с новым одноклассником?"},"vocabularyItems":[{"word":"What''s your name?","uz":"Ismingiz nima?","ru":"Как вас зовут?","ipa":"/wɒts jɔː neɪm/"},{"word":"Nice to meet you.","uz":"Tanishganimdan xursandman.","ru":"Приятно познакомиться.","ipa":"/naɪs tə miːt juː/"}],"grammarNote":{"rule":"I''m + Name / My name is + Name","simpleExplanationUz":"O‘zingizni tanishtirishda «I''m» (I am qisqartmasi) yoki «My name is» dan foydalaning.","simpleExplanationRu":"Для представления используйте «I''m» (сокращение от I am) или «My name is».","structure":"I''m [Name] / My name is [Name]","positiveExamples":["I''m Aziza.","My name is Ben."],"negativeExamples":["Only saying a name without ''I''m'' or ''My name is'' in full replies."],"questions":["What''s your name?"],"commonMistakes":["Yolg‘iz ismni aytib to‘xtash yoki salom o‘rniga ''Goodbye'' deyish."]},"pronunciationFocus":{"uz":"«What''s» so‘zida «t» va «s» birga talaffuz qilinadi; BrE /jɔː/ va AmE /jɔːr/ farqiga e’tibor bering.","ru":"В «What''s» звуки /ts/ произносятся слитно; обратите внимание на BrE /jɔː/ и AmE /jɔːr/."},"examples":["Aziza: Hi, I''m Aziza. What''s your name?","Ben: I''m Ben. Nice to meet you."],"guidedPractice":{"uz":"Ikki flashcard orqali iboralarni eslab, talaffuzini tinglang.","ru":"Повторите фразы по двум карточкам и прослушайте произношение."},"independentPractice":{"uz":"Lola sizdan ismingizni so‘raganda Sam sifatida to‘liq gap bilan javob yozing.","ru":"Ответьте полным предложением от имени Sam на вопрос Лолы."},"listeningRef":"media_eng_starter_dialogue","readingRef":"lesson_eng_starter_read","speakingTask":{"uz":"Ovozli namunadan so‘ng «Hi, I''m ... Nice to meet you.» iborasini ovoz chiqarib takrorlang.","ru":"После аудио примера повторите вслух: «Hi, I''m ... Nice to meet you.»."},"writingTask":{"uz":"O‘zingizni tanishtiruvchi 1 ta to‘liq gap yozing.","ru":"Напишите 1 полное предложение знакомства."},"knowledgeCheck":"q_lesson_eng_starter_quiz","finalQuiz":"q_lesson_eng_starter_practice","feedbackRules":{"uz":"Yolg‘iz ism yoki ''Goodbye'' yozilganda to‘liq gap tuzilishi eslatiladi.","ru":"При ответе одним именем или словом ''Goodbye'' напоминается полная конструкция."},"summaryAndRevision":{"uz":"Salomlashish va tanishuv iboralari spaced-repetition kartochkalarida mustahkamlanadi.","ru":"Фразы приветствия и знакомства закрепляются в карточках интервального повторения."}}'::jsonb, '[{"id":"lesson_eng_starter_read","stepNumber":1,"type":"concept","title":"Asosiy tushuncha","titleRu":"Основное правило","content":"Ingliz tilida «Hello» — salom, «Hi» — salom (kundalik suhbatda). O‘zingizni tanishtirish uchun «I''m ...» yoki «My name is ...» deb ismingizni ayting. Suhbatdoshning ismini so‘rash uchun «What''s your name?», javobdan keyin esa «Nice to meet you.» deymiz.","contentRu":"По-английски «Hello» и «Hi» означают приветствие. Чтобы представиться, скажите «I''m ...» или «My name is ...». Чтобы спросить имя, используйте «What''s your name?», а в ответ — «Nice to meet you.».","highlightNotes":["Hello / Hi — Salom","I''m Aziza / My name is Aziza — Men Azizaman","What''s your name? — Ismingiz nima?","Nice to meet you. — Tanishganimdan xursandman."]},{"id":"lesson_eng_starter_example","stepNumber":2,"type":"audio_simulation","title":"Birga misol ko‘ramiz","titleRu":"Разберём пример вместе","content":"Toshkentdagi maktab oldida Aziza va Ben ilk bor tanishmoqda. Suhbatni tinglang va matnli bayonni ochib iboralarni solishtiring.","contentRu":"У школы в Ташкенте Азиза и Бен знакомятся впервые. Прослушайте диалог и при необходимости откройте текст.","media":{"id":"media_eng_starter_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a1-starter-dialogue.wav","title":"Aziza va Ben tanishuv dialogi","titleUz":"Aziza va Ben tanishuv dialogi","titleRu":"Диалог знакомства Азизы и Бена","transcript":"Aziza: Hi, I''m Aziza. What''s your name?\nBen: I''m Ben. Nice to meet you.","posterImage":"/lesson-media/english/a1-starter-greeting.png","posterAlt":"Toshkentdagi maktab oldida Aziza va Ben salomlashmoqda","posterAltUz":"Toshkentdagi maktab oldida Aziza va Ben salomlashmoqda","posterAltRu":"Азиза и Бен приветствуют друг друга перед школой в Ташкенте","durationSeconds":5.907,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Aziza: Hi, I''m Aziza. What''s your name?\nBen: I''m Ben. Nice to meet you.","speakerName":"Aziza & Ben"}},{"id":"lesson_eng_starter_flashcards","stepNumber":3,"type":"flashcard","title":"Iboralarni eslab qolamiz","titleRu":"Запоминаем фразы","content":"Kartochkani ochishdan oldin iborani eslab ko‘ring, talaffuzni tinglang va «Javobni ko‘rish» tugmasini bosing.","contentRu":"Перед открытием карточки вспомните фразу, послушайте произношение и нажмите «Показать ответ».","flashcards":[{"id":"fc_eng_starter_1","front":"What''s your name?","backUz":"Ismingiz nima?","backRu":"Как вас зовут?","partOfSpeech":"phrase","ipa":"/wɒts jɔː neɪm/","ipaAmE":"/wɒts jɔːr neɪm/","cefrLevel":"A1","example":"Hi, I''m Aziza. What''s your name?","exampleUz":"Salom, men Azizaman. Ismingiz nima?","exampleRu":"Привет, я Азиза. Как тебя зовут?","audioSrc":"/lesson-media/english/a1-starter-whats-your-name.wav","imageSrc":"/lesson-media/english/a1-starter-greeting.png","alt":"Toshkentdagi maktab oldida ikki o‘quvchi salomlashib suhbatlashmoqda","altRu":"Двое учеников приветствуют друг друга и общаются перед школой в Ташкенте","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_starter_2","front":"Nice to meet you.","backUz":"Tanishganimdan xursandman.","backRu":"Приятно познакомиться.","partOfSpeech":"phrase","ipa":"/naɪs tə miːt juː/","ipaAmE":"/naɪs tuː miːt juː/","cefrLevel":"A1","example":"I''m Ben. Nice to meet you.","exampleUz":"Men Benman. Tanishganimdan xursandman.","exampleRu":"Я Бен. Приятно познакомиться.","audioSrc":"/lesson-media/english/a1-starter-nice-to-meet-you.wav","imageSrc":"/lesson-media/english/a1-starter-greeting.png","alt":"Maktab hovlisida uchrashgan do‘stlar qo‘l silkib ko‘rishmoqda","altRu":"Друзья во дворе школы приветливо машут друг другу рукой","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_starter_try","stepNumber":4,"type":"interactive_question","title":"O‘rganganingizni sinab ko‘ring","titleRu":"Проверьте свои знания","content":"Yangi suhbatdosh sizdan ismingizni so‘rayapti. O‘zingizni Sam sifatida inglizcha to‘liq gap bilan tanishtiring.","contentRu":"Новый собеседник спрашивает ваше имя. Представьтесь от имени Sam полным английским предложением.","interactiveQuestion":{"id":"q_lesson_eng_starter_quiz","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Self-introduction","difficulty":"easy","questionType":"text_input","evaluationMode":"deterministic","text":"Lola: «Hi, I''m Lola. What''s your name?» — O‘zingizni Sam deb inglizcha to‘liq gap bilan tanishtiring.","textRu":"Лола: «Hi, I''m Lola. What''s your name?» — Представьтесь от имени Sam полным предложением по-английски.","options":[],"acceptedAnswers":["I''m Sam","I am Sam","My name is Sam","My name''s Sam","Hi, I''m Sam","Hello, I''m Sam","Hi, I am Sam","Hello, I am Sam","Hi, my name is Sam","Hello, my name is Sam","Hi, my name''s Sam","Hello, my name''s Sam","Hi I''m Sam","Hello I''m Sam","Hi I am Sam","Hello I am Sam","Hi my name is Sam","Hello my name is Sam","Hi my name''s Sam","Hello my name''s Sam"],"explanation":"Ajoyib! O‘zingizni ingliz tilida «I''m Sam» yoki «My name is Sam» deb tabiiy va to‘liq tanishtirdingiz.","explanationRu":"Отлично! Вы естественно представились полной фразой «I''m Sam» или «My name is Sam».","wrongFeedback":"Faqat ism yoki xayrlashuv so‘zini yozmang. O‘zingizni tanishtirish uchun «I''m ...» yoki «My name is ...» shaklida to‘liq gap yozing.","wrongFeedbackRu":"Не пишите только имя или прощание. Представьтесь полной фразой «I''m ...» или «My name is ...»."}}]'::jsonb, '{"id":"q_lesson_eng_starter_practice","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Polite greeting reply","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Yangi tanishgan do‘stingiz «I''m Ben» dedi. Odob bilan qanday javob berasiz?","textRu":"Новый знакомый сказал «I''m Ben». Как вежливо ответить?","options":["Nice to meet you.","Goodbye.","What is your name?"],"correctIndex":0,"mistakeFeedbackByOption":{"Goodbye.":{"uz":"«Goodbye.» — suhbat oxirida xayrlashish uchun ishlatiladi, tanishuv boshida emas.","ru":"«Goodbye.» используется при прощании, а не в начале знакомства."},"What is your name?":{"uz":"Do‘stingiz hozirgina ismini («I''m Ben») aytdi; bu yerda xushmuomalalik iborasi kerak.","ru":"Собеседник уже назвал своё имя («I''m Ben»); здесь нужна вежливая ответная фраза."}},"explanation":"«Nice to meet you.» — yangi tanishgan kishiga «Tanishganimdan xursandman» deyishning tabiiy usuli.","explanationRu":"«Nice to meet you.» — естественный способ сказать «Приятно познакомиться» новому собеседнику.","wrongFeedback":"Tanishuvda do‘stingiz ismini aytgach, xushmuomalalik bilan salomlashuv javobini tanlang.","wrongFeedbackRu":"После того как собеседник назвал имя, выберите вежливую фразу знакомства."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_m1_greetings', 'course_eng_01', 'skill_eng_vocab', 'vocabulary', 'vocabulary', 'A1', 'mod_eng_a1_m1', 'unit_eng_a1_u1', 'Kun vaqtiga qarab rasmiy va kundalik salomlashish hamda ahvol so‘rash iboralarini moslaydi.', 'Подбирает приветствия по времени суток и фразы о самочувствии в диалоге.', '[]'::jsonb, 'Kun vaqti bo‘yicha salomlashish va ahvol so‘rash', 'Приветствия по времени суток и вежливый диалог', 6, 'Ertalab va kechqurun salomlashish («Good morning», «Good evening») hamda ahvol so‘rash («How are you?», «I''m fine, thanks.») iboralarini o‘rganasiz.', 'Вы изучите утренние и вечерние приветствия («Good morning», «Good evening») и обмен вопросами о делах.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Maktabda o‘qituvchi yoki kattalar bilan uchrashganda kun vaqtiga mos salomlashish muhim.","ru":"При встрече с учителем или взрослыми важно выбирать приветствие по времени суток."},"learningObjective":{"uz":"O‘quvchi 4 ta asosiy salomlashish iborasini o‘zbekcha ma’nosi bilan moslaydi va muloqotni to‘ldiradi.","ru":"Ученик соотносит 4 базовые фразы приветствия со значениями и завершает мини-диалог."},"warmUp":{"uz":"Tongda o‘qituvchingizni ko‘rganingizda inglizcha nima deysiz?","ru":"Как вы поприветствуете учителя утром по-английски?"},"vocabularyItems":[{"word":"Good morning","uz":"Xayrli tong","ru":"Доброе утро","ipa":"/ɡʊd ˈmɔːnɪŋ/"},{"word":"Good evening","uz":"Xayrli kech","ru":"Добрый вечер","ipa":"/ɡʊd ˈiːvnɪŋ/"},{"word":"How are you?","uz":"Ishlaringiz qanday?","ru":"Как у вас дела?","ipa":"/haʊ ɑː juː/"},{"word":"I''m fine, thanks.","uz":"Yaxshiman, rahmat.","ru":"У меня всё хорошо, спасибо.","ipa":"/aɪm faɪn θæŋks/"}],"grammarNote":{"rule":"Good + [morning / afternoon / evening] + Title/Name","simpleExplanationUz":"Rasmiy murojaatda salomdan so‘ng «Mr. / Mrs. / Ms.» bilan familiya yoki ism qo‘yiladi.","simpleExplanationRu":"В вежливом обращении после приветствия добавляется «Mr. / Mrs. / Ms.» или имя.","structure":"Good morning, Mr. Karim. How are you?","positiveExamples":["Good morning, Madina!","I''m fine, thanks."],"negativeExamples":["Good night! (used only when parting at night or going to sleep, not as a greeting)"],"questions":["How are you?"],"commonMistakes":["Kechki salomlashishda ''Good evening'' o‘rniga ''Good night'' deb yuborish."]},"pronunciationFocus":{"uz":"«Good» so‘zidagi /d/ tovushi keyingi undosh oldida yumshoq aytiladi.","ru":"Звук /d/ в слове «Good» перед следующим согласным произносится мягко без паузы."},"examples":["Madina: Good morning, Mr. Karim. How are you?","Mr. Karim: I''m fine, thanks."],"guidedPractice":{"uz":"Dialogdagi 4 ta iborani juftlash va talaffuz kartochkalari bilan mustahkamlang.","ru":"Закрепите 4 фразы через аудио-карточки и сопоставление пар."},"independentPractice":{"uz":"Kechki uchrashuv vaziyatida to‘g‘ri salomlashishni tanlang.","ru":"Выберите верное приветствие для вечерней встречи."},"listeningRef":"media_eng_a1_m1_morning_gate_dialogue","readingRef":"lesson_eng_a1_m1_greetings_concept","speakingTask":{"uz":"O‘zingizni tongda sinfdoshingizga «Good morning! How are you?» deb salomlashayotgandek tasavvur qiling.","ru":"Произнесите вслух утреннее приветствие: «Good morning! How are you?»."},"writingTask":{"uz":"O‘qituvchingizga ertalabki 2 gapli salom yozing.","ru":"Напишите короткое утреннее приветствие из 2 фраз."},"knowledgeCheck":"q_eng_a1_m1_greet_match","finalQuiz":"q_eng_a1_m1_greet_conv","feedbackRules":{"uz":"''Good night'' va ''Good evening'' farqi aniq ko‘rsatiladi.","ru":"Разъясняется различие между ''Good night'' (прощание) и ''Good evening'' (приветствие)."},"summaryAndRevision":{"uz":"4 ta yangi karta A1 M1 flashcard to‘plamiga qo‘shiladi.","ru":"4 новые карточки добавляются в набор повторения модуля A1.1."}}'::jsonb, '[{"id":"lesson_eng_a1_m1_greetings_concept","stepNumber":1,"type":"concept","title":"Kun vaqtiga qarab salomlashish","titleRu":"Приветствие по времени суток","content":"Tongda — «Good morning», kunduzi — «Good afternoon», kechqurun uchrashganda — «Good evening» deymiz. E’tibor bering: «Good night» salomlashish emas, uxlashdan oldin yoki tunda xayrlashganda aytiladi.","contentRu":"Утром говорят «Good morning», днём — «Good afternoon», вечером при встрече — «Good evening». Важно: «Good night» — это прощание на ночь, а не приветствие.","highlightNotes":["Good morning — Xayrli tong (tongda)","Good evening — Xayrli kech (kechqurun uchrashganda)","How are you? — Ishlaringiz qanday?","I''m fine, thanks. — Yaxshiman, rahmat."]},{"id":"lesson_eng_a1_m1_greetings_audio","stepNumber":2,"type":"audio_simulation","title":"Maktab darvozasi oldidagi suhbat","titleRu":"Диалог у ворот школы","content":"Madina va ustoz Karim ertalab maktab darvozasi oldida ko‘rishdi. Suhbatni tinglang.","contentRu":"Мадина и учитель Карим встречаются утром у ворот школы. Прослушайте диалог.","media":{"id":"media_eng_a1_m1_morning_gate_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a1/a1-m1-morning-gate-dialogue.wav","title":"Ertalabki maktab darvozasidagi suhbat","titleUz":"Ertalabki maktab darvozasidagi suhbat","titleRu":"Утренний диалог у школьных ворот","transcript":"Madina: Good morning, Mr. Karim. How are you?\nMr. Karim: Good morning, Madina! I''m fine, thanks. How are you?\nMadina: I''m great, thank you!","posterImage":"/lesson-media/english/a1/a1-m1-morning-greeting.png","posterAlt":"Ertalabki maktab darvozasi oldida o‘quvchi qiz va o‘qituvchi salomlashmoqda","posterAltUz":"Ertalabki maktab darvozasi oldida o‘quvchi qiz va o‘qituvchi salomlashmoqda","posterAltRu":"Утром у ворот школы ученица и учитель приветствуют друг друга","durationSeconds":11.575,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Madina: Good morning, Mr. Karim. How are you?\nMr. Karim: Good morning, Madina! I''m fine, thanks. How are you?\nMadina: I''m great, thank you!","speakerName":"Madina & Mr. Karim"}},{"id":"lesson_eng_a1_m1_greetings_flashcards","stepNumber":3,"type":"flashcard","title":"Salomlashish kartochkalari","titleRu":"Карточки приветствий","content":"Har bir iborani tinglab ma’nosini eslang va takrorlang.","contentRu":"Прослушайте каждую фразу, вспомните значение и закрепите её.","flashcards":[{"id":"fc_eng_a1_m1_1","front":"Good morning.","backUz":"Xayrli tong.","backRu":"Доброе утро.","partOfSpeech":"phrase","ipa":"/ɡʊd ˈmɔːnɪŋ/","ipaAmE":"/ɡʊd ˈmɔːrnɪŋ/","cefrLevel":"A1","example":"Good morning, Mr. Karim.","exampleUz":"Xayrli tong, janob Karim.","exampleRu":"Доброе утро, господин Карим.","audioSrc":"/lesson-media/english/a1/a1-m1-good-morning.wav","imageSrc":"/lesson-media/english/a1/a1-m1-morning-greeting.png","alt":"Quyosh chiqayotgan saharda maktab darvozasi oldida uchrashgan o‘quvchi va ustoz","altRu":"На рассвете у ворот школы встретились ученица и учитель","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m1_2","front":"Good evening.","backUz":"Xayrli kech.","backRu":"Добрый вечер.","partOfSpeech":"phrase","ipa":"/ɡʊd ˈiːvnɪŋ/","cefrLevel":"A1","example":"Good evening, Mrs. Azizova.","exampleUz":"Xayrli kech, Azizova xonim.","exampleRu":"Добрый вечер, госпожа Азизова.","audioSrc":"/lesson-media/english/a1/a1-m1-good-evening.wav","imageSrc":"/lesson-media/english/a1/a1-m4-home-study.png","alt":"Oy va yulduzlar ko‘ringan qorong‘i deraza yonidagi xonada stol chirog‘i yonib turibdi","altRu":"В комнате у тёмного окна с луной и звёздами горит настольная лампа","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m1_3","front":"How are you?","backUz":"Ahvolingiz qanday?","backRu":"Как вы поживаете?","partOfSpeech":"phrase","ipa":"/haʊ ɑː juː/","ipaAmE":"/haʊ ɑːr juː/","cefrLevel":"A1","example":"Hello, Ali! How are you?","exampleUz":"Salom, Ali! Ahvolingiz qanday?","exampleRu":"Привет, Али! Как дела?","audioSrc":"/lesson-media/english/a1/a1-m1-how-are-you.wav","imageSrc":"/lesson-media/english/a1/a1-m1-morning-greeting.png","alt":"Maktab oldida suhbat boshlayotgan ikki suhbatdosh","altRu":"Два собеседника, начинающие разговор перед школой","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m1_4","front":"I''m fine, thanks.","backUz":"Yaxshiman, rahmat.","backRu":"Всё хорошо, спасибо.","partOfSpeech":"phrase","ipa":"/aɪm faɪn θæŋks/","cefrLevel":"A1","example":"I''m fine, thanks. And you?","exampleUz":"Yaxshiman, rahmat. O‘zingizchi?","exampleRu":"Хорошо, спасибо. А вы?","audioSrc":"/lesson-media/english/a1/a1-m1-im-fine-thanks.wav","imageSrc":"/lesson-media/english/a1/a1-m1-morning-greeting.png","alt":"Tabassum bilan qo‘l silkib javob berayotgan ustoz","altRu":"Улыбающийся учитель приветливо машет рукой","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a1_m1_greetings_match","stepNumber":4,"type":"interactive_question","title":"So‘zlarni moslash mashqi","titleRu":"Упражнение на сопоставление фраз","content":"Har bir inglizcha iborani to‘g‘ri o‘zbekcha ma’nosi bilan juftlang.","contentRu":"Соедините каждую английскую фразу с её точным значением.","interactiveQuestion":{"id":"q_eng_a1_m1_greet_match","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Greetings matching","difficulty":"easy","questionType":"word_match","evaluationMode":"deterministic","text":"Inglizcha salomlashish iboralarini o‘zbekcha ma’nosi bilan moslang:","textRu":"Сопоставьте английские фразы приветствия с их переводом:","options":[],"matchPairs":[{"id":"pair_gm","left":"Good morning","right":"Xayrli tong"},{"id":"pair_ge","left":"Good evening","right":"Xayrli kech"},{"id":"pair_hay","left":"How are you?","right":"Ahvolingiz qanday?"},{"id":"pair_ift","left":"I''m fine, thanks.","right":"Yaxshiman, rahmat."}],"explanation":"Barakalla! Ertalab ''Good morning'', kechqurun ''Good evening'', hol-ahvol uchun ''How are you?'' — ''I''m fine, thanks.'' juftliklari to‘g‘ri.","explanationRu":"Отлично! Утром «Good morning», вечером «Good evening», а для обмена вопросом о делах — «How are you?» и «I''m fine, thanks.».","wrongFeedback":"Kun vaqtini bildiruvchi ''morning'' (tong) va ''evening'' (kech) so‘zlariga qarab juftliklarni qayta tekshiring.","wrongFeedbackRu":"Обратите внимание на слова ''morning'' (утро) и ''evening'' (вечер) и проверьте пары ещё раз."}}]'::jsonb, '{"id":"q_eng_a1_m1_greet_conv","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Conversation completion: Evening greeting","difficulty":"easy","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Soat kechki 19:30. Timur qo‘shnisi Azizova xonim bilan ko‘chada uchrashdi.","Timur: «___»","Mrs. Azizova: «Good evening, Timur! How are you?»"],"text":"Kechki soat 19:30 dagi uchrashuvda Timur qaysi ibora bilan salomlashishi kerak?","textRu":"Какой фразой Тимур должен поприветствовать соседку вечером в 19:30?","options":["Good night, Mrs. Azizova.","Good morning, Mrs. Azizova.","Good evening, Mrs. Azizova.","Goodbye, Mrs. Azizova."],"correctIndex":2,"mistakeFeedbackByOption":{"Good night, Mrs. Azizova.":{"uz":"«Good night» salomlashish emas — faqat kechasi xayrlashayotganda («Xayrli tun») ishlatiladi.","ru":"«Good night» — это прощание перед сном, а не приветствие при встрече."},"Good morning, Mrs. Azizova.":{"uz":"Soat kechki 19:30; «Good morning» esa faqat ertalab aytiladi.","ru":"Сейчас 19:30 вечера; «Good morning» говорят только утром."},"Goodbye, Mrs. Azizova.":{"uz":"«Goodbye» suhbatni yakunlab xayrlashish iborasi; Timur esa endi uchrashdi.","ru":"«Goodbye» говорят при уходе, а Тимур только встретился с соседкой."}},"explanation":"Soat kechki 19:30 da uchrashganda «Good evening» bilan salomlashiladi.","explanationRu":"При встрече вечером в 19:30 используется приветствие «Good evening».","wrongFeedback":"Suhbat kechqurun boshlanayotganiga e’tibor bering: xayrlashuv emas, kechki salomlashish kerak.","wrongFeedbackRu":"Обратите внимание: встреча начинается вечером, поэтому нужно вечернее приветствие, а не прощание."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_m1_speaking', 'course_eng_01', 'skill_eng_vocab', 'speaking', 'speaking', 'A1', 'mod_eng_a1_m1', 'unit_eng_a1_u1', 'O‘z ismi, shahri va salomlashuvdan iborat 3 gapli og‘zaki tanishtiruv matnini tuzadi va o‘zini baholaydi.', 'Составляет устное представление из 3 предложений и оценивает себя по рубрике.', '[]'::jsonb, 'Speaking: O‘zingizni va shahringizni tanishtirish', 'Speaking: Устное представление себя и родного города', 5, 'Namunani tinglab, o‘zingiz haqingizda 3 ta qisqa gap tuzasiz va mezonlar asosida o‘zingizni baholaysiz.', 'Прослушав образец, вы составите 3 коротких предложения о себе и оцените свой ответ по критериям.', 'Bu mustaqil nutq mashqi va o‘zini baholash vositasidir; avtomatik sertifikatlash yoki rasmiy CEFR imtihoni o‘rnini bosmaydi.', 'Это самостоятельное речевое упражнение и самооценка; оно не является автоматической сертификацией CEFR.', '{"intro":{"uz":"Yangi til klubi yoki sinfda o‘zingizni 10 soniyada tanishtira olish juda foydali.","ru":"Умение представиться за 10 секунд в новом классе или клубе — важный первый шаг."},"learningObjective":{"uz":"O‘quvchi salomlashish, ism va shahar («I am from ...») bilan 3 gapli tanishtiruv tuzadi.","ru":"Ученик строит мини-монолог из 3 фраз: приветствие, имя и город («I am from ...»)."},"warmUp":{"uz":"«I am from Tashkent» va «My name is ...» iboralarini eslang.","ru":"Вспомните фразы «I am from Tashkent» и «My name is ...»."},"vocabularyItems":[{"word":"I am from ...","uz":"Men ...danman","ru":"Я из ...","ipa":"/aɪ æm frɒm/"}],"grammarNote":{"rule":"Hello! My name is [Name]. I am from [City]. Nice to meet you.","simpleExplanationUz":"Qayerdan ekaningizni aytish uchun «I am from + shahar» (yoki «I''m from ...») tuzilmasini ishlating.","simpleExplanationRu":"Чтобы назвать город, используйте конструкцию «I am from + город».","structure":"I am from [City].","positiveExamples":["I am from Tashkent.","I am from Samarkand."],"negativeExamples":["I from Tashkent (missing verb ''am'')"],"questions":["Where are you from?"],"commonMistakes":["«I am» dagi ''am'' bog‘lovchi fe’lini tushirib qoldirish: «I from Tashkent»."]},"pronunciationFocus":{"uz":"«from» so‘zi gap o‘rtasida /frəm/ shaklida yumshoq aytiladi.","ru":"Предлог «from» в беглой речи звучит мягко — /frəm/."},"examples":["Hello! My name is Dilnoza. I am from Tashkent. Nice to meet you."],"guidedPractice":{"uz":"Dilnozaning audio namunasini tinglab, har bir gapdan keyin pauza qilib takrorlang.","ru":"Прослушайте аудио Дилнозы и повторите по одной фразе."},"independentPractice":{"uz":"O‘z tanishtiruv matningizni yozing/ayting va namunaviy javob hamda mezonlar bilan solishtiring.","ru":"Подготовьте своё представление и сверьте его с образцом и критериями самооценки."},"listeningRef":"media_eng_a1_m1_self_intro_model","readingRef":"lesson_eng_a1_m1_speaking_concept","speakingTask":{"uz":"Salomlashish, ism, shahar va «Nice to meet you.» qismlarini qo‘shib nutq tayyorlang.","ru":"Подготовьте устный ответ с приветствием, именем, городом и фразой знакомства."},"writingTask":{"uz":"Nutq tayanchingizni qisqa matn ko‘rinishida yozib tekshiring.","ru":"Запишите черновик своего устного представления для самопроверки."},"knowledgeCheck":"q_eng_a1_m1_speaking_prompt","finalQuiz":"q_eng_a1_m1_speaking_reinf","feedbackRules":{"uz":"O‘quvchi o‘zini 3 mezon asosida mustaqil baholaydi.","ru":"Ученик самостоятельно оценивает ответ по 3 критериям."},"summaryAndRevision":{"uz":"«I am from ...» tuzilmasi M2 «to be» darslariga ko‘prik bo‘ladi.","ru":"Конструкция «I am from ...» подготавливает к урокам глагола «to be» в модуле 2."}}'::jsonb, '[{"id":"lesson_eng_a1_m1_speaking_concept","stepNumber":1,"type":"concept","title":"3 qadamli tanishtiruv formulasi","titleRu":"Формула знакомства из 3 шагов","content":"O‘zingizni qisqa va chiroyli tanishtirish uchun 3 ta qadam yetarli: 1) Salomlashing («Hello!»), 2) Ismingiz va shahringizni ayting («My name is ... I am from ...»), 3) Xushmuomalalik bilan yakunlang («Nice to meet you.»).","contentRu":"Чтобы уверенно представиться, достаточно 3 шагов: 1) Поздоровайтесь («Hello!»), 2) Назовите имя и город («My name is ... I am from ...»), 3) Завершите фразой «Nice to meet you.».","highlightNotes":["1. Hello! / Good morning!","2. My name is [Name]. I am from [City].","3. Nice to meet you."]},{"id":"lesson_eng_a1_m1_speaking_audio","stepNumber":2,"type":"audio_simulation","title":"Nutq namunasini tinglash","titleRu":"Прослушивание образца речи","content":"Dilnozaning ovozli tanishtiruvini tinglang va intonatsiyaga e’tibor bering.","contentRu":"Прослушайте аудио-образец Дилнозы и обратите внимание на интонацию.","media":{"id":"media_eng_a1_m1_self_intro_model","kind":"audio","language":"en","source":"/lesson-media/english/a1/a1-m1-self-intro-model.wav","title":"O‘zini tanishtirish namunasi","titleUz":"O‘zini tanishtirish namunasi","titleRu":"Образец устного представления себя","transcript":"Dilnoza: Hello! My name is Dilnoza. I am from Tashkent. Nice to meet you.","posterImage":"/lesson-media/english/a1/a1-m1-morning-greeting.png","posterAlt":"Maktab hovlisida salomlashayotgan o‘quvchi va o‘qituvchi","posterAltUz":"Maktab hovlisida salomlashayotgan o‘quvchi va o‘qituvchi","posterAltRu":"Ученица и учитель приветствуют друг друга во дворе школы","durationSeconds":6.952,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Dilnoza: Hello! My name is Dilnoza. I am from Tashkent. Nice to meet you.","speakerName":"Dilnoza"}},{"id":"lesson_eng_a1_m1_speaking_task","stepNumber":3,"type":"interactive_question","title":"Speaking: O‘zingizni baholash mashqi","titleRu":"Speaking: Практика и самооценка","content":"Ingliz tilida o‘zingizni tanishtiruvchi nutqingizni tayyorlang, ovoz chiqarib ayting va quyida matn ko‘rinishida yozib namuna bilan solishtiring.","contentRu":"Произнесите вслух представление о себе, запишите его ниже и проверьте себя по критериям.","interactiveQuestion":{"id":"q_eng_a1_m1_speaking_prompt","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"speaking","cefrLevel":"A1","topic":"Guided speaking self-introduction","difficulty":"easy","questionType":"speaking_prompt","evaluationMode":"self_assessed","text":"Ingliz tili to‘garagida o‘zingizni tanishtiring (salomlashish, ism, shahar va xushmuomalalik iborasi).","textRu":"Представьтесь на занятии английского клуба (приветствие, имя, город и вежливая фраза).","options":[],"sampleResponse":"Hello! My name is Dilnoza. I am from Tashkent. Nice to meet you.","rubricCriteria":[{"id":"crit_greet","labelUz":"Salomlashish iborasi ishlatildi (Hello / Good morning)","labelRu":"Использовано приветствие (Hello / Good morning)"},{"id":"crit_name_city","labelUz":"Ism va shahar «am/is» fe’li bilan to‘g‘ri aytildi (My name is ... I am from ...)","labelRu":"Имя и город названы с глаголом «am/is» (My name is ... I am from ...)"},{"id":"crit_polite","labelUz":"Suhbat «Nice to meet you.» bilan yakunlandi","labelRu":"Речь завершена фразой «Nice to meet you.»"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil mashq): bu topshiriq rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельная практика): задание не даёт официального сертификата CEFR.","explanation":"Namunadagi uch qismli tuzilma (salomlashish + ism/shahar + Nice to meet you.) A1 darajasida tabiiy tanishtiruv hisoblanadi.","explanationRu":"Трёхчастная структура из образца (приветствие + имя/город + Nice to meet you.) соответствует уровню A1.","wrongFeedback":"Gaplaringizda «am» yoki «is» fe’li tushib qolmaganini va uchala mezon bajarilganini tekshiring.","wrongFeedbackRu":"Проверьте, не пропущен ли глагол «am» или «is» и выполнены ли все три критерия."}}]'::jsonb, '{"id":"q_eng_a1_m1_speaking_reinf","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"speaking","cefrLevel":"A1","topic":"Saying your hometown","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"«Men Buxorodanman» jumlasining grammatik jihatdan to‘g‘ri inglizcha shakli qaysi?","textRu":"Какой английский вариант фразы «Я из Бухары» грамматически правильный?","options":["I from Bukhara.","My name from Bukhara.","I is from Bukhara.","I am from Bukhara."],"correctIndex":3,"mistakeFeedbackByOption":{"I from Bukhara.":{"uz":"O‘zbek tilida «...danman» qo‘shimchasi yetarli, ammo ingliz tilida «I» dan keyin «am» fe’lini yozish shart.","ru":"В английском предложении нельзя опускать глагол-связку «am» после «I»."},"My name from Bukhara.":{"uz":"«My name» — «mening ismim» degani; shahar aytish uchun «I am from ...» kerak.","ru":"«My name» означает «моё имя»; для указания города нужно «I am from ...»."},"I is from Bukhara.":{"uz":"«is» faqat «he/she/it» bilan ishlatiladi; «I» bilan doim «am» keladi.","ru":"Форма «is» используется с «he/she/it»; с местоимением «I» всегда употребляется «am»."}},"explanation":"«I» olmoshi bilan doim «am» ishlatiladi: «I am from Bukhara.».","explanationRu":"С местоимением «I» всегда используется «am»: «I am from Bukhara.».","wrongFeedback":"Ingliz gapida fe’l (am) tushib qolmasligiga va «I» bilan moslashishiga e’tibor bering.","wrongFeedbackRu":"Следите, чтобы в английском предложении не пропадал глагол «am» и он согласовался с «I»."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_u1_checkpoint', 'course_eng_01', 'skill_eng_vocab', 'vocabulary', 'checkpoint', 'A1', 'mod_eng_a1_m1', 'unit_eng_a1_u1', '1-modul yakuniy sinovida yangi suhbat vaziyatini to‘g‘ri yakunlab, 2-modulni ochadi.', 'Проходит итоговую проверку 1-го модуля в новой диалоговой ситуации и открывает 2-й модуль.', '[]'::jsonb, '1-modul yakuni: Tanishuv va salomlashish sinovi', 'Итог модуля 1: Проверка по теме знакомства и приветствий', 5, '1-modul bo‘yicha mustaqil nazorat: yangi vaziyatda salomlashish, ism aytish va ahvol so‘rashni tekshirasiz.', 'Самостоятельная проверка по 1-му модулю: выбор вежливых реплик в новой ситуации общения.', 'Bu modul yakuniy tekshiruvi ichki o‘quv bosqichini ochadi va rasmiy CEFR sertifikati bermaydi.', 'Эта проверка модуля открывает следующий учебный блок и не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"1-modulda o‘rgangan barcha salomlashish va tanishtiruv ko‘nikmalaringizni yangi hayotiy vaziyatda sinab ko‘ring.","ru":"Проверьте все навыки приветствия и знакомства из 1-го модуля в новой жизненной ситуации."},"learningObjective":{"uz":"O‘quvchi qabulxonadagi yangi muloqot vaziyatida kamida 70% ball bilan 2-modulni ochadi.","ru":"Ученик решает новую диалоговую задачу в приёмной с результатом от 70% для перехода к модулю 2."},"warmUp":{"uz":"Qabulxonada yangi o‘qituvchi bilan birinchi bor gaplashayotganingizni tasavvur qiling.","ru":"Представьте, что вы впервые обращаетесь к преподавателю на стойке регистрации."},"vocabularyItems":[{"word":"Good afternoon","uz":"Xayrli kun","ru":"Добрый день","ipa":"/ɡʊd ˌɑːftəˈnuːn/"}],"grammarNote":{"rule":"Polite Greeting + Self-Introduction","simpleExplanationUz":"Suhbat boshida salomlashib, so‘ng o‘z ismingizni «I''m ...» yoki «My name is ...» bilan aytasiz.","simpleExplanationRu":"В начале беседы поприветствуйте собеседника и назовите своё имя.","structure":"Good afternoon! My name is [Name].","positiveExamples":["Good afternoon, Miss Nilufar. My name is Anvar."],"negativeExamples":["Good night, Miss Nilufar. (wrong time/purpose)"],"questions":["How are you?"],"commonMistakes":["Suhbat boshida xayrlashish iborasini tanlash."]},"pronunciationFocus":{"uz":"«afternoon» so‘zida urg‘u oxirgi bo‘g‘inga tushadi: /ˌɑːftəˈnuːn/.","ru":"В слове «afternoon» главное ударение падает на последний слог."},"examples":["Anvar: Good afternoon, Miss Nilufar. My name is Anvar."],"guidedPractice":{"uz":"Sinov savolini diqqat bilan o‘qing va kontekstga mos javobni tanlang.","ru":"Внимательно прочитайте контекст ситуации и выберите уместную реплику."},"independentPractice":{"uz":"Agar birinchi urinish muvaffaqiyatsiz bo‘lsa, boshqa vaziyatli qayta sinov beriladi.","ru":"При неудачной попытке предлагается альтернативная ситуация для повторной проверки."},"listeningRef":"media_eng_a1_m1_morning_gate_dialogue","readingRef":"lesson_eng_a1_u1_cp_concept","speakingTask":{"uz":"To‘g‘ri javobni tanlagach, jumlani ovoz chiqarib o‘qing.","ru":"После выбора правильного ответа прочтите фразу вслух."},"writingTask":{"uz":"Yangi suhbatdosh uchun 2 gapli salomlashuv tuzing.","ru":"Составьте приветствие из 2 фраз для нового знакомого."},"knowledgeCheck":"q_eng_a1_u1_cp_main","finalQuiz":"q_eng_a1_u1_cp_reinf","feedbackRules":{"uz":"Har bir chalg‘ituvchi javob uchun aniq xato sababi beriladi.","ru":"Для каждого неверного варианта указана конкретная причина ошибки."},"summaryAndRevision":{"uz":"1-modul sinovi muvaffaqiyatli yakunlansa, 2-modul («To be» va maktab hayoti) ochiladi.","ru":"Успешная сдача проверки открывает 2-й модуль («To be» и школьная жизнь)."}}'::jsonb, '[{"id":"lesson_eng_a1_u1_cp_concept","stepNumber":1,"type":"concept","title":"1-modul yakuniy tekshiruvi","titleRu":"Итоговая проверка модуля 1","content":"Bu bosqichda 1-modul mavzularini yangi vaziyatda qo‘llaysiz. Keyingi modulni ochish uchun kamida 70% natija talab etiladi.","contentRu":"На этом этапе вы применяете знания 1-го модуля в новой ситуации. Для открытия следующего модуля нужно набрать не менее 70%."},{"id":"lesson_eng_a1_u1_cp_quiz","stepNumber":2,"type":"interactive_question","title":"Sinov topshirig‘i","titleRu":"Контрольное задание","content":"Vaziyatga mos to‘liq va xushmuomala javobni tanlang.","contentRu":"Выберите вежливый и подходящий ответ для ситуации.","interactiveQuestion":{"id":"q_eng_a1_u1_cp_main","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Unit 1 checkpoint: Reception desk","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Soat kunduzgi 14:00. Anvar kutubxona qabulxonasiga keldi va Miss Nilufar bilan birinchi bor tanishmoqda. Qaysi javob eng to‘g‘ri?","textRu":"14:00 дня. Анвар подошёл к стойке библиотеки и впервые знакомится с мисс Нилуфар. Какой вариант верный?","options":["Good afternoon, Miss Nilufar. My name is Anvar.","Good night, Miss Nilufar. Goodbye.","How are you? Only Sam.","Good morning, Miss Nilufar. See you tomorrow."],"correctIndex":0,"mistakeFeedbackByOption":{"Good night, Miss Nilufar. Goodbye.":{"uz":"Kunduzgi 14:00 da «Good night» va «Goodbye» deyish muloqot boshlanishiga mos emas.","ru":"В 14:00 для начала разговора не подходят «Good night» и «Goodbye»."},"How are you? Only Sam.":{"uz":"Bu yerda o‘z ismingizni «My name is Anvar» deb to‘liq aytish va salomlashish kerak.","ru":"Здесь нужно поздороваться и представиться полной фразой «My name is Anvar»."},"Good morning, Miss Nilufar. See you tomorrow.":{"uz":"14:00 — kunduzi («Good afternoon»), shuningdek «See you tomorrow» xayrlashuv iborasi.","ru":"14:00 — это день («Good afternoon»), а «See you tomorrow» означает «Увидимся завтра»."}},"explanation":"Kunduzi salomlashish uchun «Good afternoon», o‘zini tanishtirish uchun esa «My name is Anvar.» ishlatiladi.","explanationRu":"Днём для приветствия используется «Good afternoon», а для представления — «My name is Anvar.».","wrongFeedback":"Soat kunduzgi 14:00 ekaniga va suhbat endi boshlanayotganiga e’tibor bering.","wrongFeedbackRu":"Учтите время суток (14:00 — день) и то, что диалог только начинается."}}]'::jsonb, '{"id":"q_eng_a1_u1_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Unit 1 checkpoint reinforcement","difficulty":"easy","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Miss Nilufar: «Nice to meet you, Anvar! How are you today?»","Anvar: «___»"],"text":"Anvar qabulxonada Miss Nilufarning savoliga qanday tabiiy javob beradi?","textRu":"Как Анвар естественно ответит на вопрос мисс Нилуфар в библиотеке?","options":["My name is library.","I''m fine, thank you. And you?","Good night, thank you."],"correctIndex":1,"mistakeFeedbackByOption":{"My name is library.":{"uz":"«How are you?» ahvolingizni so‘raydi, ismingizni yoki joy nomini emas.","ru":"Вопрос «How are you?» спрашивает о самочувствии, а не о названии места."},"Good night, thank you.":{"uz":"«Good night» xayrlashish iborasi; ahvol so‘ralganda «I''m fine, thank you.» deyiladi.","ru":"«Good night» — прощание на ночь; на вопрос о делах отвечают «I''m fine, thank you.»."}},"explanation":"«How are you?» savoliga «I''m fine, thank you. And you?» deb javob berish eng tabiiy va xushmuomala usuldir.","explanationRu":"На вопрос «How are you?» естественно ответить «I''m fine, thank you. And you?».","wrongFeedback":"Suhbatdosh «How are you?» deb ahvolingizni so‘rayapti — unga mos javob tanlang.","wrongFeedbackRu":"Собеседник спрашивает, как ваши дела — выберите соответствующий ответ."}'::jsonb, '{"id":"q_eng_a1_u1_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Unit 1 checkpoint alternate retry","difficulty":"easy","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Laylo sport murabbiyi Rustam bilan soat 08:30 da uchrashdi.","Laylo: «Good morning, Coach Rustam! I''m Laylo. I am from Samarkand.»","Coach Rustam: «Good morning, Laylo! ___»"],"text":"Murabbiy Rustam Layloning tanishuviga qanday javob qaytaradi?","textRu":"Как тренер Рустам ответит на представление Лейлы?","options":["What is Samarkand?","Nice to meet you, Laylo!","Goodbye, Laylo!"],"correctIndex":1,"mistakeFeedbackByOption":{"What is Samarkand?":{"uz":"Yangi tanishgan o‘quvchiga avval «Nice to meet you» bilan xushmuomala javob beriladi.","ru":"При первом знакомстве сначала вежливо отвечают «Nice to meet you»."},"Goodbye, Laylo!":{"uz":"Ular endigina uchrashishdi, shuning uchun xayrlashish o‘rinsiz.","ru":"Они только что встретились, поэтому прощаться неуместно."}},"explanation":"O‘zini tanishtirgan suhbatdoshga «Nice to meet you, [Name]!» deb javob beriladi.","explanationRu":"После знакомства собеседнику отвечают «Nice to meet you, [Name]!».","wrongFeedback":"Yangi tanishuvda xushmuomalalik bilan javob berish iborasini tanlang.","wrongFeedbackRu":"Выберите вежливую ответную фразу при первом знакомстве."}'::jsonb, true, true, false),
  ('lesson_eng_foundation_02', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'grammar', 'A1', 'mod_eng_a1_m2', 'unit_eng_a1_u2', 'Shaxs olmoshlari (I, you, he, she) bilan «to be» (am, are, is) shakllarini to‘g‘ri bog‘laydi.', 'Правильно сочетает личные местоимения (I, you, he, she) с формами «to be» (am, are, is).', '["lesson_eng_starter"]'::jsonb, 'Men, siz va oddiy gaplar', 'Личные местоимения и глагол «to be»', 5, 'I — men, you — siz, he — u (erkak), she — u (ayol). I bilan am, you bilan are, he va she bilan is ishlatiladi. Student — o‘quvchi.', 'I — я, you — вы/ты, he — он, she — она. С I используется am, с you — are, с he и she — is.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Ingliz tilida kim haqida gapirayotganimizga qarab «to be» fe’li am, are yoki is ko‘rinishini oladi.","ru":"В английском языке глагол «to be» меняется на am, are или is в зависимости от подлежащего."},"learningObjective":{"uz":"O‘quvchi I am, You are, He/She is shakllarini o‘zbekcha tarjimasi bilan to‘g‘ri tanlaydi.","ru":"Ученик правильно выбирает формы I am, You are и He/She is."},"warmUp":{"uz":"Oldingi darsdagi «I''m Aziza» jumlasidagi «''m» nimani bildiradi?","ru":"Что означает сокращение «''m» в предложении «I''m Aziza» из прошлого урока?"},"vocabularyItems":[{"word":"student","uz":"o‘quvchi / talaba","ru":"ученик / студент","ipa":"/ˈstjuːdənt/"},{"word":"teacher","uz":"o‘qituvchi","ru":"учитель","ipa":"/ˈtiːtʃə/"}],"grammarNote":{"rule":"I + am | You/We/They + are | He/She/It + is","simpleExplanationUz":"O‘zbek tilida «Men o‘quvchiman» gapida fe’l oxirda qo‘shimcha bo‘ladi, ingliz tilida esa egadan darhol keyin am/is/are keladi.","simpleExplanationRu":"В английском языке связка am/is/are ставится сразу после подлежащего и не опускается.","structure":"Subject + am/is/are + a/an + noun","positiveExamples":["I am a student.","You are a student.","She is a teacher."],"negativeExamples":["I am not a teacher.","She is not a student."],"questions":["Are you a student?","Is she a teacher?"],"commonMistakes":["«I is a student» deyish yoki «a» artiklini tushirib qoldirish."]},"pronunciationFocus":{"uz":"«I am» tez nutqda /aɪm/, «She is» esa /ʃiːz/ tarzida qisqartirilishi mumkin.","ru":"В разговорной речи «I am» часто звучит как /aɪm/, а «She is» как /ʃiːz/."},"examples":["I am a student.","You are a student.","She is a student."],"guidedPractice":{"uz":"Namuna gaplardagi am, are va is o‘rnini solishtiring.","ru":"Сравните употребление am, are и is в примерах."},"independentPractice":{"uz":"«I ___ a student» va «She ___ a teacher» gaplarini mustaqil to‘ldiring.","ru":"Самостоятельно заполните пропуски в двух различных предложениях."},"listeningRef":"media_eng_starter_dialogue","readingRef":"lesson_eng_foundation_02_example","speakingTask":{"uz":"O‘zingiz va do‘stingiz haqida 2 ta gap ayting: «I am a student. She is a teacher.»","ru":"Произнесите 2 фразы: «I am a student. She is a teacher.»."},"writingTask":{"uz":"«He is ...» va «I am ...» bilan 2 ta gap yozing.","ru":"Напишите 2 предложения с «He is ...» и «I am ...»."},"knowledgeCheck":"q_lesson_eng_foundation_02","finalQuiz":"q_lesson_eng_foundation_02_practice","feedbackRules":{"uz":"Har bir olmosh uchun mos «to be» shakli eslatiladi.","ru":"При ошибке напоминается соответствие местоимения и формы «to be»."},"summaryAndRevision":{"uz":"I -> am, you -> are, he/she -> is qoidasi keyingi Present Simple darsiga asos bo‘ladi.","ru":"Правило I -> am, you -> are, he/she -> is служит базой для следующих уроков."}}'::jsonb, '[{"id":"lesson_eng_foundation_02_read","stepNumber":1,"type":"concept","title":"Asosiy tushuncha","titleRu":"Основное правило","content":"I — men, you — siz, he — u (erkak), she — u (ayol). I bilan am, you bilan are, he va she bilan is ishlatiladi. Student — o‘quvchi.","contentRu":"I — я, you — вы/ты, he — он, she — она. С I используется am, с you — are, с he и she — is. Student — ученик."},{"id":"lesson_eng_foundation_02_example","stepNumber":2,"type":"visual_example","title":"Birga misol ko‘ramiz","titleRu":"Разберём пример вместе","content":"I am a student. — Men o‘quvchiman. You are a student. — Siz o‘quvchisiz. She is a student. — U o‘quvchi. A so‘zi bu yerda bitta o‘quvchi haqida gapirilayotganini bildiradi.","contentRu":"I am a student. — Я ученик. You are a student. — Вы ученик. She is a student. — Она ученица. Артикль a указывает на одного человека."},{"id":"lesson_eng_foundation_02_try","stepNumber":3,"type":"interactive_question","title":"O‘rganganingizni sinab ko‘ring","titleRu":"Проверьте свои знания","content":"Misolga tayangan holda javobni tanlang.","contentRu":"Выберите правильную форму глагола.","interactiveQuestion":{"id":"q_lesson_eng_foundation_02","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Subject pronoun I + to be","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"«Men o‘quvchiman» gapini to‘ldiring. I ___ a student.","textRu":"Дополните предложение «Я ученик»: I ___ a student.","options":["is","are","am"],"correctIndex":2,"mistakeFeedbackByOption":{"is":{"uz":"«is» faqat he, she, it bilan ishlatiladi; «I» bilan emas.","ru":"«is» используется с he, she, it, но не с местоимением «I»."},"are":{"uz":"«are» you, we, they bilan keladi; «I» uchun «am» ishlatiladi.","ru":"«are» используется с you, we, they; для «I» нужна форма «am»."}},"explanation":"I bilan am ishlatiladi. I am a student — Men o‘quvchiman.","explanationRu":"С местоимением I используется форма am: I am a student — Я ученик.","wrongFeedback":"Ega «I» (men) bo‘lganda «to be» ning qaysi shakli ishlatilishini eslang.","wrongFeedbackRu":"Вспомните, какая форма «to be» используется с подлежащим «I»."}}]'::jsonb, '{"id":"q_lesson_eng_foundation_02_practice","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Subject pronoun she + to be","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"«U o‘qituvchi» gapini to‘ldiring. She ___ a teacher.","textRu":"Дополните предложение «Она учитель»: She ___ a teacher.","options":["am","is","are"],"correctIndex":1,"mistakeFeedbackByOption":{"am":{"uz":"«am» faqat «I» olmoshi bilan keladi.","ru":"Форма «am» употребляется только с местоимением «I»."},"are":{"uz":"«are» ko‘plik va «you» uchun ishlatiladi; «she» birlikda.","ru":"«are» используется с «you» и во множественном числе, а «she» — единственное число."}},"explanation":"He va she bilan is ishlatiladi: She is a teacher — U o‘qituvchi.","explanationRu":"С he и she используется форма is: She is a teacher — Она учитель.","wrongFeedback":"«She» (3-shaxs birlik) bilan «am» yoki «are» emas, birlikdagi shakl qo‘yiladi.","wrongFeedbackRu":"С местоимением 3-го лица единственного числа «she» нужна форма «is»."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_m2_sentence_builder', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'grammar', 'A1', 'mod_eng_a1_m2', 'unit_eng_a1_u2', 'Inglizcha SVO so‘z tartibida maktab buyumlari va kundalik o‘qish haqida gap tuzadi hamda xatoni tuzatadi.', 'Составляет предложения о школьных предметах в порядке SVO и исправляет грамматические ошибки.', '[]'::jsonb, 'Gap tuzish: Kundalik maktab hayoti', 'Построение предложений: Школьные будни', 7, 'O‘zbek tilidan farqli ravishda ingliz tilida fe’l egadan keyin keladi (SVO tartibi). Maktab so‘zlari va so‘z tartibini mashq qilasiz.', 'В отличие от узбекского (SOV), в английском языке глагол стоит сразу после подлежащего (SVO). Отработаем школьную лексику и порядок слов.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"O‘zbekcha «Ular kutubxonada kitob o‘qiydi» gapida fe’l oxirida keladi, inglizchada esa «They read books in the library.» — fe’l darhol egadan keyin turadi.","ru":"В английском предложении сказуемое следует сразу за подлежащим (Subject + Verb + Object + Place)."},"learningObjective":{"uz":"O‘quvchi 4 ta maktab so‘zini o‘rganadi, bo‘laklardan SVO gap tuzadi va 3-shaxs -s xatosini tuzatadi.","ru":"Ученик осваивает 4 школьных слова, собирает предложение в порядке SVO и исправляет ошибку с -s."},"warmUp":{"uz":"Maktab sumkangizda nimalar bor? «notebook» so‘zini eslaysizmi?","ru":"Что лежит у вас в школьном рюкзаке?"},"vocabularyItems":[{"word":"notebook","uz":"daftar","ru":"тетрадь","ipa":"/ˈnəʊtbʊk/"},{"word":"classroom","uz":"sinf xonasi","ru":"классная комната","ipa":"/ˈklɑːsruːm/"},{"word":"schedule","uz":"dars jadvali","ru":"расписание","ipa":"/ˈʃedjuːl/"},{"word":"homework","uz":"uy vazifasi","ru":"домашнее задание","ipa":"/ˈhəʊmwɜːk/"}],"grammarNote":{"rule":"Subject + Verb + Object + Place/Time (SVO)","simpleExplanationUz":"Ingliz gapining qat’iy tartibi: 1) Kim? (They), 2) Nima qiladi? (read), 3) Nimani? (books), 4) Qayerda? (in the library).","simpleExplanationRu":"Строгий порядок слов: 1) Кто? (They), 2) Что делает? (read), 3) Что? (books), 4) Где? (in the library).","structure":"Subject + Verb(+s) + Object + Place","positiveExamples":["They read books in the library.","He goes to school at eight."],"negativeExamples":["They in the library books read. (Uzbek SOV interference)"],"questions":["Do they read books in the library?"],"commonMistakes":["O‘zbekcha tartibda fe’lni gap oxiriga surish yoki ''he/she'' bilan ''-s/-es'' tushirib qoldirish."]},"pronunciationFocus":{"uz":"«schedule» so‘zi Britancha /ˈʃedjuːl/ va Amerikancha /ˈskedʒuːl/ tarzida aytiladi.","ru":"Слово «schedule» произносится как /ˈʃedjuːl/ (BrE) или /ˈskedʒuːl/ (AmE)."},"examples":["They read books in the library.","He goes to school at eight."],"guidedPractice":{"uz":"4 ta maktab kartochkasi bilan so‘zlarni mustahkamlang.","ru":"Повторите 4 школьных слова по карточкам."},"independentPractice":{"uz":"Aralash so‘zlardan to‘g‘ri ingliz gapini yig‘ing va xatoli gapni tuzating.","ru":"Соберите предложение из слов и исправьте ошибку в другом предложении."},"listeningRef":"media_eng_a1_m2_notebook","readingRef":"lesson_eng_a1_m2_sb_visual","speakingTask":{"uz":"Tuzilgan «They read books in the library.» gapini urg‘u bilan ayting.","ru":"Прочитайте вслух собранное предложение «They read books in the library.»."},"writingTask":{"uz":"Sinfdagi bir odat haqida SVO tartibida 1 ta gap yozing.","ru":"Напишите 1 предложение о школьном распорядке в порядке SVO."},"knowledgeCheck":"q_eng_a1_m2_order_1","finalQuiz":"q_eng_a1_m2_err_1","feedbackRules":{"uz":"SOV so‘z tartibi xatosi va -es qo‘shimchasi qoidasi tushuntiriladi.","ru":"Объясняется ошибка порядка слов SOV и правило окончания -es в 3-м лице."},"summaryAndRevision":{"uz":"SVO tartibi va maktab so‘zlari keying Present Simple darsida mustahkamlanadi.","ru":"Порядок слов SVO и школьная лексика закрепляются в следующем уроке."}}'::jsonb, '[{"id":"lesson_eng_a1_m2_sb_concept","stepNumber":1,"type":"concept","title":"Inglizcha gap tartibi (SVO)","titleRu":"Порядок слов в английском предложении (SVO)","content":"O‘zbek tilida fe’l gap oxirida keladi («Ular kutubxonada kitob o‘qiydi»). Ingliz tilida esa fe’l egadan darhol keyin turadi: Ega + Fe’l + To‘ldiruvchi + O‘rin/Vaqt («They read books in the library.»).","contentRu":"В английском предложении глагол стоит сразу после подлежащего: Подлежащее + Глагол + Дополнение + Место/Время («They read books in the library.»).","highlightNotes":["1. Ega (Subject): They","2. Fe’l (Verb): read","3. Nima? (Object): books","4. Qayerda? (Place): in the library."]},{"id":"lesson_eng_a1_m2_sb_visual","stepNumber":2,"type":"visual_example","title":"Sinf xonasi va o‘quv buyumlari","titleRu":"Школьный класс и учебные предметы","content":"Sinf xonasi rasmidagi buyumlarga qarang va namuna gapni o‘qing: «We have a schedule and a notebook in the classroom.»","contentRu":"Посмотрите на иллюстрацию класса и прочтите пример: «We have a schedule and a notebook in the classroom.»","media":{"id":"media_eng_a1_m2_school_classroom_img","kind":"image","language":"en","source":"/lesson-media/english/a1/a1-m2-school-classroom.png","title":"Sinf xonasi va o‘quv stoli","titleUz":"Sinf xonasi va o‘quv stoli","titleRu":"Школьный класс и парта","alt":"Sinf xonasida yashil doska, dars jadvali belgisi, parta ustida ochiq daftar, qalam va olma","altUz":"Sinf xonasida yashil doska, dars jadvali belgisi, parta ustida ochiq daftar, qalam va olma","altRu":"Школьный класс с зелёной доской, сеткой расписания, партой, открытой тетрадью, карандашом и яблоком","reviewStatus":"approved"}},{"id":"lesson_eng_a1_m2_sb_flashcards","stepNumber":3,"type":"flashcard","title":"Maktab so‘zlari kartochkalari","titleRu":"Карточки школьной лексики","content":"Yangi maktab so‘zlarining talaffuzini tinglang va eslab qoling.","contentRu":"Послушайте произношение новых школьных слов и запомните их.","flashcards":[{"id":"fc_eng_a1_m2_1","front":"notebook","backUz":"daftar","backRu":"тетрадь","partOfSpeech":"noun","ipa":"/ˈnəʊtbʊk/","ipaAmE":"/ˈnoʊtbʊk/","cefrLevel":"A1","example":"My notebook is on the desk.","exampleUz":"Mening daftarim parta ustida.","exampleRu":"Моя тетрадь на парте.","audioSrc":"/lesson-media/english/a1/a1-m2-notebook.wav","imageSrc":"/lesson-media/english/a1/a1-m2-school-classroom.png","alt":"Sinf xonasida parta ustida ochiq holda turgan oq varaqli yozuv buyumi va qalam","altRu":"Раскрытый белый бумажный блок с листами и карандаш на парте в классе","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m2_2","front":"classroom","backUz":"sinf xonasi","backRu":"классная комната","partOfSpeech":"noun","ipa":"/ˈklɑːsruːm/","ipaAmE":"/ˈklæsruːm/","cefrLevel":"A1","example":"Our classroom is bright and clean.","exampleUz":"Bizning sinf xonamiz yorug‘ va toza.","exampleRu":"Наша классная комната светлая и чистая.","audioSrc":"/lesson-media/english/a1/a1-m2-classroom.wav","imageSrc":"/lesson-media/english/a1/a1-m2-school-classroom.png","alt":"Yashil doskali va partali yorug‘ o‘quv joyi ko‘rinishi","altRu":"Светлое учебное помещение с зелёной доской и партой","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m2_3","front":"schedule","backUz":"dars jadvali","backRu":"расписание","partOfSpeech":"noun","ipa":"/ˈʃedjuːl/","ipaAmE":"/ˈskedʒuːl/","cefrLevel":"A1","example":"Look at the Monday schedule on the wall.","exampleUz":"Devordagi dushanba kungi jadvalga qarang.","exampleRu":"Посмотрите на расписание на стене.","audioSrc":"/lesson-media/english/a1/a1-m2-schedule.wav","imageSrc":"/lesson-media/english/a1/a1-m2-school-classroom.png","alt":"Devorning o‘ng tomonidagi rangli katakchalardan iborat haftalik reja taxtasi","altRu":"Настенная таблица с цветными блоками на правой стене","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m2_4","front":"homework","backUz":"uy vazifasi","backRu":"домашнее задание","partOfSpeech":"noun","ipa":"/ˈhəʊmwɜːk/","ipaAmE":"/ˈhoʊmwɜːrk/","cefrLevel":"A1","example":"I do my homework after school.","exampleUz":"Men maktabdan keyin uy vazifamni bajaraman.","exampleRu":"Я делаю домашнее задание после школы.","audioSrc":"/lesson-media/english/a1/a1-m2-homework.wav","imageSrc":"/lesson-media/english/a1/a1-m4-home-study.png","alt":"Stol chirog‘i ostida ochiq yozuv daftari va ruchka","altRu":"Открытая тетрадь и ручка под тёплым светом настольной лампы","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a1_m2_sb_order","stepNumber":4,"type":"interactive_question","title":"So‘zlarni tartiblash (Gap tuzish)","titleRu":"Порядок слов в предложении","content":"Bo‘laklarni bosib, «Ular kutubxonada kitob o‘qiydi» ma’nosidagi to‘g‘ri ingliz gapini tuzing.","contentRu":"Расставьте слова по порядку (SVO), чтобы получилось: «Они читают книги в библиотеке».","interactiveQuestion":{"id":"q_eng_a1_m2_order_1","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"SVO sentence ordering","difficulty":"easy","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Ular kutubxonada kitob o‘qiydi» gapini inglizcha to‘g‘ri tartibda tuzing:","textRu":"Составьте английское предложение «Они читают книги в библиотеке» в правильном порядке:","options":[],"orderedTokens":["They","read","books","in","the","library."],"acceptedAnswers":["They read books in the library."],"explanation":"To‘g‘ri tartib: Ega (They) + Fe’l (read) + To‘ldiruvchi (books) + Joy (in the library.).","explanationRu":"Правильный порядок SVO: Подлежащее (They) + Глагол (read) + Дополнение (books) + Место (in the library.).","wrongFeedback":"Ingliz tilida «kim» so‘zidan keyin darhol harakat (read) keladi, joy (in the library.) esa oxirida turadi.","wrongFeedbackRu":"В английском языке сразу за подлежащим ставится действие (read), а место (in the library.) — в конце."}}]'::jsonb, '{"id":"q_eng_a1_m2_err_1","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Error correction: 3rd person -es","difficulty":"easy","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"He go to school at eight.","text":"«He go to school at eight.» gapidagi xatoni tuzatilgan to‘g‘ri variantni tanlang:","textRu":"Выберите исправленный вариант предложения «He go to school at eight.»:","options":["He goes to school at eight.","He going to school at eight.","He is go to school at eight.","He to school goes at eight."],"correctIndex":0,"mistakeFeedbackByOption":{"He going to school at eight.":{"uz":"«He going» yordamchi fe’lsiz xato, shuningdek har kungi odat uchun Present Simple («goes») ishlatiladi.","ru":"«He going» неверно без вспомогательного глагола; для регулярного действия нужен Present Simple («goes»)."},"He is go to school at eight.":{"uz":"O‘zbek tilidagi «boradi» ma’nosida «is» va asosiy fe’l («go») birga qo‘yilmaydi — «goes» deyiladi.","ru":"Глаголы «is» и «go» нельзя ставить вместе для обычного действия — нужна форма «goes»."},"He to school goes at eight.":{"uz":"Bu o‘zbekcha SOV tartibidan ko‘chirilgan; inglizchada «goes» egadan keyin turishi kerak.","ru":"Здесь нарушен английский порядок слов SVO: глагол «goes» должен стоять сразу после «He»."}},"explanation":"Present Simple da «he / she / it» bilan fe’lga «-s» yoki «-es» qo‘shiladi: «go» -> «goes».","explanationRu":"В Present Simple с «he / she / it» к глаголу добавляется «-s» или «-es»: «go» -> «goes».","wrongFeedback":"«He» (3-shaxs birlik) bilan fe’l oxiriga «-es» qo‘shilishini va fe’l o‘rnini tekshiring.","wrongFeedbackRu":"Проверьте окончание «-es» у глагола с «He» и порядок слов SVO."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_m2_daily_life', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'grammar', 'A1', 'mod_eng_a1_m2', 'unit_eng_a1_u2', 'Bo‘sh joyga Present Simple 3-shaxs shaklini yozadi va kundalik odatlar haqida gap tuzadi.', 'Вставляет форму 3-го лица Present Simple и строит предложения о повседневной жизни.', '["node_eng_a1_u1_checkpoint"]'::jsonb, 'Kundalik hayot: Present Simple amaliyoti', 'Повседневная жизнь: практика Present Simple', 6, 'Oila a’zolari va sinfdoshlarning kundalik odatlarini Present Simple zamonida to‘g‘ri yozishni mashq qilasiz.', 'Вы отработаете правильное написание форм Present Simple для описания привычек семьи и одноклассников.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Har kuni takrorlanadigan ishlar haqida gapirganda «I/we/they» bilan fe’l o‘zgarmaydi, «he/she/my sister» bilan esa «-s/-es/-ies» oladi.","ru":"Для регулярных действий с «I/we/they» глагол остаётся в базовой форме, а с «he/she/my sister» получает окончание «-s/-es/-ies»."},"learningObjective":{"uz":"O‘quvchi «study -> studies» o‘zgarishini yozma kiritishda to‘g‘ri qo‘llaydi.","ru":"Ученик верно применяет чередование «study -> studies» при заполнении пропуска."},"warmUp":{"uz":"«cry -> cries» kabi «undosh + y» bilan tugagan fe’llarni eslang.","ru":"Вспомните изменение глаголов на «согласная + y» в 3-м лице единственного числа."},"vocabularyItems":[{"word":"study","uz":"o‘qimoq / o‘rganmoq","ru":"учиться / изучать","ipa":"/ˈstʌdi/"},{"word":"together","uz":"birga","ru":"вместе","ipa":"/təˈɡeðə/"}],"grammarNote":{"rule":"Consonant + y -> -ies (study -> studies)","simpleExplanationUz":"Fe’l «undosh + y» harfi bilan tugasa va ega «he / she / it» bo‘lsa, «y» o‘rniga «-ies» yoziladi.","simpleExplanationRu":"Если глагол оканчивается на «согласная + y», то в 3-м лице ед. ч. «y» меняется на «-ies».","structure":"My sister + studies + English.","positiveExamples":["My sister studies English every morning.","We go to school together."],"negativeExamples":["My sister doesn''t study at night."],"questions":["Does your sister study English?"],"commonMistakes":["«My sister study» (3-shaxs qo‘shimchasini tushirish) yoki «studys» deb yozish."]},"pronunciationFocus":{"uz":"«studies» so‘zi /ˈstʌdiz/ deb yumshoq /z/ tovushi bilan tugaydi.","ru":"Форма «studies» произносится со звонким /z/ на конце: /ˈstʌdiz/."},"examples":["My sister studies English at school every morning.","We go to school together."],"guidedPractice":{"uz":"«study» fe’lining «he/she» bilan qanday o‘zgarishini misolda ko‘ring.","ru":"Изучите пример изменения глагола «study» в 3-м лице."},"independentPractice":{"uz":"Bo‘sh joyga to‘g‘ri fe’l shaklini yozib kiriting.","ru":"Введите правильную форму глагола в пропуск."},"listeningRef":"media_eng_a1_grammar_daily_routine","readingRef":"lesson_eng_a1_m2_dl_visual","speakingTask":{"uz":"Opa-ukangiz yoki do‘stingiz har kuni nima qilishi haqida 1 gap ayting.","ru":"Скажите вслух 1 фразу о том, что ваш друг или сестра делает каждый день."},"writingTask":{"uz":"«studies» so‘zi bilan 1 ta yangi gap yozing.","ru":"Напишите 1 предложение со словом «studies»."},"knowledgeCheck":"q_eng_a1_m2_daily_fill","finalQuiz":"q_eng_a1_m2_daily_order","feedbackRules":{"uz":"«y -> ies» imlo qoidasi eslatiladi.","ru":"При ошибке напоминается правило правописания «y -> ies»."},"summaryAndRevision":{"uz":"2-modul yakuniy sinoviga tayyorgarlik tugallanadi.","ru":"Завершается подготовка к проверке 2-го модуля."}}'::jsonb, '[{"id":"lesson_eng_a1_m2_dl_concept","stepNumber":1,"type":"concept","title":"«Undosh + y» fe’llari va birlik shakli","titleRu":"Глаголы на «согласная + y» в Present Simple","content":"Present Simple zamonida «he», «she» yoki «my sister» kabi bitta shaxs ega bo‘lsa, «undosh + y» bilan tugagan fe’llarda «y» harfi «-ies» ga aylanadi: «study» -> «studies», «try» -> «tries».","contentRu":"В Present Simple с подлежащим в 3-м лице единственного числа (he, she, my sister) у глаголов на «согласная + y» буква «y» заменяется на «-ies»: «study» -> «studies».","highlightNotes":["I / We / They -> study","He / She / My sister -> studies","Play (unli + y) -> plays (y tushmaydi)"]},{"id":"lesson_eng_a1_m2_dl_visual","stepNumber":2,"type":"visual_example","title":"Maktabdagi odatlar misoli","titleRu":"Пример школьного распорядка","content":"Rasmdagi sinf xonasini ko‘rib, ikki gapni solishtiring: «I study math on Tuesday. My brother studies English every morning.»","contentRu":"Сравните два предложения: «I study math on Tuesday. My brother studies English every morning.»","media":{"id":"media_eng_a1_m2_school_classroom_img","kind":"image","language":"en","source":"/lesson-media/english/a1/a1-m2-school-classroom.png","title":"Sinf xonasi va o‘quv stoli","titleUz":"Sinf xonasi va o‘quv stoli","titleRu":"Школьный класс и парта","alt":"Sinf xonasida yashil doska, dars jadvali belgisi, parta ustida ochiq daftar, qalam va olma","altUz":"Sinf xonasida yashil doska, dars jadvali belgisi, parta ustida ochiq daftar, qalam va olma","altRu":"Школьный класс с зелёной доской, сеткой расписания, партой, открытой тетрадью, карандашом и яблоком","reviewStatus":"approved"}},{"id":"lesson_eng_a1_m2_dl_fill","stepNumber":3,"type":"interactive_question","title":"Bo‘sh joyni to‘ldiring","titleRu":"Заполните пропуск","content":"Qavsdagi fe’lni Present Simple da to‘g‘ri shaklda yozing.","contentRu":"Напишите глагол из скобок в правильной форме Present Simple.","interactiveQuestion":{"id":"q_eng_a1_m2_daily_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Present Simple fill_blank","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"My sister ___ English at school every morning.","text":"Qavsdagi fe’lni mos shaklda yozing: «My sister ___ (study) English at school every morning.»","textRu":"Вставьте глагол в нужной форме: «My sister ___ (study) English at school every morning.»","options":[],"acceptedAnswers":["studies"],"explanation":"«My sister» (she) 3-shaxs birlik bo‘lgani uchun «study» fe’li «studies» shakliga o‘zgaradi.","explanationRu":"«My sister» (she) — 3-е лицо ед. ч., поэтому «study» меняется на «studies».","wrongFeedback":"Ega «my sister» (she) bo‘lganda, «undosh + y» bilan tugagan fe’l oxirini «-ies» ga o‘zgartirib yozing.","wrongFeedbackRu":"При подлежащем «my sister» (she) замените конечную «y» после согласной на «-ies»."}}]'::jsonb, '{"id":"q_eng_a1_m2_daily_order","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Sentence ordering: Daily routine","difficulty":"easy","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Biz maktabga birga boramiz» gapini so‘zlardan to‘g‘ri tuzing:","textRu":"Составьте предложение «Мы вместе ходим в школу» в правильном порядке:","options":[],"orderedTokens":["We","go","to","school","together."],"acceptedAnswers":["We go to school together."],"explanation":"Ko‘plikdagi «We» bilan fe’l qo‘shimchasiz («go») keladi: «We go to school together.».","explanationRu":"С местоимением «We» глагол употребляется без окончания: «We go to school together.».","wrongFeedback":"Gapni «We» bilan boshlab, darhol harakat («go to school») va oxirida «together.» ni qo‘ying.","wrongFeedbackRu":"Начните с «We», затем поставьте глагол с направлением («go to school»), а в конце — «together.»."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_grammar_01', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'grammar', 'A1', 'mod_eng_a1_m2', 'unit_eng_a1_u2', 'Present Simple da tasdiq, inkor (don''t/doesn''t) va savol (Do/Does) shakllarini o‘zbekcha L1 xatolarisiz ishlatadi.', 'Употребляет утверждения, отрицания (don''t/doesn''t) и вопросы (Do/Does) в Present Simple.', '["node_eng_vocab"]'::jsonb, 'Grammar: Present Simple va «to be» kundalik hayotda', 'Grammar: Present Simple и «to be» в повседневной жизни', 10, 'Kundalik odatlarni tasvirlashda Present Simple tasdiq (I walk / he walks), inkor (don''t / doesn''t) va savol (Do / Does) qoidalarini o‘rganasiz.', 'Вы освоите утверждения (I walk / he walks), отрицания (don''t / doesn''t) и вопросы (Do / Does) в Present Simple.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Har kuni bajaradigan odatlarimiz uchun Present Simple zamoni ishlatiladi; u «to be» (am/is/are) bilan aralashtirilmaydi.","ru":"Для регулярных привычек используется Present Simple; его нельзя смешивать с конструкцией «to be» (am/is/are)."},"learningObjective":{"uz":"O‘quvchi 3-shaxs birlikda «does» va ko‘plikda inkor «don''t» shakllarini to‘g‘ri tanlaydi.","ru":"Ученик правильно выбирает «does» для 3-го лица ед. ч. и «don''t» для множественного числа."},"warmUp":{"uz":"«I am a student» («to be») va «I walk to school» (harakat) orasidagi farq nima?","ru":"В чём разница между «I am a student» и «I walk to school»?"},"vocabularyItems":[{"word":"every evening","uz":"har oqshom","ru":"каждый вечер","ipa":"/ˈevri ˈiːvnɪŋ/"},{"word":"take the bus","uz":"avtobusga minmoq","ru":"ехать на автобусе","ipa":"/teɪk ðə bʌs/"}],"grammarNote":{"rule":"Present Simple: Verb / Verb+s | Negative: don''t / doesn''t + base verb | Question: Do / Does + Subject + base verb?","simpleExplanationUz":"«I/you/we/they» bilan fe’lning asosiy shakli va «don''t / Do» ishlatiladi. «He/she/it» bilan esa tasdiqda «-s/-es» qo‘shiladi, inkor va savolda «doesn''t / Does» keladi.","simpleExplanationRu":"С «I/you/we/they» используется начальная форма глагола и «don''t / Do». С «he/she/it» в утверждении добавляется «-s/-es», а в отрицании и вопросе ставится «doesn''t / Does».","structure":"Subject + don''t / doesn''t + Verb(base)","positiveExamples":["I walk at eight o''clock.","My sister takes the bus.","My brother does his homework."],"negativeExamples":["They don''t go to school on Sundays.","She doesn''t take the bus."],"questions":["Do you walk to school every day?","Does he do his homework?"],"commonMistakes":["«is do» kabi «to be» + fe’l qo‘shish, 3-shaxsda «do» dan «-es» ni tushirish yoki «They doesn''t» deyish."]},"pronunciationFocus":{"uz":"«does» so‘zi /dʌz/ deb o‘qiladi («duz» emas!), «doesn''t» esa /ˈdʌznt/.","ru":"Слово «does» читается /dʌz/, а отрицание «doesn''t» — /ˈdʌznt/."},"examples":["Aziza: Do you walk to school every day?","Ben: Yes, I walk at eight o''clock, and my sister takes the bus."],"guidedPractice":{"uz":"Aziza va Ben suhbatini tinglab, «walk» va «takes» farqini kuzating.","ru":"Прослушайте диалог Азизы и Бена, обратив внимание на «walk» и «takes»."},"independentPractice":{"uz":"«My brother ___ his homework» va «They ___ go to school» mashqlarini bajaring.","ru":"Выполните задания на выбор «does» и «don''t»."},"listeningRef":"media_eng_a1_grammar_daily_routine","readingRef":"eng_gram_step_1","speakingTask":{"uz":"Maktabga qanday borishingiz haqida 1 gap ayting: «I walk to school» yoki «I take the bus.»","ru":"Скажите вслух, как вы добираетесь до школы."},"writingTask":{"uz":"«don''t» va «does» so‘zlari bilan 2 ta gap yozing.","ru":"Напишите 2 предложения со словами «don''t» и «does»."},"knowledgeCheck":"q_eng_gram_01","finalQuiz":"q_eng_gram_reinf_01","feedbackRules":{"uz":"O‘zbekcha L1 xatolari (copula aralashtirish, -s tushirish) aniq izohlanadi.","ru":"Ошибки интерференции (смешение с to be, пропуск -s) подробно объясняются."},"summaryAndRevision":{"uz":"Present Simple qoidalari A1 2-modul sinoviga tayyorlaydi.","ru":"Правила Present Simple подготавливают к итоговой проверке 2-го модуля."}}'::jsonb, '[{"id":"eng_gram_step_1","stepNumber":1,"type":"concept","title":"1. Present Simple qoidasi","titleRu":"1. Правило Present Simple","subtitle":"Kundalik odatlar va «to be» farqi","subtitleRu":"Повседневные привычки и отличие от «to be»","content":"Kundalik takrorlanadigan harakatlar uchun Present Simple ishlatiladi: I/you/we/they + fe’l («don''t»), he/she/it + fe’l-s/-es («doesn''t»). Diqqat: harakat fe’li oldiga «is/are» qo‘yilmaydi («is do» xato).","contentRu":"Для регулярных действий используется Present Simple: I/you/we/they + глагол («don''t»), he/she/it + глагол-s/-es («doesn''t»). Важно: не ставьте «is/are» перед обычным глаголом.","highlightNotes":["He / She / My brother -> does / goes / takes","I / You / We / They -> do / go / take / don''t","He / She / It inkori -> doesn''t + asosiy fe’l"]},{"id":"eng_gram_step_2_media","stepNumber":2,"type":"audio_simulation","title":"2. Kundalik odatlar suhbati","titleRu":"2. Диалог о повседневных привычках","content":"Aziza va Benning maktabga borish odatlari haqidagi suhbatini tinglang.","contentRu":"Прослушайте диалог Азизы и Бена о том, как они добираются до школы.","media":{"id":"media_eng_a1_grammar_daily_routine","kind":"audio","language":"en","source":"/lesson-media/english/a1/a1-grammar-daily-routine-dialogue.wav","title":"Kundalik maktab odatlari haqida suhbat","titleUz":"Kundalik maktab odatlari haqida suhbat","titleRu":"Диалог о повседневных школьных привычках","transcript":"Aziza: Do you walk to school every day?\nBen: Yes, I walk at eight o''clock, and my sister takes the bus.","posterImage":"/lesson-media/english/a1/a1-m2-school-classroom.png","posterAlt":"Sinf xonasida parta ustidagi daftar, qalam va yashil doska","posterAltUz":"Sinf xonasida parta ustidagi daftar, qalam va yashil doska","posterAltRu":"Школьная парта с тетрадью, карандашом и зелёной доской в классе","durationSeconds":6.11,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Aziza: Do you walk to school every day?\nBen: Yes, I walk at eight o''clock, and my sister takes the bus.","speakerName":"Aziza & Ben"}},{"id":"eng_gram_step_2","stepNumber":3,"type":"interactive_question","title":"3. Grammatika Savoli","titleRu":"3. Грамматический вопрос","subtitle":"To‘g‘ri shaklni tanlang","subtitleRu":"Выберите правильную форму","content":"Gapni to‘g‘ri fe’l shakli bilan to‘ldiring.","contentRu":"Дополните предложение правильной формой глагола.","interactiveQuestion":{"id":"q_eng_gram_01","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Present Simple 3rd person singular","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"To‘g‘ri fe’l shaklini tanlang: «My brother ___ his homework every evening.»","textRu":"Выберите верную форму глагола: «My brother ___ his homework every evening.»","options":["do","doing","is do","does"],"correctIndex":3,"mistakeFeedbackByOption":{"do":{"uz":"«My brother» — 3-shaxs birlik (he). Present Simple da «do» fe’liga «-es» qo‘shilib «does» bo‘ladi.","ru":"«My brother» — 3-е лицо ед. ч. (he). В Present Simple к «do» добавляется «-es» -> «does»."},"doing":{"uz":"«every evening» har kungi odatni bildiradi; «doing» esa yordamchi fe’lsiz gapda fe’l bo‘la olmaydi.","ru":"«every evening» указывает на регулярное действие; «doing» без вспомогательного глагола не используется."},"is do":{"uz":"Present Simple da «to be» (is) bilan asosiy fe’l («do») birga ishlatilmaydi.","ru":"В Present Simple связка «is» не ставится перед смысловым глаголом «do»."}},"explanation":"«My brother» (he) 3-shaxs birlik bo‘lgani uchun har kungi odatda «does» shakli ishlatiladi.","explanationRu":"С подлежащим 3-го лица ед. ч. «My brother» (he) в Present Simple употребляется «does».","wrongFeedback":"«My brother» bitta shaxs (he) va «every evening» doimiy odat ekanini hisobga oling.","wrongFeedbackRu":"Учтите, что «My brother» (he) — 3-е лицо ед. ч., а «every evening» — регулярное действие."}}]'::jsonb, '{"id":"q_eng_gram_reinf_01","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Present Simple negative (don''t)","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Mustahkamlash: «Ular yakshanba kunlari maktabga bormaydi» gapini to‘g‘ri to‘ldiring: «They ___ go to school on Sundays.»","textRu":"Закрепление: дополните предложение «They ___ go to school on Sundays.»","options":["doesn''t","aren''t","don''t","not"],"correctIndex":2,"mistakeFeedbackByOption":{"doesn''t":{"uz":"«doesn''t» faqat «he/she/it» bilan ishlatiladi; ko‘plikdagi «They» bilan «don''t» keladi.","ru":"«doesn''t» используется только с «he/she/it»; с местоимением «They» нужно «don''t»."},"aren''t":{"uz":"Gapda asosiy harakat fe’li («go») bor, shuning uchun inkor «aren''t» emas, «don''t» bilan yasaladi.","ru":"В предложении есть смысловой глагол «go», поэтому отрицание строится через «don''t», а не «aren''t»."},"not":{"uz":"Ingliz tilida Present Simple inkorida yolg‘iz «not» qo‘yilmaydi, yordamchi fe’l («don''t») kerak.","ru":"В Present Simple нельзя ставить просто «not» перед глаголом — нужен вспомогательный глагол «don''t»."}},"explanation":"Ko‘plikdagi «They» bilan Present Simple inkori «don''t + asosiy fe’l» orqali yasaladi.","explanationRu":"С подлежащим «They» отрицание в Present Simple образуется с помощью «don''t + глагол».","wrongFeedback":"«They» ko‘plikda va gapda «go» harakat fe’li borligini eslang.","wrongFeedbackRu":"Помните, что «They» — множественное число, а «go» — смысловой глагол."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_u2_checkpoint', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'checkpoint', 'A1', 'mod_eng_a1_m2', 'unit_eng_a1_u2', '2-modul yakuniy sinovida Dilnozaning dars jadvali va kundalik odatlari bo‘yicha Present Simple shakllarini to‘g‘ri qo‘llaydi.', 'В итоговой проверке 2-го модуля применяет формы Present Simple в новом контексте расписания Дилнозы.', '["node_eng_a1_m2_daily_life"]'::jsonb, '2-modul yakuni: «To be» va Present Simple sinovi', 'Итог модуля 2: Проверка «to be» и Present Simple', 5, '2-modul bo‘yicha mustaqil tekshiruv: shanba kunidagi odatlar va inkor gaplardagi xatolarni tuzatish.', 'Проверка 2-го модуля: формы 3-го лица единственного числа и исправление ошибок отрицания.', 'Bu modul sinovi 3-modulni ochadi; rasmiy CEFR sertifikati bermaydi.', 'Эта проверка открывает 3-й модуль и не даёт официального сертификата CEFR.', '{"intro":{"uz":"2-modulda o‘rganilgan «to be» va Present Simple qoidalarini yangi jadval vaziyatida sinang.","ru":"Проверьте правила «to be» и Present Simple в новой ситуации с расписанием на неделю."},"learningObjective":{"uz":"O‘quvchi 3-shaxs «-es» qo‘shimchasini to‘g‘ri yozadi va «doesn''t» bilan xatoni tuzatadi.","ru":"Ученик верно пишет окончание «-es» и исправляет ошибку с «doesn''t»."},"warmUp":{"uz":"«ch» harf birikmasi bilan tugaydigan «watch» fe’li «she» bilan qanday yoziladi?","ru":"Как пишется глагол «watch» в форме «she»?"},"vocabularyItems":[{"word":"watch","uz":"tomosha qilmoq","ru":"смотреть","ipa":"/wɒtʃ/"}],"grammarNote":{"rule":"-ch, -sh, -s, -x, -o -> + -es","simpleExplanationUz":"«watch» kabi -ch bilan tugagan fe’llarga «he/she/it» da «-es» qo‘shiladi: «watches».","simpleExplanationRu":"К глаголам на -ch, -sh, -s, -x, -o в 3-м лице ед. ч. добавляется «-es».","structure":"Dilnoza watches cartoons on Saturday.","positiveExamples":["Dilnoza watches cartoons on Saturday evenings."],"negativeExamples":["She doesn''t watch TV in the morning."],"questions":["Does Dilnoza watch cartoons?"],"commonMistakes":["«watchs» deb ''e'' ni tushirib yuborish."]},"pronunciationFocus":{"uz":"«watches» /ˈwɒtʃɪz/ — oxirida alohida bo‘g‘in eshitiladi.","ru":"В «watches» /ˈwɒtʃɪz/ окончание образует дополнительный слог."},"examples":["Dilnoza watches cartoons on Saturday evenings."],"guidedPractice":{"uz":"«Dilnoza» bitta shaxs (she) ekaniga e’tibor bering.","ru":"Обратите внимание, что «Dilnoza» — это 3-е лицо единственного числа."},"independentPractice":{"uz":"Bo‘sh joyni to‘ldiring va xato gapni tuzating.","ru":"Заполните пропуск и исправьте ошибку."},"listeningRef":"media_eng_a1_grammar_daily_routine","readingRef":"lesson_eng_a1_u2_cp_concept","speakingTask":{"uz":"Dam olish kunidagi odatlaringiz haqida 1 gap ayting.","ru":"Скажите 1 фразу о своей привычке на выходных."},"writingTask":{"uz":"«watches» so‘zi bilan 1 gap tuzing.","ru":"Составьте 1 предложение со словом «watches»."},"knowledgeCheck":"q_eng_a1_u2_cp_main","finalQuiz":"q_eng_a1_u2_cp_reinf","feedbackRules":{"uz":"-ch dan keyingi -es qo‘shimchasi tushuntiriladi.","ru":"Объясняется правило добавления -es после -ch."},"summaryAndRevision":{"uz":"Sinovdan o‘tgach, 3-modul (Joylashuv va vaqt) ochiladi.","ru":"После прохождения теста открывается 3-й модуль (Предлоги места и время)."}}'::jsonb, '[{"id":"lesson_eng_a1_u2_cp_concept","stepNumber":1,"type":"concept","title":"2-modul yakuniy tekshiruvi","titleRu":"Итоговая проверка модуля 2","content":"Bu sinovda Dilnozaning dushanba va shanba kungi odatlari haqidagi yangi gaplarni to‘g‘ri tuzasiz.","contentRu":"В этой проверке вы закрепите Present Simple на примере расписания Дилнозы."},{"id":"lesson_eng_a1_u2_cp_quiz","stepNumber":2,"type":"interactive_question","title":"Sinov topshirig‘i","titleRu":"Контрольное задание","content":"Qavsdagi fe’lni mos shaklga keltirib bo‘sh joyga yozing.","contentRu":"Поставьте глагол в скобках в нужную форму.","interactiveQuestion":{"id":"q_eng_a1_u2_cp_main","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Unit 2 checkpoint: Present Simple -es","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"Dilnoza ___ cartoons on Saturday evenings.","text":"Gapni to‘g‘ri fe’l shakli bilan to‘ldiring: «Dilnoza ___ (watch) cartoons on Saturday evenings.»","textRu":"Заполните пропуск верной формой глагола: «Dilnoza ___ (watch) cartoons on Saturday evenings.»","options":[],"acceptedAnswers":["watches"],"explanation":"Fe’l «-ch» bilan tugagani uchun «Dilnoza» (she) bilan oxiriga «-es» qo‘shiladi: «watches».","explanationRu":"Поскольку глагол оканчивается на «-ch», с «Dilnoza» (she) добавляется «-es»: «watches».","wrongFeedback":"«Dilnoza» (she) 3-shaxs birlik bo‘lib, «-ch» bilan tugagan fe’l oxiriga «-es» qo‘shishni unutmang.","wrongFeedbackRu":"С подлежащим 3-го лица ед. ч. «Dilnoza» к глаголу на «-ch» нужно добавить окончание «-es»."}}]'::jsonb, '{"id":"q_eng_a1_u2_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Unit 2 checkpoint error correction","difficulty":"easy","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"She don''t like cold tea.","text":"«She don''t like cold tea.» gapidagi xatoni tuzating:","textRu":"Исправьте ошибку в предложении «She don''t like cold tea.»:","options":["She doesn''t like cold tea.","She doesn''t likes cold tea.","She not like cold tea."],"correctIndex":0,"mistakeFeedbackByOption":{"She doesn''t likes cold tea.":{"uz":"«doesn''t» kelganidan keyin asosiy fe’l («like») ga ikkinchi marta «-s» qo‘shilmaydi!","ru":"После «doesn''t» основной глагол («like») остаётся без окончания «-s»!"},"She not like cold tea.":{"uz":"Present Simple inkorida «not» yolg‘iz kelmaydi, «doesn''t» yordamchi fe’li kerak.","ru":"Отрицание в Present Simple требует вспомогательного глагола «doesn''t», одного «not» недостаточно."}},"explanation":"«She» bilan inkor «doesn''t» orqali yasaladi va asosiy fe’l («like») qo‘shimchasiz qoladi.","explanationRu":"С «She» отрицание образуется через «doesn''t», а смысловой глагол («like») остаётся в базовой форме.","wrongFeedback":"«She» bilan qaysi inkor yordamchisi kelishini va «doesn''t» dan keyin «-s» tushishini tekshiring.","wrongFeedbackRu":"Проверьте форму отрицания для «She» и помните, что после «doesn''t» окончание «-s» не ставится."}'::jsonb, '{"id":"q_eng_a1_u2_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"Unit 2 checkpoint alternate retry","difficulty":"easy","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"They is in the library on Monday.","text":"«They is in the library on Monday.» gapining to‘g‘ri variantini tanlang:","textRu":"Выберите исправленный вариант предложения «They is in the library on Monday.»:","options":["They am in the library on Monday.","They be in the library on Monday.","They are in the library on Monday."],"correctIndex":2,"mistakeFeedbackByOption":{"They am in the library on Monday.":{"uz":"«am» faqat «I» bilan ishlatiladi; ko‘plikdagi «They» bilan «are» keladi.","ru":"«am» используется только с «I»; с «They» нужна форма «are»."},"They be in the library on Monday.":{"uz":"Hozirgi zamonda «to be» fe’li ega bilan moslashib «are» shakliga o‘tishi shart.","ru":"В настоящем времени глагол «to be» согласуется с «They» и принимает форму «are»."}},"explanation":"«They» ko‘plik olmoshi bo‘lgani uchun «are» bilan bog‘lanadi: «They are in the library on Monday.».","explanationRu":"Местоимение множественного числа «They» требует формы «are».","wrongFeedback":"Ko‘plikdagi «They» olmoshi bilan «to be» ning qaysi shakli ishlatilishini tanlang.","wrongFeedbackRu":"Выберите форму «to be», которая сочетается с местоимением «They»."}'::jsonb, true, true, false),
  ('lesson_eng_vocab_01', 'course_eng_01', 'skill_eng_vocab', 'vocabulary', 'vocabulary', 'A1', 'mod_eng_a1_m3', 'unit_eng_a1_u3', 'Xonadagi buyumlarning joylashuvini (beside, between, behind) ko‘rib va tinglab aniq farqlaydi.', 'Определяет расположение предметов в комнате (beside, between, behind) по изображению и на слух.', '[]'::jsonb, 'Vocabulary: Xona buyumlari va joylashuv (beside, between, behind)', 'Vocabulary: Предметы в комнате и предлоги места (beside, between, behind)', 8, 'Xonadagi buyumlar qayerda turganini aytish uchun «beside» (yonida), «between» (orasida) va «behind» (orqasida) predloglarini o‘rganasiz.', 'Вы научитесь описывать расположение вещей в комнате с помощью предлогов «beside», «between» и «behind».', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Buyum qayerda turganini aytish uchun o‘zbek tilida so‘z oxiriga «yonida», «orasida», «orqasida» qo‘yiladi; ingliz tilida esa predlog otdan oldin keladi.","ru":"В английском языке предлоги места («beside», «between», «behind») ставятся перед существительным."},"learningObjective":{"uz":"O‘quvchi rasm va audio dialog asosida «beside», «between» va «behind» o‘rinlarini aniq ajratadi.","ru":"Ученик безошибочно различает положения «beside», «between» и «behind» по иллюстрации и аудио."},"warmUp":{"uz":"Xonangizda ryukzagingiz yoki daftaringiz hozir qayerda turibdi?","ru":"Где сейчас в вашей комнате лежит рюкзак или тетрадь?"},"vocabularyItems":[{"word":"beside","uz":"yonida","ru":"рядом с","ipa":"/bɪˈsaɪd/"},{"word":"between","uz":"ikki narsa orasida","ru":"между двумя предметами","ipa":"/bɪˈtwiːn/"},{"word":"behind","uz":"orqasida","ru":"позади / за","ipa":"/bɪˈhaɪnd/"},{"word":"armchair","uz":"kreslo","ru":"кресло","ipa":"/ˈɑːmtʃeə/"}],"grammarNote":{"rule":"Item + is/are + beside / between / behind + Reference Object","simpleExplanationUz":"«beside the desk» (stol yonida), «between the chair and the shelf» (stul va javon orasida), «behind the armchair» (kreslo orqasida).","simpleExplanationRu":"Предлог ставится перед названием предмета: «beside the desk», «between A and B», «behind the armchair».","structure":"The [item] is [preposition] the [furniture].","positiveExamples":["The notebook is beside the desk.","The lamp is between the chair and the shelf.","The backpack is behind the armchair."],"negativeExamples":["The notebook is the desk beside. (Uzbek postposition order)"],"questions":["Where is my notebook?"],"commonMistakes":["«between» (ikki narsa orasida) bilan «behind» (orqasida) ni chalkashtirish."]},"pronunciationFocus":{"uz":"«beside», «between», «behind» so‘zlarining birinchi bo‘g‘ini urg‘usiz /bɪ-/ bilan boshlanadi.","ru":"В словах «beside», «between», «behind» первый слог безударный (/bɪ-/), а ударение на втором слоге."},"examples":["It is beside the desk.","The lamp is between the chair and the shelf.","Your backpack is behind the armchair."],"guidedPractice":{"uz":"3 qismli rasm va 4 ta flashcard orqali har bir joylashuvni eslab qoling.","ru":"Изучите трёхзонную иллюстрацию и 4 карточки с предлогами."},"independentPractice":{"uz":"Chiroq va ryukzak joylashuvi haqidagi ikki savolga mustaqil javob bering.","ru":"Ответьте на вопросы о положении лампы и рюкзака."},"listeningRef":"media_eng_a1_vocab_room_prepositions_dialogue","readingRef":"eng_vocab_step_1","speakingTask":{"uz":"Rasmdagi uch buyum joylashuvini ingliz tilida ovoz chiqarib ayting.","ru":"Опишите вслух положение трёх предметов на иллюстрации."},"writingTask":{"uz":"O‘z xonangizdagi 2 ta buyum joylashuvini «beside» va «behind» bilan yozing.","ru":"Напишите 2 предложения о своей комнате со словами «beside» и «behind»."},"knowledgeCheck":"q_eng_vocab_01","finalQuiz":"q_eng_vocab_reinf_01","feedbackRules":{"uz":"Har bir predlogning fazoviy farqi rasm zonasi bilan bog‘lab tushuntiriladi.","ru":"Пространственное различие предлогов объясняется со ссылкой на зоны рисунка."},"summaryAndRevision":{"uz":"4 ta karta spaced-repetition tizimida saqlanadi.","ru":"4 карточки сохраняются в системе интервального повторения."}}'::jsonb, '[{"id":"eng_vocab_step_1","stepNumber":1,"type":"concept","title":"1. Joylashuv predloglari","titleRu":"1. Предлоги места в комнате","subtitle":"Beside, between, behind","subtitleRu":"Рядом, между, позади","content":"Ingliz tilida buyum o‘rnini aytganda predlog otdan oldin keladi: «beside» — yonida, «between» — ikki narsa orasida, «behind» — orqasida. Masalan: «beside the desk» — stol yonida.","contentRu":"В английском языке предлог ставится перед предметом: «beside» — рядом, «between» — между двумя предметами, «behind» — позади.","highlightNotes":["beside — yonida (yonma-yon)","between A and B — ikki narsa orasida","behind — orqasida (orqa tomonda)","armchair — yumshoq kreslo"]},{"id":"eng_vocab_step_2_media","stepNumber":2,"type":"audio_simulation","title":"2. Xonadagi buyumlarni topamiz","titleRu":"2. Находим предметы в комнате","content":"Rasmdagi uchta hududga qarab Aziza va Ben suhbatini tinglang.","contentRu":"Посмотрите на три зоны на картинке и прослушайте диалог Азизы и Бена.","media":{"id":"media_eng_a1_vocab_room_prepositions_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a1/a1-vocab-room-prepositions-dialogue.wav","title":"Xonadagi buyumlar joylashuvi suhbati","titleUz":"Xonadagi buyumlar joylashuvi suhbati","titleRu":"Диалог о расположении предметов в комнате","transcript":"Aziza: Where is my notebook?\nBen: It is beside the desk, and the lamp is between the chair and the shelf.\nAziza: What about my backpack?\nBen: Your backpack is behind the armchair.","posterImage":"/lesson-media/english/a1/a1-vocab-room-prepositions.png","posterAlt":"Xonada uchta alohida hududda stol, stul, kitob javoni, chiroq va kreslo joylashuvi ko‘rsatilgan","posterAltUz":"Xonada uchta alohida hududda stol, stul, kitob javoni, chiroq va kreslo joylashuvi ko‘rsatilgan","posterAltRu":"В комнате в трёх зонах показано расположение стола, стула, книжной полки, лампы и кресла","durationSeconds":9.832,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Aziza: Where is my notebook?\nBen: It is beside the desk, and the lamp is between the chair and the shelf.\nAziza: What about my backpack?\nBen: Your backpack is behind the armchair.","speakerName":"Aziza & Ben"}},{"id":"eng_vocab_step_3_flashcards","stepNumber":3,"type":"flashcard","title":"3. Joylashuv kartochkalari","titleRu":"3. Карточки предлогов и мебели","content":"Har bir so‘zni rasm va ovoz orqali mustahkamlang.","contentRu":"Закрепите каждое слово с помощью изображения и аудио.","flashcards":[{"id":"fc_eng_a1_m3_beside","front":"beside","backUz":"yonida","backRu":"рядом с","partOfSpeech":"preposition","ipa":"/bɪˈsaɪd/","cefrLevel":"A1","example":"The notebook is beside the desk.","exampleUz":"Daftar stolning yonida.","exampleRu":"Тетрадь рядом со столом.","audioSrc":"/lesson-media/english/a1/a1-m3-beside.wav","imageSrc":"/lesson-media/english/a1/a1-vocab-room-prepositions.png","alt":"Chap hududda ko‘k stol chetida kichik stend ustida sariq daftar turibdi","altRu":"В левой зоне рисунка жёлтая тетрадь лежит на подставке сбоку от синего стола","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m3_between","front":"between","backUz":"ikki narsa orasida","backRu":"между двумя предметами","partOfSpeech":"preposition","ipa":"/bɪˈtwiːn/","cefrLevel":"A1","example":"The lamp is between the chair and the shelf.","exampleUz":"Chiroq stul va javon orasida turibdi.","exampleRu":"Лампа стоит между стулом и полкой.","audioSrc":"/lesson-media/english/a1/a1-m3-between.wav","imageSrc":"/lesson-media/english/a1/a1-vocab-room-prepositions.png","alt":"Markaziy hududda chapda stul, o‘ngda kitob javoni, ularning qoq markazida esa iliq nurli chiroq turibdi","altRu":"В центральной зоне лампа стоит на столике посередине: слева стул, справа книжная полка","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m3_behind","front":"behind","backUz":"orqasida","backRu":"позади / за","partOfSpeech":"preposition","ipa":"/bɪˈhaɪnd/","cefrLevel":"A1","example":"The backpack is behind the armchair.","exampleUz":"Ryukzak kresloning orqasida.","exampleRu":"Рюкзак за креслом.","audioSrc":"/lesson-media/english/a1/a1-m3-behind.wav","imageSrc":"/lesson-media/english/a1/a1-vocab-room-prepositions.png","alt":"O‘ng hududda yashil kreslo suyanchig‘ining narigi tomonida ko‘k ryukzakning yuqori qismi ko‘rinib turibdi","altRu":"В правой зоне верхняя часть синего рюкзака видна с обратной стороны зелёного кресла","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a1_m3_armchair","front":"armchair","backUz":"yumshoq kreslo","backRu":"кресло","partOfSpeech":"noun","ipa":"/ˈɑːmtʃeə/","ipaAmE":"/ˈɑːrmtʃer/","cefrLevel":"A1","example":"There is a green armchair in the corner.","exampleUz":"Burchakda yashil kreslo bor.","exampleRu":"В углу стоит зелёное кресло.","audioSrc":"/lesson-media/english/a1/a1-m3-armchair.wav","imageSrc":"/lesson-media/english/a1/a1-vocab-room-prepositions.png","alt":"Xonaning o‘ng tomonidagi ikki tirsakli qulay yashil o‘rindiq","altRu":"Мягкое зелёное сиденье с подлокотниками в правой части комнаты","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"eng_vocab_step_2","stepNumber":4,"type":"interactive_question","title":"4. Sinov Savoli","titleRu":"4. Проверочный вопрос","subtitle":"Joylashuvni aniqlang","subtitleRu":"Определите расположение","content":"Suhbat va rasmga asoslanib, chiroq (lamp) qayerda turganini tanlang.","contentRu":"На основе диалога и рисунка выберите, где стоит лампа.","interactiveQuestion":{"id":"q_eng_vocab_01","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Spatial prepositions in room","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Dialog va xona tartibiga ko‘ra, chiroq (lamp) qayerda turibdi?","textRu":"Согласно диалогу и плану комнаты, где находится лампа?","options":["behind the sofa","beside the window","under the desk","between the chair and the shelf"],"correctIndex":3,"mistakeFeedbackByOption":{"behind the sofa":{"uz":"«behind» — orqasida degani; dialogda kreslo orqasida ryukzak turibdi, chiroq emas.","ru":"«behind» означает «позади»; в диалоге позади кресла лежит рюкзак, а не лампа."},"beside the window":{"uz":"«beside» yonida degani (stol yonida daftar bor); chiroq esa ikki buyum o‘rtasida turibdi.","ru":"«beside» означает «рядом»; лампа же стоит между двумя предметами."},"under the desk":{"uz":"«under» — ostida degani; chiroq stol tagida emas, ikki buyum orasida.","ru":"«under» означает «под»; лампа стоит не под столом, а между двумя объектами."}},"explanation":"Dialogda Ben: «the lamp is between the chair and the shelf» (stul va javon orasida) deydi.","explanationRu":"В диалоге Бен говорит: «the lamp is between the chair and the shelf» (между стулом и полкой).","wrongFeedback":"Chiroq ikki narsa o‘rtasida turganini eslang va «between» predlogiga e’tibor bering.","wrongFeedbackRu":"Вспомните, что лампа находится посередине между двумя предметами («between»)."}}]'::jsonb, '{"id":"q_eng_vocab_reinf_01","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Spatial prepositions reinforcement","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Mustahkamlash: Sizning ryukzakingiz kresloning orqa tomonida turibdi. Ingliz tilida qaysi predlog to‘g‘ri?","textRu":"Закрепление: ваш рюкзак стоит с обратной стороны кресла. Какой предлог верный?","options":["between","under","behind","inside"],"correctIndex":2,"mistakeFeedbackByOption":{"between":{"uz":"«between» — ikki narsaning o‘rtasida degani; bu yerda faqat kreslo orqasi haqida gap ketyapti.","ru":"«between» означает «между двумя предметами», а не позади одного."},"under":{"uz":"«under» — ostida/tagida degani, orqasida emas.","ru":"«under» означает «под», а не «позади»."},"inside":{"uz":"«inside» — ichida degani; ryukzak kresloning ichida emas.","ru":"«inside» означает «внутри», а рюкзак стоит сзади."}},"explanation":"«behind» — biror narsaning orqa tomonida («behind the armchair») ma’nosini beradi.","explanationRu":"«behind» означает «позади / за» («behind the armchair»).","wrongFeedback":"«orqa tomonida» ma’nosini beruvchi inglizcha predlogni tanlang.","wrongFeedbackRu":"Выберите английский предлог со значением «позади»."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_listening_01', 'course_eng_01', 'skill_eng_listening', 'listening', 'listening', 'A1', 'mod_eng_a1_m3', 'unit_eng_a1_u3', 'Audio e’londagi soat ifodasi va kun qismi («in the afternoon») dalilidan foydalanib aniq vaqtni topadi.', 'Определяет точное время по часовому выражению и уточнению части дня («in the afternoon») в аудио.', '["node_eng_gram"]'::jsonb, 'Listening: Audio xabarlar va vaqt ko‘rsatkichlari', 'Listening: Аудиосообщения и время дня', 12, 'Kundalik suhbatlarda vaqt, uchrashuv soatlari va audio xabarlarni tinglab tushunish ko‘nikmasi.', 'Навык понимания времени встреч и расписания в коротких аудиообъявлениях.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"E’lonlarda faqat soat raqamini emas, «in the morning» yoki «in the afternoon» kabi kun vaqtini ham eshitib olish zarur.","ru":"В объявлениях важно слышать не только время, но и уточнение части дня: «in the morning» или «in the afternoon»."},"learningObjective":{"uz":"O‘quvchi «quarter past three in the afternoon» iborasini 03:15 bilan adashtirmasdan 15:15 deb aniqlaydi.","ru":"Ученик отличает 15:15 от 03:15 по контексту «in the afternoon»."},"warmUp":{"uz":"«Quarter» so‘zi soatda necha daqiqani anglatadi?","ru":"Сколько минут означает слово «quarter» применительно ко времени?"},"vocabularyItems":[{"word":"quarter past","uz":"chorak (15 daqiqa) o‘tdi","ru":"пятнадцать минут (после часа)","ipa":"/ˈkwɔːtə pɑːst/"},{"word":"in the afternoon","uz":"kunduzi / tushdan keyin","ru":"днём / после полудня","ipa":"/ɪn ði ˌɑːftəˈnuːn/"}],"grammarNote":{"rule":"quarter past [hour] + in the morning / in the afternoon","simpleExplanationUz":"«Quarter past three» — 3:15 ham, 15:15 ham bo‘lishi mumkin; «in the afternoon» kunduzgi 15:15 ekanini isbotlaydi.","simpleExplanationRu":"Выражение «quarter past three» само по себе может означать 03:15 или 15:15; уточнение «in the afternoon» доказывает 15:15.","structure":"starts at [time] + in the afternoon","positiveExamples":["The lecture starts at quarter past three in the afternoon."],"negativeExamples":["03:15 is in the morning / at night, not in the afternoon."],"questions":["What time does the lecture start?"],"commonMistakes":["«in the afternoon» dalilini eshitmasdan 03:15 AM ni belgilash."]},"pronunciationFocus":{"uz":"«quarter» so‘zi /ˈkwɔːtə/ tarzida talaffuz qilinadi.","ru":"Слово «quarter» произносится как /ˈkwɔːtə/."},"examples":["Excuse me, the university lecture starts at quarter past three in the afternoon in hall B."],"guidedPractice":{"uz":"Audio xabarni tinglab, kerak bo‘lsa «Matnli bayon» ni ochib tekshiring.","ru":"Прослушайте аудио и при необходимости сверьтесь со скрытым текстом."},"independentPractice":{"uz":"E’lon vaqti (15:15) hamda mustahkamlash vaqtini (16:30) aniqlang.","ru":"Определите время лекции (15:15) и время в задании закрепления (16:30)."},"listeningRef":"media_eng_listening_lecture_time","readingRef":"eng_list_step_1","speakingTask":{"uz":"«At quarter past three in the afternoon» iborasini ovoz chiqarib takrorlang.","ru":"Повторите вслух: «At quarter past three in the afternoon»."},"writingTask":{"uz":"Bugungi darsingiz soat nechada boshlanishini yozing.","ru":"Напишите время начала вашего занятия."},"knowledgeCheck":"q_eng_listening_01","finalQuiz":"q_eng_reinf_01","feedbackRules":{"uz":"03:15 AM va 15:15 PM farqi «in the afternoon» dalili bilan tushuntiriladi.","ru":"Разница между 03:15 AM и 15:15 объясняется ссылкой на «in the afternoon»."},"summaryAndRevision":{"uz":"Keyingi darsda «quarter to» (chorak kam) va ertalabki avtobus jadvali o‘rganiladi.","ru":"В следующем уроке изучается «quarter to» и утреннее расписание автобуса."}}'::jsonb, '[{"id":"eng_list_step_1","stepNumber":1,"type":"concept","title":"1. Tinglab tushunish strategiyasi","titleRu":"1. Стратегия аудирования","subtitle":"Kalit so‘zlarni ilg‘ash","subtitleRu":"Поиск ключевых слов","content":"Ingliz tilida tinglashda har bir so‘zni emas, asosiy ma’no tashuvchi so‘zlarni (vaqt, kun qismi, joy) tutib olish muhimdir.","contentRu":"При аудировании важно улавливать ключевые слова: время, часть дня и место.","highlightNotes":["Vaqt ifodalari: \"quarter past\" (chorak o‘tdi), \"half past\" (yarim), \"quarter to\" (chorak kam)","Kun qismi dalillari: \"in the morning\" (ertalab), \"in the afternoon\" (kunduzi)"]},{"id":"eng_list_step_2","stepNumber":2,"type":"audio_simulation","title":"2. Audio Xabarni Tinglash","titleRu":"2. Прослушивание аудиообъявления","subtitle":"Suhbat parchasi","subtitleRu":"Фрагмент объявления","content":"Quyidagi audio e’lonni tinglang va ma’ruza boshlanadigan aniq vaqtni (kun vaqti bilan) aniqlang.","contentRu":"Прослушайте объявление и определите точное время начала лекции с учётом времени суток.","media":{"id":"media_eng_listening_lecture_time","kind":"audio","language":"en","source":"/lesson-media/english/a1-listening-lecture-time.wav","title":"Universitet ma''ruzasi vaqti e''loni","titleUz":"Universitet ma''ruzasi vaqti e''loni","titleRu":"Объявление о времени университетской лекции","transcript":"Excuse me, the university lecture starts at quarter past three in the afternoon in hall B.","durationSeconds":5.546,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Excuse me, the university lecture starts at quarter past three in the afternoon in hall B.","speakerName":"Sarah (O‘qituvchi)"}},{"id":"eng_list_step_3","stepNumber":3,"type":"interactive_question","title":"3. Amaliy Mashq","titleRu":"3. Практическое задание","subtitle":"Tinglab tushunish testi","subtitleRu":"Тест на понимание на слух","content":"Audio xabardagi vaqt ko‘rsatkichiga asoslanib javob bering.","contentRu":"Ответьте на вопрос, опираясь на услышанное время и часть дня.","interactiveQuestion":{"id":"q_eng_listening_01","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A1","topic":"Listening time and AM/PM clues","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audio xabarga ko‘ra, ma’ruza soat nechada boshlanadi?","textRu":"Согласно аудиообъявлению, во сколько начинается лекция?","options":["03:15 (quarter past three AM)","15:15 (quarter past three)","15:30 (half past three)","14:45 (quarter to three)"],"correctIndex":1,"mistakeFeedbackByOption":{"03:15 (quarter past three AM)":{"uz":"Audio xabarda «in the afternoon» (kunduzi) deyilgan — shuning uchun tungi 03:15 AM emas, kunduzgi 15:15 to‘g‘ri!","ru":"В аудио прозвучало «in the afternoon» (днём), поэтому верно дневное время 15:15, а не 03:15 AM."},"15:30 (half past three)":{"uz":"«Half past» 30 daqiqani bildiradi; e’londa esa «quarter past three» (15 daqiqa) aytildi.","ru":"«Half past» означает половину часа (:30), а в аудио сказано «quarter past three» (:15)."},"14:45 (quarter to three)":{"uz":"«Quarter to three» — uchga chorak kam (14:45); audioda «quarter past» (uchdan chorak o‘tdi) deyilgan.","ru":"«Quarter to three» — без четверти три (14:45), а в аудио прозвучало «quarter past» (15:15)."}},"explanation":"\"Quarter past three in the afternoon\" — kunduzgi soat uchdan 15 daqiqa o‘tganini (15:15) bildiradi.","explanationRu":"«Quarter past three in the afternoon» означает 15 минут четвёртого днём, то есть 15:15.","wrongFeedback":"Audiodagi «quarter past three» va kun qismi dalili («in the afternoon») ga diqqat qiling.","wrongFeedbackRu":"Обратите внимание на «quarter past three» и уточнение времени суток «in the afternoon»."}}]'::jsonb, '{"id":"q_eng_reinf_01","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A1","topic":"Half past time format","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Mustahkamlash: \"Half past four\" kunduzi qaysi vaqtni anglatadi?","textRu":"Закрепление: какое дневное время означает «Half past four»?","options":["16:15","16:45","16:30","17:00"],"correctIndex":2,"mistakeFeedbackByOption":{"16:15":{"uz":"16:15 — «quarter past four» bo‘ladi; «half» esa yarim soat (30 daqiqa).","ru":"16:15 — это «quarter past four», а «half» означает 30 минут."},"16:45":{"uz":"16:45 — «quarter to five»; «half past four» esa 4 dan 30 daqiqa o‘tishi.","ru":"16:45 — это «quarter to five», а «half past four» — 16:30."},"17:00":{"uz":"17:00 — «five o''clock».","ru":"17:00 — это «five o''clock»."}},"explanation":"\"Half past four\" — to‘rtdan o‘ttiz daqiqa o‘tganini (16:30) bildiradi.","explanationRu":"«Half past four» означает половину пятого (16:30).","wrongFeedback":"«Half past» — berilgan soatdan 30 daqiqa o‘tganini bildiradi.","wrongFeedbackRu":"«Half past» означает 30 минут после указанного часа."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_m3_time_schedule', 'course_eng_01', 'skill_eng_listening', 'listening', 'listening', 'A1', 'mod_eng_a1_m3', 'unit_eng_a1_u3', 'Avtobus jadvali e’lonidan «quarter to» va «o''clock» vaqtlarini tinglab aniq raqamli soatga aylantiradi.', 'Переводит услышанные выражения «quarter to» и «o''clock» из расписания в точное цифровое время.', '["node_eng_a1_u2_checkpoint"]'::jsonb, 'Avtobus jadvali va «quarter to» vaqtlari', 'Расписание автобусов и время «quarter to»', 7, '«Quarter to eight» (07:45) va «quarter past eight» (08:15) farqini hamda ertalab/kechki soatlarni jadval suhbatida o‘rganasiz.', 'Вы научитесь отличать «quarter to eight» (07:45) от «quarter past eight» (08:15) в диалоге о транспорте.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Avtobus yoki poyezdga kechikmaslik uchun «quarter to» (15 daqiqa kam) va «quarter past» (15 daqiqa o‘tdi) ni darhol ajratish kerak.","ru":"Чтобы не опоздать на автобус, важно сразу различать «quarter to» (без 15) и «quarter past» (15 минут после)."},"learningObjective":{"uz":"O‘quvchi ertalabki «quarter to eight» iborasini 07:45 deb topadi va «half past two in the afternoon» ni 14:30 deb yozadi.","ru":"Ученик определяет «quarter to eight» утром как 07:45 и записывает «half past two in the afternoon» как 14:30."},"warmUp":{"uz":"«Sakkizga o‘n besh daqiqa kam» soat nechaga teng?","ru":"Сколько часов и минут означает «без пятнадцати восемь»?"},"vocabularyItems":[{"word":"quarter to","uz":"chorak (15 daqiqa) kam","ru":"без пятнадцати","ipa":"/ˈkwɔːtə tuː/"},{"word":"half past","uz":"yarim (30 daqiqa o‘tdi)","ru":"половина","ipa":"/hɑːf pɑːst/"},{"word":"o''clock","uz":"soat (aniq soat)","ru":"ровно (часов)","ipa":"/əˈklɒk/"}],"grammarNote":{"rule":"quarter to [N] = [N - 1]:45","simpleExplanationUz":"«Quarter to eight» — sakkizga hali 15 daqiqa bor, ya’ni 07:45 (08:45 emas!).","simpleExplanationRu":"«Quarter to eight» означает, что до 8 часов не хватает 15 минут — то есть 07:45.","structure":"leaves at quarter to [hour]","positiveExamples":["The morning bus leaves at quarter to eight (07:45)."],"negativeExamples":["08:15 is quarter past eight, and 19:45 is in the evening."],"questions":["When does the morning bus leave?"],"commonMistakes":["«quarter to eight» ni 08:45 yoki 08:15 deb tushunish."]},"pronunciationFocus":{"uz":"«o''clock» da urg‘u ikkinchi bo‘g‘inga tushadi: /əˈklɒk/.","ru":"В слове «o''clock» ударение падает на второй слог: /əˈklɒk/."},"examples":["The morning bus to the city library leaves at quarter to eight."],"guidedPractice":{"uz":"Soat rasmi va avtobus suhbatini solishtirib, 3 ta vaqt kartasini ko‘ring.","ru":"Сопоставьте рисунок часов, диалог и 3 карточки времени."},"independentPractice":{"uz":"Avtobus jo‘nash vaqtini tanlang va tushdan keyingi vaqtni yozing.","ru":"Выберите время отправления автобуса и запишите дневное время цифрами."},"listeningRef":"media_eng_a1_m3_bus_time","readingRef":"lesson_eng_a1_m3_ts_concept","speakingTask":{"uz":"«The bus leaves at quarter to eight.» gapini ayting.","ru":"Произнесите вслух: «The bus leaves at quarter to eight.»."},"writingTask":{"uz":"Ertalab uydan chiqadigan soatingizni inglizcha yozing.","ru":"Напишите по-английски, во сколько вы выходите утром."},"knowledgeCheck":"q_eng_a1_m3_time_mcq","finalQuiz":"q_eng_a1_m3_time_fill","feedbackRules":{"uz":"07:45 vs 08:15 vs 19:45 chalg‘ituvchilari aniq izohlanadi.","ru":"Подробно объясняются отвлекающие варианты 08:15 и 19:45."},"summaryAndRevision":{"uz":"3 ta vaqt kartochkasi SRS to‘plamiga qo‘shiladi.","ru":"3 карточки со временем добавляются в повторение SRS."}}'::jsonb, '[{"id":"lesson_eng_a1_m3_ts_concept","stepNumber":1,"type":"concept","title":"«Quarter to» va «Quarter past» farqi","titleRu":"Разница между «quarter to» и «quarter past»","content":"«past» — o‘tdi, «to» — qoldi/kam degani. Shu sababli «quarter to eight» — sakkizga 15 daqiqa kam, ya’ni 07:45 bo‘ladi. «morning» so‘zi esa kechki 19:45 emasligini ko‘rsatadi.","contentRu":"«past» означает «после часа», а «to» — «до часа». Поэтому «quarter to eight» (без четверти восемь) — это 07:45, а слово «morning» исключает вечернее 19:45.","highlightNotes":["quarter past eight -> 08:15","quarter to eight -> 07:45","half past two -> 02:30 / 14:30"]},{"id":"lesson_eng_a1_m3_ts_audio","stepNumber":2,"type":"audio_simulation","title":"Ertalabki avtobus e’loni","titleRu":"Объявление утреннего автобуса","content":"Yo‘lovchi va haydovchi suhbatini tinglang hamda devor soatiga qarang.","contentRu":"Прослушайте диалог пассажира и водителя и посмотрите на часы.","media":{"id":"media_eng_a1_m3_bus_time","kind":"audio","language":"en","source":"/lesson-media/english/a1/a1-m3-bus-time.wav","title":"Ertalabki avtobus jadvali e’loni","titleUz":"Ertalabki avtobus jadvali e’loni","titleRu":"Объявление расписания утреннего автобуса","transcript":"Passenger: Excuse me, when does the morning bus leave?\nDriver: The morning bus to the city library leaves at quarter to eight.","posterImage":"/lesson-media/english/a1/a1-m3-clock-times.png","posterAlt":"Ertalabki quyoshli deraza yonida strelkali devor soati","posterAltUz":"Ertalabki quyoshli deraza yonida strelkali devor soati","posterAltRu":"Настенные стрелочные часы рядом с окном на утреннем солнце","durationSeconds":6.499,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Passenger: Excuse me, when does the morning bus leave?\nDriver: The morning bus to the city library leaves at quarter to eight.","speakerName":"Passenger & Driver"}},{"id":"lesson_eng_a1_m3_ts_flashcards","stepNumber":3,"type":"flashcard","title":"Vaqt kartochkalari","titleRu":"Карточки времени","content":"Asosiy soat iboralarini tinglab eslab qoling.","contentRu":"Прослушайте и запомните выражения вре