tasviri","altRu":"Изображение круглого циферблата со стрелками в правом нижнем углу набора из шести предметов","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a1_m3_ts_quiz","stepNumber":4,"type":"interactive_question","title":"Avtobus vaqtini aniqlang","titleRu":"Определите время автобуса","content":"Tinglangan e’longa ko‘ra, avtobus soat nechada jo‘naydi?","contentRu":"Согласно прослушанному объявлению, во сколько отправляется автобус?","interactiveQuestion":{"id":"q_eng_a1_m3_time_mcq","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A1","topic":"Quarter to vs quarter past","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi ertalabki avtobus shahar kutubxonasiga soat nechada jo‘naydi?","textRu":"Во сколько утренний автобус из аудио отправляется к городской библиотеке?","options":["08:15","07:45","19:45","07:15"],"correctIndex":1,"mistakeFeedbackByOption":{"08:15":{"uz":"08:15 — «quarter past eight» (8 dan o‘tdi); e’londa esa «quarter to eight» (8 ga 15 kam) deyildi.","ru":"08:15 — это «quarter past eight», а в объявлении сказано «quarter to eight»."},"19:45":{"uz":"Suhbatda «morning bus» (ertalabki avtobus) deyilgan, shuning uchun kechki 19:45 emas.","ru":"В диалоге речь идёт об утреннем автобусе («morning bus»), а не о 19:45."},"07:15":{"uz":"07:15 — «quarter past seven»; e’londa esa sakkizga chorak kam (07:45) aytildi.","ru":"07:15 — это «quarter past seven», а прозвучало без четверти восемь (07:45)."}},"explanation":"«Morning bus» + «quarter to eight» — ertalabki soat 07:45 ni bildiradi.","explanationRu":"«Morning bus» + «quarter to eight» означает 07:45 утра.","wrongFeedback":"«to eight» (8 ga kam) va «morning» (ertalab) so‘zlariga e’tibor bering.","wrongFeedbackRu":"Обратите внимание на предлог «to» (до восьми) и слово «morning» (утро)."}}]'::jsonb, '{"id":"q_eng_a1_m3_time_fill","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A1","topic":"Digital time conversion","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"It is half past two in the afternoon. Digital time: ___","text":"Kunduzgi «half past two in the afternoon» vaqtini 24 soatlik raqamli ko‘rinishda (HH:MM) yozing.","textRu":"Запишите дневное время «half past two in the afternoon» в 24-часовом формате (ЧЧ:ММ).","options":[],"acceptedAnswers":["14:30"],"explanation":"«Half past two» — ikki yarim, «in the afternoon» esa kunduzgi vaqtni ko‘rsatadi: 14:30.","explanationRu":"«Half past two» — половина третьего, а «in the afternoon» указывает на день: 14:30.","wrongFeedback":"Kunduzgi 2 yarimni 24 soatlik ko‘rinishda ikki nuqta bilan (masalan, 13:30 kabi) yozing.","wrongFeedbackRu":"Запишите половину третьего дня в 24-часовом формате с двоеточием."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_u3_checkpoint', 'course_eng_01', 'skill_eng_vocab', 'vocabulary', 'checkpoint', 'A1', 'mod_eng_a1_m3', 'unit_eng_a1_u3', '3-modul yakuniy sinovida joylashuv predloglari va kechki vaqt jadvalini to‘g‘ri tahlil qiladi.', 'В итоговой проверке 3-го модуля исправляет ошибку с предлогом места и определяет вечернее время.', '["node_eng_a1_m3_time_schedule"]'::jsonb, '3-modul yakuni: Joylashuv va vaqt sinovi', 'Итог модуля 3: Предлоги места и время', 5, '3-modul bo‘yicha nazorat: yoshlar markazidagi stol o‘rni va kechki poyezd vaqtini aniqlash.', 'Проверка 3-го модуля: исправление ошибки в расположении мебели и определение времени поезда.', 'Bu modul sinovi 4-modulni ochadi; rasmiy CEFR sertifikati bermaydi.', 'Эта проверка открывает 4-й модуль и не выдаёт официальный сертификат CEFR.', '{"intro":{"uz":"Endi xona joylashuvi va soat vaqtini birgalikda yangi vaziyatda tekshiramiz.","ru":"Проверим предлоги места и время в новой ситуации."},"learningObjective":{"uz":"O‘quvchi ingliz tilidagi predlog o‘rnini tuzatadi va «half past ten in the evening» ni 22:30 deb topadi.","ru":"Ученик исправляет порядок слов с предлогом и переводит «half past ten in the evening» в 22:30."},"warmUp":{"uz":"«beside» so‘zi narsaning nomidan oldin keladimi yoki keyin?","ru":"Предлог «beside» ставится перед существительным или после него?"},"vocabularyItems":[{"word":"night train","uz":"tungi poyezd","ru":"ночной поезд","ipa":"/naɪt treɪn/"}],"grammarNote":{"rule":"Preposition BEFORE noun + Time disambiguation","simpleExplanationUz":"Ingliz tilida «window beside» deyilmaydi — «beside the window» deyiladi.","simpleExplanationRu":"По-английски предлог ставится перед существительным: «beside the window».","structure":"The study desk is beside the window.","positiveExamples":["The study desk is beside the window."],"negativeExamples":["The study desk is the window beside."],"questions":["Where is the study desk?"],"commonMistakes":["O‘zbekcha ko‘makchi tartibida predlogni otdan keyin qo‘yish."]},"pronunciationFocus":{"uz":"«evening» ikki bo‘g‘in bilan /ˈiːvnɪŋ/ deb o‘qiladi.","ru":"Слово «evening» произносится в два слога: /ˈiːvnɪŋ/."},"examples":["The study desk is beside the window.","The train leaves at 22:30."],"guidedPractice":{"uz":"Xatoli gapni o‘qib, predlog joyini to‘g‘rilang.","ru":"Прочтите предложение с ошибкой и выберите верное положение предлога."},"independentPractice":{"uz":"Kechki poyezd vaqtini aniqlang.","ru":"Определите время вечернего поезда."},"listeningRef":"media_eng_a1_m3_bus_time","readingRef":"lesson_eng_a1_u3_cp_concept","speakingTask":{"uz":"«The study desk is beside the window.» gapini ayting.","ru":"Прочтите вслух: «The study desk is beside the window.»."},"writingTask":{"uz":"22:30 vaqtini so‘z bilan yozing.","ru":"Запишите время 22:30 словами."},"knowledgeCheck":"q_eng_a1_u3_cp_main","finalQuiz":"q_eng_a1_u3_cp_reinf","feedbackRules":{"uz":"O‘zbekcha postpozitsiya tartibi va AM/PM farqi tushuntiriladi.","ru":"Объясняется порядок предлога и разница времени суток."},"summaryAndRevision":{"uz":"3-modul yakunlangach, 4-modul (O‘qish, yozish va A1 chiqish sinovi) ochiladi.","ru":"После проверки открывается 4-й модуль (Чтение, письмо и итоговый тест A1)."}}'::jsonb, '[{"id":"lesson_eng_a1_u3_cp_concept","stepNumber":1,"type":"concept","title":"3-modul yakuniy tekshiruvi","titleRu":"Итоговая проверка модуля 3","content":"Bu bosqichda predlog joylashuvi va kun vaqtini aniqlash bo‘yicha bilimingiz sinovdan o‘tkaziladi.","contentRu":"На этом этапе проверяется знание предлогов места и времени суток."},{"id":"lesson_eng_a1_u3_cp_quiz","stepNumber":2,"type":"interactive_question","title":"Xatoni tuzatish","titleRu":"Исправление ошибки","content":"O‘zbekcha so‘z tartibi aralashib ketgan gapning to‘g‘ri inglizcha shaklini tanlang.","contentRu":"Выберите правильный английский вариант предложения.","interactiveQuestion":{"id":"q_eng_a1_u3_cp_main","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Unit 3 checkpoint: Preposition position","difficulty":"easy","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"The study desk is the window beside.","text":"«The study desk is the window beside.» gapidagi xatoni tuzating:","textRu":"Исправьте ошибку в предложении «The study desk is the window beside.»:","options":["The study desk is beside the window.","The study desk beside is the window.","Beside is the study desk the window."],"correctIndex":0,"mistakeFeedbackByOption":{"The study desk beside is the window.":{"uz":"Predlog («beside») «is» fe’lidan oldinga emas, balki «the window» dan oldinga qo‘yiladi.","ru":"Предлог «beside» ставится после глагола «is», непосредственно перед «the window»."},"Beside is the study desk the window.":{"uz":"Bu gapda ega va fe’l tartibi buzilgan: avval ega («The study desk»), keyin «is beside the window» keladi.","ru":"Нарушен порядок SVO: сначала подлежащее «The study desk», затем «is beside the window»."}},"explanation":"Ingliz tilida «beside» predlogi otdan oldin keladi: «The study desk is beside the window.».","explanationRu":"В английском языке предлог ставится перед существительным: «The study desk is beside the window.».","wrongFeedback":"«beside» so‘zi «the window» dan oldin turishi kerakligini tekshiring.","wrongFeedbackRu":"Убедитесь, что предлог «beside» стоит прямо перед «the window»."}}]'::jsonb, '{"id":"q_eng_a1_u3_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A1","topic":"Unit 3 checkpoint: Evening train time","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"E’londa: «The train departs at half past ten in the evening.» — Poyezd soat nechada jo‘naydi?","textRu":"В объявлении сказано: «The train departs at half past ten in the evening.» — Во сколько отправляется поезд?","options":["22:30","10:30","21:30","22:15"],"correctIndex":0,"mistakeFeedbackByOption":{"10:30":{"uz":"«in the evening» (kechqurun) deyilgani uchun ertalabki 10:30 emas, kechki 22:30 to‘g‘ri!","ru":"Указание «in the evening» означает вечернее время — 22:30, а не 10:30 утра."},"21:30":{"uz":"«half past ten» — o‘n yarim (22:30), to‘qqiz yarim emas.","ru":"«half past ten» — половина одиннадцатого (22:30), а не 21:30."},"22:15":{"uz":"«half past» 30 daqiqani bildiradi; 15 daqiqa «quarter past» bo‘ladi.","ru":"«half past» означает 30 минут, а 15 минут — это «quarter past»."}},"explanation":"«Half past ten» (10:30) + «in the evening» (kechqurun) = 22:30.","explanationRu":"«Half past ten» + «in the evening» = 22:30.","wrongFeedback":"«half past ten» va «in the evening» iboralarini birga hisoblang.","wrongFeedbackRu":"Совместите «half past ten» и время суток «in the evening»."}'::jsonb, '{"id":"q_eng_a1_u3_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"Unit 3 checkpoint alternate retry","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Qayta sinov: «The green ball is between two white boxes.» — Yashil koptok qayerda turibdi?","textRu":"Повторная проверка: «The green ball is between two white boxes.» — Где находится зелёный мяч?","options":["Oq qutining orqa tomonida","Ikki oq qutining o‘rtasida","Oq qutining ichida"],"correctIndex":1,"mistakeFeedbackByOption":{"Oq qutining orqa tomonida":{"uz":"«orqa tomonida» — «behind» bo‘ladi; «between» esa ikki narsa o‘rtasini bildiradi.","ru":"«Позади» — это «behind», а «between» означает «между двумя предметами»."},"Oq qutining ichida":{"uz":"«ichida» — «inside» yoki «in»; «between» esa ikki narsa orasida.","ru":"«Внутри» — это «in/inside», а «between» — «между»."}},"explanation":"«between two white boxes» — ikkita oq quti orasida degan ma’noni anglatadi.","explanationRu":"«between two white boxes» означает «между двумя белыми коробками».","wrongFeedback":"«between» predlogining aniq ma’nosini eslang.","wrongFeedbackRu":"Вспомните точное значение предлога «between»."}'::jsonb, true, true, false),
  ('lesson_eng_reading_01', 'course_eng_01', 'skill_eng_reading', 'reading', 'reading', 'A1', 'mod_eng_a1_m4', 'unit_eng_a1_u4', 'Qisqa maktab matnidan asosiy g‘oyani hamda aniq dalilni (kun va harakat) ajratib oladi.', 'Выделяет главную мысль и точные факты (день и действие) в коротком школьном тексте.', '["node_eng_list"]'::jsonb, 'Asosiy g‘oya va dalil', 'Главная мысль и факты в тексте', 8, 'Asosiy g‘oya butun matn nima haqida ekanini qisqacha aytadi. Sana, miqdor yoki alohida misol g‘oyani tasdiqlovchi dalil bo‘lishi mumkin.', 'Главная мысль кратко передаёт суть текста, а даты и примеры служат подтверждающими фактами.', 'Ichki modul sinovlari va A1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Qisqa inglizcha matnni o‘qiganda barcha gaplarni birlashtiruvchi asosiy g‘oya va aniq faktlarni ajrata olish muhim.","ru":"При чтении короткого текста важно отличать общую главную мысль от конкретных фактов."},"learningObjective":{"uz":"O‘quvchi «repair club» haqidagi matndan asosiy g‘oya va juma kungi dalilni topadi.","ru":"Ученик находит главную мысль и факт о пятнице в тексте про «repair club»."},"warmUp":{"uz":"«fix» (tuzatmoq) va «reduce waste» (chiqindini kamaytirmoq) iboralarini bog‘lab ko‘ring.","ru":"Свяжите понятия «чинить» (fix) и «сокращать отходы» (reduce waste)."},"vocabularyItems":[{"word":"repair club","uz":"ta’mirlash to‘garagi","ru":"клуб ремонта","ipa":"/rɪˈpeə klʌb/"},{"word":"reduce waste","uz":"chiqindini kamaytirmoq","ru":"сокращать отходы","ipa":"/rɪˈdjuːs weɪst/"}],"grammarNote":{"rule":"Main Idea (all sentences combined) vs Specific Detail (On Fridays...)","simpleExplanationUz":"Asosiy g‘oya barcha gaplarni umumlashtiradi, dalil esa «qachon?», «nima?» degan aniq savolga javob beradi.","simpleExplanationRu":"Главная мысль обобщает весь абзац, а факт отвечает на конкретный вопрос (когда? что?).","structure":"On + [Day(s)] + Subject + Verb","positiveExamples":["On Fridays students fix broken lamps.","The club helps reduce waste."],"negativeExamples":["The club is open every day. (contradicts ''On Fridays'')"],"questions":["What is the main idea?","Which detail matches the text?"],"commonMistakes":["Matnda yo‘q kun yoki narx haqidagi taxminiy variantni tanlash."]},"pronunciationFocus":{"uz":"«reuse» /ˌriːˈjuːz/ so‘zidagi «re-» qayta bajarishni bildiradi.","ru":"Приставка «re-» в «reuse» /ˌriːˈjuːz/ означает повторное действие."},"examples":["The school opened a repair club. On Fridays students fix broken lamps and learn to reuse old parts. The club helps reduce waste."],"guidedPractice":{"uz":"Misol matnidagi 3 ta gapni o‘qing va umumiy foydani toping.","ru":"Прочитайте три предложения текста и определите его цель."},"independentPractice":{"uz":"Asosiy g‘oya va aniq dalil savollarini matnga tayangan holda yeching.","ru":"Решите задания на главную мысль и факт по тексту."},"listeningRef":"media_eng_listening_lecture_time","readingRef":"lesson_eng_reading_01_example","speakingTask":{"uz":"Matn mazmunini bir gap bilan o‘z so‘zingizda ayting.","ru":"Перескажите суть текста одним предложением."},"writingTask":{"uz":"Maktab to‘garagi haqida 1 ta jumla yozing.","ru":"Напишите 1 предложение о школьном кружке."},"knowledgeCheck":"q_live_eng_reading_01_quiz","finalQuiz":"q_live_eng_reading_01_practice","feedbackRules":{"uz":"Har bir noto‘g‘ri variant matndagi dalilga zid ekani ko‘rsatiladi.","ru":"Объясняется, почему каждый неверный вариант противоречит тексту."},"summaryAndRevision":{"uz":"Keyingi darsda o‘zingiz haqingizda qisqa xabar yozasiz.","ru":"В следующем уроке вы напишете короткое сообщение о себе."}}'::jsonb, '[{"id":"lesson_eng_reading_01_concept","stepNumber":1,"type":"concept","title":"Qoida","titleRu":"Правило чтения","content":"Asosiy g‘oya butun matn nima haqida ekanini qisqacha aytadi. Sana, miqdor yoki alohida misol g‘oyani tasdiqlovchi dalil bo‘lishi mumkin.","contentRu":"Главная мысль кратко передаёт тему всего текста, а дата, число или пример подтверждают её как факт."},{"id":"lesson_eng_reading_01_example","stepNumber":2,"type":"visual_example","title":"Ishlangan misol","titleRu":"Разобранный пример","content":"«The school opened a repair club. On Fridays students fix broken lamps and learn to reuse old parts. The club helps reduce waste.» Matnning mavzusi ta’mirlash to‘garagi orqali chiqindini kamaytirish.","contentRu":"«The school opened a repair club. On Fridays students fix broken lamps and learn to reuse old parts. The club helps reduce waste.» Тема текста — сокращение отходов через школьный клуб ремонта."},{"id":"lesson_eng_reading_01_test","stepNumber":3,"type":"interactive_question","title":"Bilimingizni tekshiring","titleRu":"Проверьте понимание","content":"Variantlardan birini tanlang va javobingizni tekshiring.","contentRu":"Выберите верный вариант на основе текста.","interactiveQuestion":{"id":"q_live_eng_reading_01_quiz","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"Reading main idea","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"The school opened a repair club. On Fridays students fix broken lamps and learn to reuse old parts. The club helps reduce waste.","text":"Matnning asosiy g‘oyasi qaysi?","textRu":"Какова главная мысль текста?","options":["Chiroqlar qimmat turadi","To‘garak buyumlarni ta’mirlab, chiqindini kamaytiradi","Juma eng qisqa kun","Maktab eski buyumlarni sotadi"],"correctIndex":1,"mistakeFeedbackByOption":{"Chiroqlar qimmat turadi":{"uz":"Matnda chiroqlarning narxi haqida hech narsa yozilmagan.","ru":"В тексте ничего не говорится о стоимости ламп."},"Juma eng qisqa kun":{"uz":"Juma kuni to‘garak o‘tilishi aytilgan, kunning qisqaligi haqida gap yo‘q.","ru":"Пятница указана как день работы клуба, а не как самый короткий день."},"Maktab eski buyumlarni sotadi":{"uz":"Matnda buyumlar sotilishi emas, ta’mirlanib qayta ishlatilishi («reuse») yozilgan.","ru":"В тексте говорится о ремонте и повторном использовании, а не о продаже."}},"explanation":"Uchala jumla ta’mirlash to‘garagining faoliyati va uning chiqindini kamaytirish foydasini bog‘laydi.","explanationRu":"Все три предложения объединяются темой работы клуба ремонта и снижения отходов.","wrongFeedback":"Matndagi «fix», «reuse» va «reduce waste» kalit iboralariga tayanib javob tanlang.","wrongFeedbackRu":"Опирайтесь на ключевые слова текста: «fix», «reuse» и «reduce waste»."}}]'::jsonb, '{"id":"q_live_eng_reading_01_practice","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"Reading specific detail","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"The school opened a repair club. On Fridays students fix broken lamps and learn to reuse old parts. The club helps reduce waste.","text":"Qaysi jumla matndagi aniq dalilga mos?","textRu":"Какое утверждение соответствует факту из текста?","options":["To‘garak har kuni ochiq","O‘quvchilar juma kuni chiroqlarni tuzatadi","Maktab faqat yangi qismlar sotib oladi","To‘garak may oyida ochilgan"],"correctIndex":1,"mistakeFeedbackByOption":{"To‘garak har kuni ochiq":{"uz":"Matnda faqat «On Fridays» (juma kunlari) haqida aytilgan, har kuni emas.","ru":"В тексте указаны только пятницы («On Fridays»), а не каждый день."},"Maktab faqat yangi qismlar sotib oladi":{"uz":"Aksincha, o‘quvchilar eski qismlarni qayta ishlatishni («reuse old parts») o‘rganadi.","ru":"Наоборот, ученики учатся повторно использовать старые детали («reuse old parts»)."},"To‘garak may oyida ochilgan":{"uz":"Matnda may oyi haqida ma’lumot berilmagan.","ru":"Май месяц в тексте не упоминается."}},"explanation":"Matnda «On Fridays students fix broken lamps» (juma kunlari chiroqlar tuzatilishi) aniq aytilgan.","explanationRu":"В тексте прямо сказано: «On Fridays students fix broken lamps».","wrongFeedback":"Matndan aynan qaysi kun va qanday ish bajarilishi yozilganini toping.","wrongFeedbackRu":"Найдите в тексте точный день недели и действие учеников."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_m4_writing', 'course_eng_01', 'skill_eng_reading', 'writing', 'writing', 'A1', 'mod_eng_a1_m4', 'unit_eng_a1_u4', 'O‘z xonasi va kechki o‘qish vaqti haqida «to be», joylashuv predlogi va soat bilan 3–4 gapli xabar yozadi.', 'Пишет короткое сообщение (3–4 предложения) о своей комнате и времени занятий, оценивая себя по рубрике.', '["node_eng_a1_u3_checkpoint"]'::jsonb, 'Writing: Xonam va o‘qish vaqtim haqida qisqa xabar', 'Writing: Короткое сообщение о комнате и времени занятий', 7, 'A1 da o‘rgangan barcha mavzularni birlashtirib, do‘stingizga xonangiz va o‘qish vaqtingiz haqida 3–4 gapli xabar yozasiz.', 'Объединив изученные темы A1, вы напишете короткое письмо другу о комнате и учёбе и проверите его по критериям.', 'Bu mustaqil yozma mashq va o‘zini baholash vositasidir; rasmiy CEFR sertifikati bermaydi.', 'Это самостоятельное письменное задание и самооценка; оно не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"Yozishda barcha bilimlaringiz — «I am», «beside/behind», «every evening» va soat birlashadi.","ru":"На письме соединяются изученные конструкции: «I am», предлоги места и точное время."},"learningObjective":{"uz":"O‘quvchi 3–4 bog‘langan gapdan iborat xabar yozadi va 4 mezon bo‘yicha tekshiradi.","ru":"Ученик пишет сообщение из 3–4 связанных фраз и проверяет его по 4 критериям."},"warmUp":{"uz":"Xonangizda yozuv stolingiz deraza yoki chiroqqa nisbatan qayerda turadi?","ru":"Где в вашей комнате стоит письменный стол?"},"vocabularyItems":[{"word":"study desk","uz":"o‘quv stoli","ru":"письменный стол","ipa":"/ˈstʌdi desk/"},{"word":"window","uz":"deraza","ru":"окно","ipa":"/ˈwɪndəʊ/"}],"grammarNote":{"rule":"Short Paragraph: Greeting + Room Position + Study Time","simpleExplanationUz":"Har bir gapni bosh harf bilan boshlab, nuqta bilan tugating; fe’l va predloglarni to‘g‘ri joylang.","simpleExplanationRu":"Начинайте каждое предложение с заглавной буквы, ставьте точку и проверяйте глаголы с предлогами.","structure":"I am [Name]. My desk is [preposition] the window. I study at [time].","positiveExamples":["My desk is beside the window. I do my homework at six o''clock."],"negativeExamples":["my desk beside window. i study 6 (missing verb, preposition/article, capitalization)"],"questions":["Where is your desk and when do you study?"],"commonMistakes":["«is» fe’lini tushirib qoldirish yoki vaqt oldidan «at» qo‘ymaslik."]},"pronunciationFocus":{"uz":"«window» /ˈwɪndəʊ/ so‘zida oxiridagi «w» alohida talaffuz qilinmaydi.","ru":"В слове «window» /ˈwɪndəʊ/ конечная «w» не произносится как отдельный звук."},"examples":["Hi Ben! I am in my room now. My desk is beside the window, and my lamp is on the desk. I do my homework at seven o''clock in the evening."],"guidedPractice":{"uz":"Kechki o‘qish burchagi rasmini va namuna xabarni o‘rganing.","ru":"Рассмотрите иллюстрацию рабочего стола и изучите образец сообщения."},"independentPractice":{"uz":"O‘z xabaringizni yozing va so‘zlardan to‘g‘ri gap tuzing.","ru":"Напишите своё сообщение и выполните задание на порядок слов."},"listeningRef":null,"readingRef":"lesson_eng_a1_m4_wr_visual","speakingTask":{"uz":"Yozgan xabaringizni ovoz chiqarib o‘qib bering.","ru":"Прочитайте написанное сообщение вслух."},"writingTask":{"uz":"3–4 gapdan iborat shaxsiy xabar yozish.","ru":"Написание личного сообщения из 3–4 предложений."},"knowledgeCheck":"q_eng_a1_m4_writing_prompt","finalQuiz":"q_eng_a1_m4_writing_order","feedbackRules":{"uz":"4 mezonli rubrika bilan o‘zini baholash ta’minlanadi.","ru":"Предусмотрена самооценка по 4 критериям."},"summaryAndRevision":{"uz":"4-modul sinovi va A1 chiqish imtihoniga tayyor.","ru":"Готово к проверке 4-го модуля и итоговому тесту A1."}}'::jsonb, '[{"id":"lesson_eng_a1_m4_wr_concept","stepNumber":1,"type":"concept","title":"Qisqa xabar tuzilishi","titleRu":"Структура короткого сообщения","content":"3–4 gapli xabar yozish uchun reja tuzing: 1) Salomlashing, 2) Stol yoki buyum joylashuvini «beside/behind» bilan ayting, 3) Soat nechada o‘qishingizni «at ... o''clock» bilan yozing.","contentRu":"План сообщения из 3–4 фраз: 1) Приветствие, 2) Место стола/вещей с «beside/behind», 3) Время занятий с предлогом «at»."},{"id":"lesson_eng_a1_m4_wr_visual","stepNumber":2,"type":"visual_example","title":"Namuna rasm va matn","titleRu":"Иллюстрация и образец","content":"Rasmga qarang: kechki o‘qish stolida chiroq, daftar va choy finjoni bor. Namuna: «My desk is beside the window. I study English at seven o''clock in the evening.»","contentRu":"Посмотрите на рисунок вечернего рабочего стола. Пример: «My desk is beside the window. I study English at seven o''clock in the evening.»","media":{"id":"media_eng_a1_m4_home_study_img","kind":"image","language":"en","source":"/lesson-media/english/a1/a1-m4-home-study.png","title":"Uydagi o‘qish burchagi","titleUz":"Uydagi o‘qish burchagi","titleRu":"Учебный уголок дома","alt":"Kechki deraza yonidagi yozuv stolida chiroq, ochiq kundalik daftar, ruchka va choy finjoni","altUz":"Kechki deraza yonidagi yozuv stolida chiroq, ochiq kundalik daftar, ruchka va choy finjoni","altRu":"Вечерний письменный стол у окна с лампой, открытой тетрадью, ручкой и чашкой чая","reviewStatus":"approved"}},{"id":"lesson_eng_a1_m4_wr_prompt","stepNumber":3,"type":"interactive_question","title":"Writing: Mustaqil yozish va o‘zini baholash","titleRu":"Writing: Самостоятельное письмо и самооценка","content":"Do‘stingizga xonangiz va o‘qish vaqtingiz haqida 3–4 gap yozing, so‘ng namuna bilan solishtiring.","contentRu":"Напишите другу 3–4 предложения о своей комнате и времени учёбы, затем сверьте по рубрике.","interactiveQuestion":{"id":"q_eng_a1_m4_writing_prompt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"writing","cefrLevel":"A1","topic":"Short message writing","difficulty":"medium","questionType":"writing_prompt","evaluationMode":"self_assessed","text":"Do‘stingizga xonangizdagi buyum joylashuvi va dars tayyorlash vaqtingiz haqida 3–4 ta inglizcha gap yozing.","textRu":"Напишите другу 3–4 предложения на английском о расположении вещей в комнате и времени подготовки к урокам.","options":[],"sampleResponse":"Hi Ben! I am in my study room. My desk is beside the window, and my backpack is behind the chair. I do my homework at seven o''clock in the evening.","rubricCriteria":[{"id":"crit_w_greet","labelUz":"Salomlashish va «I am» / «is» to‘g‘ri ishlatildi","labelRu":"Использовано приветствие и верная форма «I am» / «is»"},{"id":"crit_w_prep","labelUz":"Kamida bitta joylashuv predlogi (beside / between / behind) qatnashdi","labelRu":"Использован хотя бы один предлог места (beside / between / behind)"},{"id":"crit_w_time","labelUz":"O‘qish vaqti «at ...» bilan aniq yozildi","labelRu":"Время занятий указано с предлогом «at ...»"},{"id":"crit_w_punct","labelUz":"Gaplar bosh harf va nuqta bilan yakunlandi","labelRu":"Предложения оформлены с заглавной буквы и точкой"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil yozma mashq): bu vazifa rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельное письмо): задание не даёт официального сертификата CEFR.","explanation":"Namunadagi xabar salomlashish, joylashuv predlogi («beside», «behind») va kechki soatni («at seven o''clock») aniq bog‘laydi.","explanationRu":"Образец объединяет приветствие, предлоги места («beside», «behind») и точное вечернее время.","wrongFeedback":"Gaplaringizda «is», joylashuv predlogi va «at» bilan soat borligini qayta tekshiring.","wrongFeedbackRu":"Проверьте наличие глагола «is», предлога места и времени с «at»."}}]'::jsonb, '{"id":"q_eng_a1_m4_writing_order","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"writing","cefrLevel":"A1","topic":"Sentence ordering with preposition","difficulty":"easy","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Mening stolim deraza yonida» gapini to‘g‘ri tartibda tuzing:","textRu":"Составьте предложение «Мой стол находится рядом с окном» в правильном порядке:","options":[],"orderedTokens":["My","desk","is","beside","the","window."],"acceptedAnswers":["My desk is beside the window."],"explanation":"To‘g‘ri tartib: My desk + is + beside + the window.","explanationRu":"Правильный порядок: My desk + is + beside + the window.","wrongFeedback":"Ega («My desk») dan keyin «is» va predlog («beside the window.») kelishini eslang.","wrongFeedbackRu":"После подлежащего «My desk» поставьте «is» и затем «beside the window.»."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a1_u4_checkpoint', 'course_eng_01', 'skill_eng_reading', 'reading', 'checkpoint', 'A1', 'mod_eng_a1_m4', 'unit_eng_a1_u4', '4-modul yakuniy sinovida yangi kutubxona e’lonini tushunib, A1 chiqish sinovini ochadi.', 'В итоговой проверке 4-го модуля анализирует новое библиотечное объявление и открывает выходной тест A1.', '["node_eng_a1_m4_writing"]'::jsonb, '4-modul yakuni: O‘qish va muloqot sinovi', 'Итог модуля 4: Проверка чтения и общения', 5, 'Samarqand yoshlar kutubxonasining shanba kungi e’loni asosida tushunish va javob berish sinovi.', 'Проверка понимания субботнего объявления молодёжной библиотеки в Самарканде.', 'Bu modul sinovi A1 chiqish testini ochadi; rasmiy CEFR sertifikati bermaydi.', 'Эта проверка открывает итоговый тест A1 и не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"4-modulda o‘rgangan matn tahlili va yozma muloqot ko‘nikmalaringizni yangi e’londa sinang.","ru":"Примените навыки чтения и общения из 4-го модуля к новому объявлению."},"learningObjective":{"uz":"O‘quvchi kutubxona e’lonidan aniq kun, vaqt va qatnashish shartini topadi.","ru":"Ученик находит день, время и правило участия в объявлении библиотеки."},"warmUp":{"uz":"E’londa «free» (bepul) va «Saturday morning» iboralarini izlang.","ru":"Найдите в объявлении слова «free» и «Saturday morning»."},"vocabularyItems":[{"word":"free","uz":"bepul","ru":"бесплатно","ipa":"/friː/"},{"word":"bring","uz":"olib kelmoq","ru":"приносить","ipa":"/brɪŋ/"}],"grammarNote":{"rule":"Scanning notices for day, time, and required item","simpleExplanationUz":"E’lonlarda shart va vaqtni aniq ajratish uchun «at» va «bring» so‘zlariga qarang.","simpleExplanationRu":"В объявлениях ищите время после «at» и требования после глагола «bring».","structure":"Starts at [time]. Please bring [item].","positiveExamples":["The club meets at ten o''clock on Saturday morning."],"negativeExamples":["Tickets cost ten dollars. (contradicts ''free'')"],"questions":["What should visitors bring?"],"commonMistakes":["Matnda yo‘q narx yoki boshqa kunni tanlash."]},"pronunciationFocus":{"uz":"«Saturday» so‘zida urg‘u birinchi bo‘g‘inda: /ˈsætədeɪ/.","ru":"В слове «Saturday» ударение падает на первый слог: /ˈsætədeɪ/."},"examples":["Samarkand Youth Library: Our English reading club meets on Saturday morning at ten o''clock. Entry is free. Please bring one notebook and a pen."],"guidedPractice":{"uz":"E’lon matnini diqqat bilan o‘qib, savollarga javob bering.","ru":"Прочтите объявление и ответьте на вопросы."},"independentPractice":{"uz":"Asosiy savol va mustahkamlash suhbatini yakunlang.","ru":"Пройдите основное задание и диалог закрепления."},"listeningRef":"media_eng_listening_lecture_time","readingRef":"lesson_eng_a1_u4_cp_concept","speakingTask":{"uz":"Do‘stingizni shanba kungi to‘garakka taklif qilib 1 gap ayting.","ru":"Пригласите друга в субботний клуб одной фразой."},"writingTask":{"uz":"To‘garakka nima olib borishingizni yozing.","ru":"Напишите, что вы возьмёте с собой в клуб."},"knowledgeCheck":"q_eng_a1_u4_cp_main","finalQuiz":"q_eng_a1_u4_cp_reinf","feedbackRules":{"uz":"Har bir chalg‘ituvchi javob e’lon matni bilan solishtiriladi.","ru":"Каждый отвлекающий вариант сопоставляется с фактами из объявления."},"summaryAndRevision":{"uz":"A1 yakuniy chiqish sinovi ochiladi.","ru":"Открывается итоговый экзамен уровня A1."}}'::jsonb, '[{"id":"lesson_eng_a1_u4_cp_concept","stepNumber":1,"type":"concept","title":"4-modul yakuniy tekshiruvi","titleRu":"Итоговая проверка модуля 4","content":"Samarqand yoshlar kutubxonasi e’lonini diqqat bilan o‘qing va berilgan savollarga matndagi dalillar asosida javob bering.","contentRu":"Внимательно прочтите объявление молодёжной библиотеки и ответьте на вопросы строго по тексту."},{"id":"lesson_eng_a1_u4_cp_quiz","stepNumber":2,"type":"interactive_question","title":"E’lon tahlili","titleRu":"Анализ объявления","content":"Matndagi aniq ma’lumotga mos javobni tanlang.","contentRu":"Выберите вариант, точно соответствующий тексту объявления.","interactiveQuestion":{"id":"q_eng_a1_u4_cp_main","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"Unit 4 checkpoint: Library notice","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Samarkand Youth Library: Our English reading club meets on Saturday morning at ten o''clock. Entry is free. Please bring one notebook and a pen.","text":"E’longa ko‘ra, shanba kungi o‘qish to‘garagi haqida qaysi ma’lumot to‘g‘ri?","textRu":"Какой факт о субботнем клубе чтения верен согласно объявлению?","options":["Kirish bepul va daftar bilan ruchka olib kelish kerak","To‘garak kechki soat o‘nda boshlanadi","Kirish uchun chipta sotib olish shart","Faqat yakshanba kunlari o‘tkaziladi"],"correctIndex":0,"mistakeFeedbackByOption":{"To‘garak kechki soat o‘nda boshlanadi":{"uz":"Matnda «Saturday morning at ten o''clock» (ertalab soat 10:00) deyilgan, kechqurun emas.","ru":"В тексте сказано «Saturday morning at ten o''clock» (10:00 утра), а не вечером."},"Kirish uchun chipta sotib olish shart":{"uz":"E’londa «Entry is free» (kirish bepul) deb aniq ko‘rsatilgan.","ru":"В объявлении прямо написано «Entry is free» (вход бесплатный)."},"Faqat yakshanba kunlari o‘tkaziladi":{"uz":"«Saturday» — shanba kuni; yakshanba esa «Sunday».","ru":"«Saturday» — это суббота, а воскресенье по-английски «Sunday»."}},"explanation":"Matnda «Entry is free. Please bring one notebook and a pen.» deb aniq yozilgan.","explanationRu":"В объявлении указано: «Entry is free. Please bring one notebook and a pen.».","wrongFeedback":"E’londagi «morning», «free» va «bring» so‘zlariga qarab tekshiring.","wrongFeedbackRu":"Проверьте в тексте слова «morning», «free» и «bring»."}}]'::jsonb, '{"id":"q_eng_a1_u4_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"Unit 4 checkpoint: Club dialogue","difficulty":"easy","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Kutubxonachi: «Good morning! Are you here for the Saturday reading club?»","O‘quvchi: «___»"],"text":"O‘quvchi kutubxonachiga qanday mos javob beradi?","textRu":"Как ученик ответит библиотекарю?","options":["No, I is not a library.","Good night! The club is closed.","Yes, I am! Here is my notebook."],"correctIndex":2,"mistakeFeedbackByOption":{"No, I is not a library.":{"uz":"«I» bilan «is» ishlatilmaydi, shuningdek ma’no jihatidan ham mos emas.","ru":"С местоимением «I» нельзя использовать «is», да и по смыслу ответ не подходит."},"Good night! The club is closed.":{"uz":"Kutubxonachi ertalab «Good morning!» dedi; «Good night» esa tunda xayrlashish.","ru":"Библиотекарь поздоровался утром («Good morning!»), поэтому «Good night» неуместно."}},"explanation":"«Are you here...?» savoliga qisqa tasdiq javobi — «Yes, I am!».","explanationRu":"Краткий утвердительный ответ на вопрос «Are you...?» — «Yes, I am!».","wrongFeedback":"«Are you...?» savoliga «I am» bilan qisqa tasdiq javobini tanlang.","wrongFeedbackRu":"Выберите краткий положительный ответ с «I am» на вопрос «Are you...?»."}'::jsonb, '{"id":"q_eng_a1_u4_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"Unit 4 checkpoint alternate retry","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Community Center Notice: Table tennis practice is on Tuesday at four o''clock in Room 3. Bring sports shoes.","text":"Qayta sinov: E’longa ko‘ra, stol tennisi mashg‘uloti qayerda va soat nechada bo‘ladi?","textRu":"Повторная проверка: где и во сколько проходит тренировка по настольному теннису?","options":["Payshanba kuni soat 3 da, 4-xonada","Seshanba kuni soat 4 da, 3-xonada","Seshanba kuni soat 4 da, hovlida"],"correctIndex":1,"mistakeFeedbackByOption":{"Payshanba kuni soat 3 da, 4-xonada":{"uz":"«Tuesday» — seshanba (payshanba «Thursday»), vaqt esa «four o''clock», xona — «Room 3».","ru":"«Tuesday» — вторник (а не четверг), время — 4 часа, кабинет — 3."},"Seshanba kuni soat 4 da, hovlida":{"uz":"E’londa hovli emas, «Room 3» (3-xona) ko‘rsatilgan.","ru":"В объявлении указана комната 3 («Room 3»), а не двор."}},"explanation":"«Tuesday» (seshanba), «four o''clock» (soat 4) va «Room 3» (3-xona) to‘liq mos keladi.","explanationRu":"«Tuesday» (вторник), «four o''clock» (4 часа) и «Room 3» (комната 3) точно соответствуют тексту.","wrongFeedback":"Matndagi kun (Tuesday), soat (four) va xona raqamini (Room 3) tekshiring.","wrongFeedbackRu":"Сверьте день недели (Tuesday), время (four) и номер комнаты (Room 3)."}'::jsonb, true, true, false),
  ('lesson_eng_a1_exit', 'course_eng_01', 'skill_eng_reading', 'integrated', 'exit_assessment', 'A1', 'mod_eng_a1_m4', 'unit_eng_a1_u4', 'A1 yakuniy integratsiyalashgan sinovida tinglash, to‘ldirish, gap tuzish va o‘qish vazifalarini kamida 70% bilan bajaradi.', 'Проходит итоговую комплексную проверку уровня A1 (аудирование, заполнение, порядок слов, чтение) с результатом от 70%.', '["node_eng_a1_u4_checkpoint"]'::jsonb, 'A1 Yakuniy sinov: Kafedagi buyurtma va kundalik muloqot', 'Итоговый тест A1: Заказ в кафе и чтение', 10, 'A1 darajasini yakunlovchi ko‘p bosqichli sinov: tinglash, grammatik bo‘shliqni to‘ldirish, gap tuzish va matn tahlili.', 'Комплексная итоговая проверка уровня A1: аудирование, подстановка формы, порядок слов и чтение.', 'Ushbu A1 yakuniy sinovi BilimYo‘l ichki o‘quv darajasini baholaydi va A2 moduliga o‘tishni ochadi; rasmiy xalqaro CEFR sertifikati bermaydi.', 'Итоговый тест A1 оценивает внутренний учебный прогресс и открывает уровень A2; он не является официальным сертификатом CEFR.', '{"intro":{"uz":"A1 darajasidagi barcha 4 modulda o‘rgangan ko‘nikmalaringizni kafedagi real buyurtma va e’lon vaziyatida sinab ko‘rasiz.","ru":"В итоговом тесте A1 вы примените навыки всех 4 модулей в ситуации заказа в кафе и чтения."},"learningObjective":{"uz":"O‘quvchi 4 xil topshiriqni (listening, fill_blank, sentence_order, reading) kamida 70% natija bilan bajaradi.","ru":"Ученик выполняет 4 разноформатных задания с результатом не ниже 70%."},"warmUp":{"uz":"Kafeda buyurtma berish va yopilish soatini so‘rash iboralarini eslang.","ru":"Вспомните, как сделать заказ и спросить время закрытия кафе."},"vocabularyItems":[{"word":"green tea","uz":"ko‘k choy","ru":"зелёный чай","ipa":"/ɡriːn tiː/"},{"word":"cheese sandwich","uz":"pishloqli sendvich","ru":"сэндвич с сыром","ipa":"/tʃiːz ˈsænwɪtʃ/"}],"grammarNote":{"rule":"Integrated A1: Present Simple + Time + Prepositions","simpleExplanationUz":"Yakuniy sinovda «closes at half past eight in the evening» (20:30), «opens» (3-shaxs birlik) va SVO tartibi tekshiriladi.","simpleExplanationRu":"В тесте проверяются время закрытия (20:30), форма 3-го лица «opens» и порядок слов SVO.","structure":"Subject + Verb(+s) + Object + at [time]","positiveExamples":["We close at half past eight in the evening.","The cafe opens at nine o''clock."],"negativeExamples":["The cafe close at 08:30 AM."],"questions":["Is the cafe open until eight o''clock?"],"commonMistakes":["Kechki 20:30 o‘rniga ertalabki 08:30 ni belgilash."]},"pronunciationFocus":{"uz":"«sandwich» so‘zida o‘rtadagi «d» odatda o‘qilmaydi: /ˈsænwɪtʃ/.","ru":"В слове «sandwich» буква «d» в беглой речи выпадает: /ˈsænwɪtʃ/."},"examples":["Waiter: Yes, we close at half past eight in the evening."],"guidedPractice":{"uz":"Avval kafedagi audioni tinglang, so‘ng bosqichma-bosqich 4 ta sinov topshirig‘ini bajaring.","ru":"Сначала прослушайте диалог в кафе, затем выполните 4 задания."},"independentPractice":{"uz":"Har bir bosqichdagi savollarga mustaqil javob bering.","ru":"Самостоятельно ответьте на задания каждого этапа."},"listeningRef":"media_eng_a1_exit_cafe_order","readingRef":"lesson_eng_a1_exit_step_5","speakingTask":{"uz":"Kafeda choy va sendvich buyurtma qilishni ovoz chiqarib mashq qiling.","ru":"Потренируйтесь вслух заказывать чай и сэндвич в кафе."},"writingTask":{"uz":"«A cup of green tea, please.» iborasini yozing.","ru":"Запишите фразу заказа: «A cup of green tea, please.»."},"knowledgeCheck":"q_eng_a1_exit_listen","finalQuiz":"q_eng_a1_exit_read","feedbackRules":{"uz":"Har bir savolda xato sababi va o‘rinli misol beriladi.","ru":"Каждый вопрос содержит разбор ошибок и объяснение."},"summaryAndRevision":{"uz":"A1 chiqish sinovidan muvaffaqiyatli o‘tish A2 darajasini ochish huquqini beradi.","ru":"Успешная сдача итогового теста A1 открывает переход на уровень A2."}}'::jsonb, '[{"id":"lesson_eng_a1_exit_step_1","stepNumber":1,"type":"audio_simulation","title":"1. Tinglash: Kafedagi buyurtma","titleRu":"1. Аудирование: Заказ в кафе","content":"Laylo va ofitsiant o‘rtasidagi suhbatni tinglang. Buyurtma va yopilish vaqtiga diqqat qiling.","contentRu":"Прослушайте диалог Лейлы и официанта. Обратите внимание на заказ и время закрытия.","media":{"id":"media_eng_a1_exit_cafe_order","kind":"audio","language":"en","source":"/lesson-media/english/a1/a1-exit-cafe-order.wav","title":"A1 yakuniy tinglash: Kafedagi buyurtma","titleUz":"A1 yakuniy tinglash: Kafedagi buyurtma","titleRu":"Итоговое аудирование A1: Заказ в кафе","transcript":"Waiter: Good afternoon! What would you like?\nLaylo: Hello! A cup of green tea and one cheese sandwich, please. Is the cafe open until eight o''clock?\nWaiter: Yes, we close at half past eight in the evening.","posterImage":"/lesson-media/english/a1/a1-m4-home-study.png","posterAlt":"Stol ustida choy finjoni, ochiq daftar va qalam tasvirlangan","posterAltUz":"Stol ustida choy finjoni, ochiq daftar va qalam tasvirlangan","posterAltRu":"На столе изображены чашка чая, открытая тетрадь и ручка","durationSeconds":14.157,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Waiter: Good afternoon! What would you like?\nLaylo: Hello! A cup of green tea and one cheese sandwich, please. Is the cafe open until eight o''clock?\nWaiter: Yes, we close at half past eight in the evening.","speakerName":"Waiter & Laylo"}},{"id":"lesson_eng_a1_exit_step_2","stepNumber":2,"type":"interactive_question","title":"2. Tinglab tushunish savoli","titleRu":"2. Вопрос по аудированию","content":"Suhbatga asoslanib to‘g‘ri vaqt va buyurtmani tanlang.","contentRu":"Выберите верное время закрытия кафе согласно диалогу.","interactiveQuestion":{"id":"q_eng_a1_exit_listen","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A1","topic":"A1 Exit: Cafe closing time","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi suhbatga ko‘ra, kafe soat nechada yopiladi?","textRu":"Согласно диалогу, во сколько закрывается кафе?","options":["08:30","20:00","19:30","20:30"],"correctIndex":3,"mistakeFeedbackByOption":{"08:30":{"uz":"Ofitsiant «in the evening» (kechqurun) dedi — shuning uchun ertalabki 08:30 emas, kechki 20:30 to‘g‘ri!","ru":"Официант уточнил «in the evening» (вечером), поэтому верно 20:30, а не 08:30 утра."},"20:00":{"uz":"Laylo «eight o''clock» gacha ochiqmi deb so‘radi, ammo ofitsiant «half past eight» (20:30) da yopilishini aytdi.","ru":"Лейла спросила про 8 часов («eight o''clock»), но официант ответил «half past eight» (20:30)."},"19:30":{"uz":"19:30 — «half past seven»; audioda «half past eight» deyildi.","ru":"19:30 — это «half past seven», а в аудио прозвучало «half past eight»."}},"explanation":"«Half past eight in the evening» — kechki soat 20:30 ni anglatadi.","explanationRu":"«Half past eight in the evening» означает 20:30 вечера.","wrongFeedback":"Ofitsiantning «half past eight» va «in the evening» so‘zlariga e’tibor bering.","wrongFeedbackRu":"Обратите внимание на слова официанта «half past eight» и «in the evening»."}},{"id":"lesson_eng_a1_exit_step_3","stepNumber":3,"type":"interactive_question","title":"3. Bo‘sh joyni to‘ldirish","titleRu":"3. Заполнение пропуска","content":"Qavsdagi fe’lni Present Simple da to‘g‘ri yozing.","contentRu":"Вставьте глагол в нужной форме Present Simple.","interactiveQuestion":{"id":"q_eng_a1_exit_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"A1 Exit: Present Simple 3rd person","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"The city cafe ___ at nine o''clock every morning.","text":"Gapni to‘g‘ri shaklda to‘ldiring: «The city cafe ___ (open) at nine o''clock every morning.»","textRu":"Дополните предложение: «The city cafe ___ (open) at nine o''clock every morning.»","options":[],"acceptedAnswers":["opens"],"explanation":"«The city cafe» bitta joy (it) bo‘lgani uchun Present Simple da fe’lga «-s» qo‘shiladi: «opens».","explanationRu":"«The city cafe» (it) — 3-е лицо ед. ч., поэтому к глаголу добавляется «-s»: «opens».","wrongFeedback":"«The city cafe» (it) 3-shaxs birlik ekanini hisobga olib, qavsdagi fe’l oxiriga «-s» qo‘shing.","wrongFeedbackRu":"Поскольку «The city cafe» (it) — 3-е лицо ед. ч., добавьте к глаголу окончание «-s»."}},{"id":"lesson_eng_a1_exit_step_4","stepNumber":4,"type":"interactive_question","title":"4. Gap tuzish","titleRu":"4. Составление предложения","content":"So‘zlarni to‘g‘ri inglizcha tartibda joylashtiring.","contentRu":"Расставьте слова в правильном английском порядке.","interactiveQuestion":{"id":"q_eng_a1_exit_order","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A1","topic":"A1 Exit: SVO with preposition","difficulty":"easy","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Men choyimni deraza yonida ichaman» ma’nosidagi gapni tuzing:","textRu":"Составьте предложение «Я пью свой чай рядом с окном»:","options":[],"orderedTokens":["I","drink","my","tea","beside","the","window."],"acceptedAnswers":["I drink my tea beside the window."],"explanation":"To‘g‘ri tartib: Ega (I) + Fe’l (drink) + To‘ldiruvchi (my tea) + Joy (beside the window.).","explanationRu":"Правильный порядок: I + drink + my tea + beside the window.","wrongFeedback":"«I drink my tea» qismidan keyin joylashuv predlogini («beside the window.») qo‘ying.","wrongFeedbackRu":"После «I drink my tea» поставьте предлог места («beside the window.»)."}},{"id":"lesson_eng_a1_exit_step_5","stepNumber":5,"type":"interactive_question","title":"5. Qisqa e’lonni o‘qish","titleRu":"5. Чтение короткого объявления","content":"Dam olish kunidagi klub e’lonini o‘qing va to‘g‘ri javobni tanlang.","contentRu":"Прочтите объявление о клубе выходного дня и выберите верный ответ.","interactiveQuestion":{"id":"q_eng_a1_exit_read","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"A1 Exit: Weekend club notice","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Navoi Book Cafe: Our Sunday English chat table meets between 4:00 PM and 5:00 PM. New beginners are welcome, and tea is free for students.","text":"E’longa ko‘ra, Navoi Book Cafe haqida qaysi javob to‘g‘ri?","textRu":"Что верно о Navoi Book Cafe согласно объявлению?","options":["Yakshanba kuni soat 16:00–17:00 orasida suhbat davrasi bor va talabalarga choy bepul","Suhbat davrasi faqat ilg‘or darajadagilar uchun","Uchrashuv shanba kuni ertalab soat to‘rtda bo‘ladi","Talabalar choy uchun qo‘shimcha haq to‘laydi"],"correctIndex":0,"mistakeFeedbackByOption":{"Suhbat davrasi faqat ilg‘or darajadagilar uchun":{"uz":"Matnda «New beginners are welcome» (yangi boshlovchilar ham taklif etiladi) deyilgan.","ru":"В объявлении сказано «New beginners are welcome» (приглашаются новички)."},"Uchrashuv shanba kuni ertalab soat to‘rtda bo‘ladi":{"uz":"«Sunday» — yakshanba, «4:00 PM» — kunduzi 16:00, shanba tongi emas.","ru":"«Sunday» — воскресенье, «4:00 PM» — 16:00 дня, а не субботнее утро."},"Talabalar choy uchun qo‘shimcha haq to‘laydi":{"uz":"Matnda «tea is free for students» (talabalarga choy bepul) deb ko‘rsatilgan.","ru":"В тексте написано «tea is free for students» (чай для студентов бесплатный)."}},"explanation":"Matndagi «Sunday ... between 4:00 PM and 5:00 PM» (16:00–17:00) va «tea is free for students» dalillari to‘liq mos.","explanationRu":"В тексте указаны «Sunday ... between 4:00 PM and 5:00 PM» и «tea is free for students».","wrongFeedback":"Matndagi kun (Sunday), PM vaqti va «free» so‘zini tekshiring.","wrongFeedbackRu":"Сверьте день недели (Sunday), время PM и слово «free»."}}]'::jsonb, '{"id":"q_eng_a1_exit_reinf","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A1","topic":"A1 Exit: Ordering politely","difficulty":"easy","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Waiter: «Good afternoon! What would you like?»","Laylo: «___»"],"text":"Laylo kafeda odob bilan choy va sendvichni qanday buyurtma qiladi?","textRu":"Как Лейла вежливо закажет чай и сэндвич в кафе?","options":["Give me tea now! Goodbye.","A cup of green tea and a sandwich, please.","What''s your sandwich name?"],"correctIndex":1,"mistakeFeedbackByOption":{"Give me tea now! Goodbye.":{"uz":"Buyurtma berishda «please» (iltimos) ishlatish odobli; «Goodbye» esa ketayotganda aytiladi.","ru":"При заказе вежливо использовать «please», а «Goodbye» говорят при уходе."},"What''s your sandwich name?":{"uz":"«What''s your name?» faqat odamning ismini so‘rashda ishlatiladi.","ru":"Фраза «What''s your name?» используется только при знакомстве с людьми."}},"explanation":"«A cup of green tea and a sandwich, please.» — A1 darajasidagi eng tabiiy va xushmuomala buyurtma.","explanationRu":"«A cup of green tea and a sandwich, please.» — естественный вежливый заказ уровня A1.","wrongFeedback":"Kafeda «please» bilan xushmuomala buyurtma berish shaklini tanlang.","wrongFeedbackRu":"Выберите вежливую форму заказа с «please»."}'::jsonb, '{"id":"q_eng_a1_exit_alt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A1","topic":"A1 Exit alternate retry","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Bukhara Study Center: Morning English desk opens at quarter past eight. Bags go behind the green chairs.","text":"Qayta sinov: E’longa ko‘ra, sumkalar qayerga qo‘yiladi va markaz soat nechada ochiladi?","textRu":"Повторная проверка: во сколько открывается центр и куда нужно ставить сумки?","options":["07:45 da ochiladi, sumkalar stullar orasiga qo‘yiladi","08:15 da ochiladi, sumkalar yashil stullar orqasiga qo‘yiladi","20:15 da ochiladi, sumkalar stol yoniga qo‘yiladi"],"correctIndex":1,"mistakeFeedbackByOption":{"07:45 da ochiladi, sumkalar stullar orasiga qo‘yiladi":{"uz":"«quarter past eight» — 08:15 (07:45 «quarter to eight»), «behind» esa orqasida degani.","ru":"«quarter past eight» — 08:15, а предлог «behind» означает «позади»."},"20:15 da ochiladi, sumkalar stol yoniga qo‘yiladi":{"uz":"E’londa «Morning» (ertalab) va «behind the green chairs» deyilgan.","ru":"В объявлении сказано «Morning» (утро) и «behind the green chairs» (за зелёными стульями)."}},"explanation":"«Morning ... quarter past eight» = 08:15, «behind the green chairs» = yashil stullar orqasida.","explanationRu":"«Morning ... quarter past eight» — 08:15, а «behind the green chairs» — за зелёными стульями.","wrongFeedback":"«Morning», «quarter past eight» va «behind» so‘zlarini matndan tekshiring.","wrongFeedbackRu":"Сверьте в тексте слова «Morning», «quarter past eight» и «behind»."}'::jsonb, true, true, false),
  ('lesson_eng_a2_m1_directions', 'course_eng_01', 'skill_eng_listening', 'listening', 'listening', 'A2', 'mod_eng_a2_m1', 'unit_eng_a2_u1', 'Shahar ko‘chalarida metro yoki avtobus bekatiga yo‘l so‘raydi va berilgan yo‘nalishni tinglab tushunadi.', 'Спрашивает дорогу к метро или остановке и понимает устные указания маршрута.', '["node_eng_a1_exit"]'::jsonb, 'Transport va shahar bo‘ylab yo‘l so‘rash', 'Транспорт и ориентирование в городе', 8, 'Buyruq fe’llari (Go straight, Turn right) va harakat predloglari (along, past, across from) yordamida Oybek metrosiga yo‘l topishni o‘rganasiz.', 'Вы научитесь понимать и объяснять маршрут в городе с глаголами направления и предлогами along, past, across from.', 'Ushbu darsdagi og‘zaki mashq mustaqil amaliyot uchun mo‘ljallangan; rasmiy CEFR sertifikati bermaydi.', 'Устное задание в уроке предназначено для самостоятельной практики и не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"Yangi shaharda metro yoki avtobus bekatini topish uchun qisqa yo‘nalish iboralarini aniq tushunish kerak.","ru":"Чтобы легко найти метро или остановку в новом районе, важно уверенно понимать указания маршрута."},"learningObjective":{"uz":"O‘quvchi «along, past, across from» predloglari bilan audio yo‘nalishni aniqlaydi va 3 bosqichli yo‘l ko‘rsatishni aytadi.","ru":"Ученик определяет маршрут по аудио с предлогами «along, past, across from» и составляет устный маршрут из 3 шагов."},"warmUp":{"uz":"A1 darajasidagi «beside, behind» so‘zlarini eslab, endi harakat yo‘nalishini ko‘rsatuvchi fe’llarga o‘tamiz.","ru":"Вспомните предлоги «beside, behind» из A1 и перейдите к глаголам движения по улице."},"vocabularyItems":[{"word":"turn left","uz":"chapga burilmoq","ru":"повернуть налево","ipa":"/tɜːn left/"},{"word":"go past","uz":"yonidan o‘tmoq","ru":"пройти мимо","ipa":"/ɡəʊ pɑːst/"},{"word":"across from","uz":"qarama-qarshi tomonda","ru":"напротив","ipa":"/əˈkrɒs frɒm/"},{"word":"bus stop","uz":"avtobus bekati","ru":"автобусная остановка","ipa":"/ˈbʌs stɒp/"}],"grammarNote":{"rule":"Imperatives + Prepositions of Movement (along / past / across from)","simpleExplanationUz":"Yo‘l ko‘rsatishda gap to‘g‘ridan-to‘g‘ri buyruq fe’li bilan boshlanadi (ega «you» yozilmaydi): «Go straight along...», «Walk past...», «Turn right at...».","simpleExplanationRu":"При объяснении маршрута используйте повелительное наклонение без «you»: «Go straight along...», «Walk past...», «Turn right at...».","structure":"[Base Verb] + [along / past / at] + [Landmark]","positiveExamples":["Go straight along Navoi Street.","Walk past the post office and turn right at the pharmacy."],"negativeExamples":["Don''t turn left before the bridge."],"questions":["Excuse me, how do I get to Oybek Metro Station?","Where is the nearest bus stop?"],"commonMistakes":["«Go past» (yonidan o‘tib ketmoq) o‘rniga «Go across» (ko‘chani kesib o‘tmoq) ni almashtirib yuborish."]},"pronunciationFocus":{"uz":"«past» BrE da cho‘ziq /pɑːst/, AmE da /pæst/ aytiladi; «turn» so‘zidagi /ɜː/ tovushi cho‘ziladi.","ru":"В слове «past» в BrE звучит долгий /ɑː/, в AmE /æ/; в «turn» гласный /ɜː/ произносится протяжно."},"examples":["Go straight along Navoi Street, walk past the post office, and turn right at the pharmacy.","The metro entrance is across from the park."],"guidedPractice":{"uz":"Xarita tasviri va Kamolaning ovozli tushuntirishini tinglab, 4 ta flashcard iborasini mustahkamlang.","ru":"Изучите карту и диалог Камолы, затем закрепите 4 фразы на карточках."},"independentPractice":{"uz":"Audio bo‘yicha metro kirish joyini toping va kitob do‘konidan bekatgacha yo‘lni og‘zaki tushuntiring.","ru":"Определите вход в метро по аудио и составьте устное объяснение маршрута к остановке."},"listeningRef":"media_eng_a2_m1_directions_dialogue","readingRef":"lesson_eng_a2_m1_concept","speakingTask":{"uz":"Kitob do‘konidan avtobus bekatigacha bo‘lgan yo‘lni 3 ta qisqa buyruq gapi bilan ayting.","ru":"Объясните дорогу от книжного магазина до остановки в 3 коротких предложениях."},"writingTask":{"uz":"«Walk past ... and turn left.» qolipida 1 ta yo‘nalish gapini tartiblang.","ru":"Соберите предложение по модели «Walk past ... and turn left.»."},"knowledgeCheck":"q_eng_a2_m1_listen_mcq","finalQuiz":"q_eng_a2_m1_speaking","feedbackRules":{"uz":"Har bir chalg‘ituvchi variant burilish yoki mo‘ljal xatosini aniq ko‘rsatadi.","ru":"Каждый неверный вариант объясняет путаницу в повороте или ориентире."},"summaryAndRevision":{"uz":"Yo‘nalish iboralari SRS kartochkalarida va 1-bo‘lim sinovida qayta tekshiriladi.","ru":"Фразы ориентирования закрепляются в карточках SRS и в проверке раздела 1."}}'::jsonb, '[{"id":"lesson_eng_a2_m1_concept","stepNumber":1,"type":"concept","title":"Yo‘l ko‘rsatish formulasi","titleRu":"Формула объяснения маршрута","content":"Ingliz tilida yo‘l tushuntirishda fe’lning oddiy shakli (Go, Walk, Turn) ishlatiladi. «along» ko‘cha bo‘ylab yurishni, «past» bino yonidan o‘tishni, «across from» esa ko‘chaning narigi tomonidagi joyni bildiradi.","contentRu":"При объяснении дороги используют повелительную форму глагола (Go, Walk, Turn). «along» означает движение вдоль улицы, «past» — мимо здания, а «across from» — напротив через дорогу.","highlightNotes":["Go straight along Navoi Street — Navoiy ko‘chasi bo‘ylab to‘g‘ri yuring","Walk past the post office — Pochta yonidan o‘ting","Turn right at the pharmacy — Dorixonada o‘ngga buriling","Across from the park — Bog‘ning qarama-qarshi tomonida"]},{"id":"lesson_eng_a2_m1_audio","stepNumber":2,"type":"audio_simulation","title":"Tinglash: Oybek metrosiga yo‘l","titleRu":"Аудирование: Дорога к метро Ойбек","content":"Sayyoh va Kamolaning suhbatini tinglang. Qaysi bino yonidan o‘tish va qayerda burilish kerakligiga e’tibor bering.","contentRu":"Прослушайте диалог туриста и Камолы. Обратите внимание, мимо какого здания нужно пройти и где повернуть.","media":{"id":"media_eng_a2_m1_directions_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a2/a2-m1-directions-dialogue.wav","title":"Oybek metrosiga yo‘l so‘rash suhbati","titleUz":"Oybek metrosiga yo‘l so‘rash suhbati","titleRu":"Диалог о дороге к станции метро Ойбек","transcript":"Tourist: Excuse me, how do I get to Oybek Metro Station?\nKamola: Go straight along Navoi Street, walk past the post office, and turn right at the pharmacy. The metro entrance is across from the park.\nTourist: Thank you! And where is the bus stop?\nKamola: Turn left after the bookshop. The bus stop is right there.","posterImage":"/lesson-media/english/a2/a2-m1-city-map.png","posterAlt":"Ko‘chalar kesishmasi, bino belgilari va punktir yo‘nalish chizig‘i ko‘rsatilgan shahar xaritasi","posterAltUz":"Ko‘chalar kesishmasi, bino belgilari va punktir yo‘nalish chizig‘i ko‘rsatilgan shahar xaritasi","posterAltRu":"Городская карта с перекрёстками, значками зданий и пунктирным маршрутом","durationSeconds":20.2,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Tourist: Excuse me, how do I get to Oybek Metro Station?\nKamola: Go straight along Navoi Street, walk past the post office, and turn right at the pharmacy. The metro entrance is across from the park.\nTourist: Thank you! And where is the bus stop?\nKamola: Turn left after the bookshop. The bus stop is right there.","speakerName":"Tourist & Kamola"}},{"id":"lesson_eng_a2_m1_flashcards","stepNumber":3,"type":"flashcard","title":"Yo‘nalish kartochkalari","titleRu":"Карточки направлений","content":"Talaffuzni tinglang, avval ma’nosini eslang, so‘ng «Javobni ko‘rish» tugmasini bosing.","contentRu":"Прослушайте произношение, вспомните значение и откройте перевод.","flashcards":[{"id":"fc_eng_a2_m1_1","front":"turn left","backUz":"chapga burilmoq","backRu":"повернуть налево","partOfSpeech":"phrase","ipa":"/tɜːn left/","ipaAmE":"/tɜːrn left/","cefrLevel":"A2","example":"Turn left after the bookshop to reach the bus stop.","exampleUz":"Bekatga chiqish uchun kitob do‘konidan keyin chapga buriling.","exampleRu":"Поверните налево после книжного магазина, чтобы выйти к остановке.","audioSrc":"/lesson-media/english/a2/a2-m1-turn-left.wav","imageSrc":"/lesson-media/english/a2/a2-m1-city-map.png","alt":"Shahar xaritasi: bino belgilari, ko‘chalar va punktir yo‘l chizig‘i","altRu":"Городская карта со значками зданий, улицами и пунктирной линией пути","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m1_2","front":"go past","backUz":"yonidan o‘tmoq","backRu":"пройти мимо","partOfSpeech":"phrase","ipa":"/ɡəʊ pɑːst/","ipaAmE":"/ɡoʊ pæst/","cefrLevel":"A2","example":"Go past the post office and stay on Navoi Street.","exampleUz":"Pochta yonidan o‘ting va Navoiy ko‘chasida davom eting.","exampleRu":"Пройдите мимо почты и идите дальше по улице Навои.","audioSrc":"/lesson-media/english/a2/a2-m1-go-past.wav","imageSrc":"/lesson-media/english/a2/a2-m1-city-map.png","alt":"Pochta, dorixona va yashil bog‘ tasvirlangan shahar chorrahasi","altRu":"Городской перекрёсток со значками почты, аптеки и зелёного сквера","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m1_3","front":"across from","backUz":"qarama-qarshi tomonda","backRu":"напротив","partOfSpeech":"preposition","ipa":"/əˈkrɒs frɒm/","ipaAmE":"/əˈkrɔːs frʌm/","cefrLevel":"A2","example":"The metro entrance is across from the green park.","exampleUz":"Metro kirish joyi yashil bog‘ning qarama-qarshi tomonida.","exampleRu":"Вход в метро находится напротив зелёного парка.","audioSrc":"/lesson-media/english/a2/a2-m1-across-from.wav","imageSrc":"/lesson-media/english/a2/a2-m1-city-map.png","alt":"Piyoda o‘tish chizig‘ining ikki chetida joylashgan bino va yashil bog‘","altRu":"Здание и зелёный парк по две стороны от городской дороги","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m1_4","front":"bus stop","backUz":"avtobus bekati","backRu":"автобусная остановка","partOfSpeech":"noun","ipa":"/ˈbʌs stɒp/","ipaAmE":"/ˈbʌs stɑːp/","cefrLevel":"A2","example":"Wait at the bus stop near the corner bookshop.","exampleUz":"Burchakdagi kitob do‘koni yaqinidagi bekatda kuting.","exampleRu":"Подождите на остановке рядом с угловым книжным магазином.","audioSrc":"/lesson-media/english/a2/a2-m1-bus-stop.wav","imageSrc":"/lesson-media/english/a2/a2-m1-city-map.png","alt":"Shahar ko‘chasi burchagida oq kartochkada chizilgan ko‘k transport belgisi","altRu":"Синий дорожный значок с городским транспортом в углу схемы","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a2_m1_listen_q","stepNumber":4,"type":"interactive_question","title":"Tinglab tushunish tekshiruvi","titleRu":"Проверка понимания диалога","content":"Kamolaning ko‘rsatmalariga ko‘ra, metro kirish joyi qayerda va u yerga qanday boriladi?","contentRu":"Согласно объяснению Камолы, где находится вход в метро и как до него дойти?","interactiveQuestion":{"id":"q_eng_a2_m1_listen_mcq","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A2","topic":"Listening: Metro directions","difficulty":"easy","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi suhbatga ko‘ra, Oybek metrosiga borish uchun sayyoh qayerda o‘ngga burilishi kerak?","textRu":"Где турист должен повернуть направо по дороге к метро Ойбек согласно диалогу?","options":["Dorixonada o‘ngga buriladi, metro bog‘ning qarama-qarshi tomonida","Kitob do‘konidan keyin chapga buriladi, metro pochta yonida","Pochtada o‘ngga buriladi, metro kitob do‘koni orqasida","Bog‘ ichidan to‘g‘ri yuradi, avtobus bekati metro ichida"],"correctIndex":0,"mistakeFeedbackByOption":{"Kitob do‘konidan keyin chapga buriladi, metro pochta yonida":{"uz":"Kitob do‘konidan keyin chapga burilish metroga emas, avtobus bekatiga olib boradi.","ru":"Поворот налево после книжного магазина ведёт к автобусной остановке, а не к метро."},"Pochtada o‘ngga buriladi, metro kitob do‘koni orqasida":{"uz":"Kamola «walk past the post office» (pochta yonidan o‘tib keting) va «turn right at the pharmacy» dedi.","ru":"Камола сказала «walk past the post office» (пройдите мимо почты) и поверните направо у аптеки."},"Bog‘ ichidan to‘g‘ri yuradi, avtobus bekati metro ichida":{"uz":"Metro bog‘ning ichida emas, «across from the park» (bog‘ning qarama-qarshi tomonida) joylashgan.","ru":"Метро находится не внутри парка, а «across from the park» (напротив парка)."}},"explanation":"Kamola «walk past the post office, and turn right at the pharmacy. The metro entrance is across from the park» deb aniq tushuntirdi.","explanationRu":"Камола чётко сказала: пройти мимо почты, повернуть направо у аптеки, вход в метро напротив парка.","wrongFeedback":"Audioda sayyoh qaysi bino yonida burilishi va metro kirish joyi nimaning qarshisida ekanini diqqat bilan qayta tinglang.","wrongFeedbackRu":"Переслушайте в аудио, у какого здания нужно повернуть направо и напротив чего находится вход в метро."}},{"id":"lesson_eng_a2_m1_speak_q","stepNumber":5,"type":"interactive_question","title":"Speaking: Yo‘l tushuntirish mashqi","titleRu":"Speaking: Устное объяснение маршрута","content":"O‘zingizni mahalliy yo‘lboshchi deb tasavvur qiling va mehmonlarga metroga borishni 3 qadamda og‘zaki tushuntiring.","contentRu":"Представьте, что вы объясняете дорогу гостю города, и сформулируйте маршрут из 3 шагов вслух.","interactiveQuestion":{"id":"q_eng_a2_m1_speaking","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"speaking","cefrLevel":"A2","topic":"Speaking: Giving directions","difficulty":"medium","questionType":"speaking_prompt","evaluationMode":"self_assessed","text":"Do‘stingizga kitob do‘konidan bekat yoki metroga borish yo‘lini 3 ta qisqa inglizcha gap bilan tushuntiring.","textRu":"Объясните другу дорогу от книжного магазина до остановки или метро в 3 коротких предложениях по-английски.","options":[],"sampleResponse":"Go straight along Navoi Street and walk past the post office. Turn right at the pharmacy. The metro entrance is across from the park.","rubricCriteria":[{"id":"crit_a2_m1_imp","labelUz":"Buyruq fe’llari ishlatildi (Go straight / Walk past / Turn right or left)","labelRu":"Использованы глаголы направления (Go straight / Walk past / Turn right or left)"},{"id":"crit_a2_m1_prep","labelUz":"Kamida bitta harakat/joy predlogi to‘g‘ri qo‘llandi (along / past / across from)","labelRu":"Верно применён хотя бы один предлог (along / past / across from)"},{"id":"crit_a2_m1_landmark","labelUz":"Aniq mo‘ljal va manzil aytildi (post office, pharmacy, park)","labelRu":"Указаны чёткие ориентиры и цель (post office, pharmacy, park)"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil nutq mashqi): bu topshiriq rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельная речевая практика): задание не выдаёт официальный сертификат CEFR.","explanation":"Qisqa buyruq fe’llari va aniq mo‘ljallar (along, past, across from) A2 darajasida tushunarli yo‘l ko‘rsatishni ta’minlaydi.","explanationRu":"Короткие повелительные фразы с ориентирами (along, past, across from) соответствуют уровню A2.","wrongFeedback":"Gaplaringizda buyruq fe’li, predlog va bino mo‘ljallari borligini mezonlar asosida tekshiring.","wrongFeedbackRu":"Проверьте наличие глаголов направления, предлогов и ориентиров по критериям."}}]'::jsonb, '{"id":"q_eng_a2_m1_order","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"grammar","cefrLevel":"A2","topic":"Directions sentence ordering","difficulty":"easy","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Novvoyxona yonidan o‘ting va chapga buriling» gapini to‘g‘ri tartibda tuzing:","textRu":"Составьте предложение «Пройдите мимо пекарни и поверните налево» в правильном порядке:","options":[],"orderedTokens":["Walk","past","the bakery","and","turn","left."],"acceptedAnswers":["Walk past the bakery and turn left."],"explanation":"To‘g‘ri tartib: Walk past + the bakery + and + turn + left.","explanationRu":"Правильный порядок: Walk past + the bakery + and + turn + left.","wrongFeedback":"Avval yo‘nalish bildiruvchi buyruq iborasi va joy nomini, keyin bog‘lovchi va oxirida burilish ko‘rsatmasini joylang.","wrongFeedbackRu":"Сначала поставьте глагольную фразу направления и ориентир, затем союз и указание поворота в конце."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a2_u1_checkpoint', 'course_eng_01', 'skill_eng_listening', 'listening', 'checkpoint', 'A2', 'mod_eng_a2_m1', 'unit_eng_a2_u1', 'Avtobusdagi almashish ko‘rsatmasini tinglab, keyingi harakatni to‘g‘ri tanlaydi.', 'Понимает устное указание о пересадке в автобусе и выбирает верное действие.', '["node_eng_a2_m1_directions"]'::jsonb, '1-bo‘lim sinovi: Avtobus va almashish', 'Проверка раздела 1: Автобус и пересадка', 6, 'Timur va avtobus haydovchisining suhbatini tinglab, Chorsu bozoriga borish uchun qaysi bekatda tushish va qaysi transportga o‘tishni aniqlaysiz.', 'Прослушав диалог Тимура и водителя автобуса, вы определите нужную остановку и пересадку.', 'Bu ichki 1-bo‘lim yakuniy sinovi bo‘lib, rasmiy CEFR sertifikatini bermaydi.', 'Это внутренняя проверка раздела 1; она не является официальным сертификатом CEFR.', '{"intro":{"uz":"Avtobusda haydovchidan almashish bekatini so‘rash kundalik hayotda tez-tez uchraydi.","ru":"Уточнить остановку пересадки у водителя — частая городская ситуация."},"learningObjective":{"uz":"O‘quvchi 2-bekat, mo‘ljal va avtobus raqamini audiodan ajratib oladi.","ru":"Ученик извлекает из аудио номер остановки, ориентир и номер автобуса для пересадки."},"warmUp":{"uz":"«Get off», «walk past», «across from» iboralarini eslang.","ru":"Вспомните выражения «Get off», «walk past», «across from»."},"vocabularyItems":[{"word":"get off","uz":"transportdan tushmoq","ru":"выйти из транспорта","ipa":"/ɡet ɒf/"},{"word":"corner cafe","uz":"burchakdagi kafe","ru":"кафе на углу","ipa":"/ˈkɔːnə ˈkæfeɪ/"}],"grammarNote":{"rule":"Sequential Directions (Get off at ... -> Walk past ... -> Take bus ...)","simpleExplanationUz":"Bir nechta bosqichli yo‘lda har bir harakat buyruq fe’li bilan ketma-ket beriladi.","simpleExplanationRu":"В маршруте с пересадкой действия перечисляются последовательно глаголами в повелительной форме.","structure":"Get off at [stop], walk past [landmark], and take [bus number].","positiveExamples":["Get off at the second stop across from the museum."],"negativeExamples":["Do not stay on the first bus after the second stop."],"questions":["Does this bus go to Chorsu Bazaar?"],"commonMistakes":["«Get off» (tushmoq) va «Get on» (chiqmoq) fe’llarini adashtirish."]},"pronunciationFocus":{"uz":"«twenty-eight» /ˌtwenti ˈeɪt/ sonida ikkinchi qismga urg‘u tushadi.","ru":"В числительном «twenty-eight» /ˌtwenti ˈeɪt/ основное ударение падает на «eight»."},"examples":["Get off at the second stop across from the history museum."],"guidedPractice":{"uz":"Haydovchining javobini diqqat bilan tinglang.","ru":"Внимательно прослушайте ответ водителя."},"independentPractice":{"uz":"Suhbatni yakunlang va so‘zlarni moslash hamda muqobil savollarni yeching.","ru":"Завершите диалог и выполните задания на сопоставление и альтернативную проверку."},"listeningRef":"media_eng_a2_u1_cp_bus","readingRef":"lesson_eng_a2_u1_cp_concept","speakingTask":{"uz":"Haydovchining 3 qadamli ko‘rsatmasini ovoz chiqarib takrorlang.","ru":"Повторите вслух три шага маршрута от водителя."},"writingTask":{"uz":"Juftliklarni to‘g‘ri moslash bilan ma’nolarni mustahkamlang.","ru":"Закрепите значения фраз в задании на сопоставление."},"knowledgeCheck":"q_eng_a2_u1_cp_conv","finalQuiz":"q_eng_a2_u1_cp_reinf","feedbackRules":{"uz":"70% dan yuqori natija 2-modulni (Xarid va narxlar) ochadi.","ru":"Результат 70% и выше открывает модуль 2 (Покупки и цены)."},"summaryAndRevision":{"uz":"Xato qilinsa, muqobil vaziyat orqali qayta tekshiruv beriladi.","ru":"При ошибке доступна повторная проверка с новым вопросом."}}'::jsonb, '[{"id":"lesson_eng_a2_u1_cp_concept","stepNumber":1,"type":"concept","title":"1-bo‘lim sinovi qoidasi","titleRu":"Правила проверки раздела 1","content":"Bu sinovda Timur avtobusda haydovchidan Chorsu bozoriga qanday borishni so‘raydi. Qaysi bekatda tushish («get off»), qaysi bino yonidan o‘tish («walk past») va qaysi avtobusga chiqishni tinglab aniqlang.","contentRu":"В этой проверке Тимур спрашивает водителя, как добраться до базара Чорсу. Определите остановку для выхода («get off»), ориентир и номер автобуса для пересадки."},{"id":"lesson_eng_a2_u1_cp_audio","stepNumber":2,"type":"audio_simulation","title":"Tinglash: Avtobusda almashish","titleRu":"Аудирование: Пересадка в автобусе","content":"Timur va haydovchining suhbatini tinglang.","contentRu":"Прослушайте диалог Тимура и водителя.","media":{"id":"media_eng_a2_u1_cp_bus","kind":"audio","language":"en","source":"/lesson-media/english/a2/a2-u1-cp-bus-announcement.wav","title":"1-bo‘lim sinovi: Avtobusda almashish suhbati","titleUz":"1-bo‘lim sinovi: Avtobusda almashish suhbati","titleRu":"Проверка раздела 1: Разговор в автобусе о пересадке","transcript":"Timur: Excuse me, does this bus go to Chorsu Bazaar?\nDriver: Not directly. Get off at the second stop across from the history museum, walk past the corner cafe, and take bus number twenty-eight.\nTimur: Second stop across from the museum, then bus twenty-eight. Got it, thanks!","posterImage":"/lesson-media/english/a2/a2-m1-city-map.png","posterAlt":"Shahar ko‘chalari, bekat belgisi va piyoda yo‘laklari chizilgan xarita","posterAltUz":"Shahar ko‘chalari, bekat belgisi va piyoda yo‘laklari chizilgan xarita","posterAltRu":"Городские улицы, значок транспорта и пешеходные переходы на карте","durationSeconds":19.018,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Timur: Excuse me, does this bus go to Chorsu Bazaar?\nDriver: Not directly. Get off at the second stop across from the history museum, walk past the corner cafe, and take bus number twenty-eight.\nTimur: Second stop across from the museum, then bus twenty-eight. Got it, thanks!","speakerName":"Timur & Driver"}},{"id":"lesson_eng_a2_u1_cp_q","stepNumber":3,"type":"interactive_question","title":"Suhbatni yakunlash","titleRu":"Завершение диалога","content":"Haydovchining javobini to‘liq va aniq yakunlovchi qatorni tanlang.","contentRu":"Выберите реплику водителя, соответствующую услышанному маршруту.","interactiveQuestion":{"id":"q_eng_a2_u1_cp_conv","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A2","topic":"Unit 1 Checkpoint: Bus transfer","difficulty":"medium","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Timur: «Excuse me, does this bus go to Chorsu Bazaar?»","Driver: «___»"],"text":"Audiodagi ma’lumotga mos ravishda haydovchining to‘liq ko‘rsatmasini tanlang:","textRu":"Выберите верную реплику водителя согласно прослушанному диалогу:","options":["Get off at the first stop along the park and take bus 18.","Stay on this bus behind the museum until the final stop.","Walk across the museum and wait for bus 82.","Get off at the second stop across from the history museum and take bus 28."],"correctIndex":3,"mistakeFeedbackByOption":{"Get off at the first stop along the park and take bus 18.":{"uz":"Audioda «first stop» emas «second stop» va «twenty-eight» (28) avtobusi aytildi.","ru":"В аудио звучало «second stop» (вторая остановка) и автобус 28 («twenty-eight»), а не 18."},"Stay on this bus behind the museum until the final stop.":{"uz":"Haydovchi «Not directly» (to‘g‘ridan-to‘g‘ri bormaydi) dedi va muzey qarshisida tushishni aytdi.","ru":"Водитель сказал «Not directly» (прямо не идёт) и указал выйти напротив музея."},"Walk across the museum and wait for bus 82.":{"uz":"«Walk across the museum» noto‘g‘ri — bino yonidan o‘tiladi («walk past the corner cafe») va avtobus raqami 28, 82 emas.","ru":"Нужно пройти мимо кафе («walk past»), а не через музей, и номер автобуса 28, а не 82."}},"explanation":"Haydovchi «second stop across from the history museum» va «bus number twenty-eight» (28) ni aniq aytdi.","explanationRu":"Водитель назвал вторую остановку напротив исторического музея и автобус №28.","wrongFeedback":"Audiodagi bekat tartib raqami, qaysi bino qarshisida tushish va keyingi avtobus raqamini qayta tinglab tekshiring.","wrongFeedbackRu":"Переслушайте в аудио порядковый номер остановки, ориентир для выхода и номер следующего автобуса."}}]'::jsonb, '{"id":"q_eng_a2_u1_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"vocabulary","cefrLevel":"A2","topic":"Transport phrases matching","difficulty":"easy","questionType":"word_match","evaluationMode":"deterministic","text":"Transport va yo‘l ko‘rsatish iboralarini o‘zbekcha ma’nosi bilan juftlang:","textRu":"Соедините фразы о транспорте и маршруте с их узбекским переводом:","options":[],"matchPairs":[{"id":"pair_a2_u1_1","left":"get off","right":"tushmoq"},{"id":"pair_a2_u1_2","left":"turn right","right":"o‘ngga burilmoq"},{"id":"pair_a2_u1_3","left":"go past","right":"yonidan o‘tmoq"},{"id":"pair_a2_u1_4","left":"corner cafe","right":"burchakdagi kafe"}],"explanation":"«get off» — tushmoq, «turn right» — o‘ngga burilmoq, «go past» — yonidan o‘tmoq, «corner cafe» — burchakdagi kafe.","explanationRu":"Все четыре пары транспортной лексики сопоставлены точно.","wrongFeedback":"Transportdan tushish, burilish yo‘nalishi, yonidan o‘tish va burchakdagi joy nomini anglatuvchi inglizcha iboralarni ma’nosi bilan solishtiring.","wrongFeedbackRu":"Сопоставьте английские выражения выхода из транспорта, поворота, движения мимо объекта и расположения на углу с их переводом."}'::jsonb, '{"id":"q_eng_a2_u1_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A2","topic":"Unit 1 alternate route check","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"City Guide: To reach Amir Temur Square from the library, walk along Mustaqillik Avenue for five minutes and turn left at the fountain. The metro stairs are directly across from the fountain.","text":"Qayta sinov: E’longa ko‘ra, metro zinapoyasi qayerda joylashgan?","textRu":"Повторная проверка: где находится вход в метро согласно памятке?","options":["Favvoraning qarama-qarshi tomonida","Kutubxona ichida, chap burilishdan oldin","Mustaqillik shoh ko‘chasidan o‘ng tomonda","Favvoradan besh daqiqa orqada"],"correctIndex":0,"mistakeFeedbackByOption":{"Kutubxona ichida, chap burilishdan oldin":{"uz":"Matnda kutubxonadan yurib chiqish aytilgan, metro kutubxona ichida emas.","ru":"Библиотека — это точка старта, а не расположение метро."},"Mustaqillik shoh ko‘chasidan o‘ng tomonda":{"uz":"Matnda «turn left at the fountain» (favvorada chapga buriling) deyilgan.","ru":"В тексте сказано «turn left at the fountain» (поверните налево у фонтана)."},"Favvoradan besh daqiqa orqada":{"uz":"Besh daqiqa — shoh ko‘cha bo‘ylab piyoda yurish vaqti; metro favvoraning ro‘parasida («across from»).","ru":"Пять минут — время пути по проспекту, а спуск в метро прямо напротив фонтана."}},"explanation":"Matndagi «across from the fountain» iborasi favvoraning qarama-qarshi tomonini bildiradi.","explanationRu":"Фраза «across from the fountain» означает прямо напротив фонтана.","wrongFeedback":"Matndagi favvora atrofidagi harakat yo‘nalishi va metro zinapoyasi joylashuvini qayta o‘qing.","wrongFeedbackRu":"Перечитайте в тексте ориентир у фонтана и точное расположение входа в метро."}'::jsonb, true, true, false),
  ('lesson_eng_a2_m2_shopping', 'course_eng_01', 'skill_eng_vocab', 'vocabulary', 'vocabulary', 'A2', 'mod_eng_a2_m2', 'unit_eng_a2_u2', 'Do‘konda narx va miqdor so‘raydi («How much / How many»), ikkita buyumni qiyoslaydi.', 'Спрашивает цену и количество («How much / How many») и сравнивает два товара.', '["node_eng_a2_u1_checkpoint"]'::jsonb, 'Xarid qilish, narxlar va taqqoslash', 'Покупки, цены и сравнения', 8, 'Kiyim do‘konida «How much / How many» savollari, chegirma lug‘ati va qiyosiy sifatlar (-er / more) yordamida eng foydali xaridni tanlaysiz.', 'Вы научитесь задавать вопросы о цене и количестве, понимать скидки и сравнивать товары с помощью сравнительной степени.', 'Ichki modul sinovlari va A2 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A2 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Do‘kon yoki bozorda narx so‘rash, chegirma hisoblash va ikki kiyimni solishtirish har kuni kerak bo‘ladi.","ru":"Умение спросить цену, уточнить скидку и сравнить две вещи нужно в любом магазине."},"learningObjective":{"uz":"O‘quvchi «How much / How many» ni farqlaydi, qiyosiy sifat (-er / more) xatosini tuzatadi va xarid so‘zlarini moslaydi.","ru":"Ученик различает «How much / How many», исправляет двойную сравнительную степень и сопоставляет лексику покупок."},"warmUp":{"uz":"Ikki kurtkadan qaysi biri arzonroq ekanini inglizcha qanday aytasiz?","ru":"Как по-английски сказать, какая из двух курток дешевле?"},"vocabularyItems":[{"word":"discount","uz":"chegirma","ru":"скидка","ipa":"/ˈdɪskaʊnt/"},{"word":"receipt","uz":"xarid cheki","ru":"чек оплаты","ipa":"/rɪˈsiːt/"},{"word":"cheaper","uz":"arzonroq","ru":"дешевле","ipa":"/ˈtʃiːpə/"},{"word":"how much","uz":"qancha turadi","ru":"сколько стоит","ipa":"/haʊ mʌtʃ/"}],"grammarNote":{"rule":"How much vs How many + Comparatives (-er / more)","simpleExplanationUz":"Narx va sanalmaydigan otlar uchun «How much», sanaladigan ko‘plik otlar uchun «How many» ishlatiladi. Qisqa sifatga «-er» qo‘shiladi (cheaper), uzun sifat oldidan «more» keladi (more comfortable) — ikkalasi birga («more cheaper») ishlatilmaydi!","simpleExplanationRu":"Для цены и неисчисляемых существительных используется «How much», для исчисляемых во множественном числе — «How many». Коротким прилагательным добавляется «-er» (cheaper), перед длинными ставится «more» — но не оба сразу («more cheaper» — ошибка!).","structure":"How much is [item]? / [A] is cheaper / more comfortable than [B].","positiveExamples":["How much is the blue jacket?","The blue jacket is cheaper than the green coat."],"negativeExamples":["This coat is more cheaper than that one. (Xato: more va -er birga kelmaydi!)"],"questions":["How much does the green coat cost?","How many bags do you need?"],"commonMistakes":["«more cheaper» kabi qo‘shaloq qiyosiy daraja ishlatish yoki «receipt» so‘zidagi «p» harfini o‘qib yuborish."]},"pronunciationFocus":{"uz":"«receipt» /rɪˈsiːt/ so‘zida «p» harfi talaffuz qilinmaydi; «cheaper» /ˈtʃiːpə/ so‘zida «ch» qattiq /tʃ/ chiqadi.","ru":"В слове «receipt» /rɪˈsiːt/ буква «p» немая; в «cheaper» начальный звук — чёткий /tʃ/."},"examples":["The blue jacket is cheaper today with our twenty percent student discount.","May I have a receipt, please?"],"guidedPractice":{"uz":"Do‘kon rasmini, kassa suhbatini va 4 ta xarid kartochkasini o‘rganing.","ru":"Изучите иллюстрацию магазина, диалог на кассе и 4 карточки лексики."},"independentPractice":{"uz":"Xarid so‘zlarini juftlang, narx so‘roqidagi bo‘sh joyni to‘ldiring va qiyosiy sifat xatosini tuzating.","ru":"Сопоставьте термины покупок, заполните пропуск в вопросе о цене и исправьте ошибку сравнения."},"listeningRef":"media_eng_a2_m2_shop_dialogue","readingRef":"lesson_eng_a2_m2_concept","speakingTask":{"uz":"Do‘kondagi ikkita mahsulot narxini solishtirib 2 ta gap ayting.","ru":"Сравните цены двух товаров в магазине в 2 предложениях вслух."},"writingTask":{"uz":"«How ___ does ... cost?» savolini to‘g‘ri so‘z bilan to‘ldiring.","ru":"Заполните пропуск в вопросе «How ___ does ... cost?»."},"knowledgeCheck":"q_eng_a2_m2_word_match","finalQuiz":"q_eng_a2_m2_fill_much","feedbackRules":{"uz":"Qo‘shaloq qiyosiy shakl («more cheaper») va «much/many» chalkashligi darhol izohlanadi.","ru":"Ошибки двойной сравнительной степени и путаница «much/many» подробно разбираются."},"summaryAndRevision":{"uz":"Xarid lug‘ati va qiyosiy sifatlar 2-bo‘lim sinovida mustahkamlanadi.","ru":"Лексика покупок и степени сравнения проверяются в контрольной точке раздела 2."}}'::jsonb, '[{"id":"lesson_eng_a2_m2_concept","stepNumber":1,"type":"concept","title":"Narx so‘rash va taqqoslash qoidasi","titleRu":"Правило вопросов о цене и сравнений","content":"Narx so‘rashda «How much is...?» yoki «How much does ... cost?», dona sanashda esa «How many ...?» ishlatiladi. Qisqa sifatga «-er» (cheaper), 2+ bo‘g‘inli sifat oldidan esa «more» (more comfortable) qo‘yiladi.","contentRu":"Для цены используйте «How much is...?», а для количества штук — «How many...?». Коротким прилагательным добавляется «-er» (cheaper), а перед длинными ставится «more» (more comfortable).","highlightNotes":["How much does it cost? — Qancha turadi?","How many shirts? — Nechta ko‘ylak?","cheaper than ... — ...dan arzonroq","more comfortable than ... — ...dan qulayroq"]},{"id":"lesson_eng_a2_m2_visual","stepNumber":2,"type":"visual_example","title":"Do‘kon peshtaxtasi va ikki kurtka","titleRu":"Прилавок магазина и две куртки","content":"Rasmda ikki xil kiyim ko‘rsatilgan: chapda uzun yashil palto, o‘ngda esa yulduzcha belgili chegirmali ko‘k kurtka. Kassa ustida paket, xarid cheki va tangalar turibdi.","contentRu":"На иллюстрации два товара: слева длинное зелёное пальто, справа синяя куртка со знаком скидки. На прилавке видны пакет, чек и монеты.","media":{"id":"media_eng_a2_m2_shop_comparison_img","kind":"image","language":"en","source":"/lesson-media/english/a2/a2-m2-shop-comparison.png","title":"Do‘kon peshtaxtasi va kiyimlar taqqoslovi","titleUz":"Do‘kon peshtaxtasi va kiyimlar taqqoslovi","titleRu":"Сравнение одежды в магазине","alt":"Kiyim ilgichida uzun yashil palto va yulduzcha belgili ko‘k kurtka, peshtaxtada esa sumka, tangalar va chek qog‘ozi","altUz":"Kiyim ilgichida uzun yashil palto va yulduzcha belgili ko‘k kurtka, peshtaxtada esa sumka, tangalar va chek qog‘ozi","altRu":"На вешалке длинное зелёное пальто и синяя куртка со значком звезды, на прилавке пакет, монеты и бумажная лента","reviewStatus":"approved"}},{"id":"lesson_eng_a2_m2_audio","stepNumber":3,"type":"audio_simulation","title":"Tinglash: Do‘konda chegirma va xarid","titleRu":"Аудирование: Скидка и покупка в магазине","content":"Xaridor va kassir suhbatini tinglang. Qaysi kurtka arzonroq ekanini va talaba chegirmasidan keyingi narxni aniqlang.","contentRu":"Прослушайте диалог покупателя и кассира. Обратите внимание на разницу цен и студенческую скидку.","media":{"id":"media_eng_a2_m2_shop_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a2/a2-m2-shop-dialogue.wav","title":"Kiyim do‘konida narx va chegirma suhbati","titleUz":"Kiyim do‘konida narx va chegirma suhbati","titleRu":"Диалог в магазине одежды о цене и скидке","transcript":"Customer: Excuse me, how much is the green winter coat?\nCashier: The green coat is eighty dollars. The blue jacket is cheaper today — with our twenty percent student discount, it is only forty-eight dollars.\nCustomer: Forty-eight dollars? That is much better! I''ll take the blue jacket, please. May I have a receipt?\nCashier: Of course! Here is your receipt and bag.","posterImage":"/lesson-media/english/a2/a2-m2-shop-comparison.png","posterAlt":"Do‘konda ikki xil kurtka, xarid sumkasi va kassa peshtaxtasi tasviri","posterAltUz":"Do‘konda ikki xil kurtka, xarid sumkasi va kassa peshtaxtasi tasviri","posterAltRu":"Две разные куртки на вешалке, пакет и кассовый прилавок в магазине","durationSeconds":24.237,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Customer: Excuse me, how much is the green winter coat?\nCashier: The green coat is eighty dollars. The blue jacket is cheaper today — with our twenty percent student discount, it is only forty-eight dollars.\nCustomer: Forty-eight dollars? That is much better! I''ll take the blue jacket, please. May I have a receipt?\nCashier: Of course! Here is your receipt and bag.","speakerName":"Customer & Cashier"}},{"id":"lesson_eng_a2_m2_flashcards","stepNumber":4,"type":"flashcard","title":"Xarid kartochkalari","titleRu":"Карточки для покупок","content":"Yangi xarid so‘zlarining talaffuzini tinglang va ma’nosini tekshiring.","contentRu":"Послушайте произношение новой лексики и проверьте перевод.","flashcards":[{"id":"fc_eng_a2_m2_1","front":"discount","backUz":"chegirma","backRu":"скидка","partOfSpeech":"noun","ipa":"/ˈdɪskaʊnt/","ipaAmE":"/ˈdɪskaʊnt/","cefrLevel":"A2","example":"Students get a twenty percent discount on Friday.","exampleUz":"Talabalar juma kuni yigirma foizli chegirma oladi.","exampleRu":"По пятницам студенты получают скидку двадцать процентов.","audioSrc":"/lesson-media/english/a2/a2-m2-discount.wav","imageSrc":"/lesson-media/english/a2/a2-m2-shop-comparison.png","alt":"Kiyim ilgichida oltin yulduzcha belgisi osilgan ko‘k kurtka","altRu":"Синяя куртка на вешалке с золотой звёздочкой на плече","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m2_2","front":"receipt","backUz":"xarid cheki","backRu":"чек оплаты","partOfSpeech":"noun","ipa":"/rɪˈsiːt/","ipaAmE":"/rɪˈsiːt/","cefrLevel":"A2","example":"Please keep your receipt after paying at the desk.","exampleUz":"Kassada to‘lagandan keyin qog‘oz hujjatni saqlab qo‘ying.","exampleRu":"Пожалуйста, сохраните бумажный документ после оплаты на кассе.","audioSrc":"/lesson-media/english/a2/a2-m2-receipt.wav","imageSrc":"/lesson-media/english/a2/a2-m2-shop-comparison.png","alt":"Do‘kon peshtaxtasida qog‘oz lentali hujjat, yashil paket va tangalar","altRu":"На прилавке магазина длинный бумажный бланк с волнистым краем, пакет и монеты","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m2_3","front":"cheaper","backUz":"arzonroq","backRu":"дешевле","partOfSpeech":"adjective","ipa":"/ˈtʃiːpə/","ipaAmE":"/ˈtʃiːpər/","cefrLevel":"A2","example":"This blue jacket is cheaper than the winter coat.","exampleUz":"Bu ko‘k kurtka qishki paltodan arzonroq.","exampleRu":"Эта синяя куртка дешевле зимнего пальто.","audioSrc":"/lesson-media/english/a2/a2-m2-cheaper.wav","imageSrc":"/lesson-media/english/a2/a2-m2-shop-comparison.png","alt":"Kiyim ilgichidagi uzun yashil palto va ixchamroq ko‘k kurtka yorliqlari","altRu":"Длинное зелёное пальто и короткая синяя куртка с разными бирками","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m2_4","front":"how much","backUz":"qancha turadi","backRu":"сколько стоит","partOfSpeech":"phrase","ipa":"/haʊ mʌtʃ/","ipaAmE":"/haʊ mʌtʃ/","cefrLevel":"A2","example":"Excuse me, how much is this green backpack?","exampleUz":"Kechirasiz, bu yashil ryukzak qancha turadi?","exampleRu":"Извините, сколько стоит этот зелёный рюкзак?","audioSrc":"/lesson-media/english/a2/a2-m2-how-much.wav","imageSrc":"/lesson-media/english/a2/a2-m2-shop-comparison.png","alt":"Do‘kon peshtaxtasida sariq tangalar ustuni va yorliqli kiyimlar","altRu":"Ряд золотых монет на прилавке рядом с бирками на одежде","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a2_m2_match_q","stepNumber":5,"type":"interactive_question","title":"Xarid so‘zlarini moslash","titleRu":"Сопоставление слов о покупках","content":"Har bir inglizcha atamani o‘zbekcha ma’nosi bilan juftlang.","contentRu":"Соедините каждый английский термин с точным переводом.","interactiveQuestion":{"id":"q_eng_a2_m2_word_match","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A2","topic":"Shopping vocabulary matching","difficulty":"easy","questionType":"word_match","evaluationMode":"deterministic","text":"Do‘kon va narxlarga oid so‘zlarni o‘zbekcha ma’nosi bilan moslang:","textRu":"Сопоставьте слова о магазине и ценах с их значением:","options":[],"matchPairs":[{"id":"pair_a2_m2_1","left":"discount","right":"chegirma"},{"id":"pair_a2_m2_2","left":"receipt","right":"xarid cheki"},{"id":"pair_a2_m2_3","left":"cheaper","right":"arzonroq"},{"id":"pair_a2_m2_4","left":"more expensive","right":"qimmatroq"}],"explanation":"«cheaper» (arzonroq) va «more expensive» (qimmatroq) juftliklari qiyosiy sifatlarning ikki qolipini ko‘rsatadi.","explanationRu":"Пара «cheaper» и «more expensive» наглядно показывает два способа образования сравнительной степени.","wrongFeedback":"«cheaper» va «more expensive» antonim juftligini hamda «receipt» so‘zini qayta tekshiring.","wrongFeedbackRu":"Перепроверьте антонимы «cheaper» — «more expensive» и слово «receipt»."}},{"id":"lesson_eng_a2_m2_fill_q","stepNumber":6,"type":"interactive_question","title":"Narx so‘rash mashqi","titleRu":"Вопрос о цене","content":"Bo‘sh joyni kerakli so‘z bilan to‘ldiring.","contentRu":"Заполните пропуск нужным словом.","interactiveQuestion":{"id":"q_eng_a2_m2_fill_much","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"grammar","cefrLevel":"A2","topic":"How much for price","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"Excuse me, how ___ does the blue jacket cost?","text":"Bo‘sh joyga sanalmaydigan «narx» so‘rog‘i uchun to‘g‘ri so‘zni yozing: «Excuse me, how ___ does the blue jacket cost?»","textRu":"Впишите верное слово для вопроса о цене: «Excuse me, how ___ does the blue jacket cost?»","options":[],"acceptedAnswers":["much"],"explanation":"Narx va pul sanalmaydigan tushuncha bo‘lgani uchun «How much does ... cost?» deyiladi.","explanationRu":"Цена и деньги — неисчисляемое понятие, поэтому используется «How much does ... cost?».","wrongFeedback":"Narx so‘rashda «how» dan keyin sanalmaydigan otlar bilan ishlatiladigan miqdor so‘zini yozing.","wrongFeedbackRu":"Для вопроса о стоимости после «how» впишите слово, используемое с неисчисляемыми понятиями."}}]'::jsonb, '{"id":"q_eng_a2_m2_err_corr","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"grammar","cefrLevel":"A2","topic":"Error correction: Double comparative","difficulty":"medium","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"This coat is more cheaper than that one.","text":"«This coat is more cheaper than that one.» gapidagi xatoni tuzatilgan to‘g‘ri variantni tanlang:","textRu":"Выберите правильно исправленный вариант предложения «This coat is more cheaper than that one.»:","options":["This coat is most cheaper than that one.","This coat is more cheap than that one.","This coat is cheaper than that one.","This coat is cheap than that one."],"correctIndex":2,"mistakeFeedbackByOption":{"This coat is most cheaper than that one.":{"uz":"«most» orttirma daraja so‘zi va «-er» bilan birga ishlatilmaydi.","ru":"Слово «most» относится к превосходной степени и не сочетается с «-er»."},"This coat is more cheap than that one.":{"uz":"«cheap» bir bo‘g‘inli qisqa sifat, shuning uchun «more» emas «-er» qo‘shiladi.","ru":"«cheap» — короткое односложное прилагательное, ему нужен суффикс «-er», а не «more»."},"This coat is cheap than that one.":{"uz":"Ikki narsani «than» bilan taqqoslaganda sifat qiyosiy shaklda («-er») bo‘lishi shart.","ru":"При сравнении со словом «than» прилагательное должно стоять в сравнительной степени («-er»)."}},"explanation":"Qisqa «cheap» sifatiga faqat «-er» qo‘shiladi: «cheaper than». «more» ortiqcha.","explanationRu":"К короткому «cheap» добавляется только суффикс «-er»: «cheaper than», слово «more» лишнее.","wrongFeedback":"Bir bo‘g‘inli sifatlar bilan «more» emas, faqat «-er» qo‘shimchasi ishlatilishini eslang.","wrongFeedbackRu":"Вспомните, что короткие прилагательные образуют сравнительную степень только с помощью «-er»."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a2_u2_checkpoint', 'course_eng_01', 'skill_eng_vocab', 'reading', 'checkpoint', 'A2', 'mod_eng_a2_m2', 'unit_eng_a2_u2', 'Do‘kon e’lonidan chegirma va yakuniy narxni hisoblab topadi, «much/many» hamda qiyosiy sifatlarni qo‘llaydi.', 'Определяет скидку и итоговую цену из объявления, верно применяет «much/many» и сравнения.', '["node_eng_a2_m2_shopping"]'::jsonb, '2-bo‘lim sinovi: Narx va chegirma tahlili', 'Проверка раздела 2: Анализ цен и скидок', 6, 'Oziq-ovqat do‘konidagi aksiya e’lonini o‘qib foydali taklifni aniqlaysiz hamda sanaladigan va sanalmaydigan otlar bo‘yicha bilimingizni sinaysiz.', 'Вы проанализируете объявление о скидке в продуктовом магазине и проверите употребление «much/many».', 'Bu ichki 2-bo‘lim yakuniy sinovi bo‘lib, rasmiy CEFR sertifikatini bermaydi.', 'Это внутренняя проверка раздела 2; она не является официальным сертификатом CEFR.', '{"intro":{"uz":"Haqiqiy do‘konda chegirmali to‘plam va dona narxini taqqoslash to‘g‘ri qaror chiqarishga yordam beradi.","ru":"Умение сравнить акционный набор и обычную цену помогает выбрать выгодную покупку."},"learningObjective":{"uz":"O‘quvchi e’londagi chegirma shartini aniqlaydi va «How many / How much» qoidasini qo‘llaydi.","ru":"Ученик находит условия скидки в объявлении и правильно применяет «How many / How much»."},"warmUp":{"uz":"«apples» va «water» so‘zlaridan qaysi biri sanaladigan?","ru":"Какое из слов исчисляемое: «apples» или «water»?"},"vocabularyItems":[{"word":"grocery bundle","uz":"oziq-ovqat to‘plami","ru":"продуктовый набор","ipa":"/ˈɡrəʊsəri ˈbʌndl/"},{"word":"half price","uz":"yarim narx","ru":"полцены","ipa":"/hɑːf praɪs/"}],"grammarNote":{"rule":"Countable Plural (How many + -s) vs Uncountable (How much)","simpleExplanationUz":"Sanaladigan «apples, bottles» bilan «How many», sanalmaydigan «water, sugar, money» bilan «How much» ishlatiladi.","simpleExplanationRu":"С исчисляемыми во множественном числе («apples, bottles») ставится «How many», с неисчисляемыми («water, money») — «How much».","structure":"How many [countable plural]? / How much [uncountable]?","positiveExamples":["How many bottles of water do we need?"],"negativeExamples":["How much bottles of water are there? (Xato: bottles sanaladi!)"],"questions":["Which fruit bundle is cheaper?"],"commonMistakes":["Ko‘plikdagi «bottles» so‘zini «water» bilan adashtirib «How much bottles» deyish."]},"pronunciationFocus":{"uz":"«bottles» /ˈbɒtlz/ so‘zida oxirgi «-es» jarangli /z/ tovushi bilan aytiladi.","ru":"В слове «bottles» /ˈbɒtlz/ конечное «s» звучит звонко как /z/."},"examples":["Two bottles of water cost less in the weekend bundle."],"guidedPractice":{"uz":"E’londagi narx va miqdor shartlarini solishtiring.","ru":"Сравните цены и условия акции в объявлении."},"independentPractice":{"uz":"E’lon savolini, «much/many» bo‘sh joyini va muqobil xato tuzatishni bajaring.","ru":"Выполните тест по объявлению, задание с пропуском и альтернативную проверку."},"listeningRef":null,"readingRef":"lesson_eng_a2_u2_cp_concept","speakingTask":{"uz":"Qaysi to‘plam arzonroq ekanini inglizcha 1 gapda ayting.","ru":"Назовите в 1 предложении вслух, какой набор выгоднее."},"writingTask":{"uz":"Sanaladigan otlar bilan «How ...?» savolini to‘ldiring.","ru":"Заполните пропуск в вопросе с исчисляемым существительным."},"knowledgeCheck":"q_eng_a2_u2_cp_main","finalQuiz":"q_eng_a2_u2_cp_reinf","feedbackRules":{"uz":"70% dan yuqori natija 3-modulni (Takliflar va rejalar) ochadi.","ru":"Результат 70% и выше открывает модуль 3 (Приглашения и планы)."},"summaryAndRevision":{"uz":"Xato bo‘lsa, «How much bottles» xatosini tuzatish muqobili beriladi.","ru":"При ошибке доступна альтернативная проверка на исправление «How much bottles»."}}'::jsonb, '[{"id":"lesson_eng_a2_u2_cp_concept","stepNumber":1,"type":"concept","title":"2-bo‘lim sinovi tayanchi","titleRu":"Опора к проверке раздела 2","content":"E’londan foydali xaridni topishda jami narx va dona soniga qarang. Shuningdek, «bottles of water» kabi iboralarda asosiy so‘z «bottles» (sanaladigan ko‘plik) ekanini unutmang.","contentRu":"При анализе акций сравнивайте итоговую цену и количество. Помните, что в выражении «bottles of water» счёт идёт по слову «bottles» (исчисляемое множественное число)."},{"id":"lesson_eng_a2_u2_cp_q","stepNumber":2,"type":"interactive_question","title":"Do‘kon e’lonini tahlil qilish","titleRu":"Анализ объявления о скидке","content":"E’lonni o‘qing va ikki taklifni solishtirib to‘g‘ri javobni tanlang.","contentRu":"Прочтите объявление, сравните два предложения и выберите верный вывод.","interactiveQuestion":{"id":"q_eng_a2_u2_cp_main","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"reading","cefrLevel":"A2","topic":"Unit 2 Checkpoint: Comparing prices","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Fresh Market Notice: One bottle of apple juice costs 3 dollars. Our Family Bundle has two bottles of apple juice and one bag of oranges for 7 dollars total. With a student card, you get 1 dollar off the Family Bundle.","text":"Talaba kartasi bor xaridor Family Bundle (2 shisha sharbat + 1 paket apelsin) uchun qancha to‘laydi?","textRu":"Сколько заплатит покупатель со студенческой картой за Family Bundle (2 бутылки сока + 1 пакет апельсинов)?","options":["7 dollar to‘laydi, chunki chegirma faqat bitta shisha sharbatga ishlaydi","6 dollar to‘laydi, chunki talaba kartasi bilan 1 dollar chegirma bor","5 dollar to‘laydi, chunki ikki shisha sharbatning har biri yarim narxda","8 dollar to‘laydi, chunki apelsinlar alohida hisoblanadi"],"correctIndex":1,"mistakeFeedbackByOption":{"7 dollar to‘laydi, chunki chegirma faqat bitta shisha sharbatga ishlaydi":{"uz":"Matnda «With a student card, you get 1 dollar off the Family Bundle» deyilgan, ya’ni 7 dollardan 1 dollar ayriladi.","ru":"В тексте указана скидка 1 доллар именно на весь набор Family Bundle (7 - 1 = 6)."},"5 dollar to‘laydi, chunki ikki shisha sharbatning har biri yarim narxda":{"uz":"Yarim narx haqida yozilmagan; to‘plam 7 dollar, chegirma esa 1 dollar.","ru":"Про полцены в объявлении ничего не сказано; скидка составляет 1 доллар."},"8 dollar to‘laydi, chunki apelsinlar alohida hisoblanadi":{"uz":"«for 7 dollars total» — apelsin to‘plam ichiga kiradi va chegirma narxni kamaytiradi, oshirmaydi.","ru":"Апельсины уже включены в общую цену («for 7 dollars total»), а скидка уменьшает сумму."}},"explanation":"Family Bundle narxi 7 dollar, talaba kartasi esa 1 dollar chegirma beradi: 7 - 1 = 6 dollar.","explanationRu":"Набор стоит 7 долларов, а по студенческой карте действует скидка 1 доллар: итого 6 долларов.","wrongFeedback":"«7 dollars total» va «1 dollar off» shartlarini birga hisoblang.","wrongFeedbackRu":"Сверьте общую стоимость набора («7 dollars total») и размер скидки («1 dollar off»)."}}]'::jsonb, '{"id":"q_eng_a2_u2_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"grammar","cefrLevel":"A2","topic":"Quantifiers: How many","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"How ___ apples are in the shopping bag?","text":"Sanaladigan ko‘plik ot oldidan keladigan so‘zni yozing: «How ___ apples are in the shopping bag?»","textRu":"Вставьте нужное слово перед исчисляемым существительным во множественном числе: «How ___ apples are in the shopping bag?»","options":[],"acceptedAnswers":["many"],"explanation":"«apples» sanaladigan ko‘plik ot bo‘lgani uchun «How many apples...» deyiladi.","explanationRu":"Слово «apples» исчисляемое и стоит во множественном числе, поэтому используется «How many».","wrongFeedback":"«apples» sanaladigan ko‘plik ot bo‘lgani uchun «how» dan keyin ko‘plik miqdor so‘zini yozing.","wrongFeedbackRu":"Слово «apples» исчисляемое и стоит во множественном числе — выберите соответствующее слово после «how»."}'::jsonb, '{"id":"q_eng_a2_u2_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"grammar","cefrLevel":"A2","topic":"Error correction: Countable bottles","difficulty":"medium","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"How much bottles of water are there?","text":"«How much bottles of water are there?» gapidagi xatoni tuzatilgan to‘g‘ri shaklni tanlang:","textRu":"Выберите исправленный вариант вопроса «How much bottles of water are there?»:","options":["How much bottle of water are there?","How many water bottles is there?","How more bottles of water are there?","How many bottles of water are there?"],"correctIndex":3,"mistakeFeedbackByOption":{"How much bottle of water are there?":{"uz":"«bottles» sanaladigan va ko‘plikda («are there») turibdi, «much» bilan birlikka aylantirib bo‘lmaydi.","ru":"Глагол «are» требует множественного числа и слова «many», а не «much bottle»."},"How many water bottles is there?":{"uz":"Ko‘plikdagi «bottles» bilan «is» emas «are» ishlatiladi.","ru":"С существительным во множественном числе «bottles» нужен глагол «are», а не «is»."},"How more bottles of water are there?":{"uz":"«How more» ingliz tilida miqdor so‘rovi sifatida ishlatilmaydi.","ru":"Конструкция «How more» не используется для вопроса о количестве."}},"explanation":"Suvning o‘zi sanalmasa ham, «bottles» (shishalar) sanaladigan ko‘plik ot — shuning uchun «How many bottles...» to‘g‘ri.","explanationRu":"Хотя вода неисчисляема, «bottles» (бутылки) считаются во множественном числе, поэтому верно «How many bottles...».","wrongFeedback":"Gapda «bottles» ko‘plikda va «are there» ishlatilganini hisobga oling.","wrongFeedbackRu":"Обратите внимание на множественное число «bottles» и глагол «are there»."}'::jsonb, true, true, false),
  ('lesson_eng_a2_m3_plans', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'grammar', 'A2', 'mod_eng_a2_m3', 'unit_eng_a2_u3', 'O‘tgan voqealarni Past Simple da aytadi, «be going to» bilan reja tuzadi va «Would you like to...?» taklifiga javob beradi.', 'Рассказывает о прошлых событиях в Past Simple, строит планы с «be going to» и отвечает на приглашения.', '["node_eng_a2_u2_checkpoint"]'::jsonb, 'Takliflar, o‘tgan voqealar va dam olish rejasi', 'Приглашения, прошлые события и планы на выходные', 9, 'Nilufar va Jasur suhbati orqali Past Simple (went, visited), «be going to» rejasi hamda «Would you like to...?» taklif iboralarini o‘rganasiz.', 'На примере диалога Нилуфар и Жасура вы освоите Past Simple (went, visited), планы с «be going to» и вежливые приглашения.', 'Ichki modul sinovlari va A2 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест A2 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Do‘stingiz bilan kecha nima qilganingizni bo‘lishish va dam olish kuniga reja tuzish suhbatning asosiy qismidir.","ru":"Умение рассказать о вчерашнем дне и договориться о планах на выходные — основа живого общения."},"learningObjective":{"uz":"O‘quvchi Past Simple savollarida «Did + V1» shaklini qo‘llaydi, taklifga odobli javob tanlaydi va «going to» bilan reja yozadi.","ru":"Ученик правильно строит вопросы в Past Simple («Did + V1»), вежливо принимает приглашения и пишет план с «going to»."},"warmUp":{"uz":"«go» fe’lining o‘tgan zamon shakli qanday bo‘ladi? «goed» mi yoki «went»?","ru":"Как образуется прошедшее время глагола «go»: «goed» или «went»?"},"vocabularyItems":[{"word":"yesterday","uz":"kecha","ru":"вчера","ipa":"/ˈjestədeɪ/"},{"word":"be going to","uz":"rejalashtirmoq (...moqchi)","ru":"собираться (сделать)","ipa":"/biː ˈɡəʊɪŋ tuː/"},{"word":"would you like","uz":"xohlaysizmi","ru":"хотели бы вы","ipa":"/wʊd juː laɪk/"},{"word":"weekend","uz":"dam olish kunlari","ru":"выходные","ipa":"/ˌwiːkˈend/"}],"grammarNote":{"rule":"Past Simple (visited / went / Did + V1) vs Future Plans (am/is/are + going to + V1)","simpleExplanationUz":"Tugallangan o‘tgan ish uchun Past Simple (visited, went) ishlatiladi, ammo «Did» yoki «didn''t» bo‘lsa fe’l asosiy shaklga qaytadi («Did you go?», «didn''t go»). Oldindan o‘ylangan reja uchun esa «am/is/are + going to + fe’l» qo‘llaniladi.","simpleExplanationRu":"Для завершённых действий в прошлом используется Past Simple (visited, went), но после «Did / didn''t» глагол возвращается в начальную форму («Did you go?»). Для планов используется «am/is/are + going to + глагол».","structure":"Subject + went / visited ... | Did + Subject + go? | Subject + am/is/are + going to + V1","positiveExamples":["Yesterday I went to the history museum.","I''m going to visit the science fair on Saturday."],"negativeExamples":["Did you went to the park? (Xato! To‘g‘risi: Did you go to the park?)"],"questions":["What did you do yesterday?","Would you like to come with me?"],"commonMistakes":["«Did» yordamchi fe’lidan keyin yana o‘tgan zamon shaklini («Did you went») yozish yoki «going to» dan oldin «am/is/are» ni tushirib qoldirish."]},"pronunciationFocus":{"uz":"«I''d love to!» /aɪd lʌv tuː/ iborasida «d» qisqa eshitiladi va «love» ga urg‘u tushadi.","ru":"Во фразе «I''d love to!» /aɪd lʌv tuː/ главное ударение падает на «love»."},"examples":["Yesterday I went to the history museum.","Would you like to visit the science fair on Saturday? — I''d love to!"],"guidedPractice":{"uz":"Muzey va taqvim tasvirini, Nilufar va Jasur suhbatini hamda 4 ta flashcardni o‘rganing.","ru":"Рассмотрите иллюстрацию, прослушайте диалог Нилуфар и Жасура и изучите 4 карточки."},"independentPractice":{"uz":"Taklifga mos javobni tanlang, «going to» bilan reja yozing va Past Simple savol xatosini tuzating.","ru":"Выберите ответ на приглашение, напишите план с «going to» и исправьте ошибку в Past Simple."},"listeningRef":"media_eng_a2_m3_plans_dialogue","readingRef":"lesson_eng_a2_m3_concept","speakingTask":{"uz":"Do‘stingizni dam olish kunida kino yoki ko‘rgazmaga «Would you like to...?» bilan taklif qiling.","ru":"Пригласите друга на выставку или в кино на выходных с фразой «Would you like to...?»."},"writingTask":{"uz":"Yakshanba kungi rejangiz haqida «be going to» bilan 1 ta to‘liq gap yozing.","ru":"Напишите 1 полное предложение о плане на воскресенье с конструкцией «be going to»."},"knowledgeCheck":"q_eng_a2_m3_invite_conv","finalQuiz":"q_eng_a2_m3_plan_text","feedbackRules":{"uz":"«I''m going to» da bog‘lovchi fe’l tushib qolishi va «Did + went» xatosi batafsil izohlanadi.","ru":"Разбираются пропуск глагола «to be» перед «going to» и ошибка «Did + went»."},"summaryAndRevision":{"uz":"O‘tgan zamon va kelajak rejasini ajratish 3-bo‘lim sinovida tekshiriladi.","ru":"Различение прошедшего времени и планов проверяется в контрольной точке раздела 3."}}'::jsonb, '[{"id":"lesson_eng_a2_m3_concept","stepNumber":1,"type":"concept","title":"Kecha (Past Simple) va Reja (be going to)","titleRu":"Прошлое (Past Simple) и Планы (be going to)","content":"Kecha bo‘lgan ish uchun Past Simple (visited, went) ishlatiladi. Savolda esa «Did» o‘tgan zamonni olgani uchun asosiy fe’l o‘zgarmaydi («Did you go?»). Dam olish rejasiga «am/is/are going to + fe’l», taklifga esa «Would you like to...?» — «I''d love to!» ishlatiladi.","contentRu":"О вчерашних событиях говорят в Past Simple (visited, went), а в вопросе с «Did» глагол остаётся в начальной форме («Did you go?»). Для планов служит «am/is/are going to + глагол», для приглашения — «Would you like to...?».","highlightNotes":["Past Simple: I went to the museum yesterday.","Question: Did you go to the park? (NOT Did you went)","Plan: I''m going to visit the science fair.","Invitation: Would you like to come? — I''d love to!"]},{"id":"lesson_eng_a2_m3_visual","stepNumber":2,"type":"visual_example","title":"Kecha va dam olish kunlari taqvimi","titleRu":"Вчерашнее событие и план на выходные","content":"Chap tomonda kecha muzeyga borilgani, o‘ng tomonda esa dam olish kunlariga belgilangan reja va soat tasvirlangan.","contentRu":"Слева показан вчерашний поход в музей, а справа — отмеченные выходные дни, время и билет на мероприятие.","media":{"id":"media_eng_a2_m3_weekend_calendar_img","kind":"image","language":"en","source":"/lesson-media/english/a2/a2-m3-weekend-calendar.png","title":"Kecha va dam olish kunlari taqqoslamasi","titleUz":"Kecha va dam olish kunlari taqqoslamasi","titleRu":"Сравнение прошедших событий и планов на выходные","alt":"Ikki bo‘lakli rasm: chapda ustunli muzey va fotoapparat, o‘ngda ikki katagi ajratilgan taqvim, strelkali soat va chipta","altUz":"Ikki bo‘lakli rasm: chapda ustunli muzey va fotoapparat, o‘ngda ikki katagi ajratilgan taqvim, strelkali soat va chipta","altRu":"Иллюстрация из двух панелей: слева музей и фотоаппарат, справа настенный календарь с двумя выделенными клетками, часы и билет","reviewStatus":"approved"}},{"id":"lesson_eng_a2_m3_audio","stepNumber":3,"type":"audio_simulation","title":"Tinglash: Nilufar va Jasurning rejalari","titleRu":"Аудирование: Планы Нилуфар и Жасура","content":"Suhbatni tinglang: Jasur kecha qayerga bordi va Nilufar shanba kuni soat nechada ko‘rgazmaga bormoqchi?","contentRu":"Послушайте диалог: куда вчера ходил Жасур и во сколько Нилуфар собирается на научную выставку в субботу?","media":{"id":"media_eng_a2_m3_plans_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a2/a2-m3-plans-dialogue.wav","title":"O‘tgan kun va dam olish rejasi suhbati","titleUz":"O‘tgan kun va dam olish rejasi suhbati","titleRu":"Диалог о прошедшем дне и планах на выходные","transcript":"Nilufar: Hi Jasur! What did you do yesterday?\nJasur: Yesterday I went to the history museum with my cousin and took some photos. What about this weekend?\nNilufar: I''m going to visit the science fair on Saturday at half past two in the afternoon. Would you like to come with me?\nJasur: I''d love to! Let''s meet outside the entrance at two fifteen.","posterImage":"/lesson-media/english/a2/a2-m3-weekend-calendar.png","posterAlt":"Chapda ustunli bino va fotoapparat, o‘ngda kalendar va chipta tasvirlangan","posterAltUz":"Chapda ustunli bino va fotoapparat, o‘ngda kalendar va chipta tasvirlangan","posterAltRu":"Слева здание с колоннами и камера, справа настенный календарь и билет","durationSeconds":20.962,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Nilufar: Hi Jasur! What did you do yesterday?\nJasur: Yesterday I went to the history museum with my cousin and took some photos. What about this weekend?\nNilufar: I''m going to visit the science fair on Saturday at half past two in the afternoon. Would you like to come with me?\nJasur: I''d love to! Let''s meet outside the entrance at two fifteen.","speakerName":"Nilufar & Jasur"}},{"id":"lesson_eng_a2_m3_flashcards","stepNumber":4,"type":"flashcard","title":"Vaqt va taklif kartochkalari","titleRu":"Карточки времени и приглашений","content":"Talaffuzni tinglang va har bir iboraning vazifasini eslang.","contentRu":"Прослушайте произношение и закрепите употребление каждой фразы.","flashcards":[{"id":"fc_eng_a2_m3_1","front":"yesterday","backUz":"kecha","backRu":"вчера","partOfSpeech":"adverb","ipa":"/ˈjestədeɪ/","ipaAmE":"/ˈjestərdeɪ/","cefrLevel":"A2","example":"Yesterday I visited the history museum with my cousin.","exampleUz":"Kecha men amakivachcham bilan tarix muzeyiga bordim.","exampleRu":"Вчера я сходил в исторический музей с двоюродным братом.","audioSrc":"/lesson-media/english/a2/a2-m3-yesterday.wav","imageSrc":"/lesson-media/english/a2/a2-m3-weekend-calendar.png","alt":"Chap panelda ustunli bino va fotoapparat, o‘ngda esa oq katakli taqvim","altRu":"Левая карточка со зданием с колоннами и камерой, рядом настенная сетка дат","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m3_2","front":"be going to","backUz":"rejalashtirmoq","backRu":"намереваться","partOfSpeech":"phrase","ipa":"/biː ˈɡəʊɪŋ tuː/","ipaAmE":"/biː ˈɡoʊɪŋ tuː/","cefrLevel":"A2","example":"We are going to meet outside the entrance at two fifteen.","exampleUz":"Biz soat ikkiyu o‘n beshda kirish oldida uchrashamiz.","exampleRu":"Мы встретимся у входа в два пятнадцать.","audioSrc":"/lesson-media/english/a2/a2-m3-be-going-to.wav","imageSrc":"/lesson-media/english/a2/a2-m3-weekend-calendar.png","alt":"O‘rta ko‘k strelka orqali taqvim va tadbir chiptasiga ulangan rasm","altRu":"Синяя стрелка перехода от прошлой карточки к календарю и билету","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m3_3","front":"would you like","backUz":"istaysizmi","backRu":"желаете ли","partOfSpeech":"phrase","ipa":"/wʊd juː laɪk/","ipaAmE":"/wʊd juː laɪk/","cefrLevel":"A2","example":"Would you like to join our robotics club on Saturday?","exampleUz":"Shanba kuni robototexnika klubimizga qo‘shilishni istaysizmi?","exampleRu":"Хотите присоединиться к нашему клубу робототехники в субботу?","audioSrc":"/lesson-media/english/a2/a2-m3-would-you-like.wav","imageSrc":"/lesson-media/english/a2/a2-m3-weekend-calendar.png","alt":"Yulduzchali tadbir chiptasi va soat ko‘rsatilgan o‘ng panel","altRu":"Правая панель с билетом со звёздочкой и циферблатом часов","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m3_4","front":"weekend","backUz":"hafta oxiri","backRu":"суббота и воскресенье","partOfSpeech":"noun","ipa":"/ˌwiːkˈend/","ipaAmE":"/ˈwiːkend/","cefrLevel":"A2","example":"What are your plans for this weekend?","exampleUz":"Bu shanba-yakshanba uchun rejalaringiz qanday?","exampleRu":"Какие у вас планы на конец этой недели?","audioSrc":"/lesson-media/english/a2/a2-m3-weekend.wav","imageSrc":"/lesson-media/english/a2/a2-m3-weekend-calendar.png","alt":"O‘ng chetidagi ikki ustuni yashil rangda ajratilgan oy taqvimi jadvali","altRu":"Сетка календаря, где два последних столбца выделены зелёным цветом","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a2_m3_conv_q","stepNumber":5,"type":"interactive_question","title":"Taklifga javob berish","titleRu":"Ответ на приглашение","content":"Do‘stingizning kutubxonaga borish taklifiga eng tabiiy va grammatik to‘g‘ri javobni tanlang.","contentRu":"Выберите естественный и грамматически верный ответ на приглашение друга.","interactiveQuestion":{"id":"q_eng_a2_m3_invite_conv","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A2","topic":"Responding to invitations","difficulty":"easy","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Nilufar: «Would you like to come to the library on Sunday?»","Jasur: «___»"],"text":"Jasur yakshanba kuni taklifni mamnuniyat bilan qabul qilsa, qaysi javobni aytadi?","textRu":"Какой фразой Жасур вежливо примет приглашение в библиотеку?","options":["Yes, I am like to! When we meeting?","I went to the library yesterday afternoon.","No, I don''t went there on Sunday.","Yes, I''d love to! What time shall we meet?"],"correctIndex":3,"mistakeFeedbackByOption":{"Yes, I am like to! When we meeting?":{"uz":"«I am like to» xato — «Would you like to» taklifiga «I''d love to» (I would love to) deb javob beriladi.","ru":"Фраза «I am like to» неверна; на приглашение отвечают «I''d love to»."},"I went to the library yesterday afternoon.":{"uz":"Bu javob kechagi ish haqida, ammo Nilufar yakshanba kungi taklif uchun rozilik so‘ramoqda.","ru":"Это рассказ о вчерашнем дне, а не ответ на приглашение на воскресенье."},"No, I don''t went there on Sunday.":{"uz":"«don''t went» grammatik jihatdan xato (o‘tgan inkor — «didn''t go», kelajak — «can''t»).","ru":"Сочетание «don''t went» грамматически ошибочно."}},"explanation":"«Would you like to...?» taklifini qabul qilishda «Yes, I''d love to!» eng tabiiy ibora.","explanationRu":"Фраза «Yes, I''d love to!» — естественное согласие на приглашение «Would you like to...?».","wrongFeedback":"Taklifni xushmuomalalik bilan qabul qilish iborasi va uchrashuv vaqtini so‘raydigan to‘g‘ri savol tuzilishini tanlang.","wrongFeedbackRu":"Выберите вежливую форму согласия на приглашение и грамматически верный вопрос о времени встречи."}},{"id":"lesson_eng_a2_m3_text_q","stepNumber":6,"type":"interactive_question","title":"Reja tuzib yozish","titleRu":"Написание плана","content":"Berilgan ma’no asosida yakshanba kungi rejangizni ingliz tilida yozing.","contentRu":"Напишите предложение о своём плане на воскресенье по-английски.","interactiveQuestion":{"id":"q_eng_a2_m3_plan_text","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"writing","cefrLevel":"A2","topic":"Writing a plan with going to","difficulty":"medium","questionType":"text_input","evaluationMode":"deterministic","text":"«Men yakshanba kuni buvimni ziyorat qilmoqchiman» fikrini reja tuzilmasi bilan inglizcha to‘liq gap qilib yozing («I ...»):","textRu":"Переведите на английский предложение о плане: «Я собираюсь навестить бабушку в воскресенье» (начните с «I ...»):","options":[],"acceptedAnswers":["I''m going to visit my grandmother on Sunday","I am going to visit my grandmother on Sunday","I''m going to visit my grandma on Sunday","I am going to visit my grandma on Sunday","I''m going to visit grandma on Sunday","I am going to visit grandma on Sunday","I''m going to see my grandmother on Sunday","I am going to see my grandmother on Sunday"],"explanation":"Reja uchun «I''m / I am going to visit my grandmother on Sunday.» tuzilmasi ishlatiladi.","explanationRu":"Для плана используется конструкция «I''m / I am going to visit my grandmother on Sunday.».","wrongFeedback":"Ega + to be (am/is/are) + going to + asosiy fe’l + to‘ldiruvchi va vaqt holi tartibini saqlab, inglizcha to‘liq gap tuzing.","wrongFeedbackRu":"Соблюдайте порядок слов: подлежащее + to be (am/is/are) + going to + основной глагол + дополнение и указание времени."}}]'::jsonb, '{"id":"q_eng_a2_m3_err_did","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A2","topic":"Error correction: Past Simple question","difficulty":"medium","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"Did you went to the park yesterday?","text":"«Did you went to the park yesterday?» savolidagi grammatik xatoni tuzatilgan to‘g‘ri variantni tanlang:","textRu":"Выберите правильно исправленный вариант вопроса «Did you went to the park yesterday?»:","options":["Do you went to the park yesterday?","Did you going to the park yesterday?","Did you go to the park yesterday?","Were you go to the park yesterday?"],"correctIndex":2,"mistakeFeedbackByOption":{"Do you went to the park yesterday?":{"uz":"«yesterday» o‘tgan zamon bo‘lgani uchun yordamchi fe’l «Do» emas «Did» bo‘lishi kerak.","ru":"Со словом «yesterday» нужен прошедший вспомогательный глагол «Did», а не «Do»."},"Did you going to the park yesterday?":{"uz":"«Did» dan keyin «-ing» shakli emas, fe’lning asosiy shakli («go») keladi.","ru":"После «Did» ставится начальная форма глагола («go»), а не форма с «-ing»."},"Were you go to the park yesterday?":{"uz":"«go» harakat fe’li savolida «Were» emas «Did» yordamchi fe’li ishlatiladi.","ru":"Для вопроса с глаголом действия «go» используется «Did», а не «Were»."}},"explanation":"Past Simple savolida «Did» o‘tgan zamonni ko‘rsatgani uchun asosiy fe’l boshlang‘ich shaklda («go») yoziladi.","explanationRu":"В вопросе Past Simple показатель времени уже в слове «Did», поэтому смысловой глагол ставится в начальную форму («go»).","wrongFeedback":"«Did» yordamchi fe’lidan keyin asosiy fe’lning birinchi (boshlang‘ich) shakli kelishini eslang.","wrongFeedbackRu":"Вспомните правило: после «Did» всегда используется начальная форма смыслового глагола (V1)."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a2_u3_checkpoint', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'checkpoint', 'A2', 'mod_eng_a2_m3', 'unit_eng_a2_u3', 'O‘tgan hafta voqealari va ertangi reja zamonlarini aralashtirmay qo‘llaydi, taklifni odob bilan rad etadi.', 'Чётко различает маркеры прошлого и будущего с «going to», вежливо отклоняет приглашение с причиной.', '["node_eng_a2_m3_plans"]'::jsonb, '3-bo‘lim sinovi: O‘tgan zamon va kelajak rejasi', 'Проверка раздела 3: Прошлое и планы на будущее', 6, 'Kecha bo‘lib o‘tgan futbol o‘yini va ertangi kino rejasini vaqt ko‘rsatkichlariga qarab farqlaysiz hamda taklifni muloyimlik bilan rad etishni sinaysiz.', 'Вы отработаете различие между прошедшими событиями и планами на завтра, а также вежливый отказ от приглашения.', 'Bu ichki 3-bo‘lim yakuniy sinovi bo‘lib, rasmiy CEFR sertifikatini bermaydi.', 'Это внутренняя проверка раздела 3; она не является официальным сертификатом CEFR.', '{"intro":{"uz":"Suhbatda «last week» va «tomorrow» so‘zlariga qarab zamonni to‘g‘ri tanlash muhim.","ru":"В разговоре важно выбирать время глагола по маркерам «last week» и «tomorrow»."},"learningObjective":{"uz":"O‘quvchi vaqt belgisiga mos zamonni tanlaydi, «going to» gapini tartiblaydi va rad javobini odobli beradi.","ru":"Ученик соотносит время с временным маркером, собирает фразу с «going to» и вежливо отказывается от приглашения."},"warmUp":{"uz":"«tomorrow» so‘zi bilan «played» ishlatiladimi yoki «are going to»?","ru":"Что сочетается со словом «tomorrow»: «played» или «are going to»?"},"vocabularyItems":[{"word":"last week","uz":"o‘tgan hafta","ru":"на прошлой неделе","ipa":"/lɑːst wiːk/"},{"word":"sorry, I can''t","uz":"uzr, bora olmayman","ru":"извини, я не смогу","ipa":"/ˈsɒri aɪ kɑːnt/"}],"grammarNote":{"rule":"Time Markers Control Tense (yesterday / last week -> Past Simple; tomorrow / next weekend -> be going to)","simpleExplanationUz":"«yesterday, last week» ko‘rsatkichlari Past Simple ni, «tomorrow, tonight, after lunch» esa reja tuzilmasini («be going to») talab qiladi.","simpleExplanationRu":"Маркеры «yesterday, last week» требуют Past Simple, а «tomorrow, tonight, after lunch» указывают на план с «be going to».","structure":"We watched ... last week. | We are going to watch ... tomorrow.","positiveExamples":["Yesterday we played tennis, and tomorrow we are going to watch a film."],"negativeExamples":["Yesterday we are going to play tennis. (Xato: vaqt o‘tgan!)"],"questions":["Would you like to go to the cinema tonight?"],"commonMistakes":["Taklifni rad etganda sababsiz qo‘pol «No» deyish yoki vaqt ko‘rsatkichiga zid zamon tanlash."]},"pronunciationFocus":{"uz":"«can''t» BrE da /kɑːnt/, AmE da /kænt/ shaklida aniq talaffuz qilinadi.","ru":"Слово «can''t» произносится чётко: в BrE /kɑːnt/, в AmE /kænt/."},"examples":["I''m sorry, I can''t come tonight because I have to help my parents."],"guidedPractice":{"uz":"Vaqt ko‘rsatkichlarini tekshiring.","ru":"Сверьте временные маркеры перед выбором ответа."},"independentPractice":{"uz":"Zamon tanlash testi, gap tartiblash va taklifni rad etish muqobilini bajaring.","ru":"Выполните тест на выбор времени, порядок слов и альтернативный диалог."},"listeningRef":null,"readingRef":"lesson_eng_a2_u3_cp_concept","speakingTask":{"uz":"Kecha qilgan bitta ishingiz va ertangi bitta rejangizni aytib bering.","ru":"Назовите одно вчерашнее действие и один план на завтра."},"writingTask":{"uz":"«We are going to meet after lunch.» gapini tartiblang.","ru":"Составьте предложение «We are going to meet after lunch.»."},"knowledgeCheck":"q_eng_a2_u3_cp_main","finalQuiz":"q_eng_a2_u3_cp_reinf","feedbackRules":{"uz":"70% dan yuqori natija 4-modulni (E’lonlar va xabar yozish) ochadi.","ru":"Результат 70% и выше открывает модуль 4 (Объявления и сообщения)."},"summaryAndRevision":{"uz":"Xato qilinsa, taklifni muloyim rad etish suhbati muqobil sifatida beriladi.","ru":"При ошибке предлагается альтернативное задание на вежливый отказ."}}'::jsonb, '[{"id":"lesson_eng_a2_u3_cp_concept","stepNumber":1,"type":"concept","title":"Vaqt belgisiga qarab zamon tanlash","titleRu":"Выбор времени по временному маркеру","content":"Har bir gapda vaqt so‘ziga e’tibor bering: «yesterday / last Saturday» o‘tgan zamon (played, watched) talab qiladi, «tomorrow / this weekend» esa «am/is/are going to» rejasi bilan keladi.","contentRu":"Всегда проверяйте маркер времени в предложении: «yesterday / last Saturday» требуют Past Simple, а «tomorrow / this weekend» — конструкции «am/is/are going to»."},{"id":"lesson_eng_a2_u3_cp_q","stepNumber":2,"type":"interactive_question","title":"O‘tgan ish va ertangi reja farqi","titleRu":"Различие прошлого и будущего плана","content":"Suhbatdagi vaqt ko‘rsatkichlariga mos keladigan to‘g‘ri javobni tanlang.","contentRu":"Выберите реплику, которая верно согласуется с временными маркерами.","interactiveQuestion":{"id":"q_eng_a2_u3_cp_main","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A2","topic":"Unit 3 Checkpoint: Past vs Going to","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Sardorning «What did you do last Saturday, and what are your plans for tomorrow?» savoliga qaysi javob vaqt jihatdan to‘g‘ri?","textRu":"Какой ответ на вопрос Сардора «What did you do last Saturday, and what are your plans for tomorrow?» грамматически верен?","options":["Last Saturday we are going to watch a football match, and tomorrow we watched the cinema.","Last Saturday we watch a football match, and tomorrow we going to visit the cinema.","Last Saturday we watched a football match, and tomorrow we are going to go to the cinema.","Last Saturday we didn''t watched a match, and tomorrow we visit the cinema yesterday."],"correctIndex":2,"mistakeFeedbackByOption":{"Last Saturday we are going to watch a football match, and tomorrow we watched the cinema.":{"uz":"Zamonlar teskari qo‘yilgan: «Last Saturday» o‘tgan zamon («watched»), «tomorrow» esa reja («are going to»).","ru":"Времена перепутаны местами: для «Last Saturday» нужен Past Simple, а для «tomorrow» — «are going to»."},"Last Saturday we watch a football match, and tomorrow we going to visit the cinema.":{"uz":"«Last Saturday» bilan «watched» kerak, «we going to» da esa «are» bog‘lovchi fe’li tushib qolgan.","ru":"Для «Last Saturday» нужна форма «watched», а перед «going to» пропущен глагол «are»."},"Last Saturday we didn''t watched a match, and tomorrow we visit the cinema yesterday.":{"uz":"«didn''t» dan keyin «watched» emas «watch» keladi va «tomorrow» bilan «yesterday» bir gapda mantiqsiz.","ru":"После «didn''t» ставится «watch» без «-ed», а «tomorrow» и «yesterday» противоречат друг другу."}},"explanation":"«Last Saturday» -> Past Simple («watched»), «tomorrow» -> reja («are going to go»).","explanationRu":"«Last Saturday» требует Past Simple («watched»), а «tomorrow» — плана «are going to go».","wrongFeedback":"«Last Saturday» uchun o‘tgan zamon (-ed) va «tomorrow» uchun «to be + going to» reja shaklini tekshiring.","wrongFeedbackRu":"Сверьте прошедшее время для «Last Saturday» и конструкцию плана «to be + going to» для «tomorrow»."}}]'::jsonb, '{"id":"q_eng_a2_u3_cp_reinf","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A2","topic":"Future plan word order","difficulty":"easy","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Biz tushlikdan keyin uchrashamiz (uchrashmoqchimiz)» gapini to‘g‘ri tartibda tuzing:","textRu":"Составьте предложение «Мы собираемся встретиться после обеда» в правильном порядке:","options":[],"orderedTokens":["We","are","going to","meet","after","lunch."],"acceptedAnswers":["We are going to meet after lunch."],"explanation":"To‘g‘ri tartib: We + are + going to + meet + after + lunch.","explanationRu":"Правильный порядок: We + are + going to + meet + after + lunch.","wrongFeedback":"Gapni ega + to be + kelajak reja shakli + asosiy fe’l + oxirida vaqt iborasi tartibida tuzing.","wrongFeedbackRu":"Составьте предложение в порядке: подлежащее + to be + конструкция будущего плана + основной глагол + указание времени в конце."}'::jsonb, '{"id":"q_eng_a2_u3_cp_alt","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"speaking","cefrLevel":"A2","topic":"Declining an invitation politely","difficulty":"medium","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Aziza: «Would you like to go to the concert with us tonight?»","Timur: «___»"],"text":"Qayta sinov: Timur bugun kechqurun band bo‘lsa, taklifni qanday odob va sabab bilan rad etadi?","textRu":"Повторная проверка: как Тимур вежливо отклонит приглашение, объяснив причину?","options":["No, I don''t want your concert. Goodbye.","Sorry, I couldn''t went yesterday evening.","I''m sorry, I can''t. I have to finish my history project tonight.","Yes, I''d love to, so I am staying at home."],"correctIndex":2,"mistakeFeedbackByOption":{"No, I don''t want your concert. Goodbye.":{"uz":"Bu juda qo‘pol rad javobi; A2 muloqotida «I''m sorry, I can''t» va qisqa sabab aytiladi.","ru":"Это слишком резкий отказ; вежливо сказать «I''m sorry, I can''t» и указать причину."},"Sorry, I couldn''t went yesterday evening.":{"uz":"«couldn''t went» grammatik xato va savol bugun kechqurun («tonight») haqida.","ru":"«couldn''t went» грамматически неверно, к тому же речь идёт о сегодняшнем вечере («tonight»)."},"Yes, I''d love to, so I am staying at home.":{"uz":"«Yes, I''d love to» rozilik bildiradi, uyda qolish bilan mantiqan mos kelmaydi.","ru":"«Yes, I''d love to» означает согласие, что противоречит «staying at home»."}},"explanation":"«I''m sorry, I can''t» + sabab («I have to finish...») — taklifni odobli rad etish qolipi.","explanationRu":"«I''m sorry, I can''t» с кратким объяснением причины — вежливая форма отказа.","wrongFeedback":"Taklifni odobli uzr bilan rad etish va bunga qisqa, mantiqiy sabab keltirish qolipidagi variantni tanlang.","wrongFeedbackRu":"Выберите вариант с вежливым извинением при отказе и краткой логичной причиной."}'::jsonb, true, true, false),
  ('lesson_eng_a2_m4_messages', 'course_eng_01', 'skill_eng_reading', 'writing', 'writing', 'A2', 'mod_eng_a2_m4', 'unit_eng_a2_u4', 'Jadval o‘zgarishi haqidagi e’lonni o‘qib tushunadi va «before / after / then» hamda «can / have to» bilan qisqa xabar yozadi.', 'Понимает объявления об изменении расписания и пишет короткое сообщение с «before / after / then» и «can / have to».', '["node_eng_a2_u3_checkpoint"]'::jsonb, 'Qisqa e’lonlar va uchrashuv xabarlari', 'Короткие объявления и сообщения о встрече', 9, 'Vokzal va klub e’lonlaridan yangi vaqt va joyni topishni, so‘ng do‘stingizga «before / then» va «have to / can» yordamida qisqa xabar yozishni o‘rganasiz.', 'Вы научитесь находить новое время и место в объявлениях и писать другу сообщение с «before / then» и «have to / can».', 'Bu mustaqil yozma mashq va o‘zini baholash vositasidir; rasmiy CEFR sertifikati bermaydi.', 'Это самостоятельное письменное задание и самооценка; оно не даёт официальный сертификат CEFR.', '{"intro":{"uz":"Xona yoki poyezd vaqti o‘zgarganda e’londan aniq dalilni tez topish va do‘stga xabar berish juda muhim.","ru":"При изменении расписания важно быстро понять детали объявления и предупредить друга сообщением."},"learningObjective":{"uz":"O‘quvchi e’londagi o‘zgarishni aniqlaydi, «before / after / then» bilan 3–4 gapli xabar yozadi va «have to» ni qo‘llaydi.","ru":"Ученик находит изменения в объявлении, пишет сообщение из 3–4 фраз с «before / then» и использует «have to»."},"warmUp":{"uz":"Uchrashuv xona raqami o‘zgarsa, do‘stingizga xabarda qaysi 3 ma’lumotni albatta yozasiz?","ru":"Какие 3 детали вы обязательно напишете другу, если время и место встречи изменились?"},"vocabularyItems":[{"word":"delayed","uz":"kechiktirilgan","ru":"задержан","ipa":"/dɪˈleɪd/"},{"word":"platform","uz":"vokzal perroni","ru":"перрон вокзала","ipa":"/ˈplætfɔːm/"},{"word":"have to","uz":"majbur bo‘lmoq","ru":"приходиться","ipa":"/ˈhæf tuː/"},{"word":"before","uz":"oldin (avval)","ru":"до (перед тем как)","ipa":"/bɪˈfɔː/"}],"grammarNote":{"rule":"Time Connectors (before, after, then) + Modals (can / have to)","simpleExplanationUz":"Voqealar ketma-ketligini bog‘lash uchun «before» (oldin), «after» (keyin), «then» (so‘ng) ishlatiladi. Zarurat uchun «have to», imkoniyat yoki iltimos uchun «can» qo‘llanadi: «We have to arrive before four o''clock. Can you meet me at Gate 2?»","simpleExplanationRu":"Для последовательности действий используйте «before» (до), «after» (после), «then» (затем). Для необходимости — «have to», для просьбы — «can».","structure":"We have to [verb] before [time]. Then we can [verb].","positiveExamples":["We have to arrive at Platform 5 before 14:30.","Can you bring the tickets? Then we can sit together."],"negativeExamples":["We have to arriving early. (Xato! «have to» dan keyin fe’l asosiy shaklda keladi.)"],"questions":["Can you meet me outside Gate 2 before three o''clock?"],"commonMistakes":["«have to» ni 3-shaxs birlikda «has to» qilmaslik yoki «before» bilan «after» ma’nosini almashtirib qo‘yish."]},"pronunciationFocus":{"uz":"«delayed» /dɪˈleɪd/ so‘zida urg‘u ikkinchi bo‘g‘inga tushadi; «have to» bog‘lanishda /ˈhæftə/ kabi eshitiladi.","ru":"В слове «delayed» /dɪˈleɪd/ ударение на втором слоге; сочетание «have to» в беглой речи звучит как /ˈhæftə/."},"examples":["The afternoon club moved from Room 12 to Room 24 after three o''clock.","We have to bring our notebooks before the session starts."],"guidedPractice":{"uz":"Vokzal soati va smartfon xabari tasvirini ko‘rib, 4 ta flashcardni mustahkamlang.","ru":"Изучите иллюстрацию вокзала и смартфона и закрепите 4 карточки."},"independentPractice":{"uz":"Klub e’lonini tahlil qiling, do‘stingizga xabar yozing va modal zarurat bo‘sh joyini to‘ldiring.","ru":"Проанализируйте объявление клуба, напишите сообщение другу и заполните пропуск с «have to»."},"listeningRef":null,"readingRef":"lesson_eng_a2_m4_visual","speakingTask":{"uz":"Yozgan xabaringizni ovoz chiqarib o‘qing va o‘zingizni tekshiring.","ru":"Прочитайте написанное сообщение вслух."},"writingTask":{"uz":"Yangi vaqt va joy haqida 3–4 gapli xabar yozish.","ru":"Написание сообщения из 3–4 предложений о новом времени и месте."},"knowledgeCheck":"q_eng_a2_m4_notice_mcq","finalQuiz":"q_eng_a2_m4_writing_prompt","feedbackRules":{"uz":"O‘quvchi 3 mezon asosida xabarini tekshiradi va «have to» bo‘sh joyini mustahkamlaydi.","ru":"Ученик проверяет письмо по 3 критериям и закрепляет конструкцию «have to»."},"summaryAndRevision":{"uz":"E’lon o‘qish va vaqt bog‘lovchilari A2 yakuniy imtihoniga tayyorlaydi.","ru":"Чтение объявлений и связки времени готовят к итоговому тесту A2."}}'::jsonb, '[{"id":"lesson_eng_a2_m4_concept","stepNumber":1,"type":"concept","title":"Xabarlarda vaqt bog‘lovchilari va modallar","titleRu":"Связки времени и модальные глаголы в сообщениях","content":"Qisqa xabarda harakat tartibini «before» (avval), «after» (keyin) va «then» (so‘ng) bilan bog‘lang. Zaruratni «have to», iltimosni esa «Can you...?» bilan ayting.","contentRu":"В коротком сообщении соединяйте шаги словами «before» (до), «after» (после) и «then» (затем). Необходимость передавайте через «have to», а вежливую просьбу — через «Can you...?».","highlightNotes":["before 16:00 — soat 16:00 dan oldin","after the class — darsdan keyin","then meet at Gate 2 — so‘ng 2-darvozada uchrashing","We have to arrive early / Can you call me?"]},{"id":"lesson_eng_a2_m4_visual","stepNumber":2,"type":"visual_example","title":"Vokzal e’loni va mobil xabar","titleRu":"Вокзал и сообщение в телефоне","content":"Rasmda poyezd bekati, osma soat va telefonda kelgan ogohlantirish xabari ko‘rsatilgan. O‘zgarishni bilganingizdan so‘ng do‘stingizga aniq vaqt va joyni yozib yuboring.","contentRu":"На рисунке изображены перрон вокзала, часы и экран смартфона с уведомлением о задержке. Получив объявление, важно сразу сообщить другу новое время и место.","media":{"id":"media_eng_a2_m4_station_message_img","kind":"image","language":"en","source":"/lesson-media/english/a2/a2-m4-station-message.png","title":"Vokzal perroni va smartfon xabari","titleUz":"Vokzal perroni va smartfon xabari","titleRu":"Перрон вокзала и сообщение на смартфоне","alt":"Vokzal soyaboni ostida turgan poyezd, osma strelkali soat va ekranda rangli yozishma pufakchalari ko‘ringan smartfon","altUz":"Vokzal soyaboni ostida turgan poyezd, osma strelkali soat va ekranda rangli yozishma pufakchalari ko‘ringan smartfon","altRu":"Поезд под навесом вокзала, подвесные стрелочные часы и смартфон с цветными окнами сообщений","reviewStatus":"approved"}},{"id":"lesson_eng_a2_m4_flashcards","stepNumber":3,"type":"flashcard","title":"E’lon va xabar kartochkalari","titleRu":"Карточки объявлений и сообщений","content":"So‘zlarning talaffuzini tinglang va ma’nosini tekshiring.","contentRu":"Послушайте произношение слов и проверьте перевод.","flashcards":[{"id":"fc_eng_a2_m4_1","front":"delayed","backUz":"kechikkan","backRu":"задержан","partOfSpeech":"adjective","ipa":"/dɪˈleɪd/","ipaAmE":"/dɪˈleɪd/","cefrLevel":"A2","example":"The train to Samarkand is delayed by thirty minutes.","exampleUz":"Samarqand poyezdi o‘ttiz daqiqaga ortga surildi.","exampleRu":"Поезд в Самарканд отложен на тридцать минут.","audioSrc":"/lesson-media/english/a2/a2-m4-delayed.wav","imageSrc":"/lesson-media/english/a2/a2-m4-station-message.png","alt":"Smartfon ekranida sariq undov belgisi tushirilgan ogohlantirish qutisi","altRu":"На экране смартфона жёлтое окно с восклицательным знаком","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m4_2","front":"platform","backUz":"vokzal perroni","backRu":"перрон вокзала","partOfSpeech":"noun","ipa":"/ˈplætfɔːm/","ipaAmE":"/ˈplætfɔːrm/","cefrLevel":"A2","example":"Our train leaves from Platform 5 at two thirty.","exampleUz":"Bizning poyezd soat ikkiyu o‘ttizda beshinchi yo‘lakdan jo‘naydi.","exampleRu":"Наш поезд отправляется с пятого пути в два тридцать.","audioSrc":"/lesson-media/english/a2/a2-m4-platform.wav","imageSrc":"/lesson-media/english/a2/a2-m4-station-message.png","alt":"Ko‘k soyabon ostidagi poyezd vagonlari va sariq xavfsizlik chizig‘i","altRu":"Состав под навесом станции у жёлтой полосы безопасности","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m4_3","front":"have to","backUz":"majbur bo‘lmoq","backRu":"приходиться","partOfSpeech":"phrase","ipa":"/ˈhæf tuː/","ipaAmE":"/ˈhæf tuː/","cefrLevel":"A2","example":"We have to text Karim before we walk to the gate.","exampleUz":"Darvozaga yurishdan oldin Karimga xabar yozishimiz shart.","exampleRu":"Нам нужно написать Кариму перед тем, как пойти к выходу.","audioSrc":"/lesson-media/english/a2/a2-m4-have-to.wav","imageSrc":"/lesson-media/english/a2/a2-m4-station-message.png","alt":"Soat strelkasi va jo‘nab ketish chizig‘i oldidagi temir yo‘l bekati","altRu":"Стрелочный циферблат над поездом и экран переписки на смартфоне","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_a2_m4_4","front":"before","backUz":"oldin (avval)","backRu":"до (перед)","partOfSpeech":"preposition","ipa":"/bɪˈfɔː/","ipaAmE":"/bɪˈfɔːr/","cefrLevel":"A2","example":"Please arrive at the station ten minutes before departure.","exampleUz":"Iltimos, jo‘nashdan o‘n daqiqa oldin bekatga keling.","exampleRu":"Пожалуйста, приходите на станцию за десять минут до отправления.","audioSrc":"/lesson-media/english/a2/a2-m4-before.wav","imageSrc":"/lesson-media/english/a2/a2-m4-station-message.png","alt":"Osma soat va xabar yuborish tugmasi ko‘rsatilgan telefon rasmi","altRu":"Настенный циферблат рядом со смартфоном и зелёной кнопкой отправки","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_a2_m4_read_q","stepNumber":4,"type":"interactive_question","title":"Klub e’lonini o‘qish","titleRu":"Чтение объявления клуба","content":"E’londagi vaqt va xona o‘zgarishini o‘qing hamda to‘g‘ri qarorni tanlang.","contentRu":"Прочтите объявление о переносе занятия и выберите верное решение.","interactiveQuestion":{"id":"q_eng_a2_m4_notice_mcq","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A2","topic":"Reading public notices","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Notice: Today''s English Debate Club will not meet in Room 12 at 15:00. Because of repairs, we are moving to Room 24, and the meeting starts at 15:30. Please arrive five minutes before 15:30.","text":"E’longa ko‘ra, klub a’zolari bugun soat nechada va qaysi xonada bo‘lishi kerak?","textRu":"К какому времени и в какой кабинет должны прийти участники клуба согласно объявлению?","options":["Soat 15:00 da 12-xonada yig‘ilishadi, so‘ng 24-xonaga o‘tishadi","Ta’mirlash sababli bugungi klub mashg‘uloti bekor qilingan","Soat 15:25 gacha 24-xonaga kelishlari kerak, chunki majlis 15:30 da boshlanadi","Soat 15:35 da 24-xonaga kelishlari mumkin"],"correctIndex":2,"mistakeFeedbackByOption":{"Soat 15:00 da 12-xonada yig‘ilishadi, so‘ng 24-xonaga o‘tishadi":{"uz":"Matnda «will not meet in Room 12 at 15:00» deb aniq rad etilgan.","ru":"В тексте прямо сказано: «will not meet in Room 12 at 15:00»."},"Ta’mirlash sababli bugungi klub mashg‘uloti bekor qilingan":{"uz":"Klub bekor qilinmagan, balki 24-xonaga va soat 15:30 ga ko‘chirilgan.","ru":"Занятие не отменено, а перенесено в кабинет 24 на 15:30."},"Soat 15:35 da 24-xonaga kelishlari mumkin":{"uz":"«five minutes before 15:30» — 15:30 dan besh daqiqa oldin (15:25), keyin emas.","ru":"«five minutes before 15:30» означает за пять минут до 15:30 (в 15:25), а не позже."}},"explanation":"Yangi joy — Room 24, boshlanish vaqti — 15:30, «five minutes before 15:30» esa 15:25 ni bildiradi.","explanationRu":"Новое место — Room 24, начало в 15:30, а прийти нужно за 5 минут до начала (к 15:25).","wrongFeedback":"«will not meet», «Room 24» va «five minutes before 15:30» dalillarini tekshiring.","wrongFeedbackRu":"Сверьте в тексте «will not meet», «Room 24» и «five minutes before 15:30»."}},{"id":"lesson_eng_a2_m4_write_q","stepNumber":5,"type":"interactive_question","title":"Writing: Uchrashuv xabari yozish","titleRu":"Writing: Сообщение о встрече","content":"Do‘stingizga uchrashuv vaqti va joyi o‘zgargani haqida 3–4 gapli qisqa xabar yozing va namuna bilan solishtiring.","contentRu":"Напишите другу короткое сообщение из 3–4 предложений об изменении времени и места и сверьте с критериями.","interactiveQuestion":{"id":"q_eng_a2_m4_writing_prompt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"writing","cefrLevel":"A2","topic":"Writing a schedule change message","difficulty":"medium","questionType":"writing_prompt","evaluationMode":"self_assessed","text":"Do‘stingizga poyezd yoki klub vaqti 16:00 dan 16:30 ga ko‘chgani haqida «before / then» va «have to / can» ishlatib 3–4 gapli xabar yozing.","textRu":"Напишите другу сообщение из 3–4 фраз о переносе встречи с 16:00 на 16:30, используя «before / then» и «have to / can».","options":[],"sampleResponse":"Hi Timur! Our club meeting is delayed until 16:30 today, and we have to go to Room 24. Can you meet me outside the library before 16:15? Then we can walk upstairs together.","rubricCriteria":[{"id":"crit_a2_w_change","labelUz":"Yangi vaqt va joy aniq ko‘rsatildi (16:30, Room 24 / Gate 2)","labelRu":"Чётко указаны новое время и место встречи"},{"id":"crit_a2_w_conn","labelUz":"Kamida bitta vaqt bog‘lovchisi qatnashdi (before / after / then)","labelRu":"Использована хотя бы одна временная связка (before / after / then)"},{"id":"crit_a2_w_modal","labelUz":"«have to» yoki «can» modal fe’li to‘g‘ri qo‘llandi","labelRu":"Верно использован глагол «have to» или «can»"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil yozma mashq): bu vazifa rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельное письмо): задание не выдаёт официальный сертификат CEFR.","explanation":"Namunadagi xabar salomlashish, o‘zgarish sababi, «have to», «before» va «then we can» tuzilmalarini aniq birlashtiradi.","explanationRu":"Образец объединяет новое время, глаголы «have to / can» и связки «before / then».","wrongFeedback":"Xabaringizda yangi vaqt/joy, «before/after/then» va «have to/can» borligini tekshiring.","wrongFeedbackRu":"Проверьте наличие нового времени/места, связок времени и «have to/can»."}}]'::jsonb, '{"id":"q_eng_a2_m4_reinf_fill","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"grammar","cefrLevel":"A2","topic":"Modals of necessity: have to","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"We ___ leave early so we arrive before four o''clock.","text":"Zarurat bildiruvchi modal ifodani bo‘sh joyga yozing: «We ___ leave early so we arrive before four o''clock.»","textRu":"Впишите модальную конструкцию необходимости: «We ___ leave early so we arrive before four o''clock.»","options":[],"acceptedAnswers":["have to","must","need to"],"explanation":"Tashqi jadval yoki vaqtga ulgurish zaruratini bildirishda «have to» (shuningdek «must» yoki «need to») ishlatiladi.","explanationRu":"Для выражения необходимости успеть к сроку используется «have to» (а также «must» или «need to»).","wrongFeedback":"Kechikmaslik uchun zaruratni bildiruvchi modal fe’l yoki iborani yozing.","wrongFeedbackRu":"Укажите модальный глагол или выражение необходимости действия перед основным глаголом."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_a2_exit', 'course_eng_01', 'skill_eng_reading', 'integrated', 'exit_assessment', 'A2', 'mod_eng_a2_m4', 'unit_eng_a2_u4', 'A2 darajasining barcha ko‘nikmalarini (tinglash, o‘qish, grammatika, gap tuzish) integratsiyalashgan yakuniy sinovda namoyish etadi.', 'Демонстрирует навыки уровня A2 (аудирование, чтение, грамматику, составление фраз) в итоговом тесте.', '["node_eng_a2_m4_messages"]'::jsonb, 'A2 Yakuniy imtihoni (Integratsiyalashgan sinov)', 'Итоговый экзамен уровня A2', 10, 'Vokzal e’loni, muzey chegirmasi, Past Simple va odobli iltimoslar bo‘yicha A2 yakuniy sinovini topshiring. Muvaffaqiyatli natija B1 darajasini ochadi.', 'Пройдите комплексный тест A2 по объявлению на вокзале, скидкам, Past Simple и просьбам. Успех открывает уровень B1.', 'A2 yakuniy sinovi platforma ichidagi tayyorgarlik darajasini o‘lchaydi; u rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Итоговый тест A2 оценивает учебную готовность внутри платформы и не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"Bu yakuniy sinov A2 darajasidagi 4 modul bo‘yicha mustaqil bilimingizni tekshiradi.","ru":"Итоговый тест проверяет вашу готовность по всем 4 модулям уровня A2."},"learningObjective":{"uz":"O‘quvchi vokzal e’lonini tinglab tushunadi, chegirma matnini tahlil qiladi, Past Simple fe’lini yozadi va iltimos gapi tuzadi.","ru":"Ученик понимает объявление на слух, анализирует скидку в тексте, пишет глагол в Past Simple и строит просьбу."},"warmUp":{"uz":"«Platform», «half past two», «visited», «before» tushunchalarini yodga oling.","ru":"Вспомните лексику вокзала, время «half past two», Past Simple и союз «before»."},"vocabularyItems":[{"word":"express train","uz":"tezyurar poyezd","ru":"скорый поезд","ipa":"/ɪkˈspres treɪn/"},{"word":"half past two","uz":"soat ikki yarim","ru":"половина третьего","ipa":"/hɑːf pɑːst tuː/"}],"grammarNote":{"rule":"Integrated A2 Mastery (Listening Disambiguation + Reading Evidence + Past Simple + Modals)","simpleExplanationUz":"Vaqtlarni va platformalarni tinglashda «not ... / will depart from ...» kabi tuzatishlarga diqqat qiling; o‘qishda esa shartlarni (yosh, talaba kartasi, vaqt) solishtiring.","simpleExplanationRu":"В объявлениях обращайте внимание на уточнения «not ... / will depart from ...», а при чтении сверяйте возраст, скидки и время.","structure":"Platform + Time | Subject + V-ed | Can we [verb] before [event]?","positiveExamples":["The train will depart from Platform 5 at half past two in the afternoon."],"negativeExamples":["It will not leave from Platform 2 at two o''clock."],"questions":["Can we meet before the train leaves?"],"commonMistakes":["Eski vaqt («2:00 / Platform 2») bilan kechiktirilgan yangi vaqtni («14:30 / Platform 5») adashtirish."]},"pronunciationFocus":{"uz":"«Samarkand» va «Platform five» birikmalarida urg‘u so‘z oxiriga aniq beriladi.","ru":"В словосочетании «Platform five» ударение отчётливо выделяет номер пути."},"examples":["The afternoon express train is delayed by thirty minutes and will depart from Platform five at half past two."],"guidedPractice":{"uz":"Vokzal e’lonini oxirigacha tinglang — ikkinchi gapda tasdiq ham bor.","ru":"Дослушайте объявление до конца — во второй реплике пассажир повторяет важные детали."},"independentPractice":{"uz":"4 ta bosqichli integratsiyalashgan savolni mustaqil yeching.","ru":"Самостоятельно выполните 4 задания по всем навыкам уровня A2."},"listeningRef":"media_eng_a2_exit_station_dialogue","readingRef":"lesson_eng_a2_exit_step_3","speakingTask":{"uz":"E’londagi yangi platforma va vaqtni ingliz tilida ovoz chiqarib ayting.","ru":"Озвучьте новую платформу и время отправления по-английски."},"writingTask":{"uz":"Past Simple fe’l shaklini va «before» li iltimos gapini tuzing.","ru":"Впишите форму Past Simple и составьте предложение с «before»."},"knowledgeCheck":"q_eng_a2_exit_listen","finalQuiz":"q_eng_a2_exit_read","feedbackRules":{"uz":"70% dan yuqori natija A2 bosqichini yakunlab, B1 darajasiga yo‘l ochadi.","ru":"Результат 70% и выше завершает уровень A2 и открывает переход к B1."},"summaryAndRevision":{"uz":"A2 yakuniy sinovi muvaffaqiyatli topshirilgach B1 darajasiga o‘tish mumkin.","ru":"Успешное прохождение теста A2 открывает уровень B1."}}'::jsonb, '[{"id":"lesson_eng_a2_exit_step_1","stepNumber":1,"type":"audio_simulation","title":"1. Tinglash: Vokzal e’loni","titleRu":"1. Аудирование: Объявление на вокзале","content":"Samarqand poyezdi haqidagi e’lon va yo‘lovchi suhbatini tinglang. Qaysi platforma va soat bekor qilinganiga hamda yangi vaqtga diqqat qiling.","contentRu":"Прослушайте объявление о самаркандском поезде. Обратите внимание на отменённую и новую платформу и точное время отправления.","media":{"id":"media_eng_a2_exit_station_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/a2/a2-exit-station-dialogue.wav","title":"A2 yakuniy tinglash: Vokzaldagi e’lon","titleUz":"A2 yakuniy tinglash: Vokzaldagi e’lon","titleRu":"Итоговое аудирование A2: Объявление на вокзале","transcript":"Announcer: Attention, passengers. The afternoon express train to Samarkand will not leave from Platform two at two o''clock. It is delayed by thirty minutes and will depart from Platform five at half past two in the afternoon.\nPassenger: Did you hear that? Platform five at two thirty, not two o''clock. Let''s text Karim before we walk over.","posterImage":"/lesson-media/english/a2/a2-m4-station-message.png","posterAlt":"Poyezd perroni, osma devor soati va ekranda xabar pufakchalari ko‘rsatilgan telefon","posterAltUz":"Poyezd perroni, osma devor soati va ekranda xabar pufakchalari ko‘rsatilgan telefon","posterAltRu":"Железнодорожный перрон, подвесные часы и смартфон с пузырями сообщений","durationSeconds":22.019,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Announcer: Attention, passengers. The afternoon express train to Samarkand will not leave from Platform two at two o''clock. It is delayed by thirty minutes and will depart from Platform five at half past two in the afternoon.\nPassenger: Did you hear that? Platform five at two thirty, not two o''clock. Let''s text Karim before we walk over.","speakerName":"Announcer & Passenger"}},{"id":"lesson_eng_a2_exit_step_2","stepNumber":2,"type":"interactive_question","title":"2. Tinglash dalili","titleRu":"2. Факты из аудирования","content":"E’longa asoslanib poyezdning yangi platformasi va jo‘nash vaqtini tanlang.","contentRu":"Выберите новую платформу и точное время отправления поезда по аудио.","interactiveQuestion":{"id":"q_eng_a2_exit_listen","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"A2","topic":"A2 Exit: Station delay announcement","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi e’longa ko‘ra, Samarqand tezyurar poyezdi qaysi platformadan va soat nechada jo‘naydi?","textRu":"С какой платформы и во сколько отправляется экспресс в Самарканд согласно объявлению?","options":["2-platformadan soat 14:00 da jo‘naydi","5-platformadan tungi soat 02:30 da jo‘naydi","5-platformadan soat 14:30 da jo‘naydi","2-platformadan soat 14:30 da jo‘naydi"],"correctIndex":2,"mistakeFeedbackByOption":{"2-platformadan soat 14:00 da jo‘naydi":{"uz":"E’londa «will NOT leave from Platform two at two o''clock» (eski reja bekor) deyildi.","ru":"Диктор чётко сказал «will NOT leave from Platform two at two o''clock» — это прежнее время."},"5-platformadan tungi soat 02:30 da jo‘naydi":{"uz":"Diktor «in the afternoon» (kunduzi) dedi, shuning uchun 02:30 emas, 14:30 to‘g‘ri.","ru":"Уточнение «in the afternoon» означает день (14:30), а не ночь (02:30)."},"2-platformadan soat 14:30 da jo‘naydi":{"uz":"Poyezd 2-platformadan emas, «Platform five» (5-platforma) dan jo‘naydi.","ru":"Поезд отправляется не со 2-й, а с 5-й платформы («Platform five»)."}},"explanation":"E’londa «depart from Platform five at half past two in the afternoon» (5-platforma, kunduzi 14:30) deyildi.","explanationRu":"В объявлении указано: «Platform five at half past two in the afternoon» (5-я платформа, 14:30).","wrongFeedback":"Audiodagi poyezd jo‘naydigan platforma raqami, soat va kunning qaysi qismi (kunduzi/kechasi) aytilganini qayta tinglang.","wrongFeedbackRu":"Переслушайте в аудио номер платформы, точное время отправления и указание времени суток."}},{"id":"lesson_eng_a2_exit_step_3","stepNumber":3,"type":"interactive_question","title":"3. Muzey chegirma e’lonini o‘qish","titleRu":"3. Чтение объявления музея о скидке","content":"Dam olish kunlari uchun e’lonni o‘qing va to‘g‘ri javobni tanlang.","contentRu":"Прочтите объявление о скидках на выходных и выберите верный ответ.","interactiveQuestion":{"id":"q_eng_a2_exit_read","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A2","topic":"A2 Exit: Museum discount notice","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"City Art Museum Weekend Offer: Adult tickets cost 40,000 UZS. Children under 12 enter free, and university students pay half price after 15:00 on Saturday and Sunday.","text":"E’longa ko‘ra, talaba shanba kuni soat 15:30 da muzeyga kirsa qancha to‘laydi?","textRu":"Сколько заплатит студент, если придёт в музей в субботу в 15:30?","options":["Bepul kiradi, chunki barcha talabalar bepul","20,000 so‘m to‘laydi (soat 15:00 dan keyin yarim narx)","40,000 so‘m to‘laydi, chunki chegirma faqat yakshanba kuni","12,000 so‘m to‘laydi, chunki yosh chegirmasi bor"],"correctIndex":1,"mistakeFeedbackByOption":{"Bepul kiradi, chunki barcha talabalar bepul":{"uz":"Faqat 12 yoshgacha bolalar («Children under 12») bepul kiradi; talabalarga esa yarim narx.","ru":"Бесплатный вход только для детей до 12 лет («Children under 12»); для студентов — полцены."},"40,000 so‘m to‘laydi, chunki chegirma faqat yakshanba kuni":{"uz":"Chegirma «on Saturday and Sunday» (shanba va yakshanba) amal qiladi, 15:30 esa 15:00 dan keyin.","ru":"Скидка действует и в субботу, и в воскресенье после 15:00."},"12,000 so‘m to‘laydi, chunki yosh chegirmasi bor":{"uz":"12 — bu so‘m miqdori emas, bepul kiradigan bolalar yosh chegarasi («under 12»).","ru":"12 в объявлении — это возраст детей, а не цена билета."}},"explanation":"Kattalar chiptasi 40,000 so‘m; talabalar shanba kuni 15:00 dan keyin yarim narx (20,000 so‘m) to‘laydi.","explanationRu":"Взрослый билет — 40,000 сумов; студенты по субботам после 15:00 платят половину цены (20,000).","wrongFeedback":"«half price after 15:00 on Saturday and Sunday» shartini chipta narxi (40,000) bilan solishtiring.","wrongFeedbackRu":"Соотнесите полную цену (40,000) и условие «half price after 15:00»."}},{"id":"lesson_eng_a2_exit_step_4","stepNumber":4,"type":"interactive_question","title":"4. Past Simple fe’l shakli","titleRu":"4. Глагол в Past Simple","content":"O‘tgan zamon belgisiga qarab qavsdagi fe’lni to‘g‘ri shaklda yozing.","contentRu":"Поставьте глагол в скобках в правильную форму Past Simple.","interactiveQuestion":{"id":"q_eng_a2_exit_grammar_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A2","topic":"A2 Exit: Past Simple regular verb","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"Yesterday our class ___ the Registan museum in Samarkand.","text":"Qavsdagi fe’lni Past Simple shakliga o‘tkazib yozing: «Yesterday our class ___ (visit) the Registan museum in Samarkand.»","textRu":"Поставьте глагол в скобках в Past Simple: «Yesterday our class ___ (visit) the Registan museum in Samarkand.»","options":[],"acceptedAnswers":["visited"],"explanation":"«Yesterday» o‘tgan zamon ko‘rsatkichi bo‘lib, «visit» to‘g‘ri fe’liga «-ed» qo‘shiladi: «visited».","explanationRu":"Маркер «Yesterday» требует Past Simple; к правильному глаголу «visit» добавляется «-ed»: «visited».","wrongFeedback":"«Yesterday» o‘tgan zamon belgisi bo‘lgani uchun to‘g‘ri fe’l oxiriga «-ed» qo‘shing.","wrongFeedbackRu":"Слово «Yesterday» указывает на прошлое — добавьте к правильному глаголу окончание «-ed»."}},{"id":"lesson_eng_a2_exit_step_5","stepNumber":5,"type":"interactive_question","title":"5. Iltimos va vaqt bog‘lovchisi","titleRu":"5. Вежливая просьба и союз времени","content":"So‘zlarni to‘g‘ri tartibda joylashtirib, savol gap tuzing.","contentRu":"Расставьте фрагменты в верном порядке, чтобы получился вежливый вопрос.","interactiveQuestion":{"id":"q_eng_a2_exit_order","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"A2","topic":"A2 Exit: Polite request with before","difficulty":"medium","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Poyezd jo‘nashidan oldin uchrasha olamizmi?» savolini to‘g‘ri tartibda tuzing:","textRu":"Составьте вопрос «Можем ли мы встретиться до отправления поезда?» в правильном порядке:","options":[],"orderedTokens":["Can","we","meet","before","the train","leaves?"],"acceptedAnswers":["Can we meet before the train leaves?"],"explanation":"Savol modal «Can» bilan boshlanadi: Can + we + meet + before + the train + leaves?","explanationRu":"Вопрос начинается с модального «Can»: Can + we + meet + before + the train + leaves?","wrongFeedback":"Savolni iltimos/imkoniyat bildiruvchi modal fe’l + ega + asosiy fe’l + bog‘lovchi va so‘roq belgisi bilan tugaydigan vaqt ergash gapi tartibida tuzing.","wrongFeedbackRu":"Начните вопрос с модального глагола вежливой просьбы, затем подлежащее + основной глагол + союз и придаточное времени со знаком вопроса в конце."}}]'::jsonb, '{"id":"q_eng_a2_exit_reinf","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"A2","topic":"A2 Exit: Ticket desk dialogue","difficulty":"medium","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Passenger: «Excuse me, is the faster train more expensive?»","Clerk: «___»"],"text":"Chipta kassirining savolga mantiqiy va grammatik to‘g‘ri javobini tanlang:","textRu":"Выберите логичный и грамматически верный ответ кассира:","options":["Yes, it is more faster, and the platform was tomorrow.","No, how many money do you go past?","You have to visiting Platform 5 yesterday.","Yes, it is faster, so a ticket costs ten dollars more."],"correctIndex":3,"mistakeFeedbackByOption":{"Yes, it is more faster, and the platform was tomorrow.":{"uz":"«more faster» qo‘shaloq qiyosiy xato («faster» kifoya) va «was tomorrow» zamon jihatdan mantiqsiz.","ru":"«more faster» — ошибка двойного сравнения, а «was tomorrow» нарушает логику времени."},"No, how many money do you go past?":{"uz":"«money» sanalmaydigan ot («how much money») va gap ma’nosiz.","ru":"Со словом «money» используется «how much», а не «how many»."},"You have to visiting Platform 5 yesterday.":{"uz":"«have to» dan keyin «visit» keladi, «yesterday» esa hozirgi harakatga mos emas.","ru":"После «have to» ставится начальная форма «visit», а «yesterday» не подходит к ситуации."}},"explanation":"«faster» to‘g‘ri qiyosiy sifat va kassir chipta narxi farqini aniq tushuntirmoqda.","explanationRu":"Форма «faster» верна, и кассир логично объясняет разницу в цене билета.","wrongFeedback":"Bir bo‘g‘inli sifatning «more» siz to‘g‘ri qiyosiy darajasi va mantiqiy narx javobini tanlang.","wrongFeedbackRu":"Выберите грамматически верную сравнительную форму без «more» и логичный ответ о цене."}'::jsonb, '{"id":"q_eng_a2_exit_alt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"A2","topic":"A2 Exit alternate notice","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Bukhara Shuttle Notice: The morning shuttle to the train station leaves from Gate B across from the City Hotel at 07:45. Tickets are 15,000 UZS, and backpacks go inside the luggage rack.","text":"Qayta sinov: E’longa ko‘ra, avtobus qayerdan va soat nechada jo‘naydi?","textRu":"Повторная проверка: откуда и во сколько отправляется автобус до вокзала?","options":["City Hotel qarshisidagi B darvozadan soat 07:45 da jo‘naydi","City Hotel orqasidagi A darvozadan soat 19:45 da jo‘naydi","Vokzal ichidan soat 07:15 da jo‘naydi","B darvozadan faqat yuklarsiz soat 08:15 da jo‘naydi"],"correctIndex":0,"mistakeFeedbackByOption":{"City Hotel orqasidagi A darvozadan soat 19:45 da jo‘naydi":{"uz":"Matnda «Gate B», «across from the City Hotel» va «07:45» (ertalab) deb ko‘rsatilgan.","ru":"В объявлении указаны Gate B, «across from» (напротив) и утреннее время 07:45."},"Vokzal ichidan soat 07:15 da jo‘naydi":{"uz":"Avtobus vokzalga boradi («to the train station»), jo‘nash joyi esa Gate B va vaqti 07:45.","ru":"Автобус едет к вокзалу, а отправляется от Gate B в 07:45."},"B darvozadan faqat yuklarsiz soat 08:15 da jo‘naydi":{"uz":"Matnda ryukzaklar yuk javoniga qo‘yilishi va vaqt 07:45 ekani yozilgan.","ru":"Рюкзаки размещаются на багажной полке, а отправление в 07:45."}},"explanation":"Matndagi «Gate B across from the City Hotel at 07:45» ma’lumoti birinchi javobga to‘liq mos.","explanationRu":"В тексте чётко указано: Gate B, напротив City Hotel, 07:45.","wrongFeedback":"Matndagi darvoza harfi, mehmonxona qarshisidagi joylashuv va jo‘nash vaqtini qayta tekshiring.","wrongFeedbackRu":"Перепроверьте в тексте букву выхода, ориентир напротив отеля и время отправления."}'::jsonb, true, true, false),
  ('lesson_eng_b1_m1_travel', 'course_eng_01', 'skill_eng_listening', 'listening', 'listening', 'B1', 'mod_eng_b1_m1', 'unit_eng_b1_u1', 'Sayohat va o‘qish tajribalarini Present Perfect hamda Past Simple bilan aniq farqlab bayon qiladi; aeroportdagi bron o‘zgarishini tinglab tushunadi.', 'Различает Present Perfect и Past Simple при рассказе о поездках и опыте; понимает диалог об изменении рейса и бронирования.', '["node_eng_a2_exit"]'::jsonb, 'Travel Logistics & Experiences (Present Perfect vs Past Simple)', 'Поездки и опыт: Present Perfect и Past Simple', 10, 'You learn how to separate current travel status (Present Perfect with already/yet) from finished past details (Past Simple with yesterday/ago) during airport check-in.', 'Вы научитесь отделять текущий статус поездки (Present Perfect с already/yet) от завершённых деталей прошлого (Past Simple с yesterday/ago).', 'Ushbu darsdagi og‘zaki topshiriq mustaqil mashq uchun mo‘ljallangan; rasmiy CEFR sertifikati bermaydi.', 'Устное задание в уроке предназначено для самостоятельной практики и не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"When you travel or join an exchange program, staff ask what you have already arranged and what happened at a specific time. Safar va o‘qish hujjatlarida hozirgi natija va aniq o‘tgan vaqtni ajratish juda muhim.","ru":"В поездках и программах обмена важно различать уже готовый результат к настоящему моменту и действие, завершившееся в конкретный момент прошлого."},"learningObjective":{"uz":"Distinguish Present Perfect (experience or present result) from Past Simple (finished time) and explain a travel update aloud.","ru":"Различать Present Perfect (опыт или результат сейчас) и Past Simple (завершённое время) и устно сообщать об изменении маршрута."},"warmUp":{"uz":"In A2 you mastered Past Simple (''booked'', ''went''). Ask yourself: why do travelers say ''I have lost my boarding pass'' without ''yesterday''?","ru":"В A2 вы изучили Past Simple. Подумайте: почему путешественник говорит ''I have lost my boarding pass'' без указания ''yesterday''?"},"vocabularyItems":[{"word":"boarding pass","uz":"samolyotga chiqish taloni","ru":"посадочный талон","ipa":"/ˈbɔːdɪŋ pɑːs/"},{"word":"itinerary","uz":"safar yo‘nalish jadvali","ru":"маршрутный лист","ipa":"/aɪˈtɪnərəri/"},{"word":"reschedule","uz":"vaqtini ko‘chirmoq","ru":"перенести на другое время","ipa":"/ˌriːˈʃedjuːl/"},{"word":"accommodation","uz":"turar joy (boshpana)","ru":"жильё для проживания","ipa":"/əˌkɒməˈdeɪʃn/"}],"grammarNote":{"rule":"Present Perfect (have/has + V3) vs Past Simple (V2 / did + V1)","simpleExplanationUz":"Use Present Perfect for life experience or a past action with a result right now. Use Past Simple when you name a finished time (yesterday, two days ago). O‘zbek tilida ikkalasi ham ko‘pincha ''-gan/-di'' bilan beriladi, ammo inglizchada aniq o‘tgan vaqt kelsa faqat Past Simple ishlatiladi.","simpleExplanationRu":"Используйте Present Perfect для опыта или результата в настоящем, а Past Simple, когда назван завершённый момент (yesterday, two days ago). В русском оба времени переводятся прошедшим, но маркеры законченного времени запрещают Present Perfect.","structure":"Subject + have/has (+ already/never) + V3 | Subject + haven''t/hasn''t + V3 ... yet | Subject + V2 + [finished time]","positiveExamples":["I have already checked in online for the Prague flight.","I booked my student accommodation two days ago."],"negativeExamples":["The confirmation email hasn''t arrived yet.","We didn''t reschedule the hotel yesterday."],"questions":["Have you ever missed a connecting flight?","When did the airline update the itinerary?"],"commonMistakes":["Combining a finished time marker with Present Perfect (''I have booked it two days ago'' is wrong; say ''I booked it two days ago''), or using ''yet'' in positive statements instead of ''already''."]},"pronunciationFocus":{"uz":"Stress falls on the second syllable in ''itinerary'' /aɪˈtɪnərəri/. Notice British ''reschedule'' /ˌriːˈʃedjuːl/ vs American /ˌriːˈskedʒuːl/.","ru":"В ''itinerary'' /aɪˈtɪnərəri/ ударение падает на второй слог. Сравните британское ''reschedule'' /ˌriːˈʃedjuːl/ и американское /ˌriːˈskedʒuːl/."},"examples":["We have rescheduled passengers to 11:15 from Gate 19.","I checked the updated itinerary ten minutes ago."],"guidedPractice":{"uz":"Examine the airport boarding card illustration, listen to Sardor and the check-in agent, and review the 4 B1 flashcards.","ru":"Рассмотрите иллюстрацию посадки на рейс, прослушайте диалог Сардора и сотрудника стойки и повторите 4 карточки B1."},"independentPractice":{"uz":"Answer the listening disambiguation check, complete the Past Simple gap, and deliver your own spoken travel update.","ru":"Выполните тест по аудированию, впишите глагол в Past Simple и запишите устное сообщение о поездке."},"listeningRef":"media_eng_b1_m1_travel_dialogue","readingRef":"lesson_eng_b1_m1_concept","speakingTask":{"uz":"Explain a travel change in 3 to 4 sentences using Present Perfect (''already/yet'') plus one finished-time Past Simple detail.","ru":"Расскажите об изменении плана поездки в 3–4 предложениях с Present Perfect (''already/yet'') и одной деталью в Past Simple."},"writingTask":{"uz":"Write a negative Present Perfect sentence with ''yet'' explaining that transport has not arrived.","ru":"Напишите отрицательное предложение в Present Perfect с ''yet'' о том, что транспорт ещё не прибыл."},"knowledgeCheck":"q_eng_b1_m1_listen_mcq","finalQuiz":"q_eng_b1_m1_speaking","feedbackRules":{"uz":"Every distractor diagnoses time-marker conflict or listening detail confusion.","ru":"Каждый дистрактор разбирает конфликт маркеров времени или ошибку в деталях аудирования."},"summaryAndRevision":{"uz":"Your 4 B1 travel cards enter spaced repetition before the Unit 1 hotel checkpoint.","ru":"Все 4 карточки модуля переходят в интервальное повторение перед проверкой раздела 1."}}'::jsonb, '[{"id":"lesson_eng_b1_m1_concept","stepNumber":1,"type":"concept","title":"Present Perfect vs Past Simple in Travel","titleRu":"Present Perfect и Past Simple в поездках","content":"Choose Present Perfect (have/has + V3) when the exact past time does not matter and the result affects right now. Use ''already'' in positive updates and ''yet'' at the end of questions or negatives. Switch to Past Simple the moment you mention a finished time such as ''yesterday'' or ''two days ago''. O‘zbek tilida ikkala zamon ham ''-gan/-di'' bilan tarjima qilinishi mumkin, lekin inglizchada aniq vaqt ko‘rsatkichi kelsa Present Perfect ishlatilmaydi.","contentRu":"Выбирайте Present Perfect (have/has + V3), когда важно состояние и результат сейчас, а не точная дата в прошлом. Используйте ''already'' в утверждениях и ''yet'' в вопросах и отрицаниях. Как только вы называете завершённое время (''yesterday'', ''two days ago''), переходите на Past Simple, хотя в русском оба варианта звучат как прошедшее время.","highlightNotes":["Result now: I have already checked in online.","Unfinished check: The confirmation email hasn''t arrived yet.","Finished past time: I booked the room two days ago."]},{"id":"lesson_eng_b1_m1_audio","stepNumber":2,"type":"audio_simulation","title":"Listening: Airport Check-in & Gate Change","titleRu":"Аудирование: Регистрация и перенос рейса","content":"Listen to Sardor speaking with the airline agent. Track which departure time and gate were cancelled, what the new schedule is, and which booking detail is still missing.","contentRu":"Прослушайте разговор Сардора с сотрудником авиакомпании. Обратите внимание на отменённое и новое время вылета, номер выхода и статус бронирования жилья.","media":{"id":"media_eng_b1_m1_travel_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/b1/b1-m1-travel-dialogue.wav","title":"Aeroportda reys va turar joyni tekshirish suhbati","titleUz":"Aeroportda reys va turar joyni tekshirish suhbati","titleRu":"Диалог в аэропорту о переносе рейса и бронировании","transcript":"Sardor: Excuse me, I have already checked in online for the Prague flight, but my app shows a new itinerary.\nAgent: Let me check your boarding pass. Yes, because of morning fog, the nine thirty flight from Gate seven was cancelled. We have rescheduled passengers to eleven fifteen from Gate nineteen.\nSardor: Okay, eleven fifteen at Gate nineteen. Also, I booked my student accommodation two days ago, and the confirmation email hasn''t arrived yet.\nAgent: I see it in our partner system. I have just sent a fresh copy to your inbox, so you can show it at reception.","posterImage":"/lesson-media/english/b1/b1-m1-travel-boarding.png","posterAlt":"Aeroport uchish jadvali o‘zgarishi, QR kodli chipta va mehmonxona kaliti tasvirlangan ikki panel","posterAltUz":"Aeroport uchish jadvali o‘zgarishi, QR kodli chipta va mehmonxona kaliti tasvirlangan ikki panel","posterAltRu":"Две панели: перенос времени вылета, посадочный бланк со штрих-кодом и ключ-карта отеля","durationSeconds":37.075,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Sardor: Excuse me, I have already checked in online for the Prague flight, but my app shows a new itinerary.\nAgent: Let me check your boarding pass. Yes, because of morning fog, the nine thirty flight from Gate seven was cancelled. We have rescheduled passengers to eleven fifteen from Gate nineteen.\nSardor: Okay, eleven fifteen at Gate nineteen. Also, I booked my student accommodation two days ago, and the confirmation email hasn''t arrived yet.\nAgent: I see it in our partner system. I have just sent a fresh copy to your inbox, so you can show it at reception.","speakerName":"Sardor & Agent"}},{"id":"lesson_eng_b1_m1_flashcards","stepNumber":3,"type":"flashcard","title":"Travel Logistics Flashcards","titleRu":"Карточки: Поездки и бронирование","content":"Listen to each B1 term, recall its meaning first, and then tap to check the definition and natural sentence.","contentRu":"Прослушайте слово, вспомните перевод и только затем откройте карточку.","flashcards":[{"id":"fc_eng_b1_m1_1","front":"boarding pass","backUz":"samolyotga chiqish taloni","backRu":"посадочный талон","partOfSpeech":"noun","ipa":"/ˈbɔːdɪŋ pɑːs/","ipaAmE":"/ˈbɔːrdɪŋ pæs/","cefrLevel":"B1","example":"Please keep your boarding pass ready at Gate 19.","exampleUz":"Iltimos, 19-darvozada samolyotga chiqish taloningizni tayyor tuting.","exampleRu":"Пожалуйста, держите посадочный талон наготове у выхода 19.","audioSrc":"/lesson-media/english/b1/b1-m1-boarding-pass.wav","imageSrc":"/lesson-media/english/b1/b1-m1-travel-boarding.png","alt":"QR kodli qog‘oz varaq va uchishga tayyor havo layneri tasviri","altRu":"Бумажный бланк со штрих-кодом и силуэт самолёта","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m1_2","front":"itinerary","backUz":"safar yo‘nalish jadvali","backRu":"маршрутный лист","partOfSpeech":"noun","ipa":"/aɪˈtɪnərəri/","ipaAmE":"/aɪˈtɪnəreri/","cefrLevel":"B1","example":"We checked the updated itinerary before leaving the hotel.","exampleUz":"Mehmonxonadan chiqishdan oldin yangilangan safar jadvalini tekshirdik.","exampleRu":"Перед выходом из отеля мы проверили обновлённый маршрутный лист.","audioSrc":"/lesson-media/english/b1/b1-m1-itinerary.wav","imageSrc":"/lesson-media/english/b1/b1-m1-travel-boarding.png","alt":"Ikki manzil nuqtasini bog‘lovchi chiziq va xarita belgilari","altRu":"Пунктирная линия между двумя точками на схеме","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m1_3","front":"reschedule","backUz":"vaqtini ko‘chirmoq","backRu":"перенести на другое время","partOfSpeech":"verb","ipa":"/ˌriːˈʃedjuːl/","ipaAmE":"/ˌriːˈskedʒuːl/","cefrLevel":"B1","example":"The airline had to reschedule our morning flight due to fog.","exampleUz":"Aviakompaniya tuman sababli ertalabki reysimiz vaqtini ko‘chirishga majbur bo‘ldi.","exampleRu":"Авиакомпании пришлось перенести утренний рейс из-за тумана.","audioSrc":"/lesson-media/english/b1/b1-m1-reschedule.wav","imageSrc":"/lesson-media/english/b1/b1-m1-travel-boarding.png","alt":"Birining ustiga chiziq tortilgan va ikkinchisi yashil rangda ko‘rsatilgan ikki soat","altRu":"Два циферблата: один перечёркнут, второй отмечен зелёным","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m1_4","front":"accommodation","backUz":"turar joy (boshpana)","backRu":"жильё для проживания","partOfSpeech":"noun","ipa":"/əˌkɒməˈdeɪʃn/","ipaAmE":"/əˌkɑːməˈdeɪʃn/","cefrLevel":"B1","example":"Have you booked student accommodation near the campus yet?","exampleUz":"Kampus yaqinidan talabalar turar joyini hali bron qildingizmi?","exampleRu":"Вы уже забронировали жильё рядом с кампусом?","audioSrc":"/lesson-media/english/b1/b1-m1-accommodation.wav","imageSrc":"/lesson-media/english/b1/b1-m1-travel-boarding.png","alt":"Oltin kalit belgisi tushirilgan ko‘p qavatli bino tasviri","altRu":"Многоэтажное здание рядом с золотым значком ключа","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_b1_m1_listen_q","stepNumber":4,"type":"interactive_question","title":"Listening Check: Flight & Booking Status","titleRu":"Проверка аудирования: Рейс и жильё","content":"Based on the airport conversation, identify Sardor''s updated flight details and which item still needed action.","contentRu":"По разговору в аэропорту определите обновлённое время, выход на посадку и проблему с документами.","interactiveQuestion":{"id":"q_eng_b1_m1_listen_mcq","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"B1","topic":"Listening: Rescheduled flight details","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi suhbatga ko‘ra, Sardorning yangilangan reysi soat nechada va qaysi darvozadan uchadi, hamda qaysi hujjati hali kelmagan edi?","textRu":"Согласно диалогу, во сколько и с какого выхода вылетает обновлённый рейс Сардора, и какое подтверждение ещё не пришло?","options":["09:30 da 7-darvozadan; hali onlayn ro‘yxatdan o‘tmagan edi","11:15 da 7-darvozadan; reys umuman bekor qilinmagan edi","11:15 da 19-darvozadan; turar joy tasdiq xati hali kelmagan edi","09:30 da 19-darvozadan; chamadoni aeroportda yo‘qolgan edi"],"correctIndex":2,"mistakeFeedbackByOption":{"09:30 da 7-darvozadan; hali onlayn ro‘yxatdan o‘tmagan edi":{"uz":"09:30 va 7-darvoza tuman sababli bekor qilingan eski reys edi; Sardor esa onlayn ro‘yxatdan allaqachon o‘tgan.","ru":"09:30 и выход 7 — отменённый прежний рейс, а онлайн-регистрацию Сардор уже прошёл."},"11:15 da 7-darvozadan; reys umuman bekor qilinmagan edi":{"uz":"Xodim 09:30 dagi reys bekor bo‘lib, yangisi 19-darvozaga ko‘chirilganini aytdi.","ru":"Сотрудник сообщил об отмене рейса на 09:30 и переносе нового вылета на выход 19."},"09:30 da 19-darvozadan; chamadoni aeroportda yo‘qolgan edi":{"uz":"Sardor chamadon haqida emas, ikki kun oldin bron qilgan turar joy tasdiq xati kelmagani haqida so‘radi.","ru":"Речь шла не о багаже, а о подтверждении бронирования жилья, оформленного два дня назад."}},"explanation":"Agent confirmed the 09:30 flight from Gate 7 was cancelled and rescheduled to 11:15 from Gate 19, while Sardor''s accommodation confirmation email had not arrived yet.","explanationRu":"Сотрудник подтвердил перенос рейса с 09:30 (выход 7) на 11:15 (выход 19), а письмо о жилье ещё не поступило на почту.","wrongFeedback":"Eski reys va yangi ko‘chirilgan vaqt hamda Sardorning turar joy haqidagi izohini qayta tinglang.","wrongFeedbackRu":"Переслушайте различие между отменённым и перенесённым рейсом, а также вопрос о бронировании жилья."}},{"id":"lesson_eng_b1_m1_fill_q","stepNumber":5,"type":"interactive_question","title":"Grammar Practice: Finished Past Time","titleRu":"Грамматика: Завершённое время","content":"Choose the accurate verb form to match the finished time expression in the sentence.","contentRu":"Поставьте глагол в правильную форму с учётом маркера завершённого времени.","interactiveQuestion":{"id":"q_eng_b1_m1_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Past Simple with ago","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"I ___ my passport at the hotel reception two hours ago.","text":"Qavsdagi «leave» fe’lini vaqt ko‘rsatkichiga moslab to‘g‘ri shaklda yozing: «I ___ (leave) my passport at the hotel reception two hours ago.»","textRu":"Поставьте глагол «leave» в правильную форму согласно маркеру времени: «I ___ (leave) my passport at the hotel reception two hours ago.»","options":[],"acceptedAnswers":["left"],"explanation":"''two hours ago'' marks a finished point in the past, so Past Simple (''left'') is required instead of Present Perfect.","explanationRu":"Маркер ''two hours ago'' обозначает завершённый момент в прошлом, поэтому нужен Past Simple (''left''), а не Present Perfect.","wrongFeedback":"Gapda aniq tugallangan vaqt ko‘rsatkichi borligi sababli noto‘g‘ri fe’lning ikkinchi shaklini yozing.","wrongFeedbackRu":"Из-за точного указания времени в прошлом требуется вторая форма неправильного глагола."}},{"id":"lesson_eng_b1_m1_speak_q","stepNumber":6,"type":"interactive_question","title":"Speaking: Travel Update Report","titleRu":"Speaking: Сообщение о поездке","content":"Record or say aloud a 3–4 sentence update for a classmate waiting at the airport, combining Present Perfect (''already/yet'') and one Past Simple time detail.","contentRu":"Составьте устное сообщение из 3–4 предложений об изменении планов в поездке, сочетая Present Perfect (''already/yet'') и Past Simple.","interactiveQuestion":{"id":"q_eng_b1_m1_speaking","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"speaking","cefrLevel":"B1","topic":"Speaking: Travel update with Present Perfect and Past Simple","difficulty":"medium","questionType":"speaking_prompt","evaluationMode":"self_assessed","text":"Sayohat rejangiz o‘zgargani haqida 3–4 ta gap ayting: nimalarni allaqachon bajarganingizni (already/yet) va kecha yoki bir soat oldin nima qilganingizni (Past Simple) tushuntiring.","textRu":"Расскажите в 3–4 предложениях об изменении маршрута: что уже сделано (already/yet) и что произошло в конкретный момент прошлого (Past Simple).","options":[],"sampleResponse":"I have already printed my boarding pass, and the airline has rescheduled our departure to 11:15. I checked the updated itinerary ten minutes ago. However, my hotel confirmation hasn''t arrived yet.","rubricCriteria":[{"id":"crit_b1_m1_pp","labelUz":"Kamida bitta Present Perfect (''already'' yoki ''yet'' bilan) to‘g‘ri ishlatildi","labelRu":"Верно использован Present Perfect (с ''already'' или ''yet'')"},{"id":"crit_b1_m1_ps","labelUz":"Aniq vaqt ko‘rsatkichi bilan Past Simple gapi qo‘shildi","labelRu":"Добавлено предложение в Past Simple с точным маркером времени"},{"id":"crit_b1_m1_vocab","labelUz":"Sayohat lug‘atidan kamida 2 ta so‘z qo‘llandi (boarding pass, itinerary, reschedule, accommodation)","labelRu":"Использовано минимум 2 термина темы (boarding pass, itinerary, reschedule, accommodation)"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil nutq mashqi): natija avtomatik nutq tekshiruvisiz mezonlar asosida baholanadi va rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельная практика): задание оценивается по критериям без автопроверки речи и не выдаёт официальный сертификат CEFR.","explanation":"Combining ''already/yet'' for current readiness with a Past Simple timestamp makes travel updates accurate and natural at B1.","explanationRu":"Сочетание ''already/yet'' для текущего статуса и Past Simple для конкретных событий прошлого делает сообщение естественным для B1.","wrongFeedback":"Gaplaringizda Present Perfect (''already/yet''), aniq vaqtli Past Simple va sayohat so‘zlari borligini tekshiring.","wrongFeedbackRu":"Проверьте наличие Present Perfect (''already/yet''), Past Simple с маркером времени и лексики модуля."}}]'::jsonb, '{"id":"q_eng_b1_m1_reinf_text","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Present Perfect negative with yet","difficulty":"medium","questionType":"text_input","evaluationMode":"deterministic","text":"«Avtobus hali yetib kelmadi» ma’nosini Present Perfect inkor shaklida ingliz tilida to‘liq gap bilan yozing.","textRu":"Напишите на английском полное отрицательное предложение в Present Perfect со значением «Автобус ещё не прибыл».","options":[],"acceptedAnswers":["The bus hasn''t arrived yet","The bus has not arrived yet","The airport shuttle hasn''t arrived yet","The airport shuttle has not arrived yet","The shuttle bus hasn''t arrived yet","The shuttle bus has not arrived yet"],"explanation":"Negative Present Perfect puts ''hasn''t / has not + V3'' before ''yet'' at the end of the clause: ''The bus hasn''t arrived yet.''","explanationRu":"В отрицании Present Perfect ставится ''hasn''t / has not + V3'', а маркер ожидания выносится в конец предложения.","wrongFeedback":"Birlikdagi ega uchun inkor yordamchi fe’l, uchinchi shakl fe’li va gap oxirida kutish ravishini qo‘llang.","wrongFeedbackRu":"Для единственного числа используйте отрицательную форму вспомогательного глагола, третью форму и наречие ожидания в конце."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_b1_u1_checkpoint', 'course_eng_01', 'skill_eng_listening', 'listening', 'checkpoint', 'B1', 'mod_eng_b1_m1', 'unit_eng_b1_u1', 'Mehmonxona qabulxonasidagi suhbatni tinglab to‘g‘ri javobni tanlaydi va Present Perfect hamda Past Simple xatolarini tuzatadi.', 'Понимает диалог на стойке регистрации в отеле и исправляет ошибки в Present Perfect и Past Simple.', '["node_eng_b1_m1_travel"]'::jsonb, 'Unit 1 Checkpoint: Hotel & Itinerary Verification', 'Проверка раздела 1: Отель и проверка брони', 7, 'Verify your Module 1 mastery by resolving a hotel room change conversation, fixing a finished-time tense clash, and applying experience markers.', 'Проверьте знания модуля 1: выберите ответ администратора отеля, исправьте конфликт времён и вставьте маркер жизненного опыта.', 'Bu ichki 1-bo‘lim sinovi bo‘lib, rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Это внутренняя проверка раздела 1; она не является официальным сертификатом CEFR.', '{"intro":{"uz":"Hotels often adjust reservations after check-in. Listening carefully helps you confirm the right room and keep keycards organized.","ru":"В отеле нередко меняют номер после заселения. Важно точно расслышать условия и номер новой комнаты."},"learningObjective":{"uz":"Select the accurate reception reply from audio evidence and eliminate tense conflicts with ''yesterday'' and ''ever''.","ru":"Выбрать точный ответ администратора по аудио и устранить ошибки с маркерами ''yesterday'' и ''ever''."},"warmUp":{"uz":"Remember: ''ever'' asks about life experience up to now, while ''yesterday'' locks the verb into Past Simple.","ru":"Помните: ''ever'' спрашивает о жизненном опыте до настоящего момента, а ''yesterday'' требует только Past Simple."},"vocabularyItems":[{"word":"reservation","uz":"oldindan band qilish","ru":"бронирование","ipa":"/ˌrezəˈveɪʃn/"},{"word":"courtyard","uz":"ichki hovli","ru":"внутренний двор","ipa":"/ˈkɔːtjɑːd/"}],"grammarNote":{"rule":"Experience Questions (Have you ever + V3?) vs Finished Time (Past Simple)","simpleExplanationUz":"Place ''ever'' directly before V3 in questions (''Have you ever stayed...?''). Never pair Present Perfect with ''yesterday'' or ''last night''.","simpleExplanationRu":"Ставьте ''ever'' прямо перед V3 в вопросах (''Have you ever stayed...?''). Никогда не сочетайте Present Perfect со словами ''yesterday'' или ''last night''.","structure":"Have/Has + Subject + ever + V3? | Subject + V2 + yesterday","positiveExamples":["I checked in yesterday for a three-night stay."],"negativeExamples":["I have never stayed in Room 204 before."],"questions":["Have you ever asked to change a noisy hotel room?"],"commonMistakes":["Writing ''has landed yesterday'' instead of ''landed yesterday''."]},"pronunciationFocus":{"uz":"In fluent questions, ''Have you'' reduces to /həv jə/ while stress stays on ''ever'' and the main participle.","ru":"В беглой речи ''Have you'' сокращается до /həv jə/, а ударение падает на ''ever'' и смысловой глагол."},"examples":["Since you still have two nights left, would you like to move to Room 412?"],"guidedPractice":{"uz":"Listen to the hotel guest and receptionist before completing the dialogue.","ru":"Прослушайте разговор гостя и администратора перед выбором реплики."},"independentPractice":{"uz":"Solve the conversation completion, error correction, and alternate experience gap.","ru":"Выполните дополнение диалога, исправление ошибки и альтернативный пропуск."},"listeningRef":"media_eng_b1_u1_cp_hotel_dialogue","readingRef":"lesson_eng_b1_u1_cp_concept","speakingTask":{"uz":"Politely request a quieter room away from street noise in two sentences.","ru":"Вежливо попросите более тихий номер вдали от улицы в двух предложениях."},"writingTask":{"uz":"Identify and fix the tense error triggered by ''yesterday evening''.","ru":"Найдите и исправьте ошибку времени, вызванную маркером ''yesterday evening''."},"knowledgeCheck":"q_eng_b1_u1_cp_listen_conv","finalQuiz":"q_eng_b1_u1_cp_reinf_err","feedbackRules":{"uz":"Checkpoint requires 70% mastery to unlock Module 2.","ru":"Для открытия модуля 2 требуется набрать 70% в этой проверке."},"summaryAndRevision":{"uz":"Module 2 shifts from travel status to workplace deadlines and conditional backup plans.","ru":"В модуле 2 мы перейдём от поездок к рабочим срокам и условным запасным планам."}}'::jsonb, '[{"id":"lesson_eng_b1_u1_cp_concept","stepNumber":1,"type":"concept","title":"Checkpoint Briefing: Reception & Tense Accuracy","titleRu":"Инструкция проверки: Отель и точность времён","content":"Before advancing to Module 2, confirm that you can catch exact room and duration facts in speech and keep finished-time markers separate from Present Perfect. Note that ''ever'' fits experience questions before the past participle, whereas ''yesterday'' always calls for Past Simple. Tinglashda eski va yangi xona raqamini ajrating.","contentRu":"Перед переходом к модулю 2 убедитесь, что вы точно различаете детали номера в диалоге и не смешиваете маркеры завершённого прошлого с Present Perfect. Слово ''ever'' ставится перед третьей формой глагола в вопросах об опыте."},{"id":"lesson_eng_b1_u1_cp_audio","stepNumber":2,"type":"audio_simulation","title":"Listening: Hotel Room Switch","titleRu":"Аудирование: Смена номера в отеле","content":"Listen to the guest and receptionist. Notice why the guest wants to move and which room number and side the receptionist offers.","contentRu":"Прослушайте диалог гостя и администратора. Обратите внимание на причину смены номера и предложенную новую комнату.","media":{"id":"media_eng_b1_u1_cp_hotel_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/b1/b1-u1-cp-hotel-dialogue.wav","title":"1-bo‘lim sinovi: Mehmonxonada xonani almashtirish suhbati","titleUz":"1-bo‘lim sinovi: Mehmonxonada xonani almashtirish suhbati","titleRu":"Проверка раздела 1: Смена номера в отеле","transcript":"Guest: Good afternoon. I checked in yesterday for a three-night stay, and I''ve never stayed in Room two zero four before, but the street noise kept me awake.\nReceptionist: I''m really sorry about that. Since you still have two nights left, would you like to move to Room four twelve? It faces the quiet courtyard away from the elevator.\nGuest: Courtyard side away from the elevator sounds perfect. Should I return the old key card now?\nReceptionist: Yes, please. I have already updated your reservation, so here is your new card for Room four twelve.","posterImage":"/lesson-media/english/b1/b1-m1-travel-boarding.png","posterAlt":"Mehmonxona binosi, kalit belgisi va yangilangan safar kartochkasi tasviri","posterAltUz":"Mehmonxona binosi, kalit belgisi va yangilangan safar kartochkasi tasviri","posterAltRu":"Здание отеля, золотой значок ключа и обновлённая карта маршрута","durationSeconds":34.267,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Guest: Good afternoon. I checked in yesterday for a three-night stay, and I''ve never stayed in Room two zero four before, but the street noise kept me awake.\nReceptionist: I''m really sorry about that. Since you still have two nights left, would you like to move to Room four twelve? It faces the quiet courtyard away from the elevator.\nGuest: Courtyard side away from the elevator sounds perfect. Should I return the old key card now?\nReceptionist: Yes, please. I have already updated your reservation, so here is your new card for Room four twelve.","speakerName":"Guest & Receptionist"}},{"id":"lesson_eng_b1_u1_cp_q","stepNumber":3,"type":"interactive_question","title":"Conversation Completion: Receptionist''s Offer","titleRu":"Дополнение диалога: Ответ администратора","content":"Choose the receptionist''s reply that accurately reflects the audio recording.","contentRu":"Выберите ответ администратора, который соответствует аудиозаписи.","interactiveQuestion":{"id":"q_eng_b1_u1_cp_listen_conv","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"B1","topic":"Checkpoint: Hotel conversation completion","difficulty":"medium","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Guest: \"Room 204 is noisy, and I still have two nights left.\"","Receptionist: \"___\""],"text":"Audiodagi suhbat mazmuniga mos keladigan mehmonxona xodimining javobini tanlang:","textRu":"Выберите реплику администратора, соответствующую аудиодиалогу:","options":["You have to stay in Room 204 for three more nights near the elevator.","I cancelled your entire reservation because you checked in yesterday.","Would you like to move to Room 204 facing the main street?","I have updated your booking to Room 412 on the quiet courtyard side."],"correctIndex":3,"mistakeFeedbackByOption":{"You have to stay in Room 204 for three more nights near the elevator.":{"uz":"Mehmon 204-xonadan shikoyat qildi va 2 kechasi qolgan edi; xodim tinch hovli tomondagi 412-xonani taklif qildi.","ru":"Гость жаловался на шум в 204-м номере (осталось 2 ночи), и ему предложили тихий 412-й номер."},"I cancelled your entire reservation because you checked in yesterday.":{"uz":"Bron bekor qilinmadi, aksincha xodim uni yangi xonaga o‘tkazib yangiladi.","ru":"Бронирование не отменяли — его обновили на другую комнату."},"Would you like to move to Room 204 facing the main street?":{"uz":"204-xona shovqinli ko‘cha tomondagi eski xona edi, yangisi esa hovli tomonda.","ru":"Номер 204 с окнами на улицу был как раз прежним шумным номером."}},"explanation":"The receptionist apologizes for the street noise and updates the booking to Room 412 facing the quiet courtyard away from the elevator.","explanationRu":"Администратор извиняется за уличный шум и обновляет бронь на тихий номер 412 во внутренний двор.","wrongFeedback":"Xodim qaysi yangi xona raqamini va qaysi tinch tomonni taklif qilganini qayta tinglang.","wrongFeedbackRu":"Переслушайте, какой новый номер комнаты и какую тихую сторону предложил администратор."}}]'::jsonb, '{"id":"q_eng_b1_u1_cp_reinf_err","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Checkpoint: Fixing Present Perfect + finished time","difficulty":"medium","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"Our flight has landed at Tashkent airport yesterday evening.","text":"Tugallangan vaqt belgisi bilan mos kelmaydigan fe’l xatosini tuzating:","textRu":"Исправьте ошибку времени глагола при маркере завершённого прошлого:","options":["Our flight has land at Tashkent airport yesterday evening.","Our flight landed at Tashkent airport yesterday evening.","Our flight was landed at Tashkent airport yesterday evening.","Our flight had landing at Tashkent airport yesterday evening."],"correctIndex":1,"mistakeFeedbackByOption":{"Our flight has land at Tashkent airport yesterday evening.":{"uz":"«yesterday evening» bilan Present Perfect ishlatilmaydi, bundan tashqari «has» dan keyin V1 kelmaydi.","ru":"Со словом «yesterday evening» Present Perfect запрещён, к тому же после «has» нужна 3-я форма."},"Our flight was landed at Tashkent airport yesterday evening.":{"uz":"«land» (qo‘nmoq) bu yerda faol harakat bo‘lgani uchun majhul nisbat («was landed») kerak emas.","ru":"Самолёт совершил посадку сам (активный залог), страдательный «was landed» здесь лишний."},"Our flight had landing at Tashkent airport yesterday evening.":{"uz":"«had» dan keyin «-ing» shakli emas, o‘tgan zamonning oddiy shakli (V2) qo‘llanadi.","ru":"После «had» не ставится «-ing»; здесь нужен обычный Past Simple."}},"explanation":"''yesterday evening'' specifies a finished past time, so Past Simple (''landed'') is required.","explanationRu":"Маркер ''yesterday evening'' указывает на завершённое время в прошлом, поэтому требуется Past Simple (''landed'').","wrongFeedback":"Gapdagi aniq o‘tgan vaqt ko‘rsatkichiga mos keladigan to‘g‘ri faol o‘tgan zamon shaklini tanlang.","wrongFeedbackRu":"Выберите правильную форму активного прошедшего времени для завершённого момента в прошлом."}'::jsonb, '{"id":"q_eng_b1_u1_cp_alt_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Alternate: Experience marker ever","difficulty":"medium","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"Have you ___ missed a train because of heavy traffic?","text":"Savol gapda hayotiy tajribani («biror marta») so‘rash uchun bo‘sh joyga mos ravishni yozing: «Have you ___ missed a train because of heavy traffic?»","textRu":"Вставьте наречие жизненного опыта («когда-либо») в вопрос: «Have you ___ missed a train because of heavy traffic?»","options":[],"acceptedAnswers":["ever"],"explanation":"''ever'' is used in Present Perfect questions to ask ''at any time in your life up to now''.","explanationRu":"Наречие ''ever'' используется в вопросах Present Perfect со значением «когда-либо в жизни».","wrongFeedback":"So‘roq gaplarda inkor ma’nosi o‘rniga hayotiy tajribani («biror marta») so‘rovchi qisqa ravishni qo‘llang.","wrongFeedbackRu":"В вопросах используется короткое наречие со значением «когда-либо в жизни»."}'::jsonb, true, true, false),
  ('lesson_eng_b1_m2_work_study', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'grammar', 'B1', 'mod_eng_b1_m2', 'unit_eng_b1_u2', 'Ish yoki o‘qishdagi kechikish sababini (because, since, so) tushuntiradi va First Conditional bilan zaxira reja tuzadi.', 'Объясняет причину задержки на работе или учёбе (because, since, so) и формулирует запасной план в First Conditional.', '["node_eng_b1_u1_checkpoint"]'::jsonb, 'Work, Study & Unexpected Problems (First Conditional + Cause/Reason)', 'Учёба, работа и сбои: First Conditional и причина', 10, 'You learn how to explain a technical setback clearly using ''because/since/so'' and build realistic First Conditional backup plans without putting ''will'' in the ''if''-clause.', 'Вы научитесь объяснять причину сбоя через ''because/since/so'' и строить реальные запасные планы в First Conditional без ''will'' после ''if''.', 'Ichki modul sinovlari va B1 chiqish testi o‘quv dasturi doirasidagi tayyorgarlikni tekshiradi; ular rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Внутренние модульные проверки и итоговый тест B1 оценивают учебный прогресс и не выдают официальный международный сертификат CEFR.', '{"intro":{"uz":"Unexpected server outages or tight deadlines happen in university and office life. Strong B1 speakers explain the cause quickly and offer a clear Plan B.","ru":"На учёбе и работе часто случаются технические сбои перед дедлайном. Важно быстро назвать причину и предложить чёткий запасной план."},"learningObjective":{"uz":"Connect causes and results with ''because/since/so'' and construct accurate First Conditional plans (''If + Present Simple, will + V1'').","ru":"Связывать причину и следствие через ''because/since/so'' и составлять планы по модели First Conditional (''If + Present Simple, will + V1'')."},"warmUp":{"uz":"In A2 you planned with ''going to''. Now imagine your upload portal breaks at 2:50 p.m. before a 4:00 p.m. deadline: what happens IF it stays offline?","ru":"В A2 вы использовали ''going to''. А как выразить условие: что вы сделаете, ЕСЛИ портал не заработает к трём часам?"},"vocabularyItems":[{"word":"deadline","uz":"topshirish oxirgi muddati","ru":"крайний срок сдачи","ipa":"/ˈdedlaɪn/"},{"word":"backup plan","uz":"zaxira chorasi","ru":"запасной вариант действий","ipa":"/ˈbækʌp plæn/"},{"word":"postpone","uz":"keyinga surmoq","ru":"отложить на потом","ipa":"/pəˈspəʊn/"},{"word":"resubmit","uz":"qaytadan topshirmoq","ru":"отправить повторно","ipa":"/ˌriːsəbˈmɪt/"}],"grammarNote":{"rule":"First Conditional (If + Present Simple, will + V1) & Cause/Result (because / since / so)","simpleExplanationUz":"Use First Conditional for real future possibilities: the ''if''-clause takes Present Simple, and the main clause takes ''will''. O‘zbek tilida ikkala qismda ham kelasi zamon (''agar ishlamasa, yuboramiz'') ko‘rinadi, lekin inglizchada ''if'' dan keyin hech qachon ''will'' qo‘yilmaydi. Shuningdek, bitta gapda ham ''because'', ham ''so'' ni birga ishlatmang.","simpleExplanationRu":"В First Conditional после ''if'' всегда ставится Present Simple (никогда ''will''!), а в главной части — ''will + V1''. В русском в обеих частях звучит будущее («если не сработает, отправим»), поэтому легко допустить ошибку. И не объединяйте ''because'' и ''so'' в одном предложении.","structure":"If + Subject + Present Simple, Subject + will + V1 | Because/Since + [cause], [result] | [cause], so + [result]","positiveExamples":["If the portal stays offline, we will email the PDF directly.","Since the server crashed, we exported a local backup."],"negativeExamples":["If the portal does not come back online by three, we will postpone the demo.","We didn''t lose the file because Timur saved a copy."],"questions":["What will we do if the printer stops working before noon?","Why couldn''t Timur upload the report on time?"],"commonMistakes":["Putting ''will/won''t'' inside the ''if''-clause (''If it won''t work...'' -> wrong; say ''If it doesn''t work...''), and writing double connectors (''Because it rained, so we stayed'' -> remove ''so'')."]},"pronunciationFocus":{"uz":"Notice the quick contraction ''we''ll'' /wiːl/ vs full ''will'' /wɪl/, and second-syllable stress in ''postpone'' /pəˈspəʊn/.","ru":"Обратите внимание на краткую форму ''we''ll'' /wiːl/ и ударение на второй слог в ''postpone'' /pəˈspəʊn/."},"examples":["The upload portal stopped working because of server maintenance, so I exported a backup.","If the portal does not recover by 3:00 p.m., we will email the PDF."],"guidedPractice":{"uz":"Study the troubleshooting flowchart illustration, listen to Timur and Kamola, and review the 4 B1 cards.","ru":"Изучите схему запасного плана, прослушайте диалог Тимура и Камолы и повторите 4 карточки."},"independentPractice":{"uz":"Identify the root cause and Plan B from audio, fill the negative conditional verb, and fix a double-connector error.","ru":"Определите причину и план Б по аудио, впишите условие в Present Simple и исправьте двойную связку."},"listeningRef":"media_eng_b1_m2_work_dialogue","readingRef":"lesson_eng_b1_m2_concept","speakingTask":{"uz":"State a study problem with ''since'' and offer a First Conditional backup step.","ru":"Назовите учебную проблему через ''since'' и предложите запасной шаг в First Conditional."},"writingTask":{"uz":"Remove redundant connectors in a cause-and-result sentence.","ru":"Уберите лишнюю связку в предложении с причиной и следствием."},"knowledgeCheck":"q_eng_b1_m2_listen_mcq","finalQuiz":"q_eng_b1_m2_cond_fill","feedbackRules":{"uz":"Feedback targets ''if + will'' L1 transfer and ''because... so...'' double-conjunction errors.","ru":"Подсказки разбирают перенос будущего времени после ''if'' и двойной союз ''because... so...''."},"summaryAndRevision":{"uz":"You are ready for Unit 2''s university IT memo checkpoint.","ru":"Вы готовы к проверке раздела 2 по объявлению университетской IT-службы."}}'::jsonb, '[{"id":"lesson_eng_b1_m2_concept","stepNumber":1,"type":"concept","title":"First Conditional & Cause-Result Connectors","titleRu":"First Conditional и связки причины и следствия","content":"When a real problem threatens a deadline, First Conditional connects the condition (''If + Present Simple'') to the action plan (''will + V1''). Never place ''will'' inside the ''if''-clause, even though both Uzbek and Russian translate the condition with future meaning. Use ''because'' or ''since'' before a reason, or ''so'' before a result, never both together. Inglizchada bitta gapda ''because'' va ''so'' yonma-yon kelmaydi.","contentRu":"Для реальных условий будущего используйте First Conditional: после ''if'' ставится Present Simple (без ''will''), а в основной части — ''will + V1''. Слова ''because'' и ''since'' вводят причину, а ''so'' — результат; в одном английском предложении их не совмещают.","highlightNotes":["Condition (Present Simple): If the portal doesn''t work by 3:00,","Result (will + V1): we will email the PDF directly.","Single connector: Because the server crashed, we exported a backup."]},{"id":"lesson_eng_b1_m2_audio","stepNumber":2,"type":"audio_simulation","title":"Listening: Server Outage Before Deadline","titleRu":"Аудирование: Сбой сервера перед дедлайном","content":"Listen to Timur and Kamola discussing a blocked submission portal. Pay attention to what caused the issue, whether the file is safe, and what Plan B they choose at 3:00 p.m.","contentRu":"Прослушайте диалог Тимура и Камолы о сбое портала. Запомните причину проблемы, сохранность файла и запасной план на 15:00.","media":{"id":"media_eng_b1_m2_work_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/b1/b1-m2-work-dialogue.wav","title":"O‘qish va ish: Server muammosi va zaxira reja suhbati","titleUz":"O‘qish va ish: Server muammosi va zaxira reja suhbati","titleRu":"Работа и учёба: сбой сервера и запасной план","transcript":"Timur: Hi Kamola, the upload portal has stopped working because of unexpected server maintenance, so I can''t submit our team report before the four o''clock deadline.\nKamola: Thanks for telling me early. Have you saved a local PDF copy on your laptop?\nTimur: Yes, I exported a backup ten minutes ago, so nothing is lost.\nKamola: Great. If the portal does not come back online by three o''clock, we will email the PDF directly to Dr. Karim and postpone the live demo until Thursday morning.","posterImage":"/lesson-media/english/b1/b1-m2-work-problem.png","posterAlt":"To‘xtatib qo‘yilgan yuklash oynasi, server ogohlantirish belgisi va zaxira yuborish sxemasi","posterAltUz":"To‘xtatib qo‘yilgan yuklash oynasi, server ogohlantirish belgisi va zaxira yuborish sxemasi","posterAltRu":"Приостановленная загрузка на ноутбуке, предупреждение о сервере и резервный канал отправки","durationSeconds":31.019,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Timur: Hi Kamola, the upload portal has stopped working because of unexpected server maintenance, so I can''t submit our team report before the four o''clock deadline.\nKamola: Thanks for telling me early. Have you saved a local PDF copy on your laptop?\nTimur: Yes, I exported a backup ten minutes ago, so nothing is lost.\nKamola: Great. If the portal does not come back online by three o''clock, we will email the PDF directly to Dr. Karim and postpone the live demo until Thursday morning.","speakerName":"Timur & Kamola"}},{"id":"lesson_eng_b1_m2_flashcards","stepNumber":3,"type":"flashcard","title":"Troubleshooting & Deadlines Flashcards","titleRu":"Карточки: Сроки и запасной план","content":"Listen carefully to stress and syllable breaks, test your recall, and reveal the Uzbek/Russian explanation.","contentRu":"Прослушайте произношение, проверьте себя и откройте перевод.","flashcards":[{"id":"fc_eng_b1_m2_1","front":"deadline","backUz":"topshirish oxirgi muddati","backRu":"крайний срок сдачи","partOfSpeech":"noun","ipa":"/ˈdedlaɪn/","ipaAmE":"/ˈdedlaɪn/","cefrLevel":"B1","example":"Our team submitted the slides two hours before the deadline.","exampleUz":"Jamoamiz slaydlarni oxirgi muddatdan ikki soat oldin topshirdi.","exampleRu":"Наша команда сдала слайды за два часа до крайнего срока.","audioSrc":"/lesson-media/english/b1/b1-m2-deadline.wav","imageSrc":"/lesson-media/english/b1/b1-m2-work-problem.png","alt":"Sariq ogohlantirish belgisi yonida turgan taqvim va soat","altRu":"Календарь и циферблат рядом с жёлтым треугольным знаком","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m2_2","front":"backup plan","backUz":"zaxira chorasi","backRu":"запасной вариант действий","partOfSpeech":"noun","ipa":"/ˈbækʌp plæn/","ipaAmE":"/ˈbækʌp plæn/","cefrLevel":"B1","example":"Always prepare a backup plan in case the Wi-Fi drops.","exampleUz":"Wi-Fi uzilib qolsa deb har doim zaxira chorasini tayyorlab qo‘ying.","exampleRu":"Всегда готовьте запасной вариант на случай отключения Wi-Fi.","audioSrc":"/lesson-media/english/b1/b1-m2-backup-plan.wav","imageSrc":"/lesson-media/english/b1/b1-m2-work-problem.png","alt":"Asosiy yo‘ldan ajralib chiquvchi yashil yo‘nalish va hujjat belgisi","altRu":"Зелёная стрелка обхода со значком облачного файла","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m2_3","front":"postpone","backUz":"keyinga surmoq","backRu":"отложить на потом","partOfSpeech":"verb","ipa":"/pəˈspəʊn/","ipaAmE":"/pəˈspoʊn/","cefrLevel":"B1","example":"We had to postpone the presentation until Thursday morning.","exampleUz":"Taqdimotni payshanba tongigacha keyinga surishga majbur bo‘ldik.","exampleRu":"Нам пришлось отложить презентацию до утра четверга.","audioSrc":"/lesson-media/english/b1/b1-m2-postpone.wav","imageSrc":"/lesson-media/english/b1/b1-m2-work-problem.png","alt":"Ustiga chiziq tortilgan qizil soat yonidagi o‘ngga yo‘nalgan strelka","altRu":"Перечёркнутый красный циферблат рядом со стрелкой вправо","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m2_4","front":"resubmit","backUz":"qaytadan topshirmoq","backRu":"отправить повторно","partOfSpeech":"verb","ipa":"/ˌriːsəbˈmɪt/","ipaAmE":"/ˌriːsəbˈmɪt/","cefrLevel":"B1","example":"If the upload fails, please resubmit the PDF by email.","exampleUz":"Agar yuklash ishlamasa, PDF faylni elektron pochta orqali qaytadan topshiring.","exampleRu":"Если загрузка не пройдёт, отправьте PDF повторно по почте.","audioSrc":"/lesson-media/english/b1/b1-m2-resubmit.wav","imageSrc":"/lesson-media/english/b1/b1-m2-work-problem.png","alt":"Noutbuk ekranidan xat konverti tomon yo‘nalgan yashil tasdiq belgisi","altRu":"Зелёный маркер передачи файла от ноутбука к почтовому конверту","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_b1_m2_listen_q","stepNumber":4,"type":"interactive_question","title":"Listening Check: Cause & Plan B","titleRu":"Проверка аудирования: Причина и запасной план","content":"Identify why the upload failed and what the team will do if the system stays down at 3:00 p.m.","contentRu":"Определите причину сбоя и действия команды, если портал не заработает к 15:00.","interactiveQuestion":{"id":"q_eng_b1_m2_listen_mcq","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"B1","topic":"Listening: Problem cause and First Conditional plan","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi suhbatga ko‘ra, Timur hisobotni yuklay olmasligiga nima sabab bo‘ldi va portal soat 15:00 gacha ishlamasa jamoa nima qiladi?","textRu":"Почему Тимур не смог загрузить отчёт и что сделает команда, если портал не заработает к 15:00?","options":["Timurning noutbuki buzilib fayl o‘chdi; loyihani butunlay bekor qilishadi","Server texnik xizmati portalni to‘xtatdi; PDF ni pochta orqali yuborib, jonli taqdimotni payshanbaga ko‘chirishadi","Muddat soat 15:00 da tugadi; portal ochilishini juma kunigacha kutishadi","Doktor Karim ta’tilga chiqdi; hisobotni qog‘ozda chop etishadi"],"correctIndex":1,"mistakeFeedbackByOption":{"Timurning noutbuki buzilib fayl o‘chdi; loyihani butunlay bekor qilishadi":{"uz":"Timur 10 daqiqa oldin mahalliy PDF zaxirasini saqlab olganini aytdi, demak hech narsa yo‘qolmagan.","ru":"Тимур сохранил локальную копию PDF 10 минут назад, поэтому данные не потеряны."},"Muddat soat 15:00 da tugadi; portal ochilishini juma kunigacha kutishadi":{"uz":"Asosiy muddat 16:00 edi; 15:00 esa pochta orqali yuborish qarori qabul qilinadigan nazorat vaqti, taqdimot esa payshanbaga ko‘chiriladi.","ru":"Дедлайн был в 16:00, а 15:00 — точка проверки перед отправкой по почте; демонстрация переносится на четверг."},"Doktor Karim ta’tilga chiqdi; hisobotni qog‘ozda chop etishadi":{"uz":"Ular PDF faylni bevosita Doktor Karimga elektron pochta orqali yuborishga kelishib olishdi.","ru":"Команда договорилась отправить PDF напрямую доктору Кариму по электронной почте."}},"explanation":"Unexpected server maintenance blocked the portal; if it stays offline at 3:00 p.m., they will email the saved PDF to Dr. Karim and postpone the live demo until Thursday morning.","explanationRu":"Причина — внезапное техобслуживание сервера; при сбое к 15:00 команда отправит PDF по почте и перенесёт демо на утро четверга.","wrongFeedback":"Suhbatda aytilgan uzilish sababi, PDF zaxirasi va payshanba kuni haqidagi rejasini qayta tinglang.","wrongFeedbackRu":"Переслушайте в аудио причину сбоя, судьбу PDF-копии и решение на случай простоя в 15:00."}},{"id":"lesson_eng_b1_m2_fill_q","stepNumber":5,"type":"interactive_question","title":"Grammar Practice: First Conditional Clause","titleRu":"Грамматика: Условие в First Conditional","content":"Complete the negative ''if''-clause with the correct tense form of ''work''.","contentRu":"Дополните отрицательное условие правильной формой глагола ''work''.","interactiveQuestion":{"id":"q_eng_b1_m2_cond_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"First Conditional negative if-clause","difficulty":"medium","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"If the lab printer ___ tomorrow morning, we will submit digital copies.","text":"Qavsdagi «work» fe’lining inkor shaklini First Conditional qoidasiga moslab yozing: «If the lab printer ___ (not / work) tomorrow morning, we will submit digital copies.»","textRu":"Раскройте скобки в условии First Conditional: «If the lab printer ___ (not / work) tomorrow morning, we will submit digital copies.»","options":[],"acceptedAnswers":["doesn''t work","does not work"],"explanation":"In First Conditional, the ''if''-clause requires Present Simple even when referring to ''tomorrow morning'': ''doesn''t work'' (singular subject ''printer'').","explanationRu":"В придаточном с ''if'' всегда нужен Present Simple даже со словом ''tomorrow morning'': для единственного числа — ''doesn''t work''.","wrongFeedback":"Shart ergash gapida kelasi yordamchi fe’l ishlatmang; birlikdagi ega uchun hozirgi oddiy zamon inkorini qo‘ying.","wrongFeedbackRu":"Не ставьте будущее время в часть с условием: используйте отрицание настоящего простого времени для третьего лица."}}]'::jsonb, '{"id":"q_eng_b1_m2_cause_err","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Cause and result single connector","difficulty":"medium","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"Because the power went out, so we postponed the meeting.","text":"Sabab va oqibat bog‘lovchilari qo‘shilib ketgan xatoni tuzating:","textRu":"Исправьте ошибку лишнего союза в предложении причины и следствия:","options":["Because the power went out, therefore we postponed the meeting.","Because the power went out, we postponed the meeting.","Since the power went out, so we postponed the meeting.","So the power went out, because we postponed the meeting."],"correctIndex":1,"mistakeFeedbackByOption":{"Because the power went out, therefore we postponed the meeting.":{"uz":"«Because» ishlatilganda asosiy gap boshida «therefore» qo‘shish ham ortiqcha ikkilangan bog‘lovchi bo‘ladi.","ru":"При наличии «Because» добавлять «therefore» перед главной частью также избыточно."},"Since the power went out, so we postponed the meeting.":{"uz":"«Since» sababni bildiradi, shuning uchun «so» natija bog‘lovchisi bilan bir gapda kelmaydi.","ru":"«Since» уже вводит причину, поэтому союз «so» во второй части лишний."},"So the power went out, because we postponed the meeting.":{"uz":"Bu variantda sabab va oqibat o‘rni almashib ketgan va ma’no buzilgan.","ru":"Здесь перепутаны местами причина и следствие."}},"explanation":"English uses either ''Because/Since + cause, result'' OR ''cause, so + result'' — never both connectors in the same sentence.","explanationRu":"В английском используется либо ''Because/Since'' в начале, либо ''so'' перед результатом, но не оба союза одновременно.","wrongFeedback":"Bitta gapda faqat bitta sabab yoki oqibat bog‘lovchisini qoldiradigan to‘g‘ri variantni tanlang.","wrongFeedbackRu":"Выберите вариант, где в одном предложении остаётся только одна связка причины или следствия."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_b1_u2_checkpoint', 'course_eng_01', 'skill_eng_reading', 'reading', 'checkpoint', 'B1', 'mod_eng_b1_m2', 'unit_eng_b1_u2', 'Universitet IT bildirishnomasidan shart va muddat o‘zgarishini aniqlaydi hamda First Conditional jumlasini tuzadi.', 'Находит условия и перенос сроков в уведомлении IT-службы и составляет условное предложение.', '["node_eng_b1_m2_work_study"]'::jsonb, 'Unit 2 Checkpoint: Internship Troubleshooting Memo', 'Проверка раздела 2: Служебная записка о сбое', 7, 'Read an official campus Wi-Fi maintenance memo, verify the automatic deadline extension, order a First Conditional sentence, and write a warning with ''unless''.', 'Прочтите уведомление о техработах Wi-Fi, рассчитайте продлённый дедлайн, соберите условное предложение и составьте предупреждение с ''unless''.', 'Bu ichki 2-bo‘lim sinovi bo‘lib, rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Это внутренняя проверка раздела 2; она не является официальным сертификатом CEFR.', '{"intro":{"uz":"Workplace memos often hide key conditions inside ''unless'' clauses and extension rules. Reading accurately prevents missed deadlines.","ru":"В рабочих объявлениях важные условия часто выражены через ''unless'' и правила продления сроков."},"learningObjective":{"uz":"Extract deadline extensions from a memo and produce accurate ''if/unless'' conditional sentences.","ru":"Извлекать условия продления сроков из текста и строить предложения с ''if'' и ''unless''."},"warmUp":{"uz":"Remember: ''unless'' means ''if ... not'', so the verb after ''unless'' stays positive.","ru":"Помните: ''unless'' означает «если не», поэтому глагол после него стоит в утвердительной форме."},"vocabularyItems":[{"word":"outage","uz":"tizim uzilishi","ru":"сбой в работе сети","ipa":"/ˈaʊtɪdʒ/"},{"word":"extension","uz":"muddatni uzaytirish","ru":"продление срока","ipa":"/ɪkˈstenʃn/"}],"grammarNote":{"rule":"Unless (= if not) + Positive Present Simple, will + V1","simpleExplanationUz":"''Unless'' means ''if you do not''. Never add ''not'' inside an ''unless''-clause: say ''Unless you save a backup'', NOT ''Unless you don''t save''.","simpleExplanationRu":"Союз ''unless'' уже несёт отрицание («если не»), поэтому после него используется утвердительный Present Simple.","structure":"Unless + Subject + Present Simple, Subject + will + V1","positiveExamples":["Unless you download the pack beforehand, you will need mobile data."],"negativeExamples":["Do not use ''won''t'' or ''don''t'' directly after ''unless'' for this warning."],"questions":["When must a 14:00 assignment be submitted after the 3-hour extension?"],"commonMistakes":["Using double negation (''Unless you don''t save...'') or placing ''will'' after ''unless''."]},"pronunciationFocus":{"uz":"Stress the second syllable in ''unless'' /ʌnˈles/ and ''extension'' /ɪkˈstenʃn/.","ru":"Ударение падает на второй слог в словах ''unless'' /ʌnˈles/ и ''extension'' /ɪkˈstenʃn/."},"examples":["Assignments due at 14:00 automatically receive a 3-hour extension."],"guidedPractice":{"uz":"Check every time window and condition in the campus IT memo carefully.","ru":"Внимательно сопоставьте временные интервалы и условия в памятке."},"independentPractice":{"uz":"Answer the memo comprehension question, order the conditional clause, and write an ''unless'' warning.","ru":"Ответьте на вопрос по тексту, соберите предложение и напишите предупреждение с ''unless''."},"listeningRef":null,"readingRef":"lesson_eng_b1_u2_cp_concept","speakingTask":{"uz":"Warn a teammate aloud about backing up slides before a network outage.","ru":"Устно предупредите коллегу о необходимости сохранить слайды до отключения сети."},"writingTask":{"uz":"Write a First Conditional warning using ''unless'' or ''if ... don''t''.","ru":"Напишите предупреждение в First Conditional с ''unless'' или ''if ... don''t''."},"knowledgeCheck":"q_eng_b1_u2_cp_read_mcq","finalQuiz":"q_eng_b1_u2_cp_reinf_order","feedbackRules":{"uz":"Score 70% or higher to unlock Module 3 narrative storytelling.","ru":"Наберите не менее 70%, чтобы открыть модуль 3."},"summaryAndRevision":{"uz":"Next, Module 3 connects Past Continuous and Past Simple for coherent storytelling.","ru":"Далее в модуле 3 вы объедините Past Continuous и Past Simple для рассказа историй."}}'::jsonb, '[{"id":"lesson_eng_b1_u2_cp_concept","stepNumber":1,"type":"concept","title":"Checkpoint Briefing: ''Unless'' & Deadline Logic","titleRu":"Инструкция проверки: ''Unless'' и логика сроков","content":"In official notices, ''unless'' replaces ''if ... not'' with a positive verb. For example, ''Unless you download the file before 13:00'' equals ''If you do not download the file before 13:00''. Always calculate time extensions carefully against the original deadline. Qo‘shimcha soatlarni dastlabki muddatga qo‘shib hisoblang.","contentRu":"В деловых объявлениях союз ''unless'' заменяет ''if ... not'' и требует утвердительного глагола. Всегда прибавляйте время продления к исходному дедлайну."},{"id":"lesson_eng_b1_u2_cp_read_q","stepNumber":2,"type":"interactive_question","title":"Reading Check: IT Maintenance Memo","titleRu":"Чтение: Уведомление IT-службы","content":"Read the university IT notice carefully and determine the exact revised deadline and preparation step.","contentRu":"Прочтите объявление IT-службы и определите новый срок сдачи и способ избежать расхода мобильного трафика.","interactiveQuestion":{"id":"q_eng_b1_u2_cp_read_mcq","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"B1","topic":"Checkpoint: Reading IT maintenance memo","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"University IT Notice: Library Wi-Fi maintenance runs from 13:00 to 15:00 on Wednesday. Unless you download reading packs beforehand, you will need mobile data. Assignments due at 14:00 automatically receive a 3-hour extension.","text":"Bildirishnomaga ko‘ra, soat 14:00 ga belgilangan topshiriq eng kechi qachon topshirilishi kerak va talabalar mobil internet sarflamaslik uchun nima qilishi lozim?","textRu":"До какого времени можно сдать работу, назначенную на 14:00, и как студентам избежать траты мобильного интернета?","options":["Soat 15:00 gacha; soat 14:00 da kutubxona Wi-Fi tarmog‘iga ulanish kerak","Soat 14:00 gacha; hech qanday muddat uzaytirish berilmaydi","Soat 17:00 gacha; o‘quv materiallarini 13:00 dan oldin yuklab olish kerak","Soat 16:00 gacha; faqat mobil internet orqali yuklab olish kerak"],"correctIndex":2,"mistakeFeedbackByOption":{"Soat 15:00 gacha; soat 14:00 da kutubxona Wi-Fi tarmog‘iga ulanish kerak":{"uz":"13:00–15:00 oralig‘ida Wi-Fi ta’mirda bo‘ladi, uzaytirish esa 15:00 gacha emas, +3 soat (17:00 gacha).","ru":"С 13:00 до 15:00 Wi-Fi отключён, а продление составляет 3 часа от 14:00 (до 17:00)."},"Soat 14:00 gacha; hech qanday muddat uzaytirish berilmaydi":{"uz":"Matnda 14:00 dagi topshiriqlar avtomatik ravishda 3 soatlik uzaytirish olishi aniq yozilgan.","ru":"В тексте прямо сказано, что задания на 14:00 автоматически продлеваются на 3 часа."},"Soat 16:00 gacha; faqat mobil internet orqali yuklab olish kerak":{"uz":"14:00 + 3 soat = 17:00 bo‘ladi; materiallarni oldindan yuklab olsangiz mobil internet kerak bo‘lmaydi.","ru":"14:00 + 3 часа дают 17:00, а заблаговременная загрузка избавляет от мобильного трафика."}},"explanation":"14:00 plus a 3-hour extension gives a 17:00 deadline, and downloading packs before 13:00 avoids needing mobile data during the 13:00–15:00 maintenance.","explanationRu":"14:00 плюс 3 часа продления дают 17:00, а скачивание материалов до 13:00 позволяет обойтись без мобильного интернета.","wrongFeedback":"14:00 ga berilgan uzaytirish soatini qo‘shing va «beforehand» so‘zi qaysi soatdan oldinni anglatishini tekshiring.","wrongFeedbackRu":"Прибавьте указанное продление к 14:00 и проверьте, что означает «beforehand»."}}]'::jsonb, '{"id":"q_eng_b1_u2_cp_reinf_order","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Checkpoint: First Conditional word order","difficulty":"medium","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Agar avtobus kechiksa, biz taksi olamiz» shartli gapini to‘g‘ri tartibda tuzing:","textRu":"Составьте условное предложение «Если автобус опоздает, мы возьмём такси» в верном порядке:","options":[],"orderedTokens":["If","the bus","arrives late,","we","will take","a taxi."],"acceptedAnswers":["If the bus arrives late, we will take a taxi."],"explanation":"Condition clause comes first (''If the bus arrives late,''), followed by the future result (''we will take a taxi.'').","explanationRu":"Сначала ставится условие с запятой, затем результат с модальным глаголом будущего действия.","wrongFeedback":"Avval shart ergash gapini vergul bilan yakunlang, so‘ng ega va kelajak harakat qismini joylashtiring.","wrongFeedbackRu":"Сначала соберите условную часть с запятой на конце, затем подлежащее и основное действие."}'::jsonb, '{"id":"q_eng_b1_u2_cp_alt_text","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"B1","topic":"Alternate: First Conditional warning with unless","difficulty":"medium","questionType":"text_input","evaluationMode":"deterministic","text":"«Agar zaxira nusxa saqlamasangiz, faylni yo‘qotasiz» ma’nosidagi ogohlantirishni First Conditional shaklida («Unless ...» yoki «If you don''t ...» bilan) ingliz tilida yozing.","textRu":"Напишите на английском предупреждение в First Conditional («Если не сохраните резервную копию, потеряете файл»), используя «Unless ...» или «If you don''t ...».","options":[],"acceptedAnswers":["Unless you save a backup, you will lose the file","Unless you save a backup, you''ll lose the file","Unless you save a backup you will lose the file","Unless you save a backup you''ll lose the file","If you don''t save a backup, you will lose the file","If you don''t save a backup, you''ll lose the file","If you do not save a backup, you will lose the file","If you do not save a backup, you''ll lose the file","If you don''t save a backup you will lose the file","If you don''t save a backup you''ll lose the file","If you do not save a backup you will lose the file","If you do not save a backup you''ll lose the file"],"explanation":"Both ''Unless you save a backup, you will lose the file.'' and ''If you don''t save a backup, you will lose the file.'' express the warning accurately.","explanationRu":"Оба варианта (''Unless you save...'' и ''If you don''t save...'') грамматически точно передают предупреждение.","wrongFeedback":"Shart qismida hozirgi zamon fe’lini qo‘llang, natija qismida esa kelajak yordamchi fe’lini unutmang.","wrongFeedbackRu":"В условии используйте настоящее простое время, а в части результата — глагол будущего действия."}'::jsonb, true, true, false),
  ('lesson_eng_b1_m3_narrative', 'course_eng_01', 'skill_eng_reading', 'reading', 'writing', 'B1', 'mod_eng_b1_m3', 'unit_eng_b1_u3', 'O‘tgan davomli (Past Continuous) va sodda (Past Simple) zamonlarni hamda nisbiy olmoshlarni (who, which, where) bog‘lab izchil hikoya tuzadi.', 'Сочетает Past Continuous, Past Simple и определительные придаточные (who, which, where) для связного рассказа.', '["node_eng_b1_u2_checkpoint"]'::jsonb, 'Sequential Storytelling & Relative Clauses (Past Continuous vs Past Simple)', 'Связный рассказ и определительные придаточные', 11, 'You learn how to set a background scene with Past Continuous, introduce a sudden interruption with Past Simple, and connect people, objects, and places smoothly using ''who, which, where''.', 'Вы научитесь задавать фон действия с помощью Past Continuous, вводить внезапное событие в Past Simple и уточнять детали через ''who, which, where''.', 'Ushbu darsdagi yozma hikoya mashqi mustaqil amaliyot bo‘lib, rasmiy CEFR sertifikati bermaydi.', 'Письменное задание предназначено для самостоятельной практики и не заменяет официальный сертификат CEFR.', '{"intro":{"uz":"Good stories never sound like flat lists of verbs. Speakers paint an ongoing background scene first, then drop in the turning point that changed the outcome.","ru":"Интересный рассказ не похож на сухой список глаголов: сначала задаётся фон процесса, а затем вводится поворотное событие."},"learningObjective":{"uz":"Combine Past Continuous background actions with Past Simple interruptions and link nouns accurately with ''who, which, where''.","ru":"Сочетать фоновое действие в Past Continuous с прерывающим событием в Past Simple и связывать детали с помощью ''who, which, where''."},"warmUp":{"uz":"Picture a hackathon workshop: your team is running a test, and suddenly the lights go out. How do English speakers show which action was longer?","ru":"Представьте хакатон: команда тестирует модель, и внезапно гаснет свет. Как показать, какое действие длилось дольше?"},"vocabularyItems":[{"word":"meanwhile","uz":"shu paytda (ayni vaqtda)","ru":"тем временем","ipa":"/ˈmiːnwaɪl/"},{"word":"eventually","uz":"oxir-oqibat","ru":"в конце концов","ipa":"/ɪˈventʃuəli/"},{"word":"colleague","uz":"hamkasb","ru":"коллега по работе","ipa":"/ˈkɒliːɡ/"},{"word":"milestone","uz":"muhim bosqich","ru":"ключевая веха","ipa":"/ˈmaɪlstəʊn/"}],"grammarNote":{"rule":"Past Continuous (was/were + V-ing) + Past Simple (V2) & Relative Clauses (who / which / where)","simpleExplanationUz":"Use Past Continuous (''was testing'') for the ongoing background and Past Simple (''cut'') for the sudden interruption. Use ''who'' for people, ''which'' for things, and ''where'' for places (meaning ''in that place''). O‘zbek va rus tillaridan farqli o‘laroq, nisbiy gapda ortiqcha olmosh (''who she helped'' emas, faqat ''who helped'') qo‘shilmaydi.","simpleExplanationRu":"Используйте Past Continuous (''was testing'') для длительного фона и Past Simple (''cut'') для внезапного события. Для людей берите ''who'', для предметов — ''which'', для места действия («где») — ''where''. Не дублируйте подлежащее лишним местоимением (''who she helped'' — ошибка).","structure":"While + Subject + was/were + V-ing, Subject + V2 | Noun + who/which/where + clause","positiveExamples":["While our team was testing the prototype, a storm cut the electricity.","A student who sat beside us lent us a battery which kept the laptop running."],"negativeExamples":["We weren''t expecting a storm while we were working in the lab."],"questions":["What was your team doing when the power went out?","Where is the workshop where you built the prototype?"],"commonMistakes":["Adding a duplicate pronoun after ''who/which'' (''the colleague who he lent us'' -> ''the colleague who lent us''), or confusing ''where'' (action inside a place) with ''which'' (describing the place as an object)."]},"pronunciationFocus":{"uz":"Use weak forms /wəz/ for ''was'' and /wə/ for ''were'' in background clauses. ''Colleague'' /ˈkɒliːɡ/ has two syllables, not three.","ru":"В потоке речи ''was'' /wəz/ и ''were'' /wə/ звучат безударно. Слово ''colleague'' /ˈkɒliːɡ/ состоит из двух слогов."},"examples":["While we were testing the sensor in the workshop where we built it, the electricity went out.","Eventually, we reached the final milestone."],"guidedPractice":{"uz":"Follow the 3-panel timeline illustration, listen to Bekzod''s hackathon story, and practice the 4 narrative cards.","ru":"Изучите трёхшаговую схему рассказа, прослушайте историю Бекзода и закрепите 4 карточки."},"independentPractice":{"uz":"Solve the listening event check, match narrative connectors, write a relative adverb, and compose a mini-story.","ru":"Выполните тест на понимание истории, сопоставьте связки, заполните пропуск с относительным наречием и напишите мини-рассказ."},"listeningRef":"media_eng_b1_m3_story_dialogue","readingRef":"lesson_eng_b1_m3_concept","speakingTask":{"uz":"Retell Bekzod''s turning point in 3 sentences using ''while'', ''when'', and ''eventually''.","ru":"Перескажите поворотный момент истории Бекзода в 3 предложениях со словами ''while'', ''when'' и ''eventually''."},"writingTask":{"uz":"Write a 4–5 sentence mini-story about an unexpected event with Past Continuous, Past Simple, and a relative clause.","ru":"Напишите мини-историю из 4–5 предложений о неожиданном случае с Past Continuous, Past Simple и определительным придаточным."},"knowledgeCheck":"q_eng_b1_m3_word_match","finalQuiz":"q_eng_b1_m3_writing","feedbackRules":{"uz":"Feedback distinguishes background duration vs interruption and clarifies ''who/which/where'' roles.","ru":"Подсказки разграничивают фон и прерывание, а также функции ''who/which/where''."},"summaryAndRevision":{"uz":"All 4 narrative cards enter SRS review before the Unit 3 story audit checkpoint.","ru":"Карточки модуля переходят в повторение перед проверкой раздела 3."}}'::jsonb, '[{"id":"lesson_eng_b1_m3_concept","stepNumber":1,"type":"concept","title":"Background Action, Interruption & Relative Clauses","titleRu":"Фон, прерывание и определительные придаточные","content":"Start a story by setting the ongoing scene with Past Continuous (''was/were + V-ing''), then introduce the sudden event in Past Simple. Connect extra detail smoothly with ''who'' (people), ''which'' (things), and ''where'' (places where an action happens). Never repeat a subject pronoun right after ''who'' or ''which''. O‘zbek tilida «yordam bergan hamkasb» iborasida ortiqcha olmosh bo‘lmaganidek, inglizchada ham «who he helped» deb yozilmaydi.","contentRu":"Начинайте рассказ с длительного фона в Past Continuous (''was/were + V-ing''), а внезапное событие подавайте в Past Simple. Уточняйте детали через ''who'' (люди), ''which'' (предметы) и ''where'' (место действия), но не ставьте лишнее местоимение после ''who/which''.","highlightNotes":["Background + interruption: While we were testing the prototype, a storm cut the power.","Person: a student who sat beside us (NOT who he sat)","Place of action: the workshop where we built it"]},{"id":"lesson_eng_b1_m3_audio","stepNumber":2,"type":"audio_simulation","title":"Listening: The Science Hackathon Rescue","titleRu":"Аудирование: Спасение проекта на хакатоне","content":"Listen to Bekzod telling Nodira about an unexpected power cut. Focus on what his team was doing when the power stopped and how they finished the presentation.","contentRu":"Прослушайте рассказ Бекзода Нодире о внезапном отключении электричества. Запомните, что делала команда в этот момент и что помогло выступить.","media":{"id":"media_eng_b1_m3_story_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/b1/b1-m3-story-dialogue.wav","title":"Ilmiy xakatondagi kutilmagan voqea hikoyasi","titleUz":"Ilmiy xakatondagi kutilmagan voqea hikoyasi","titleRu":"История о неожиданном случае на научном хакатоне","transcript":"Bekzod: You won''t believe what happened at the science hackathon last Friday! While our team was testing the sensor prototype in the workshop where we built it, a sudden storm cut the electricity.\nNodira: Oh no! Did you lose all your test data?\nBekzod: Almost! Fortunately, a student who sat at the table beside us lent us a portable battery which kept the laptop running.\nNodira: That was lucky! So did you eventually present on stage?\nBekzod: Yes, we eventually reached the final milestone and finished in second place!","posterImage":"/lesson-media/english/b1/b1-m3-story-timeline.png","posterAlt":"Uch bosqichli voqea chizig‘i: taqdimot tayyorgarligi, elektr uzilishi va yutuq pog‘onasi","posterAltUz":"Uch bosqichli voqea chizig‘i: taqdimot tayyorgarligi, elektr uzilishi va yutuq pog‘onasi","posterAltRu":"Трёхэтапная линия событий: подготовка презентации, отключение света и призовой пьедестал","durationSeconds":32.13,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Bekzod: You won''t believe what happened at the science hackathon last Friday! While our team was testing the sensor prototype in the workshop where we built it, a sudden storm cut the electricity.\nNodira: Oh no! Did you lose all your test data?\nBekzod: Almost! Fortunately, a student who sat at the table beside us lent us a portable battery which kept the laptop running.\nNodira: That was lucky! So did you eventually present on stage?\nBekzod: Yes, we eventually reached the final milestone and finished in second place!","speakerName":"Bekzod & Nodira"}},{"id":"lesson_eng_b1_m3_flashcards","stepNumber":3,"type":"flashcard","title":"Storytelling Connectors Flashcards","titleRu":"Карточки: Связки повествования","content":"Listen to each storytelling word, recall its role in a sequence, and reveal the full card.","contentRu":"Прослушайте слово, вспомните его роль в рассказе и откройте карточку.","flashcards":[{"id":"fc_eng_b1_m3_1","front":"meanwhile","backUz":"shu paytda (ayni vaqtda)","backRu":"тем временем","partOfSpeech":"adverb","ipa":"/ˈmiːnwaɪl/","ipaAmE":"/ˈmiːnwaɪl/","cefrLevel":"B1","example":"I wrote the summary; meanwhile, Ali checked the charts.","exampleUz":"Men xulosani yozdim; shu paytda Ali grafiklarni tekshirdi.","exampleRu":"Я написал резюме; тем временем Али проверил графики.","audioSrc":"/lesson-media/english/b1/b1-m3-meanwhile.wav","imageSrc":"/lesson-media/english/b1/b1-m3-story-timeline.png","alt":"Parallel ketayotgan ikki moviy to‘lqinli chiziq tasviri","altRu":"Две параллельные голубые волнистые полосы рядом","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m3_2","front":"eventually","backUz":"oxir-oqibat","backRu":"в конце концов","partOfSpeech":"adverb","ipa":"/ɪˈventʃuəli/","ipaAmE":"/ɪˈventʃuəli/","cefrLevel":"B1","example":"After three attempts, the code eventually worked smoothly.","exampleUz":"Uch urinishdan keyin kod oxir-oqibat ravon ishladi.","exampleRu":"После трёх попыток код в конце концов заработал плавно.","audioSrc":"/lesson-media/english/b1/b1-m3-eventually.wav","imageSrc":"/lesson-media/english/b1/b1-m3-story-timeline.png","alt":"Uch bosqichli chiziqning yakuniy nuqtasida ko‘ringan yashil bayroqcha","altRu":"Зелёный флажок в завершении трёхступенчатой линии","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m3_3","front":"colleague","backUz":"hamkasb","backRu":"коллега по работе","partOfSpeech":"noun","ipa":"/ˈkɒliːɡ/","ipaAmE":"/ˈkɑːliːɡ/","cefrLevel":"B1","example":"A colleague who works in IT lent me a spare adapter.","exampleUz":"IT bo‘limida ishlaydigan bir hamkasb menga zaxira adapter berib turdi.","exampleRu":"Коллега из IT-отдела одолжил мне запасной адаптер.","audioSrc":"/lesson-media/english/b1/b1-m3-colleague.wav","imageSrc":"/lesson-media/english/b1/b1-m3-story-timeline.png","alt":"Quvvat manbaini uzatayotgan ikki jamoa a’zosi silueti","altRu":"Два силуэта команды, передающие друг другу батарею","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m3_4","front":"milestone","backUz":"muhim bosqich","backRu":"ключевая веха","partOfSpeech":"noun","ipa":"/ˈmaɪlstəʊn/","ipaAmE":"/ˈmaɪlstoʊn/","cefrLevel":"B1","example":"Finishing the prototype was a major milestone for our group.","exampleUz":"Prototipni yakunlash guruhimiz uchun katta muhim bosqich bo‘ldi.","exampleRu":"Завершение прототипа стало важной частью пути для нашей группы.","audioSrc":"/lesson-media/english/b1/b1-m3-milestone.wav","imageSrc":"/lesson-media/english/b1/b1-m3-story-timeline.png","alt":"Pog‘onali zinapoya cho‘qqisidagi yulduzli nishon","altRu":"Звёздный значок на вершине ступенчатой диаграммы","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_b1_m3_listen_q","stepNumber":4,"type":"interactive_question","title":"Listening Check: Event & Rescue","titleRu":"Проверка аудирования: Событие и спасение","content":"Choose the statement that accurately reflects the background action and solution from Bekzod''s story.","contentRu":"Выберите вариант, точно передающий фоновое действие и решение проблемы из рассказа Бекзода.","interactiveQuestion":{"id":"q_eng_b1_m3_listen_mcq","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"B1","topic":"Listening: Hackathon story sequence","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Bekzodning hikoyasiga ko‘ra, bo‘ron elektrni o‘chirgan paytda jamoa nima qilayotgan edi va taqdimotni qanday saqlab qolishdi?","textRu":"Чем занималась команда в момент отключения электричества и как удалось спасти презентацию?","options":["Ustaxonada sensor prototipini sinovdan o‘tkazayotgan edi; qo‘shni stoldagi talaba ko‘chma batareya berib turdi","Sahnada taqdimot qilayotgan edi; barcha test ma’lumotlari butunlay o‘chib ketdi","Yangi generator sotib olgani chiqishgan edi; ular musobaqadan chiqib ketishdi","Loyiha rejalarini yozishayotgan edi; chiroq o‘chgani uchun birinchi o‘rinni olishdi"],"correctIndex":0,"mistakeFeedbackByOption":{"Sahnada taqdimot qilayotgan edi; barcha test ma’lumotlari butunlay o‘chib ketdi":{"uz":"Elektr uzilganda ular hali ustaxonada prototipni sinab ko‘rishayotgan edi va ma’lumotlar saqlab qolindi.","ru":"В момент сбоя команда ещё тестировала прототип в мастерской, и данные удалось спасти."},"Yangi generator sotib olgani chiqishgan edi; ular musobaqadan chiqib ketishdi":{"uz":"Ular musobaqadan chiqib ketishmadi, aksincha qo‘shni talabaning batareyasi yordamida 2-o‘rinni egallashdi.","ru":"Они не выбыли, а благодаря батарее соседа по столу выступили и заняли второе место."},"Loyiha rejalarini yozishayotgan edi; chiroq o‘chgani uchun birinchi o‘rinni olishdi":{"uz":"Jamoa sensor prototipini sinovdan o‘tkazayotgan edi va yakunda ikkinchi o‘rinni qo‘lga kiritdi.","ru":"Команда тестировала прототип датчика и в итоге заняла второе место, а не первое."}},"explanation":"They were testing the sensor prototype in the workshop when the storm hit, and a student beside them lent a portable battery so they could finish in second place.","explanationRu":"Во время шторма команда тестировала прототип в мастерской; сосед по столу одолжил переносную батарею.","wrongFeedback":"Elektr uzilgan vaqtdagi davomiy harakat va noutbukni ishlatib qolgan yordamchi buyum haqida qayta tinglang.","wrongFeedbackRu":"Переслушайте, какое действие длилось в момент отключения света и кто помог с питанием ноутбука."}},{"id":"lesson_eng_b1_m3_match_q","stepNumber":5,"type":"interactive_question","title":"Vocabulary Match: Narrative Connectors","titleRu":"Сопоставление: Связки повествования","content":"Match each English storytelling word or relative pronoun with its Uzbek meaning.","contentRu":"Сопоставьте каждое английское слово с его значением.","interactiveQuestion":{"id":"q_eng_b1_m3_word_match","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"B1","topic":"Narrative connectors matching","difficulty":"easy","questionType":"word_match","evaluationMode":"deterministic","text":"Hikoya bog‘lovchilari va nisbiy so‘zlarni o‘zbekcha ma’nosi bilan moslang:","textRu":"Сопоставьте связки рассказа и относительные слова с их переводом:","options":[],"matchPairs":[{"id":"pair_b1_m3_1","left":"meanwhile","right":"shu paytda (ayni vaqtda)"},{"id":"pair_b1_m3_2","left":"eventually","right":"oxir-oqibat"},{"id":"pair_b1_m3_3","left":"where","right":"qaysi joyda (joy bog‘lovchisi)"},{"id":"pair_b1_m3_4","left":"who","right":"kimki (shaxs bog‘lovchisi)"}],"explanation":"''meanwhile'' links parallel actions, ''eventually'' marks the final outcome, ''where'' refers to a place, and ''who'' refers to a person.","explanationRu":"''meanwhile'' связывает параллельные действия, ''eventually'' указывает на итог, ''where'' — на место, ''who'' — на человека.","wrongFeedback":"Har bir bog‘lovchining vaqt yoki shaxs/joyga ishora qiluvchi vazifasini solishtiring.","wrongFeedbackRu":"Сравните, указывает ли слово на время, итог, место или человека."}},{"id":"lesson_eng_b1_m3_write_q","stepNumber":6,"type":"interactive_question","title":"Writing: Short Turning-Point Story","titleRu":"Writing: Короткий рассказ с поворотом","content":"Write a 4–5 sentence mini-story about an unexpected challenge you solved, using Past Continuous + Past Simple, one relative clause, and ''eventually''.","contentRu":"Напишите мини-историю (4–5 предложений) о неожиданном случае, используя Past Continuous + Past Simple, одно определительное придаточное и ''eventually''.","interactiveQuestion":{"id":"q_eng_b1_m3_writing","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"writing","cefrLevel":"B1","topic":"Writing: Sequential narrative","difficulty":"hard","questionType":"writing_prompt","evaluationMode":"self_assessed","text":"Kutilmagan muammo va uning yechimi haqida 4–5 gapli inglizcha hikoya yozing: Past Continuous + Past Simple, bitta nisbiy gap (who/which/where) va ''eventually'' so‘zini ishlating.","textRu":"Напишите историю на 4–5 предложений о неожиданной проблеме и её решении с Past Continuous + Past Simple, союзом who/which/where и словом ''eventually''.","options":[],"sampleResponse":"Last month, I was preparing my science slides in the library where our study group meets. Suddenly, the laptop screen froze before I saved the final chart. Fortunately, a colleague who was sitting nearby helped me recover the auto-saved draft. Eventually, we submitted the presentation on time.","rubricCriteria":[{"id":"crit_b1_m3_tenses","labelUz":"Davomiy fon (Past Continuous) va uzilish voqeasi (Past Simple) to‘g‘ri birlashtirildi","labelRu":"Верно объединены фон (Past Continuous) и прерывающее событие (Past Simple)"},{"id":"crit_b1_m3_rel","labelUz":"Kamida bitta to‘g‘ri nisbiy gap (who / which / where) ortiqcha olmoshi bo‘lmagan holda yozildi","labelRu":"Использовано минимум одно придаточное с who/which/where без лишнего местоимения"},{"id":"crit_b1_m3_seq","labelUz":"Voqea yakuni ''eventually'' yoki ''meanwhile'' bog‘lovchisi bilan izchil ko‘rsatildi","labelRu":"Финал или ход событий логично связан через ''eventually'' или ''meanwhile''"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil yozma mashq): matningiz berilgan rubrika mezonlari bo‘yicha tekshiriladi va rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельное письмо): текст оценивается по критериям рубрики и не выдаёт официальный сертификат CEFR.","explanation":"Strong B1 narratives pair ongoing context (''was preparing'') with a clear turning point (''froze''), precise noun links (''where'', ''who''), and an outcome connector (''eventually'').","explanationRu":"Хороший рассказ уровня B1 сочетает длительный фон, поворотное событие, точные придаточные (who/where) и итоговую связку.","wrongFeedback":"Hikoyangizda Past Continuous + Past Simple, nisbiy gap va ''eventually'' borligini mezonlar orqali tekshiring.","wrongFeedbackRu":"Проверьте по критериям наличие Past Continuous + Past Simple, who/which/where и слова ''eventually''."}}]'::jsonb, '{"id":"q_eng_b1_m3_rel_fill","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Relative adverb where for places","difficulty":"easy","questionType":"fill_blank","evaluationMode":"deterministic","blankTemplate":"That is the science lab ___ our team built the winning prototype.","text":"Joy ichida bajarilgan harakatni bog‘lash uchun bo‘sh o‘ringa mos nisbiy so‘zni yozing: «That is the science lab ___ our team built the winning prototype.»","textRu":"Вставьте относительное слово, указывающее на место действия: «That is the science lab ___ our team built the winning prototype.»","options":[],"acceptedAnswers":["where"],"explanation":"''where'' links a place (''the science lab'') with an action that happened inside it (''our team built the winning prototype'').","explanationRu":"Слово ''where'' связывает место (''the science lab'') с действием, которое происходило внутри него.","wrongFeedback":"Shaxs yoki narsa emas, balki harakat sodir bo‘lgan joyni bog‘lovchi nisbiy so‘zni yozing.","wrongFeedbackRu":"Выберите относительное слово для обозначения места действия, а не человека или предмета."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_b1_u3_checkpoint', 'course_eng_01', 'skill_eng_grammar', 'grammar', 'checkpoint', 'B1', 'mod_eng_b1_m3', 'unit_eng_b1_u3', 'Qisqa hikoya matnidan uzilish sababini topadi, nisbiy gap xatosini tuzatadi va hikoya bog‘lovchilarini moslaydi.', 'Находит причину сбоя в коротком рассказе, исправляет ошибку в определительном придаточном и сопоставляет связки.', '["node_eng_b1_m3_narrative"]'::jsonb, 'Unit 3 Checkpoint: Event Sequence & Connector Audit', 'Проверка раздела 3: Последовательность и связки', 7, 'Audit a museum volunteer''s story for background vs interruption details, eliminate a duplicate relative pronoun, and classify narrative connectors.', 'Проанализируйте рассказ волонтёра музея, уберите лишнее местоимение в придаточном и распределите функции связок.', 'Bu ichki 3-bo‘lim sinovi bo‘lib, rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Это внутренняя проверка раздела 3; она не является официальным сертификатом CEFR.', '{"intro":{"uz":"Clean storytelling depends on accurate relative clauses and clear time markers so listeners never lose track of who did what.","ru":"Чёткий рассказ опирается на точные определительные придаточные и понятную смену фоновых и основных событий."},"learningObjective":{"uz":"Identify narrative cause-effect in a text and remove redundant pronouns after ''who/which''.","ru":"Находить последовательность событий в тексте и убирать лишние местоимения после ''who/which''."},"warmUp":{"uz":"Spot the trap: ''the engineer who she designed...'' repeats the subject twice!","ru":"Обратите внимание на ловушку: в ''the engineer who she designed...'' подлежащее повторяется дважды."},"vocabularyItems":[{"word":"unexpectedly","uz":"kutilmaganda","ru":"неожиданно","ipa":"/ˌʌnɪkˈspektɪdli/"},{"word":"prototype","uz":"dastlabki namuna","ru":"прототип","ipa":"/ˈprəʊtətaɪp/"}],"grammarNote":{"rule":"When + Past Simple vs While + Past Continuous | Zero Duplicate Pronoun in Relative Clauses","simpleExplanationUz":"Use ''while'' before an ongoing action (''while she was scanning'') and ''when'' before a short event. Never place ''he/she/it'' right after ''who/which'' when it is the subject.","simpleExplanationRu":"''while'' ставится перед длительным действием, а ''when'' — перед коротким событием. После ''who/which'' в роли подлежащего не добавляется ''he/she/it''.","structure":"While + was/were -ing | Person + who + Verb (no extra he/she)","positiveExamples":["I met an engineer who designed solar panels."],"negativeExamples":["Do not write ''who she designed''."],"questions":["What interrupted the museum check-in queue?"],"commonMistakes":["Inserting ''she/it'' after ''who/which''."]},"pronunciationFocus":{"uz":"Link ''while we were'' smoothly and pronounce the final /t/ in ''noticed'' /ˈnəʊtɪst/.","ru":"Произносите связку ''while we were'' плавно, а окончание в ''noticed'' /ˈnəʊtɪst/ — как глухой звук /t/."},"examples":["While she was scanning tickets, her tablet froze."],"guidedPractice":{"uz":"Read the museum check-in passage carefully before answering.","ru":"Внимательно прочтите отрывок о работе волонтёра перед ответом."},"independentPractice":{"uz":"Solve the reading check, fix the duplicate-pronoun error, and match the 4 narrative functions.","ru":"Ответьте на вопрос по чтению, исправьте ошибку в придаточном и сопоставьте 4 грамматические функции."},"listeningRef":null,"readingRef":"lesson_eng_b1_u3_cp_concept","speakingTask":{"uz":"Explain in two sentences how the museum queue was cleared.","ru":"Объясните в двух предложениях, как удалось быстро обслужить очередь в музее."},"writingTask":{"uz":"Correct a sentence containing a redundant pronoun after ''who''.","ru":"Исправьте предложение с лишним местоимением после ''who''."},"knowledgeCheck":"q_eng_b1_u3_cp_read_mcq","finalQuiz":"q_eng_b1_u3_cp_reinf_err","feedbackRules":{"uz":"Passing at 70%+ unlocks Module 4 discussions and action planning.","ru":"Результат от 70% открывает модуль 4 об обсуждении и принятии решений."},"summaryAndRevision":{"uz":"Module 4 brings everything together into advice modals and reported decisions.","ru":"Модуль 4 объединит навыки в модальных советах и косвенной речи."}}'::jsonb, '[{"id":"lesson_eng_b1_u3_cp_concept","stepNumber":1,"type":"concept","title":"Checkpoint Briefing: Sequence & Clean Relative Clauses","titleRu":"Инструкция проверки: Последовательность и ''who/which''","content":"When auditing a narrative, verify two details: first, whether the background action (''was/were + -ing'') pairs cleanly with the interrupting event; second, whether ''who'' or ''which'' stands directly before the verb without an extra ''he/she/it''. Ortiqcha olmoshni olib tashlash gapni ravon qiladi.","contentRu":"При проверке рассказа следите за двумя правилами: фон в ''was/were + -ing'' сочетается с кратким прерывающим событием, а после ''who/which'' в роли подлежащего не ставится лишнее ''he/she/it''."},{"id":"lesson_eng_b1_u3_cp_read_q","stepNumber":2,"type":"interactive_question","title":"Reading Check: Museum Check-in Interruption","titleRu":"Чтение: Сбой на входе в музей","content":"Read the short museum narrative and identify what interrupted the process and how the problem was solved.","contentRu":"Прочтите короткий рассказ о музее и определите, что прервало регистрацию и кто помог решить проблему.","interactiveQuestion":{"id":"q_eng_b1_u3_cp_read_mcq","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"B1","topic":"Checkpoint: Reading narrative sequence","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"At the science museum entrance, Malika was scanning visitor tickets when her tablet suddenly froze. Because twenty guests were waiting in line, a colleague who worked at the next desk brought a printed guest list. Eventually, they checked everyone in within ten minutes.","text":"Matnga ko‘ra, chipta tekshiruvini nima to‘xtatib qo‘ydi va muammo qanday hal qilindi?","textRu":"Что прервало проверку билетов и как удалось решить проблему согласно тексту?","options":["Yigirmata mehmon ketib qoldi; muzey eshiklari o‘n daqiqaga yopildi","Skanerlash paytida planshet qotib qoldi; hamkasbi bosma mehmonlar ro‘yxatini olib keldi","Hamkasbi yangi planshet sotib oldi; chiptalar ertasi kuni tekshirildi","Elektr o‘chgani uchun ro‘yxat yo‘qoldi; mehmonlar chiptasiz kiritildi"],"correctIndex":1,"mistakeFeedbackByOption":{"Yigirmata mehmon ketib qoldi; muzey eshiklari o‘n daqiqaga yopildi":{"uz":"Mehmonlar ketib qolmagan, navbatda kutib turishgan va 10 daqiqa ichida ro‘yxatdan o‘tkazilgan.","ru":"Гости не ушли — они ждали в очереди и были зарегистрированы за 10 минут."},"Hamkasbi yangi planshet sotib oldi; chiptalar ertasi kuni tekshirildi":{"uz":"Hamkasbi planshet emas, qog‘ozga chop etilgan mehmonlar ro‘yxatini olib keldi.","ru":"Коллега принёс не новый планшет, а распечатанный список гостей."},"Elektr o‘chgani uchun ro‘yxat yo‘qoldi; mehmonlar chiptasiz kiritildi":{"uz":"Muammo elektrda emas, planshetning qotib qolishida edi va hamma ro‘yxat bo‘yicha tekshirildi.","ru":"Проблема была в зависшем планшете, и всех отметили по бумажному списку."}},"explanation":"Malika''s tablet froze while she was scanning tickets, and a colleague solved it by bringing a printed guest list.","explanationRu":"Во время сканирования завис планшет Малики, а коллега принёс распечатанный список гостей.","wrongFeedback":"Matnda qaysi qurilma ishdan chiqqani va hamkasbi qanday yordam olib kelganini qayta o‘qing.","wrongFeedbackRu":"Перечитайте в тексте, какое устройство зависло и что принёс коллега."}}]'::jsonb, '{"id":"q_eng_b1_u3_cp_reinf_err","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Checkpoint: Relative clause redundant pronoun","difficulty":"medium","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"I met an engineer yesterday who she designed solar panels.","text":"Nisbiy gapdagi ortiqcha olmosh xatosini tuzating:","textRu":"Уберите лишнее местоимение в определительном придаточном предложении:","options":["I met an engineer yesterday which designed solar panels.","I met an engineer yesterday where she designed solar panels.","I met an engineer yesterday who designing solar panels.","I met an engineer yesterday who designed solar panels."],"correctIndex":3,"mistakeFeedbackByOption":{"I met an engineer yesterday which designed solar panels.":{"uz":"«which» narsa-buyumlar uchun ishlatiladi; muhandis (shaxs) uchun «who» kerak.","ru":"«which» используется для предметов, а для человека (инженера) требуется «who»."},"I met an engineer yesterday where she designed solar panels.":{"uz":"«where» joyga ishora qiladi va bu yerda ham «she» ortiqcha qolgan.","ru":"«where» обозначает место, и лишнее «she» по-прежнему мешает."},"I met an engineer yesterday who designing solar panels.":{"uz":"«who» dan keyin yordamchi fe’lsiz «-ing» kelmaydi, tugallangan o‘tgan harakat uchun «designed» kerak.","ru":"После «who» нельзя ставить «-ing» без вспомогательного глагола; нужен Past Simple «designed»."}},"explanation":"''who'' already acts as the subject of ''designed'', so ''she'' must be removed.","explanationRu":"Местоимение ''who'' уже выполняет роль подлежащего перед ''designed'', поэтому ''she'' нужно убрать.","wrongFeedback":"Shaxsni bildiruvchi nisbiy olmoshdan keyin ortiqcha olmoshsiz to‘g‘ri o‘tgan zamon fe’li keladigan variantni tanlang.","wrongFeedbackRu":"Выберите вариант с относительным местоимением для человека и глаголом в Past Simple без повторного местоимения."}'::jsonb, '{"id":"q_eng_b1_u3_cp_alt_match","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"vocabulary","cefrLevel":"B1","topic":"Alternate: Narrative structures matching","difficulty":"medium","questionType":"word_match","evaluationMode":"deterministic","text":"Hikoya tarkibidagi grammatik shakllarni ularning vazifasi bilan moslang:","textRu":"Сопоставьте грамматические конструкции рассказа с их функцией:","options":[],"matchPairs":[{"id":"pair_b1_u3_1","left":"while + was/were -ing","right":"davom etayotgan fon harakati"},{"id":"pair_b1_u3_2","left":"when + V2","right":"to‘satdan sodir bo‘lgan uzilish"},{"id":"pair_b1_u3_3","left":"who","right":"odamlarga aniqlik kiritish"},{"id":"pair_b1_u3_4","left":"which","right":"narsa va buyumlarga aniqlik kiritish"}],"explanation":"''while + was/were -ing'' sets background duration, ''when + V2'' marks interruption, ''who'' describes people, and ''which'' describes things.","explanationRu":"''while + was/were -ing'' описывает длительный фон, ''when + V2'' — прерывание, ''who'' — людей, ''which'' — предметы.","wrongFeedback":"Har bir konstruksiya davomiylik, uzilish, shaxs yoki narsadan qaysi birini bildirishini tekshiring.","wrongFeedbackRu":"Проверьте, к чему относится каждая форма: к длительному фону, прерыванию, человеку или предмету."}'::jsonb, true, true, false),
  ('lesson_eng_b1_m4_decisions', 'course_eng_01', 'skill_eng_vocab', 'integrated', 'writing', 'B1', 'mod_eng_b1_m4', 'unit_eng_b1_u4', 'Jamoaviy muhokamadan ustuvor qarorni ajratadi, ''should / ought to / must'' bilan tavsiya beradi va suhbatni o‘zlashtirma gapda yetkazadi.', 'Выбирает приоритетный шаг из обсуждения, даёт советы с ''should / ought to / must'' и передаёт чужую речь в косвенной форме.', '["node_eng_b1_u3_checkpoint"]'::jsonb, 'Discussions, Advice & Next Action (Modals + Reported Statements)', 'Обсуждение, советы и решения (Модальные глаголы и косвенная речь)', 11, 'You learn how to weigh competing team ideas, distinguish strong obligation (''must'') from advice (''should / ought to''), and report what someone said with basic tense backshift.', 'Вы научитесь взвешивать предложения команды, отличать строгую обязанность (''must'') от совета (''should / ought to'') и передавать слова собеседника в косвенной речи.', 'Ushbu darsdagi yozma qaror rejasi mustaqil amaliyotdir; rasmiy CEFR sertifikatini bermaydi.', 'Письменное задание на план действий предназначено для самостоятельной практики и не выдаёт сертификат CEFR.', '{"intro":{"uz":"In team projects, people suggest competing ideas. B1 communicators identify top priorities, recommend practical steps, and report decisions clearly to others.","ru":"В командной работе звучат разные предложения. На уровне B1 важно выделить приоритет, дать точный совет и грамотно передать решение коллегам."},"learningObjective":{"uz":"Select next actions from a discussion, apply ''should/ought to/must'' accurately, and convert direct statements into basic reported speech.","ru":"Определять дальнейший шаг по итогам беседы, верно применять ''should/ought to/must'' и переводить прямую речь в косвенную."},"warmUp":{"uz":"Suppose 30% of app testers cannot sign in, while teammates ask for dark mode. Which task is a ''must'', and how do you tell developers what the mentor said?","ru":"Допустим, 30% пользователей не могут войти в приложение, а коллеги просят тёмную тему. Что здесь обязательно (''must''), и как пересказать слова ментора?"},"vocabularyItems":[{"word":"compromise","uz":"o‘zaro kelishuv","ru":"взаимная уступка","ipa":"/ˈkɒmprəmaɪz/"},{"word":"priority","uz":"eng muhim vazifa","ru":"первоочередная задача","ipa":"/praɪˈɒrəti/"},{"word":"recommend","uz":"maslahat bermoq","ru":"советовать","ipa":"/ˌrekəˈmend/"},{"word":"outcome","uz":"yakuniy natija","ru":"итоговый результат","ipa":"/ˈaʊtkʌm/"}],"grammarNote":{"rule":"Advice & Obligation (should / ought to / must) & Reported Statements (said / told + backshift)","simpleExplanationUz":"''should'' and ''ought to'' give advice, whereas ''must'' expresses strict urgency. Never add ''to'' after ''should'' or ''must'', but always keep ''to'' in ''ought to''. In reported speech after ''said/told'', shift ''can -> could'', ''will -> would'', ''am/is -> was''. ''said'' dan keyin bevosita shaxs olmoshi kelmaydi (''told us that'', ''said that'').","simpleExplanationRu":"''should'' и ''ought to'' выражают совет, а ''must'' — строгую необходимость. После ''should/must'' частица ''to'' не ставится, а ''ought to'' всегда требует ''to''. В косвенной речи после ''said/told'' сдвигаем ''can -> could'', ''will -> would''. После ''said'' не ставится прямое дополнение (''told us'', но ''said that'').","structure":"Subject + should/must + V1 | Subject + ought to + V1 | Subject + told + [person] + (that) + [backshifted clause]","positiveExamples":["You must fix the timeout bug before Friday, and you ought to notify the testers.","The mentor told us that sign-in access was our top priority."],"negativeExamples":["We should not postpone critical bug fixes."],"questions":["Should we add dark mode before fixing the sign-in timeout?"],"commonMistakes":["Writing ''should to test'' or ''said me that'' instead of ''should test'' and ''told me that''."]},"pronunciationFocus":{"uz":"The letter ''l'' is silent in ''should'' /ʃʊd/. In natural speech, ''ought to'' blends smoothly into /ˈɔːtə/.","ru":"Буква ''l'' в ''should'' /ʃʊd/ не читается. В беглой речи ''ought to'' сливается в /ˈɔːtə/."},"examples":["You must fix the timeout bug before Friday, and we ought to run a second test on Saturday.","I will tell the developers that we are postponing new design features."],"guidedPractice":{"uz":"Inspect the prioritization board illustration, listen to the mentor and Aziz, and practice the 4 decision cards.","ru":"Изучите доску приоритетов, прослушайте диалог ментора и Азиза и повторите 4 карточки."},"independentPractice":{"uz":"Select the mentor''s prioritized reply, write an action-plan message, and convert direct speech into reported speech.","ru":"Выберите приоритетное решение ментора, напишите сообщение с планом действий и преобразуйте прямую речь в косвенную."},"listeningRef":"media_eng_b1_m4_decisions_dialogue","readingRef":"lesson_eng_b1_m4_concept","speakingTask":{"uz":"Report one teammate suggestion and recommend the top priority using ''ought to''.","ru":"Перескажите предложение коллеги и дайте рекомендацию с помощью ''ought to''."},"writingTask":{"uz":"Write a 4-sentence team update reporting a comment and recommending two next actions.","ru":"Напишите сообщение команде из 4 предложений с косвенной речью и двумя советами."},"knowledgeCheck":"q_eng_b1_m4_listen_conv","finalQuiz":"q_eng_b1_m4_writing","feedbackRules":{"uz":"Feedback catches ''said + object'' errors, missing backshift, and reversed priorities.","ru":"Подсказки разбирают ошибки ''said + дополнение'', отсутствие сдвига времени и неверный приоритет."},"summaryAndRevision":{"uz":"All 4 B1 modules are now complete; proceed to the integrated B1 Exit Assessment.","ru":"Все 4 модуля B1 пройдены; переходите к итоговому экзамену B1."}}'::jsonb, '[{"id":"lesson_eng_b1_m4_concept","stepNumber":1,"type":"concept","title":"Advice Modals & Basic Reported Statements","titleRu":"Модальные глаголы совета и косвенная речь","content":"Choose ''should'' or ''ought to'' for balanced recommendations, and reserve ''must'' for urgent rules or critical priorities. Notice that ''should'' and ''must'' connect directly to the base verb without ''to'', while ''ought to'' keeps ''to''. When reporting what someone decided earlier (''said / told us''), shift ''will -> would'', ''can -> could'', and ''am/is -> was'', and remember ''tell'' needs a listener (''told us'') while ''say'' does not. O‘zbek tilida «menga aytdi» iborasiga moslab «said me» deyish ko‘p uchraydigan xato — to‘g‘risi «told me».","contentRu":"Используйте ''should'' или ''ought to'' для рекомендаций и ''must'' для срочных правил. После ''should/must'' частица ''to'' не нужна, а в ''ought to'' она обязательна. Передавая слова в прошлом (''said / told us''), сдвигайте ''will -> would'', ''can -> could'', ''am/is -> was'' и помните: ''told us'', но ''said that'' (без ''me/us'').","highlightNotes":["Advice vs urgency: We ought to test on Saturday, and we must fix the bug first.","Listener rule: She told us that... / She said that... (NEVER said us)","Backshift: ''I can send it'' -> She said that she could send it."]},{"id":"lesson_eng_b1_m4_audio","stepNumber":2,"type":"audio_simulation","title":"Listening: Prioritizing the Product Fix","titleRu":"Аудирование: Выбор приоритета в проекте","content":"Listen to the mentor and Aziz reviewing user test feedback. Identify why sign-in is urgent, what feature is postponed, and what must happen before Friday.","contentRu":"Прослушайте беседу ментора и Азиза по результатам тестирования. Обратите внимание на главную проблему, отложенную функцию и срок исправления.","media":{"id":"media_eng_b1_m4_decisions_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/b1/b1-m4-decisions-dialogue.wav","title":"Jamoaviy muhokama va keyingi harakatni tanlash suhbati","titleUz":"Jamoaviy muhokama va keyingi harakatni tanlash suhbati","titleRu":"Командное обсуждение и выбор следующего шага","transcript":"Mentor: I reviewed your user feedback notes. Thirty percent of mobile testers could not finish the sign-in screen because the verification code expired too fast.\nAziz: Earlier, some teammates suggested adding dark mode first, since users asked for it.\nMentor: Dark mode is helpful, but sign-in access is our top priority. You must fix the timeout bug before Friday, and you ought to notify the testers once it is ready.\nAziz: Good point. I will tell the developers that we are postponing new design features until Monday, and we should run a second test on Saturday morning.","posterImage":"/lesson-media/english/b1/b1-m4-decision-board.png","posterAlt":"Muhokama pufakchalari, tarozi belgisi va ustuvor vazifalar doskasi tasvirlangan panel","posterAltUz":"Muhokama pufakchalari, tarozi belgisi va ustuvor vazifalar doskasi tasvirlangan panel","posterAltRu":"Диалоговые окна обсуждения, весы выбора и доска приоритетных задач","durationSeconds":35.381,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Mentor: I reviewed your user feedback notes. Thirty percent of mobile testers could not finish the sign-in screen because the verification code expired too fast.\nAziz: Earlier, some teammates suggested adding dark mode first, since users asked for it.\nMentor: Dark mode is helpful, but sign-in access is our top priority. You must fix the timeout bug before Friday, and you ought to notify the testers once it is ready.\nAziz: Good point. I will tell the developers that we are postponing new design features until Monday, and we should run a second test on Saturday morning.","speakerName":"Mentor & Aziz"}},{"id":"lesson_eng_b1_m4_flashcards","stepNumber":3,"type":"flashcard","title":"Decision & Action Flashcards","titleRu":"Карточки: Решения и приоритеты","content":"Listen to each B1 decision-making term, recall its Uzbek/Russian meaning, and review the example.","contentRu":"Прослушайте термин, вспомните значение и откройте пример.","flashcards":[{"id":"fc_eng_b1_m4_1","front":"compromise","backUz":"o‘zaro kelishuv","backRu":"взаимная уступка","partOfSpeech":"noun","ipa":"/ˈkɒmprəmaɪz/","ipaAmE":"/ˈkɑːmprəmaɪz/","cefrLevel":"B1","example":"Both sides reached a fair compromise on the launch date.","exampleUz":"Har ikki tomon ishga tushirish sanasi bo‘yicha adolatli o‘zaro kelishuvga erishdi.","exampleRu":"Обе стороны пришли к разумному согласию по дате запуска.","audioSrc":"/lesson-media/english/b1/b1-m4-compromise.wav","imageSrc":"/lesson-media/english/b1/b1-m4-decision-board.png","alt":"Ikki suhbat pufakchasi orasidagi tenglik tarozisi","altRu":"Значок равновесия между двумя окнами диалога","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m4_2","front":"priority","backUz":"eng muhim vazifa","backRu":"первоочередная задача","partOfSpeech":"noun","ipa":"/praɪˈɒrəti/","ipaAmE":"/praɪˈɔːrəti/","cefrLevel":"B1","example":"Fixing the login bug is our highest priority this week.","exampleUz":"Kirish xatosini tuzatish shu haftadagi eng muhim vazifamizdir.","exampleRu":"Исправление ошибки входа — наш главный фокус на этой неделе.","audioSrc":"/lesson-media/english/b1/b1-m4-priority.wav","imageSrc":"/lesson-media/english/b1/b1-m4-decision-board.png","alt":"Reja doskasining eng yuqori qatoridagi oltin yulduz","altRu":"Золотая звезда в верхней строке рабочей доски","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m4_3","front":"recommend","backUz":"maslahat bermoq","backRu":"советовать","partOfSpeech":"verb","ipa":"/ˌrekəˈmend/","ipaAmE":"/ˌrekəˈmend/","cefrLevel":"B1","example":"I strongly recommend testing the app before Friday.","exampleUz":"Ilovani juma kunigacha tekshirib ko‘rishni qat’iy maslahat beraman.","exampleRu":"Я настоятельно рекомендую протестировать приложение до пятницы.","audioSrc":"/lesson-media/english/b1/b1-m4-recommend.wav","imageSrc":"/lesson-media/english/b1/b1-m4-decision-board.png","alt":"Yashil tasdiq belgisi tomon yo‘naltirilgan oq chiziq","altRu":"Символ выбора рядом с зелёной галочкой на карточке","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}},{"id":"fc_eng_b1_m4_4","front":"outcome","backUz":"yakuniy natija","backRu":"итоговый результат","partOfSpeech":"noun","ipa":"/ˈaʊtkʌm/","ipaAmE":"/ˈaʊtkʌm/","cefrLevel":"B1","example":"Everyone was pleased with the positive outcome of the meeting.","exampleUz":"Uchrashuvning ijobiy yakuniy natijasidan hamma mamnun bo‘ldi.","exampleRu":"Все остались довольны положительным итогом встречи.","audioSrc":"/lesson-media/english/b1/b1-m4-outcome.wav","imageSrc":"/lesson-media/english/b1/b1-m4-decision-board.png","alt":"Nishon markaziga kelib tushgan moviy strelka tasviri","altRu":"Голубая стрелка, направленная точно в центр мишени","srsDefaults":{"initialBucket":0,"intervalsDays":[0,1,3,7,14]}}]},{"id":"lesson_eng_b1_m4_listen_q","stepNumber":4,"type":"interactive_question","title":"Listening Check: Choosing the Next Action","titleRu":"Проверка аудирования: Выбор действия","content":"Complete the dialogue turn to reflect the mentor''s real decision in the recording.","contentRu":"Дополните диалог репликой ментора, соответствующей аудиозаписи.","interactiveQuestion":{"id":"q_eng_b1_m4_listen_conv","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"B1","topic":"Listening: Prioritizing next action","difficulty":"medium","questionType":"conversation_completion","evaluationMode":"deterministic","dialogueContext":["Aziz: \"Should we add dark mode before fixing the sign-in timeout?\"","Mentor: \"___\""],"text":"Audiodagi muhokamaga ko‘ra, mentorning ustuvor qarorini aks ettiruvchi javobni tanlang:","textRu":"Выберите ответ ментора, отражающий принятый приоритет в диалоге:","options":["Yes, add dark mode first and postpone the sign-in bug until next month.","You do not need to test again on Saturday or notify the mobile testers.","No, sign-in access is our top priority, so you must fix the timeout bug before Friday.","Ignore the verification code problem because thirty percent is a small number."],"correctIndex":2,"mistakeFeedbackByOption":{"Yes, add dark mode first and postpone the sign-in bug until next month.":{"uz":"Aksincha, yangi dizayn funksiyalari dushanbagacha kechiktirildi, kirish xatosini tuzatish esa birinchi o‘ringa qo‘yildi.","ru":"Наоборот: новые функции дизайна отложены до понедельника, а исправление входа стало главным приоритетом."},"You do not need to test again on Saturday or notify the mobile testers.":{"uz":"Mentor sinovchilarga xabar berishni aytdi, Aziz esa shanba tongida ikkinchi test o‘tkazishni taklif qildi.","ru":"Ментор посоветовал уведомить тестировщиков, а Азиз предложил повторный тест в субботу утром."},"Ignore the verification code problem because thirty percent is a small number.":{"uz":"30% foydalanuvchi tizimga kira olmagani uchun mentor buni eng muhim muammo deb baholadi.","ru":"Из-за сбоя у 30% тестировщиков ментор назвал это главной проблемой."}},"explanation":"The mentor rejects adding dark mode first and insists that fixing the sign-in timeout bug before Friday is the top priority.","explanationRu":"Ментор отклонил идею начинать с тёмной темы и подчеркнул, что ошибка входа должна быть исправлена до пятницы.","wrongFeedback":"Mentor tungi rejim va tizimga kirish muammosidan qaysi birini ustuvor deb aytganini qayta tinglang.","wrongFeedbackRu":"Переслушайте, что ментор назвал главным приоритетом и какой срок установил."}},{"id":"lesson_eng_b1_m4_write_q","stepNumber":5,"type":"interactive_question","title":"Writing: Team Action-Plan Message","titleRu":"Writing: План действий для команды","content":"Write a 4-sentence message reporting what a teammate suggested and recommending two clear next steps.","contentRu":"Напишите сообщение из 4 предложений, передав слова коллеги в косвенной речи и предложив два следующих шага.","interactiveQuestion":{"id":"q_eng_b1_m4_writing","courseId":"course_eng_01","skillId":"skill_eng_vocab","skillDomain":"writing","cefrLevel":"B1","topic":"Writing: Reporting decisions and recommending next actions","difficulty":"hard","questionType":"writing_prompt","evaluationMode":"self_assessed","text":"Jamoaga 4 gapli ish xabari yozing: hamkasbingiz nima deganini o‘zlashtirma gapda (told/said) yetkazing va ''should'' / ''ought to'' hamda ''priority'' so‘zi bilan ikki keyingi qadamni tavsiya qiling.","textRu":"Напишите командное сообщение из 4 предложений: передайте слова коллеги через told/said и порекомендуйте два шага со словами ''should'' / ''ought to'' и ''priority''.","options":[],"sampleResponse":"Aziz told us that thirty percent of testers could not complete sign-in. Fixing that bug is our top priority before Friday. We ought to postpone new design changes until next week. We should also run a follow-up check on Saturday morning.","rubricCriteria":[{"id":"crit_b1_m4_rep","labelUz":"Kamida bitta to‘g‘ri o‘zlashtirma gap (''told us / said that'' + zamon surilishi) yozildi","labelRu":"Использована минимум одна корректная фраза косвенной речи (''told us / said that'' со сдвигом времени)"},{"id":"crit_b1_m4_mod","labelUz":"''should'' yoki ''ought to'' bilan ikkita amaliy tavsiya berildi","labelRu":"Даны две практические рекомендации с ''should'' или ''ought to''"},{"id":"crit_b1_m4_voc","labelUz":"Qaror lug‘atidan (''priority'', ''compromise'', ''recommend'', ''outcome'') kamida bittasi ishlatildi","labelRu":"Применено минимум одно слово модуля (''priority'', ''compromise'', ''recommend'', ''outcome'')"}],"selfAssessmentNoticeUz":"O‘zini baholash (mustaqil yozma topshiriq): javob rubrika mezonlari bilan solishtiriladi; rasmiy CEFR sertifikati bermaydi.","selfAssessmentNoticeRu":"Самооценка (самостоятельное письмо): проверяется по критериям рубрики и не выдаёт официальный сертификат CEFR.","explanation":"Reporting the problem clearly first, naming the priority, and closing with ''ought to / should'' actions produces concise B1 workplace communication.","explanationRu":"Чёткий пересказ проблемы, выделение приоритета и конкретные шаги с ''ought to / should'' соответствуют деловой переписке уровня B1.","wrongFeedback":"Matningizda o‘zlashtirma gap, ikkita modal tavsiya va ustuvorlik so‘zi borligini mezonlar asosida tekshiring.","wrongFeedbackRu":"Проверьте наличие косвенной речи, двух модальных рекомендаций и лексики приоритетов."}}]'::jsonb, '{"id":"q_eng_b1_m4_rep_text","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"Basic reported statement with can -> could","difficulty":"hard","questionType":"text_input","evaluationMode":"deterministic","text":"Alining «Men bugun kun tartibini yubora olaman» («I can send the agenda today») degan gapini o‘zlashtirma gapga aylantirib, «Ali told us ...» bilan boshlab ingliz tilida to‘liq yozing.","textRu":"Преобразуйте слова Али «Я могу отправить повестку дня сегодня» («I can send the agenda today») в косвенную речь на английском, начав с «Ali told us ...».","options":[],"acceptedAnswers":["Ali told us that he could send the agenda that day","Ali told us that he could send the agenda today","Ali told us he could send the agenda that day","Ali told us he could send the agenda today"],"explanation":"In reported statements, ''I'' changes to ''he'' and ''can'' shifts back to ''could'': ''Ali told us that he could send the agenda that day.''","explanationRu":"В косвенной речи ''I'' заменяется на ''he'', а модальный глагол сдвигается на шаг назад (''could'').","wrongFeedback":"O‘tgan zamondagi xabar fe’lidan keyin olmoshni uchinchi shaxsga o‘zgartiring va modal fe’lni bir bosqich orqaga suring.","wrongFeedbackRu":"После глагола речи в прошедшем времени замените местоимение и сдвиньте модальный глагол назад."}'::jsonb, NULL, false, true, false),
  ('lesson_eng_b1_exit', 'course_eng_01', 'skill_eng_reading', 'integrated', 'exit_assessment', 'B1', 'mod_eng_b1_m4', 'unit_eng_b1_u4', 'B1 darajasidagi tinglash, o‘qish, zamonlar, shartli reja, modal tavsiyalar va o‘zlashtirma gapni integratsiyalashgan yakuniy sinovda tasdiqlaydi.', 'Подтверждает владение всеми навыками уровня B1 в итоговом экзамене (аудирование, чтение, грамматика и порядок слов).', '["node_eng_b1_m4_decisions"]'::jsonb, 'B1 Integrated Exit Assessment (Travel + Problem + Narrative + Action)', 'Итоговый экзамен уровня B1', 12, 'Complete the B1 integrated exit check combining conference listening disambiguation, reading comprehension, Present Perfect grammar, reported-speech ordering, error correction, and an alternate notice task.', 'Пройдите итоговый тест B1: аудирование о конференции, чтение объявления, Present Perfect, построение косвенной речи и исправление ошибки.', 'Bu B1 ichki chiqish imtihoni bo‘lib, B2 bosqichini ochishga tayyorgarlikni tekshiradi; rasmiy xalqaro CEFR sertifikatini bermaydi.', 'Это внутренний экзамен уровня B1 для перехода к B2; он не выдаёт официальный международный сертификат CEFR.', '{"intro":{"uz":"Real B1 situations combine everything at once: arriving on time, handling an unexpected equipment failure, and acting on reported advice.","ru":"В реальных ситуациях B1 все навыки работают вместе: прибытие в поездке, сбой техники и передача рекомендаций."},"learningObjective":{"uz":"Demonstrate integrated B1 readiness across listening, reading, tense selection, reported speech, and sentence construction.","ru":"Подтвердить готовность уровня B1 в аудировании, чтении, выборе времён и косвенной речи."},"warmUp":{"uz":"Recall the four B1 pillars: Present Perfect vs Past Simple, First Conditional, Past Continuous + Past Simple, and Modals + Reported Statements.","ru":"Вспомните 4 опоры B1: Present Perfect и Past Simple, First Conditional, Past Continuous + Past Simple и модальные советы с косвенной речью."},"vocabularyItems":[{"word":"orientation","uz":"tanishuv yig‘ilishi","ru":"вводная встреча","ipa":"/ˌɔːriənˈteɪʃn/"},{"word":"alternative","uz":"muqobil variant","ru":"альтернатива","ipa":"/ɔːlˈtɜːnətɪv/"}],"grammarNote":{"rule":"Integrated B1 Synthesis: Tense Contrast + First Conditional + Reported Action","simpleExplanationUz":"Check time markers before picking Present Perfect or Past Simple, keep ''if''-clauses in Present Simple, and remember ''told + person'' + backshifted modal.","simpleExplanationRu":"Сверяйте маркеры времени перед выбором Present Perfect/Past Simple, оставляйте Present Simple после ''if'' и сдвигайте глаголы после ''told + лицо''.","structure":"have/has + V3 | If + Present Simple, will/should + V1 | told + person + that + could/would","positiveExamples":["The organizer said that if we don''t find a cable, we should share the slide link."],"negativeExamples":["Never say ''She said me that the train will arrive late''."],"questions":["Has the technician checked the storage room yet?"],"commonMistakes":["Mixing ''said me'' with missing modal backshift (''will'' instead of ''would'')."]},"pronunciationFocus":{"uz":"Use clear rising-falling intonation on discourse markers like ''Actually,'' and ''Glad you made it!''.","ru":"Выделяйте вводные слова ''Actually,'' и ''Glad you made it!'' чёткой интонацией."},"examples":["While the opening speaker was connecting his laptop, the main projector cable broke."],"guidedPractice":{"uz":"Listen to the Samarkand conference dialogue before answering the integrated tasks.","ru":"Прослушайте диалог о конференции в Самарканде перед выполнением заданий."},"independentPractice":{"uz":"Complete all 4 core steps plus reinforcement and alternate checks to pass B1 at 70%+.","ru":"Выполните все 4 задания и проверочные упражнения с результатом от 70%."},"listeningRef":"media_eng_b1_exit_dialogue","readingRef":"lesson_eng_b1_exit_step_3","speakingTask":{"uz":"Summarize the conference backup plan aloud in two reported sentences.","ru":"Устно перескажите запасной план конференции в двух предложениях косвенной речи."},"writingTask":{"uz":"Produce an accurate Present Perfect update and construct a reported advice sentence.","ru":"Составьте предложение в Present Perfect и соберите фразу с косвенным советом."},"knowledgeCheck":"q_eng_b1_exit_listen","finalQuiz":"q_eng_b1_exit_read","feedbackRules":{"uz":"A score of 70% or above completes CEFR B1 and unlocks B2.","ru":"Результат 70% и выше завершает уровень B1 и открывает B2."},"summaryAndRevision":{"uz":"Congratulations on completing CEFR B1; your next milestone is B2 interviews and source debates.","ru":"Поздравляем с завершением B1; на уровне B2 вас ждут интервью и сравнение источников."}}'::jsonb, '[{"id":"lesson_eng_b1_exit_step_1","stepNumber":1,"type":"audio_simulation","title":"1. Listening: Conference Orientation Glitch","titleRu":"1. Аудирование: Сбой на конференции","content":"Listen to Malika and Rustam at the Samarkand youth center. Track what happened during setup, what the technician is doing, and the organizer''s 10:15 backup plan.","contentRu":"Прослушайте разговор Малики и Рустама в молодёжном центре Самарканда. Запомните, что сломалось и какой план предложил организатор на 10:15.","media":{"id":"media_eng_b1_exit_dialogue","kind":"audio","language":"en","source":"/lesson-media/english/b1/b1-exit-dialogue.wav","title":"B1 yakuniy tinglash: Konferensiyadagi texnik muammo va qaror","titleUz":"B1 yakuniy tinglash: Konferensiyadagi texnik muammo va qaror","titleRu":"Итоговое аудирование B1: Техническая проблема на конференции и решение","transcript":"Malika: Hi Rustam! I have just arrived at the Samarkand youth center. My morning train arrived on time, unlike last month.\nRustam: Glad you made it! Actually, we have a small problem. While the opening speaker was connecting his laptop, the main projector cable broke.\nMalika: Has the technician checked the storage room yet?\nRustam: He is looking right now. The organizer said that if we don''t find a spare cable by ten fifteen, we should share the slide link with attendees and start the Q and A session fifteen minutes early.","posterImage":"/lesson-media/english/b1/b1-m4-decision-board.png","posterAlt":"Konferensiya muammosini muhokama qilayotgan ikki ishtirokchi va qarorlar doskasi","posterAltUz":"Konferensiya muammosini muhokama qilayotgan ikki ishtirokchi va qarorlar doskasi","posterAltRu":"Участники обсуждают техническую неполадку и план действий на доске","durationSeconds":33.248,"reviewStatus":"approved"},"visualModelData":{"type":"audio_wave","audioTranscript":"Malika: Hi Rustam! I have just arrived at the Samarkand youth center. My morning train arrived on time, unlike last month.\nRustam: Glad you made it! Actually, we have a small problem. While the opening speaker was connecting his laptop, the main projector cable broke.\nMalika: Has the technician checked the storage room yet?\nRustam: He is looking right now. The organizer said that if we don''t find a spare cable by ten fifteen, we should share the slide link with attendees and start the Q and A session fifteen minutes early.","speakerName":"Malika & Rustam"}},{"id":"lesson_eng_b1_exit_step_2","stepNumber":2,"type":"interactive_question","title":"2. Listening Evidence: Equipment Backup Plan","titleRu":"2. Факты аудирования: Запасной план","content":"Choose the statement that accurately matches the broken item and the organizer''s contingency decision.","contentRu":"Выберите вариант, который точно описывает поломку и запасной план организатора.","interactiveQuestion":{"id":"q_eng_b1_exit_listen","courseId":"course_eng_01","skillId":"skill_eng_listening","skillDomain":"listening","cefrLevel":"B1","topic":"B1 Exit: Conference listening comprehension","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","text":"Audiodagi suhbatga ko‘ra, konferensiyada qanday nosozlik yuz berdi va 10:15 gacha zaxira kabel topilmasa nima qilinadi?","textRu":"Какая поломка произошла на конференции и что сделают, если запасной кабель не найдётся до 10:15?","options":["Proyektor kabeli uzildi; slayd havolasini ulashib, savol-javobni 15 daqiqa ertaroq boshlashadi","Malikaning poyezdi kechikdi; tadbir keyingi oyga ko‘chiriladi","Spikerning noutbuki buzildi; texnik xodim do‘kondan yangi kompyuter olib keladi","Omborxona qulflanib qoldi; savol-javob qismi butunlay bekor qilinadi"],"correctIndex":0,"mistakeFeedbackByOption":{"Malikaning poyezdi kechikdi; tadbir keyingi oyga ko‘chiriladi":{"uz":"Malika o‘tgan oydan farqli o‘laroq bugun poyezdi o‘z vaqtida yetib kelganini aytdi.","ru":"Малика сказала, что сегодня поезд прибыл вовремя (задержка была в прошлом месяце)."},"Spikerning noutbuki buzildi; texnik xodim do‘kondan yangi kompyuter olib keladi":{"uz":"Noutbuk emas, asosiy proyektor kabeli uzilgan va texnik omborxonadan zaxira kabel qidirmoqda.","ru":"Сломался не ноутбук, а кабель проектора; техник ищет запасной в кладовой."},"Omborxona qulflanib qoldi; savol-javob qismi butunlay bekor qilinadi":{"uz":"Savol-javob bekor qilinmaydi, aksincha 15 daqiqa ertaroq boshlanishi aytildi.","ru":"Сессию вопросов и ответов не отменяют, а переносят на 15 минут раньше."}},"explanation":"The main projector cable broke while the speaker was connecting his laptop; if no spare cable is found by 10:15, they will share the slide link and start Q&A 15 minutes early.","explanationRu":"Сломался кабель проектора; если до 10:15 запасной не найдут, участникам отправят ссылку на слайды и начнут Q&A на 15 минут раньше.","wrongFeedback":"Proyektor bilan bog‘liq muammo va tashkilotchining 10:15 uchun aytgan ikki qadamini qayta tinglang.","wrongFeedbackRu":"Переслушайте, что случилось с проектором и какие два шага предложил организатор на 10:15."}},{"id":"lesson_eng_b1_exit_step_3","stepNumber":3,"type":"interactive_question","title":"3. Reading: Community Scholarship Guidelines","titleRu":"3. Чтение: Правила стипендии","content":"Read the scholarship update carefully and select the accurate next step for applicants.","contentRu":"Прочтите объявление о стипендии и выберите правильный шаг для кандидата.","interactiveQuestion":{"id":"q_eng_b1_exit_read","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"B1","topic":"B1 Exit: Scholarship reading comprehension","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Regional Youth Scholarship Update: Applicants who have already uploaded their essay do not need to resubmit it. However, if your mentor recommendation letter has not arrived by Friday at 18:00, you ought to contact the admissions desk before Monday morning.","text":"E’longa ko‘ra, inshosini yuklagan, ammo tavsiya xati juma soat 18:00 gacha yetib kelmagan nomzod nima qilishi kerak?","textRu":"Что должен сделать кандидат, который уже загрузил эссе, но рекомендательное письмо не пришло к 18:00 пятницы?","options":["Inshoni juma kuni qayta topshirishi va dushanba kuni kelishini kutishi kerak","Hujjatlari bekor qilingani uchun keyingi yilgacha kutishi kerak","Tavsiya xatini o‘zi yozib dushanba kuni kechqurun yuborishi kerak","Inshoni qayta yuklamaydi, lekin dushanba tongidan oldin qabul bo‘limi bilan bog‘lanishi kerak"],"correctIndex":3,"mistakeFeedbackByOption":{"Inshoni juma kuni qayta topshirishi va dushanba kuni kelishini kutishi kerak":{"uz":"Matnda allaqachon yuklangan inshoni qayta topshirish shart emasligi («do not need to resubmit») yozilgan.","ru":"В тексте указано, что уже загруженное эссе повторно отправлять не нужно («do not need to resubmit»)."},"Hujjatlari bekor qilingani uchun keyingi yilgacha kutishi kerak":{"uz":"Ariza bekor qilinmagan; nomzod dushanba tongidan oldin qabul bo‘limiga murojaat qilishi tavsiya etilgan.","ru":"Заявка не аннулирована — рекомендовано связаться с приёмной комиссией до утра понедельника."},"Tavsiya xatini o‘zi yozib dushanba kuni kechqurun yuborishi kerak":{"uz":"Matnda xatni o‘zi yozish haqida gap yo‘q, balki dushanba tongidan oldin bog‘lanish aytilgan.","ru":"Нужно связаться с отделом до утра понедельника, а не писать рекомендацию самостоятельно."}},"explanation":"Applicants who already uploaded their essay do not resubmit it, and if the recommendation letter is still missing at 18:00 Friday, they ought to contact admissions before Monday morning.","explanationRu":"Эссе повторно загружать не нужно, а при отсутствии письма к 18:00 пятницы следует связаться с комиссией до утра понедельника.","wrongFeedback":"«do not need to resubmit» va «before Monday morning» shartlarini diqqat bilan solishtiring.","wrongFeedbackRu":"Сопоставьте условия «do not need to resubmit» и «before Monday morning» в объявлении."}},{"id":"lesson_eng_b1_exit_step_4","stepNumber":4,"type":"interactive_question","title":"4. Grammar Writing: Present Perfect Progress","titleRu":"4. Грамматика: Present Perfect с already","content":"Translate the Uzbek/Russian readiness update into natural English using Present Perfect.","contentRu":"Переведите сообщение о готовности на английский в Present Perfect.","interactiveQuestion":{"id":"q_eng_b1_exit_grammar_text","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"B1 Exit: Present Perfect with already","difficulty":"medium","questionType":"text_input","evaluationMode":"deterministic","text":"«Men allaqachon elektron chiptamni yuklab oldim» gapini Present Perfect zamonida ingliz tilida yozing.","textRu":"Напишите на английском в Present Perfect: «Я уже скачал свой электронный билет».","options":[],"acceptedAnswers":["I have already downloaded my e-ticket","I''ve already downloaded my e-ticket","I have downloaded my e-ticket already","I''ve downloaded my e-ticket already","I have already downloaded my electronic ticket","I''ve already downloaded my electronic ticket","I have downloaded my electronic ticket already","I''ve downloaded my electronic ticket already","I have already downloaded my ticket","I''ve already downloaded my ticket","I have downloaded my ticket already","I''ve downloaded my ticket already"],"explanation":"Use ''I have already downloaded'' (or ''I''ve already downloaded'') + ''my e-ticket'' to express a completed action relevant right now.","explanationRu":"Для готового результата сейчас используется Present Perfect с ''already'' между вспомогательным и смысловым глаголом.","wrongFeedback":"Hozirgi natijani ko‘rsatish uchun yordamchi fe’ldan keyin darhol ravish va to‘g‘ri o‘tgan sifatdosh shaklini qo‘ying.","wrongFeedbackRu":"Поставьте наречие готовности между вспомогательным глаголом и формой причастия прошедшего времени."}},{"id":"lesson_eng_b1_exit_step_5","stepNumber":5,"type":"interactive_question","title":"5. Sentence Construction: Reported Advice","titleRu":"5. Построение фразы: Косвенный совет","content":"Order the chunks to report the mentor''s recommendation accurately.","contentRu":"Расставьте фрагменты в верном порядке, чтобы передать совет ментора.","interactiveQuestion":{"id":"q_eng_b1_exit_order","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"B1 Exit: Reported advice sentence order","difficulty":"hard","questionType":"sentence_order","evaluationMode":"deterministic","text":"«Mentor bugun zaxira rejamizni sinab ko‘rishimiz kerakligini aytdi» gapini to‘g‘ri tartibda tuzing:","textRu":"Составьте предложение «Ментор сказал, что нам следует проверить запасной план сегодня» в правильном порядке:","options":[],"orderedTokens":["The mentor","said that","we ought","to test","our backup","plan today."],"acceptedAnswers":["The mentor said that we ought to test our backup plan today."],"explanation":"Order: reporting clause (''The mentor said that'') + subject + modal (''we ought'') + infinitive (''to test'') + object + time (''our backup plan today.'').","explanationRu":"Порядок: вводная часть, затем подлежащее с модальной конструкцией и инфинитивом, дополнение и время в конце.","wrongFeedback":"Avval xabar qiluvchi shaxs va bog‘lovchi qismini, keyin modal tavsiya va harakat maqsadini oxirida vaqt bilan joylang.","wrongFeedbackRu":"Сначала поставьте подлежащее с глаголом речи, затем субъект и модальный оборот с инфинитивом и дополнением в конце."}}]'::jsonb, '{"id":"q_eng_b1_exit_reinf","courseId":"course_eng_01","skillId":"skill_eng_grammar","skillDomain":"grammar","cefrLevel":"B1","topic":"B1 Exit: Reported speech listener and backshift","difficulty":"hard","questionType":"error_correction","evaluationMode":"deterministic","sentenceWithError":"She said me that the train will arrive late.","text":"O‘zlashtirma gapdagi tinglovchi fe’li va zamon surilishi xatosini tuzating:","textRu":"Исправьте две ошибки косвенной речи (глагол и сдвиг времени):","options":["She said me that the train would arrive late.","She told me that the train would arrive late.","She told to me that the train will arrive late.","She told me that the train will arriving late."],"correctIndex":1,"mistakeFeedbackByOption":{"She said me that the train would arrive late.":{"uz":"«said» dan keyin bevosita «me» qo‘yilmaydi; shaxs ko‘rsatilganda «told me» ishlatiladi.","ru":"После «said» нельзя сразу ставить «me» — при указании адресата нужен глагол «told me»."},"She told to me that the train will arrive late.":{"uz":"«told» dan keyin «to» kelmaydi va «will» o‘tgan zamondan keyin «would» ga o‘tishi kerak.","ru":"После «told» предлог «to» не нужен, а «will» должно сдвинуться в «would»."},"She told me that the train will arriving late.":{"uz":"«will» ham zamon jihatdan orqaga surilmagan, ham «will» dan keyin «-ing» kelmaydi.","ru":"Глагол «will» не сдвинут в прошедшую форму, и после него нельзя ставить «-ing»."}},"explanation":"Use ''told me'' (no ''to'', never ''said me'') and shift ''will'' back to ''would'' after a past reporting verb.","explanationRu":"С адресатом ставится ''told me'' (без ''to''), а после глагола речи в прошлом ''will'' переходит в ''would''.","wrongFeedback":"Tinglovchi oldida ''to'' siz ishlatiladigan fe’lni va o‘tgan zamondagi modal siljishni tekshiring.","wrongFeedbackRu":"Проверьте правильный глагол речи с адресатом без ''to'' и сдвиг модального глагола."}'::jsonb, '{"id":"q_eng_b1_exit_alt","courseId":"course_eng_01","skillId":"skill_eng_reading","skillDomain":"reading","cefrLevel":"B1","topic":"B1 Exit: Alternate workshop notice","difficulty":"medium","questionType":"multiple_choice","evaluationMode":"deterministic","contextSnippet":"Internship Workshop Update: Because Room 201 is under repair until noon, the morning CV clinic has moved to Room 308. Participants who arrive after 10:15 should join the second group at 11:30.","text":"Qayta sinov: Soat 10:25 da kelgan ishtirokchi qayerga va soat nechada kirishi kerak?","textRu":"Повторная проверка: в какую аудиторию и во сколько должен пройти участник, пришедший в 10:25?","options":["201-xonaga soat 10:30 da kirishi kerak","308-xonaga soat 12:00 dan keyin kirishi kerak","308-xonaga soat 11:30 dagi ikkinchi guruhga qo‘shilishi kerak","201-xonadagi birinchi guruhga qo‘shilishi kerak"],"correctIndex":2,"mistakeFeedbackByOption":{"201-xonaga soat 10:30 da kirishi kerak":{"uz":"201-xona tushgacha ta’mirda, seminar esa 308-xonaga ko‘chirilgan.","ru":"Аудитория 201 на ремонте до полудня, семинар перенесли в 308-ю."},"308-xonaga soat 12:00 dan keyin kirishi kerak":{"uz":"10:15 dan keyin kelganlar uchun ikkinchi guruh soat 11:30 da boshlanadi.","ru":"Для опоздавших после 10:15 вторая группа начинается в 11:30, а не после 12:00."},"201-xonadagi birinchi guruhga qo‘shilishi kerak":{"uz":"Ham xona 308 ga ko‘chgan, ham 10:25 10:15 dan keyin bo‘lgani uchun ikkinchi guruhga o‘tiladi.","ru":"Семинар проходит в 308-й аудитории, а после 10:15 нужно идти во вторую группу."}},"explanation":"The clinic moved to Room 308, and anyone arriving after 10:15 joins the 11:30 second group.","explanationRu":"Семинар перенесён в аудиторию 308, а пришедшие после 10:15 присоединяются ко второй группе в 11:30.","wrongFeedback":"Ta’mirdagi xona va 10:15 dan keyin kelganlar uchun ko‘rsatilgan guruh vaqtini solishtiring.","wrongFeedbackRu":"Сравните номер заменённой аудитории и время группы для пришедших после 10:15."}'::jsonb, true, true, false)
