-- ----------------------------------------------------------------------------
-- 3. Harden public.sanitize_learner_content(JSONB) (pure pg_catalog, INVOKER-safe)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.sanitize_learner_content(p_value JSONB)
RETURNS JSONB
LANGUAGE plpgsql
IMMUTABLE
SET search_path = ''
AS $$
DECLARE
  v_result JSONB := '{}'::pg_catalog.jsonb;
  v_key TEXT;
  v_val JSONB;
  v_sanitized_val JSONB;
  v_len INT;
  v_qid TEXT;
  v_ui_shift INT;
  v_candidate JSONB;
  v_ui_rotated JSONB;
  v_seed INT;
BEGIN
  IF p_value IS NULL THEN
    RETURN NULL;
  END IF;

  IF pg_catalog.jsonb_typeof(p_value) = 'object' THEN
    v_qid := COALESCE(p_value->>'id', '');

    FOR v_key, v_val IN SELECT * FROM pg_catalog.jsonb_each(p_value) LOOP
      IF v_key IN (
        'correct_index', 'correctIndex', 'correct_option', 'correctOption',
        'correct_option_id', 'correctOptionId', 'correct_answer', 'correctAnswer',
        'answer_index', 'answerIndex', 'answer',
        'accepted_answers', 'acceptedAnswers',
        'explanation', 'explanation_ru', 'explanationRu',
        'mistake_feedback_by_option', 'mistakeFeedbackByOption'
      ) THEN
        CONTINUE;
      END IF;

      IF v_key IN ('orderedTokens', 'ordered_tokens')
         AND pg_catalog.jsonb_typeof(v_val) = 'array'
         AND pg_catalog.jsonb_array_length(v_val) >= 2 THEN
        v_len := pg_catalog.jsonb_array_length(v_val);
        v_sanitized_val := v_val;

        FOR v_seed IN 1..12 LOOP
          SELECT pg_catalog.jsonb_agg(
            public.sanitize_learner_content(elem)
            ORDER BY pg_catalog.md5(v_seed::TEXT || ':' || v_qid || ':' || ord::TEXT || ':' || elem::TEXT), ord DESC
          )
          INTO v_candidate
          FROM pg_catalog.jsonb_array_elements(v_val) WITH ORDINALITY AS t(elem, ord);

          IF v_candidate IS DISTINCT FROM v_val THEN
            v_sanitized_val := v_candidate;
            EXIT;
          END IF;
        END LOOP;

        IF v_sanitized_val = v_val THEN
          FOR v_seed IN 1..(v_len - 1) LOOP
            SELECT pg_catalog.jsonb_agg(
              public.sanitize_learner_content(v_val->(((idx - 1 + v_seed) % v_len)::INT))
              ORDER BY idx
            )
            INTO v_candidate
            FROM pg_catalog.generate_series(1, v_len) AS idx;

            IF v_candidate IS DISTINCT FROM v_val THEN
              v_sanitized_val := v_candidate;
              EXIT;
            END IF;
          END LOOP;
        END IF;

        v_result := v_result || pg_catalog.jsonb_build_object(v_key, COALESCE(v_sanitized_val, '[]'::pg_catalog.jsonb));

      ELSIF v_key IN ('matchPairs', 'match_pairs')
            AND pg_catalog.jsonb_typeof(v_val) = 'array'
            AND pg_catalog.jsonb_array_length(v_val) >= 2 THEN
        v_len := pg_catalog.jsonb_array_length(v_val);
        SELECT pg_catalog.jsonb_agg(
          (
            (public.sanitize_learner_content(v_val->idx) - 'right' - 'rightRu' - 'right_ru')
            || pg_catalog.jsonb_build_object('right', (v_val->((idx + 1) % v_len))->'right')
            || CASE
                 WHEN (v_val->((idx + 1) % v_len)) ? 'rightRu'
                 THEN pg_catalog.jsonb_build_object('rightRu', (v_val->((idx + 1) % v_len))->'rightRu')
                 ELSE '{}'::pg_catalog.jsonb
               END
            || CASE
                 WHEN (v_val->((idx + 1) % v_len)) ? 'right_ru'
                 THEN pg_catalog.jsonb_build_object('right_ru', (v_val->((idx + 1) % v_len))->'right_ru')
                 ELSE '{}'::pg_catalog.jsonb
               END
          )
          ORDER BY idx
        )
        INTO v_sanitized_val
        FROM pg_catalog.generate_series(0, v_len - 1) AS idx;

        v_result := v_result || pg_catalog.jsonb_build_object(v_key, COALESCE(v_sanitized_val, '[]'::pg_catalog.jsonb));

      ELSE
        v_result := v_result || pg_catalog.jsonb_build_object(v_key, public.sanitize_learner_content(v_val));
      END IF;
    END LOOP;

    RETURN v_result;
  ELSIF pg_catalog.jsonb_typeof(p_value) = 'array' THEN
    RETURN COALESCE((
      SELECT pg_catalog.jsonb_agg(public.sanitize_learner_content(value) ORDER BY ordinal)
      FROM pg_catalog.jsonb_array_elements(p_value) WITH ORDINALITY AS item(value, ordinal)
    ), '[]'::pg_catalog.jsonb);
  END IF;

  RETURN p_value;
END;
$$;

REVOKE ALL ON FUNCTION public.sanitize_learner_content(JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.sanitize_learner_content(JSONB) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 4. Rewrite public.learner_lessons with single math_progression CTE (Coupling #2)
--    and refresh public.admin_lessons & public.admin_save_lesson
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.unlocked_math_lesson_ids()
RETURNS TABLE (target_lesson_id TEXT)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT DISTINCT mp.target_lesson_id
  FROM bilimyol_private.math_progression(auth.uid()) mp
  WHERE auth.uid() IS NOT NULL
    AND mp.status <> 'locked'
    AND mp.target_lesson_id IS NOT NULL;
$$;

REVOKE ALL ON FUNCTION public.unlocked_math_lesson_ids() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.unlocked_math_lesson_ids() TO authenticated, service_role;

DROP VIEW IF EXISTS public.learner_lessons;
CREATE VIEW public.learner_lessons AS
WITH math_unlocked AS (
  SELECT u.target_lesson_id
  FROM public.unlocked_math_lesson_ids() u
)
SELECT
  l.id,
  l.course_id,
  l.skill_id,
  l.skill_domain,
  l.communicative_focus,
  l.cefr_level,
  l.module_id,
  l.unit_id,
  l.can_do_objective,
  l.can_do_objective_ru,
  l.prerequisites,
  l.title,
  l.title_ru,
  l.summary,
  l.summary_ru,
  l.official_cefr_disclaimer_uz,
  l.official_cefr_disclaimer_ru,
  l.pedagogy17,
  l.estimated_minutes,
  l.requires_mastery,
  CASE
    WHEN (l.course_id = 'course_math_01' AND mu.target_lesson_id IS NULL)
    THEN '[]'::pg_catalog.jsonb
    ELSE public.sanitize_learner_content(l.steps)
  END AS steps,
  CASE
    WHEN NOT (l.course_id = 'course_math_01' AND mu.target_lesson_id IS NULL)
    THEN public.sanitize_learner_content(l.reinforcement_exercise)
  END AS reinforcement_exercise,
  CASE
    WHEN NOT (l.course_id = 'course_math_01' AND mu.target_lesson_id IS NULL)
    THEN public.sanitize_learner_content(l.alternate_exercise)
  END AS alternate_exercise,
  l.is_published,
  l.is_archived,
  l.created_at,
  l.updated_at,
  (l.course_id = 'course_math_01' AND mu.target_lesson_id IS NULL) AS is_locked
FROM public.lessons l
LEFT JOIN math_unlocked mu
  ON l.course_id = 'course_math_01'
 AND mu.target_lesson_id = l.id
WHERE l.is_published AND NOT l.is_archived;

REVOKE ALL ON public.learner_lessons FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.learner_lessons TO authenticated, service_role;

DROP VIEW IF EXISTS public.admin_lessons;
CREATE VIEW public.admin_lessons AS
SELECT l.*
FROM public.lessons l
WHERE public.is_admin();

REVOKE ALL ON public.admin_lessons FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.admin_lessons TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.admin_save_lesson(p_lesson JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Faqat administrator dars saqlay oladi.' USING ERRCODE = '42501';
  END IF;
  IF pg_catalog.jsonb_typeof(p_lesson) IS DISTINCT FROM 'object'
     OR NULLIF(pg_catalog.btrim(p_lesson->>'id'), '') IS NULL
     OR pg_catalog.jsonb_typeof(p_lesson->'steps') IS DISTINCT FROM 'array'
     OR NOT EXISTS (
       SELECT 1 FROM public.skills
       WHERE id = p_lesson->>'skill_id' AND course_id = p_lesson->>'course_id'
     ) THEN
    RAISE EXCEPTION 'Dars ma’lumotlari yoki kurs/ko‘nikma konteksti noto‘g‘ri.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.lessons (
    id, course_id, skill_id, skill_domain, communicative_focus, cefr_level,
    module_id, unit_id, can_do_objective, can_do_objective_ru, prerequisites,
    title, title_ru, summary, summary_ru, estimated_minutes,
    official_cefr_disclaimer_uz, official_cefr_disclaimer_ru, pedagogy17,
    steps, reinforcement_exercise, alternate_exercise, requires_mastery,
    is_published, is_archived, updated_at
  ) VALUES (
    p_lesson->>'id',
    p_lesson->>'course_id',
    p_lesson->>'skill_id',
    COALESCE(p_lesson->>'skill_domain', p_lesson->>'skillDomain'),
    COALESCE(p_lesson->>'communicative_focus', p_lesson->>'communicativeFocus'),
    COALESCE(p_lesson->>'cefr_level', p_lesson->>'cefrLevel'),
    COALESCE(p_lesson->>'module_id', p_lesson->>'moduleId'),
    COALESCE(p_lesson->>'unit_id', p_lesson->>'unitId'),
    COALESCE(p_lesson->>'can_do_objective', p_lesson->>'canDoObjective'),
    COALESCE(p_lesson->>'can_do_objective_ru', p_lesson->>'canDoObjectiveRu'),
    CASE
      WHEN pg_catalog.jsonb_typeof(p_lesson->'prerequisites') = 'array' THEN p_lesson->'prerequisites'
      ELSE '[]'::pg_catalog.jsonb
    END,
    p_lesson->>'title',
    COALESCE(p_lesson->>'title_ru', p_lesson->>'titleRu'),
    COALESCE(p_lesson->>'summary', ''),
    COALESCE(p_lesson->>'summary_ru', p_lesson->>'summaryRu'),
    COALESCE((p_lesson->>'estimated_minutes')::INT, 15),
    COALESCE(p_lesson->>'official_cefr_disclaimer_uz', p_lesson->>'officialCefrDisclaimerUz'),
    COALESCE(p_lesson->>'official_cefr_disclaimer_ru', p_lesson->>'officialCefrDisclaimerRu'),
    CASE
      WHEN pg_catalog.jsonb_typeof(p_lesson->'pedagogy17') = 'object' THEN p_lesson->'pedagogy17'
      ELSE NULL
    END,
    p_lesson->'steps',
    CASE
      WHEN pg_catalog.jsonb_typeof(COALESCE(p_lesson->'reinforcement_exercise', p_lesson->'reinforcementExercise')) = 'object'
      THEN COALESCE(p_lesson->'reinforcement_exercise', p_lesson->'reinforcementExercise')
      ELSE NULL
    END,
    CASE
      WHEN pg_catalog.jsonb_typeof(COALESCE(p_lesson->'alternate_exercise', p_lesson->'alternateExercise')) = 'object'
      THEN COALESCE(p_lesson->'alternate_exercise', p_lesson->'alternateExercise')
      ELSE NULL
    END,
    COALESCE(
      (p_lesson->>'requires_mastery')::BOOLEAN,
      (p_lesson->>'requiresMastery')::BOOLEAN,
      pg_catalog.jsonb_path_exists(p_lesson->'steps', '$[*].masteryCheckpoint')
    ),
    COALESCE((p_lesson->>'is_published')::BOOLEAN, true),
    COALESCE((p_lesson->>'is_archived')::BOOLEAN, false),
    pg_catalog.now()
  )
  ON CONFLICT (id) DO UPDATE SET
    course_id = EXCLUDED.course_id,
    skill_id = EXCLUDED.skill_id,
    skill_domain = COALESCE(EXCLUDED.skill_domain, public.lessons.skill_domain),
    communicative_focus = COALESCE(EXCLUDED.communicative_focus, public.lessons.communicative_focus),
    cefr_level = COALESCE(EXCLUDED.cefr_level, public.lessons.cefr_level),
    module_id = COALESCE(EXCLUDED.module_id, public.lessons.module_id),
    unit_id = COALESCE(EXCLUDED.unit_id, public.lessons.unit_id),
    can_do_objective = COALESCE(EXCLUDED.can_do_objective, public.lessons.can_do_objective),
    can_do_objective_ru = COALESCE(EXCLUDED.can_do_objective_ru, public.lessons.can_do_objective_ru),
    prerequisites = CASE
      WHEN p_lesson ? 'prerequisites' THEN EXCLUDED.prerequisites
      ELSE public.lessons.prerequisites
    END,
    title = EXCLUDED.title,
    title_ru = COALESCE(EXCLUDED.title_ru, public.lessons.title_ru),
    summary = EXCLUDED.summary,
    summary_ru = COALESCE(EXCLUDED.summary_ru, public.lessons.summary_ru),
    estimated_minutes = EXCLUDED.estimated_minutes,
    official_cefr_disclaimer_uz = COALESCE(EXCLUDED.official_cefr_disclaimer_uz, public.lessons.official_cefr_disclaimer_uz),
    official_cefr_disclaimer_ru = COALESCE(EXCLUDED.official_cefr_disclaimer_ru, public.lessons.official_cefr_disclaimer_ru),
    pedagogy17 = COALESCE(EXCLUDED.pedagogy17, public.lessons.pedagogy17),
    steps = EXCLUDED.steps,
    reinforcement_exercise = CASE
      WHEN (p_lesson ? 'reinforcement_exercise' OR p_lesson ? 'reinforcementExercise')
      THEN EXCLUDED.reinforcement_exercise
      ELSE public.lessons.reinforcement_exercise
    END,
    alternate_exercise = COALESCE(EXCLUDED.alternate_exercise, public.lessons.alternate_exercise),
    requires_mastery = CASE
      WHEN (p_lesson ? 'requires_mastery' OR p_lesson ? 'requiresMastery')
      THEN EXCLUDED.requires_mastery
      ELSE (public.lessons.requires_mastery OR pg_catalog.jsonb_path_exists(EXCLUDED.steps, '$[*].masteryCheckpoint'))
    END,
    is_published = EXCLUDED.is_published,
    is_archived = EXCLUDED.is_archived,
    updated_at = pg_catalog.now();

  RETURN pg_catalog.jsonb_build_object('saved', true, 'id', p_lesson->>'id');
END;
$$;

REVOKE ALL ON FUNCTION public.admin_save_lesson(JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_save_lesson(JSONB) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 5. Private 9-mode normalization & grading helpers
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION bilimyol_private.normalize_free_text(p_text TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
SET search_path = ''
AS $$
  SELECT pg_catalog.btrim(
    pg_catalog.regexp_replace(
      pg_catalog.regexp_replace(
        pg_catalog.lower(
          pg_catalog.regexp_replace(
            pg_catalog.replace(pg_catalog.btrim(COALESCE(p_text, '')), ',', ' '),
            '[’‘`´ʻʼ]',
            '''',
            'g'
          )
        ),
        '\s+',
        ' ',
        'g'
      ),
      '[\s.,!?]+$',
      '',
      'g'
    )
  );
$$;

REVOKE ALL ON FUNCTION bilimyol_private.normalize_free_text(TEXT)
  FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION bilimyol_private.grade_question_attempt(
  p_q_body JSONB,
  p_selected_index INT,
  p_selected_text TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
SET search_path = ''
AS $$
DECLARE
  v_q_type TEXT;
  v_eval_mode TEXT;
  v_correct_index INT;
  v_options JSONB;
  v_accepted JSONB;
  v_pairs JSONB;
  v_tokens JSONB;
  v_parsed JSONB;
  v_norm_sub TEXT;
  v_joined TEXT;
  v_resp TEXT;
  v_expected_sentence TEXT;
BEGIN
  IF p_q_body IS NULL OR pg_catalog.jsonb_typeof(p_q_body) <> 'object' THEN
    RAISE EXCEPTION 'Savol server bazasida to‘liq sozlanmagan.' USING ERRCODE = '22023';
  END IF;

  v_q_type := COALESCE(
    NULLIF(pg_catalog.btrim(COALESCE(p_q_body->>'questionType', p_q_body->>'question_type', p_q_body->>'mode', '')), ''),
    'multiple_choice'
  );
  v_eval_mode := COALESCE(
    NULLIF(pg_catalog.btrim(COALESCE(p_q_body->>'evaluationMode', p_q_body->>'evaluation_mode', '')), ''),
    CASE WHEN v_q_type IN ('speaking_prompt', 'writing_prompt') THEN 'self_assessed' ELSE 'deterministic' END
  );

  -- Mode 8 & 9: self_assessed speaking_prompt / writing_prompt
  IF v_eval_mode = 'self_assessed' OR v_q_type IN ('speaking_prompt', 'writing_prompt') THEN
    IF p_selected_index IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'Tanlangan javob indeksi noto‘g‘ri.' USING ERRCODE = '22023';
    END IF;
    v_resp := COALESCE(p_selected_text, '');
    IF pg_catalog.starts_with(pg_catalog.btrim(v_resp), '{') THEN
      BEGIN
        v_parsed := v_resp::pg_catalog.jsonb;
        IF pg_catalog.jsonb_typeof(v_parsed) = 'object' AND v_parsed ? 'response' THEN
          v_resp := COALESCE(v_parsed->>'response', '');
        END IF;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
    RETURN pg_catalog.btrim(v_resp) <> '';
  END IF;

  -- Mode 1 & 2: text_input / fill_blank
  IF v_q_type IN ('text_input', 'fill_blank') THEN
    v_accepted := COALESCE(p_q_body->'acceptedAnswers', p_q_body->'accepted_answers');
    IF v_accepted IS NULL
       OR pg_catalog.jsonb_typeof(v_accepted) <> 'array'
       OR pg_catalog.jsonb_array_length(v_accepted) = 0 THEN
      RAISE EXCEPTION 'Savol server bazasida to‘liq sozlanmagan.' USING ERRCODE = '22023';
    END IF;
    v_norm_sub := bilimyol_private.normalize_free_text(p_selected_text);
    IF v_norm_sub = '' THEN
      RETURN false;
    END IF;
    RETURN EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_array_elements_text(v_accepted) AS cand
      WHERE bilimyol_private.normalize_free_text(cand) = v_norm_sub
    );
  END IF;

  -- Mode 3: word_match (strictly grades {"<leftId>":"<selectedRightText>"}; rejects pair-ID cheats)
  IF v_q_type = 'word_match' THEN
    v_pairs := COALESCE(p_q_body->'matchPairs', p_q_body->'match_pairs');
    IF v_pairs IS NULL
       OR pg_catalog.jsonb_typeof(v_pairs) <> 'array'
       OR pg_catalog.jsonb_array_length(v_pairs) < 2 THEN
      RAISE EXCEPTION 'Savol server bazasida to‘liq sozlanmagan.' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_parsed := COALESCE(p_selected_text, '')::pg_catalog.jsonb;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    IF v_parsed IS NULL OR pg_catalog.jsonb_typeof(v_parsed) <> 'object' THEN
      RETURN false;
    END IF;
    IF (SELECT pg_catalog.count(*)::INT FROM pg_catalog.jsonb_object_keys(v_parsed))
       <> pg_catalog.jsonb_array_length(v_pairs) THEN
      RETURN false;
    END IF;
    RETURN NOT EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_array_elements(v_pairs) AS pair
      WHERE NOT (v_parsed ? (pair->>'id'))
         OR bilimyol_private.normalize_free_text(v_parsed->>(pair->>'id')) = ''
         OR bilimyol_private.normalize_free_text(v_parsed->>(pair->>'id'))
            IS DISTINCT FROM bilimyol_private.normalize_free_text(pair->>'right')
    );
  END IF;

  -- Mode 4: sentence_order (canonical JSON token array or string fallback)
  IF v_q_type = 'sentence_order' THEN
    v_tokens := COALESCE(p_q_body->'orderedTokens', p_q_body->'ordered_tokens');
    IF v_tokens IS NULL
       OR pg_catalog.jsonb_typeof(v_tokens) <> 'array'
       OR pg_catalog.jsonb_array_length(v_tokens) < 2 THEN
      RAISE EXCEPTION 'Savol server bazasida to‘liq sozlanmagan.' USING ERRCODE = '22023';
    END IF;
    v_joined := COALESCE(p_selected_text, '');
    IF pg_catalog.starts_with(pg_catalog.btrim(v_joined), '[') THEN
      BEGIN
        v_parsed := v_joined::pg_catalog.jsonb;
        IF pg_catalog.jsonb_typeof(v_parsed) = 'array' THEN
          IF v_parsed = v_tokens THEN
            RETURN true;
          END IF;
          SELECT COALESCE(pg_catalog.string_agg(tok, ' ' ORDER BY ord), '')
          INTO v_joined
          FROM pg_catalog.jsonb_array_elements_text(v_parsed) WITH ORDINALITY AS t(tok, ord);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        RETURN false;
      END;
    END IF;

    v_norm_sub := bilimyol_private.normalize_free_text(v_joined);
    IF v_norm_sub = '' THEN
      RETURN false;
    END IF;

    SELECT COALESCE(pg_catalog.string_agg(tok, ' ' ORDER BY ord), '')
    INTO v_expected_sentence
    FROM pg_catalog.jsonb_array_elements_text(v_tokens) WITH ORDINALITY AS t(tok, ord);

    IF v_norm_sub = bilimyol_private.normalize_free_text(v_expected_sentence) THEN
      RETURN true;
    END IF;

    v_accepted := COALESCE(p_q_body->'acceptedAnswers', p_q_body->'accepted_answers');
    IF v_accepted IS NOT NULL AND pg_catalog.jsonb_typeof(v_accepted) = 'array' THEN
      RETURN EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements_text(v_accepted) AS cand
        WHERE bilimyol_private.normalize_free_text(cand) = v_norm_sub
      );
    END IF;
    RETURN false;
  END IF;

  -- Mode 5, 6 & 7: multiple_choice, error_correction, conversation_completion
  v_correct_index := CASE
    WHEN COALESCE(p_q_body->>'correct_index', p_q_body->>'correctIndex') ~ '^[0-9]{1,3}$'
    THEN COALESCE(p_q_body->>'correct_index', p_q_body->>'correctIndex')::INT
  END;
  v_options := p_q_body->'options';

  IF v_correct_index IS NULL THEN
    RAISE EXCEPTION 'Savol server bazasida to‘liq sozlanmagan.' USING ERRCODE = '22023';
  END IF;
  IF v_options IS NULL
     OR pg_catalog.jsonb_typeof(v_options) <> 'array'
     OR p_selected_index IS NULL
     OR p_selected_index < 0
     OR p_selected_index >= pg_catalog.jsonb_array_length(v_options) THEN
    RAISE EXCEPTION 'Tanlangan javob indeksi noto‘g‘ri.' USING ERRCODE = '22023';
  END IF;

  RETURN (p_selected_index = v_correct_index);
END;
$$;

REVOKE ALL ON FUNCTION bilimyol_private.grade_question_attempt(JSONB, INT, TEXT)
  FROM PUBLIC, anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 6. Extend bilimyol_private.submit_answer_attempt to all 9 modes + alternate_exercise
--    (Preserves 100% of W0-B1 & W1-B1 idempotency, replay, lock-ordering & dedup)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION bilimyol_private.submit_answer_attempt(
  p_user_id UUID,
  p_course_id TEXT,
  p_skill_id TEXT,
  p_lesson_id TEXT,
  p_question_id TEXT,
  p_selected_index INT,
  p_selected_text TEXT,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_caller_uid UUID;
  v_existing_id UUID;
  v_existing_is_correct BOOLEAN;
  v_question_course TEXT;
  v_question_skill TEXT;
  v_q_body JSONB;
  v_explanation TEXT;
  v_is_correct BOOLEAN := false;
  v_unique_total INT;
  v_unique_correct INT;
  v_new_skill_score INT;
  v_overall_score INT := 0;
  v_mastery_level TEXT;
  v_xp_delta INT := 0;
  v_pending_answer_xp INT := 0;
  v_total_xp INT := 0;
  v_award JSONB;
  v_eff_idempotency TEXT;
  v_clean_text TEXT;
  v_today DATE;
  v_daily_total INT := 0;
  v_daily_correct INT := 0;
  v_daily_accuracy INT := 0;
  v_reinf_target RECORD;
  v_wrong_count INT := 0;
  v_hide_mistake_spoiler BOOLEAN := false;
  v_q_row RECORD;
BEGIN
  v_caller_uid := auth.uid();
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'Xavfsizlik qoidasi: javob topshirish uchun autentifikatsiya talab qilinadi.'
      USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS DISTINCT FROM v_caller_uid THEN
    RAISE EXCEPTION 'Xavfsizlik qoidasi: boshqa foydalanuvchi nomidan javob topshirish taqiqlanadi.'
      USING ERRCODE = '42501';
  END IF;

  v_today := (pg_catalog.now() AT TIME ZONE 'Asia/Tashkent')::date;
  IF NULLIF(pg_catalog.btrim(p_course_id), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_skill_id), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_lesson_id), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_question_id), '') IS NULL
     OR p_selected_index IS NULL
     OR p_selected_index < 0
     OR p_selected_index > 100 THEN
    RAISE EXCEPTION 'Javob konteksti yoki indeksi noto‘g‘ri.' USING ERRCODE = '22023';
  END IF;

  IF pg_catalog.char_length(p_course_id) > 64
     OR pg_catalog.char_length(p_skill_id) > 64
     OR pg_catalog.char_length(p_lesson_id) > 160
     OR pg_catalog.char_length(p_question_id) > 160 THEN
    RAISE EXCEPTION 'Javob identifikatorlari ruxsat etilgan hajmdan oshib ketdi.' USING ERRCODE = '23514';
  END IF;

  v_clean_text := COALESCE(p_selected_text, '');
  IF pg_catalog.char_length(v_clean_text) > 4000 THEN
    RAISE EXCEPTION 'Javob matni 4000 belgidan oshmasligi shart.' USING ERRCODE = '23514';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    IF pg_catalog.btrim(p_idempotency_key) = '' THEN
      RAISE EXCEPTION 'Idempotency kaliti bo‘sh satr bo‘lishi mumkin emas.' USING ERRCODE = '22023';
    END IF;
    IF pg_catalog.char_length(p_idempotency_key) > 128 THEN
      RAISE EXCEPTION 'Idempotency kaliti uzunligi 128 belgidan oshmasligi shart.' USING ERRCODE = '23514';
    END IF;
    v_eff_idempotency := p_idempotency_key;
  ELSE
    v_eff_idempotency := NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.skills s
    WHERE s.id = p_skill_id AND s.course_id = p_course_id
  ) THEN
    RAISE EXCEPTION 'Ko‘nikma kurs bilan mos emas.' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('learning:' || p_user_id::TEXT, 0)
  );

  IF v_eff_idempotency IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(p_user_id::TEXT || ':' || v_eff_idempotency, 0)
    );

    SELECT aa.id, aa.is_correct
    INTO v_existing_id, v_existing_is_correct
    FROM public.answer_attempts aa
    WHERE aa.user_id = p_user_id AND aa.idempotency_key = v_eff_idempotency
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM public.answer_attempts aa
        WHERE aa.id = v_existing_id
          AND (
            aa.course_id IS DISTINCT FROM p_course_id
            OR aa.skill_id IS DISTINCT FROM p_skill_id
            OR aa.lesson_id IS DISTINCT FROM p_lesson_id
            OR aa.question_id IS DISTINCT FROM p_question_id
            OR aa.selected_index IS DISTINCT FROM p_selected_index
            OR aa.selected_answer IS DISTINCT FROM v_clean_text
          )
      ) THEN
        RAISE EXCEPTION 'Idempotency kaliti boshqa javob uchun ishlatilgan.' USING ERRCODE = '22023';
      END IF;

      SELECT COALESCE(lss.score, 50)
      INTO v_new_skill_score
      FROM public.learner_skill_scores lss
      WHERE lss.user_id = p_user_id AND lss.course_id = p_course_id AND lss.skill_id = p_skill_id;

      SELECT COALESCE(pg_catalog.round(pg_catalog.avg(lss.score))::INT, 50)
      INTO v_overall_score
      FROM public.learner_skill_scores lss
      WHERE lss.user_id = p_user_id AND lss.course_id = p_course_id;

      SELECT COALESCE(gp.xp, 0)
      INTO v_total_xp
      FROM public.gamification_profiles gp
      WHERE gp.user_id = p_user_id;

      IF v_existing_is_correct = true THEN
        SELECT exp_cand.explanation
        INTO v_explanation
        FROM (
          SELECT q.explanation AS explanation
          FROM public.questions q
          WHERE q.id = p_question_id AND NOT q.is_placement
          UNION ALL
          SELECT items.elem->>'explanation' AS explanation
          FROM public.lessons l
          CROSS JOIN LATERAL (
            SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
            FROM pg_catalog.jsonb_array_elements(
              CASE WHEN pg_catalog.jsonb_typeof(l.steps) = 'array' THEN l.steps ELSE '[]'::pg_catalog.jsonb END
            ) AS step_elem
            UNION ALL
            SELECT l.reinforcement_exercise AS elem
            WHERE pg_catalog.jsonb_typeof(l.reinforcement_exercise) = 'object'
            UNION ALL
            SELECT l.alternate_exercise AS elem
            WHERE pg_catalog.jsonb_typeof(l.alternate_exercise) = 'object'
          ) items
          WHERE l.course_id = p_course_id
            AND l.is_published
            AND NOT l.is_archived
            AND pg_catalog.jsonb_typeof(items.elem) = 'object'
            AND items.elem->>'id' = p_question_id
          UNION ALL
          SELECT g_items.elem->>'explanation' AS explanation
          FROM public.generated_lessons gl
          CROSS JOIN LATERAL (
            SELECT elem
            FROM pg_catalog.jsonb_array_elements(
              CASE WHEN pg_catalog.jsonb_typeof(gl.questions) = 'array' THEN gl.questions ELSE '[]'::pg_catalog.jsonb END
            ) AS elem
            UNION ALL
            SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
            FROM pg_catalog.jsonb_array_elements(
              CASE WHEN pg_catalog.jsonb_typeof(gl.steps) = 'array' THEN gl.steps ELSE '[]'::pg_catalog.jsonb END
            ) AS step_elem
          ) g_items
          WHERE gl.course_id = p_course_id
            AND gl.course_id <> 'course_math_01'
            AND pg_catalog.jsonb_typeof(g_items.elem) = 'object'
            AND g_items.elem->>'id' = p_question_id
        ) exp_cand
        WHERE NULLIF(pg_catalog.btrim(COALESCE(exp_cand.explanation, '')), '') IS NOT NULL
        LIMIT 1;
      ELSE
        v_explanation := 'Javob avval qayd etilgan.';
      END IF;

      RETURN pg_catalog.jsonb_build_object(
        'is_correct', v_existing_is_correct,
        'explanation', COALESCE(v_explanation, 'Javob avval qayd etilgan.'),
        'new_skill_score', COALESCE(v_new_skill_score, 50),
        'overall_score', COALESCE(v_overall_score, 50),
        'xp_awarded', 0,
        'total_xp', COALESCE(v_total_xp, 0),
        'already_processed', true
      );
    END IF;
  END IF;

  IF pg_catalog.starts_with(p_lesson_id, 'reinf_') THEN
    SELECT rt.canonical_reinf_id, rt.target_lesson_id, rt.required_score
    INTO v_reinf_target
    FROM bilimyol_private.resolve_reinforcement_target(p_course_id, p_skill_id, p_lesson_id) rt
    LIMIT 1;

    IF v_reinf_target.target_lesson_id IS NULL THEN
      RAISE EXCEPTION 'Mustahkamlash tuguni kurs va ko‘nikmaga mos emas.' USING ERRCODE = '22023';
    END IF;

    SELECT l.course_id,
           COALESCE(NULLIF(COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id'), ''), l.skill_id) AS resolved_skill,
           cand.elem AS resolved_body,
           cand.elem->>'explanation' AS resolved_exp
    INTO v_question_course, v_question_skill, v_q_body, v_explanation
    FROM public.lessons l
    CROSS JOIN LATERAL (
      SELECT l.reinforcement_exercise AS elem
      WHERE pg_catalog.jsonb_typeof(l.reinforcement_exercise) = 'object'
      UNION ALL
      SELECT l.alternate_exercise AS elem
      WHERE pg_catalog.jsonb_typeof(l.alternate_exercise) = 'object'
    ) cand
    WHERE l.id = v_reinf_target.target_lesson_id
      AND l.course_id = p_course_id
      AND l.is_published
      AND NOT l.is_archived
      AND cand.elem->>'id' = p_question_id
    LIMIT 1;

    IF v_question_course IS NULL AND NOT EXISTS (
      SELECT 1 FROM public.lessons existing_l WHERE existing_l.id = v_reinf_target.target_lesson_id
    ) THEN
      SELECT gl.course_id,
             COALESCE(NULLIF(COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id'), ''), gl.skill_id),
             cand.elem,
             cand.elem->>'explanation'
      INTO v_question_course, v_question_skill, v_q_body, v_explanation
      FROM public.generated_lessons gl
      CROSS JOIN LATERAL (
        SELECT elem
        FROM pg_catalog.jsonb_array_elements(
          CASE WHEN pg_catalog.jsonb_typeof(gl.questions) = 'array' THEN gl.questions ELSE '[]'::pg_catalog.jsonb END
        ) AS elem
        UNION ALL
        SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
        FROM pg_catalog.jsonb_array_elements(
          CASE WHEN pg_catalog.jsonb_typeof(gl.steps) = 'array' THEN gl.steps ELSE '[]'::pg_catalog.jsonb END
        ) AS step_elem
      ) cand
      WHERE gl.id = v_reinf_target.target_lesson_id
        AND gl.course_id = p_course_id
        AND gl.course_id <> 'course_math_01'
        AND (
          gl.skill_id = p_skill_id
          OR COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id') = p_skill_id
        )
        AND pg_catalog.jsonb_typeof(cand.elem) = 'object'
        AND cand.elem->>'id' = p_question_id
      LIMIT 1;
    END IF;

    IF v_question_course IS NULL THEN
      RAISE EXCEPTION 'Savol ushbu mustahkamlash mashqiga tegishli emas.' USING ERRCODE = '22023';
    END IF;
  ELSE
    SELECT l.course_id,
           COALESCE(NULLIF(COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id'), ''), l.skill_id) AS resolved_skill,
           cand.elem AS resolved_body,
           cand.elem->>'explanation' AS resolved_exp
    INTO v_question_course, v_question_skill, v_q_body, v_explanation
    FROM public.lessons l
    CROSS JOIN LATERAL (
      SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
      FROM pg_catalog.jsonb_array_elements(
        CASE WHEN pg_catalog.jsonb_typeof(l.steps) = 'array' THEN l.steps ELSE '[]'::pg_catalog.jsonb END
      ) AS step_elem
      UNION ALL
      SELECT l.alternate_exercise AS elem
      WHERE pg_catalog.jsonb_typeof(l.alternate_exercise) = 'object'
      UNION ALL
      SELECT l.reinforcement_exercise AS elem
      WHERE pg_catalog.jsonb_typeof(l.reinforcement_exercise) = 'object'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_array_elements(
            CASE WHEN pg_catalog.jsonb_typeof(l.steps) = 'array' THEN l.steps ELSE '[]'::pg_catalog.jsonb END
          ) AS s_chk
          WHERE NULLIF(COALESCE(s_chk->'interactiveQuestion', s_chk->'interactive_question')->>'id', '') IS NOT NULL
        )
    ) cand
    WHERE l.id = p_lesson_id
      AND l.is_published
      AND NOT l.is_archived
      AND pg_catalog.jsonb_typeof(cand.elem) = 'object'
      AND cand.elem->>'id' = p_question_id
    LIMIT 1;

    IF v_question_course IS NULL AND NOT EXISTS (
      SELECT 1 FROM public.lessons existing_l WHERE existing_l.id = p_lesson_id
    ) THEN
      SELECT gl.course_id,
             COALESCE(NULLIF(COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id'), ''), gl.skill_id),
             cand.elem,
             cand.elem->>'explanation'
      INTO v_question_course, v_question_skill, v_q_body, v_explanation
      FROM public.generated_lessons gl
      CROSS JOIN LATERAL (
        SELECT elem
        FROM pg_catalog.jsonb_array_elements(
          CASE WHEN pg_catalog.jsonb_typeof(gl.questions) = 'array' THEN gl.questions ELSE '[]'::pg_catalog.jsonb END
        ) AS elem
        UNION ALL
        SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
        FROM pg_catalog.jsonb_array_elements(
          CASE WHEN pg_catalog.jsonb_typeof(gl.steps) = 'array' THEN gl.steps ELSE '[]'::pg_catalog.jsonb END
        ) AS step_elem
      ) cand
      WHERE gl.id = p_lesson_id
        AND gl.course_id <> 'course_math_01'
        AND pg_catalog.jsonb_typeof(cand.elem) = 'object'
        AND cand.elem->>'id' = p_question_id
      LIMIT 1;
    END IF;
  END IF;

  IF v_question_course IS NULL THEN
    RAISE EXCEPTION 'Savol dars tarkibida yoki chop etilgan bazada topilmadi.' USING ERRCODE = '22023';
  END IF;
  IF v_question_course <> p_course_id OR v_question_skill <> p_skill_id THEN
    RAISE EXCEPTION 'Savol kurs yoki ko‘nikma kontekstiga mos emas.' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_q_body->>'correct_index', v_q_body->>'correctIndex') IS NULL
     AND COALESCE(NULLIF(COALESCE(v_q_body->>'questionType', v_q_body->>'question_type', v_q_body->>'mode', ''), ''), 'multiple_choice')
         IN ('multiple_choice', 'error_correction', 'conversation_completion') THEN
    SELECT q.correct_index, q.explanation, q.options
    INTO v_q_row
    FROM public.questions q
    WHERE q.id = p_question_id
      AND NOT q.is_placement
      AND q.course_id = v_question_course
      AND q.skill_id = v_question_skill;

    IF FOUND THEN
      v_q_body := COALESCE(v_q_body, '{}'::pg_catalog.jsonb)
        || pg_catalog.jsonb_build_object(
             'correct_index', v_q_row.correct_index,
             'options', COALESCE(v_q_body->'options', v_q_row.options)
           );
      v_explanation := COALESCE(NULLIF(v_explanation, ''), v_q_row.explanation);
    END IF;
  END IF;

  v_is_correct := bilimyol_private.grade_question_attempt(v_q_body, p_selected_index, v_clean_text);
  IF NOT v_is_correct THEN
    v_explanation := COALESCE(
      NULLIF(pg_catalog.btrim(COALESCE(v_q_body->>'wrongFeedback', v_q_body->>'wrong_feedback', '')), ''),
      NULLIF(pg_catalog.btrim(COALESCE(v_explanation, '')), '')
    );
  END IF;

  INSERT INTO public.answer_attempts (
    user_id, course_id, skill_id, lesson_id, question_id,
    selected_index, selected_answer, is_correct, idempotency_key, created_at
  )
  VALUES (
    p_user_id, p_course_id, p_skill_id, p_lesson_id, p_question_id,
    p_selected_index, v_clean_text, v_is_correct, v_eff_idempotency,
    GREATEST(
      pg_catalog.clock_timestamp(),
      COALESCE(
        (SELECT pg_catalog.max(aa_prev.created_at) + interval '1 microsecond'
         FROM public.answer_attempts aa_prev
         WHERE aa_prev.user_id = p_user_id),
        pg_catalog.clock_timestamp()
      ),
      COALESCE(
        (SELECT pg_catalog.max(ra_prev.created_at) + interval '1 microsecond'
         FROM public.reinforcement_attempts ra_prev
         WHERE ra_prev.user_id = p_user_id),
        pg_catalog.clock_timestamp()
      )
    )
  )
  ON CONFLICT (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  IF NOT FOUND AND v_eff_idempotency IS NOT NULL THEN
    RETURN bilimyol_private.submit_answer_attempt(
      p_user_id, p_course_id, p_skill_id, p_lesson_id, p_question_id,
      p_selected_index, p_selected_text, p_idempotency_key
    );
  END IF;

  SELECT pg_catalog.count(*)::INT,
         pg_catalog.count(*) FILTER (WHERE latest.is_correct = true)::INT
  INTO v_unique_total, v_unique_correct
  FROM (
    SELECT DISTINCT ON (aa.question_id) aa.question_id, aa.is_correct
    FROM public.answer_attempts aa
    WHERE aa.user_id = p_user_id AND aa.course_id = p_course_id AND aa.skill_id = p_skill_id
    ORDER BY aa.question_id, aa.created_at DESC, aa.id DESC
  ) latest;

  IF v_unique_total > 0 THEN
    v_new_skill_score := pg_catalog.round((v_unique_correct::NUMERIC / v_unique_total::NUMERIC) * 100)::INT;
  ELSE
    v_new_skill_score := CASE WHEN v_is_correct THEN 100 ELSE 0 END;
  END IF;
  v_new_skill_score := GREATEST(0, LEAST(100, v_new_skill_score));

  SELECT GREATEST(v_new_skill_score, COALESCE(pg_catalog.max(ra.after_score), 0))
  INTO v_new_skill_score
  FROM public.reinforcement_attempts ra
  WHERE ra.user_id = p_user_id
    AND ra.course_id = p_course_id
    AND ra.skill_id = p_skill_id
    AND ra.is_correct = true
    AND NOT EXISTS (
      SELECT 1 FROM public.answer_attempts newer_wrong
      WHERE newer_wrong.user_id = p_user_id
        AND newer_wrong.course_id = p_course_id
        AND newer_wrong.skill_id = p_skill_id
        AND newer_wrong.is_correct = false
        AND newer_wrong.created_at > ra.created_at
    );

  IF v_new_skill_score < 40 THEN
    v_mastery_level := 'needs_remediation';
  ELSIF v_new_skill_score < 60 THEN
    v_mastery_level := 'developing';
  ELSIF v_new_skill_score < 80 THEN
    v_mastery_level := 'proficient';
  ELSE
    v_mastery_level := 'mastered';
  END IF;

  INSERT INTO public.learner_skill_scores (
    user_id, course_id, skill_id, score, mastery_level, attempt_count, last_updated
  )
  VALUES (
    p_user_id, p_course_id, p_skill_id, v_new_skill_score, v_mastery_level, v_unique_total, pg_catalog.now()
  )
  ON CONFLICT (user_id, course_id, skill_id) DO UPDATE SET
    score = EXCLUDED.score,
    mastery_level = EXCLUDED.mastery_level,
    attempt_count = EXCLUDED.attempt_count,
    last_updated = pg_catalog.now();

  SELECT COALESCE(pg_catalog.round(pg_catalog.avg(lss.score))::INT, v_new_skill_score)
  INTO v_overall_score
  FROM public.learner_skill_scores lss
  WHERE lss.user_id = p_user_id AND lss.course_id = p_course_id;

  IF v_is_correct AND NOT EXISTS (
    SELECT 1 FROM public.gamification_events ge
    WHERE ge.user_id = p_user_id AND ge.action_key = 'answer_correct_' || p_question_id
  ) THEN
    v_pending_answer_xp := 2;
  END IF;

  INSERT INTO bilimyol_private.daily_question_outcomes (
    user_id, activity_date, question_id, is_correct, updated_at
  )
  VALUES (
    p_user_id, v_today, p_question_id, v_is_correct, pg_catalog.now()
  )
  ON CONFLICT (user_id, activity_date, question_id) DO UPDATE SET
    is_correct = EXCLUDED.is_correct,
    updated_at = EXCLUDED.updated_at;

  SELECT pg_catalog.count(*)::INT,
         pg_catalog.count(*) FILTER (WHERE dqo.is_correct)::INT
  INTO v_daily_total, v_daily_correct
  FROM bilimyol_private.daily_question_outcomes dqo
  WHERE dqo.user_id = p_user_id AND dqo.activity_date = v_today;

  v_daily_accuracy := CASE
    WHEN v_daily_total > 0
    THEN pg_catalog.round((v_daily_correct::NUMERIC * 100) / v_daily_total::NUMERIC)::INT
    ELSE 0
  END;

  INSERT INTO public.daily_learning_stats (
    user_id, activity_date, questions_answered, correct_answers,
    accuracy_percent, xp_earned, overall_score, updated_at
  )
  VALUES (
    p_user_id, v_today, v_daily_total, v_daily_correct,
    v_daily_accuracy, v_pending_answer_xp, v_overall_score, pg_catalog.now()
  )
  ON CONFLICT (user_id, activity_date) DO UPDATE SET
    questions_answered = EXCLUDED.questions_answered,
    correct_answers = EXCLUDED.correct_answers,
    accuracy_percent = EXCLUDED.accuracy_percent,
    xp_earned = public.daily_learning_stats.xp_earned + EXCLUDED.xp_earned,
    overall_score = v_overall_score,
    updated_at = pg_catalog.now();

  IF v_is_correct THEN
    v_award := bilimyol_private.award_xp(p_user_id, 2, 'answer_correct_' || p_question_id);
    v_xp_delta := CASE WHEN (v_award->>'awarded')::BOOLEAN THEN 2 ELSE 0 END;
  ELSE
    v_xp_delta := 0;
  END IF;

  PERFORM public.record_learning_activity(v_today);

  SELECT COALESCE(gp.xp, 0)
  INTO v_total_xp
  FROM public.gamification_profiles gp
  WHERE gp.user_id = p_user_id;

  IF NOT v_is_correct AND p_course_id = 'course_math_01' AND EXISTS (
    SELECT 1 FROM bilimyol_private.math_pilot_items mpi
    WHERE mpi.lesson_id = p_lesson_id AND mpi.question_id = p_question_id
  ) THEN
    SELECT pg_catalog.count(*)::INT
    INTO v_wrong_count
    FROM public.answer_attempts aa
    WHERE aa.user_id = p_user_id
      AND aa.course_id = p_course_id
      AND aa.skill_id = p_skill_id
      AND aa.lesson_id = p_lesson_id
      AND aa.question_id = p_question_id
      AND aa.is_correct = false;

    IF v_wrong_count < 2 AND NOT EXISTS (
      SELECT 1 FROM bilimyol_private.math_progression(p_user_id) mp
      WHERE mp.target_lesson_id = p_lesson_id
        AND mp.mastery_state IN ('needs_review', 'mastered')
    ) THEN
      v_hide_mistake_spoiler := true;
    END IF;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'is_correct', v_is_correct,
    'explanation', CASE
      WHEN v_hide_mistake_spoiler THEN 'Ishlangan misolni ko‘rib chiqing va qayta urinib ko‘ring.'
      ELSE COALESCE(v_explanation, 'To‘g‘ri yechim.')
    END,
    'new_skill_score', v_new_skill_score,
    'overall_score', v_overall_score,
    'xp_awarded', v_xp_delta,
    'total_xp', COALESCE(v_total_xp, 0),
    'total_attempts', v_unique_total,
    'correct_attempts', v_unique_correct,
    'already_processed', false
  );
END;
$$;

REVOKE ALL ON FUNCTION bilimyol_private.submit_answer_attempt(
  UUID, TEXT, TEXT, TEXT, TEXT, INT, TEXT, TEXT
) FROM PUBLIC, anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 7. Multi-skill & alternate_exercise support in public.complete_lesson (FIX-P1-40)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.complete_lesson(p_lesson_id TEXT, p_course_id TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_course TEXT;
  v_required_items JSONB := '[]'::pg_catalog.jsonb;
  v_alt_qid TEXT;
  v_alt_skill TEXT;
  v_required_count INT := 0;
  v_passed_count INT := 0;
  v_alt_passed BOOLEAN := false;
  v_award JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autentifikatsiya talab qilinadi.' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('learning:' || v_uid::TEXT, 0)
  );

  IF p_course_id = 'course_math_01' THEN
    SELECT n.course_id
    INTO v_course
    FROM bilimyol_private.math_progression(v_uid) n
    WHERE n.target_lesson_id = p_lesson_id AND n.status = 'completed';

    IF v_course IS NULL THEN
      IF public.can_open_math_lesson(p_lesson_id) THEN
        RAISE EXCEPTION 'Darsni yakunlash uchun ikkala tekshiruvdagi mashqlarni bajaring va ishlangan misolni qayta ko‘ring.' USING ERRCODE = '42501';
      END IF;
      RAISE EXCEPTION 'Avval tayanch mavzularni o‘zlashtiring.' USING ERRCODE = '42501';
    END IF;
  ELSE
    SELECT l.course_id,
           COALESCE((
             SELECT pg_catalog.jsonb_agg(
               pg_catalog.jsonb_build_object(
                 'qid', COALESCE(step->'interactiveQuestion', step->'interactive_question')->>'id',
                 'skill_id', COALESCE(
                   NULLIF(COALESCE(
                     COALESCE(step->'interactiveQuestion', step->'interactive_question')->>'skillId',
                     COALESCE(step->'interactiveQuestion', step->'interactive_question')->>'skill_id'
                   ), ''),
                   l.skill_id
                 )
               )
               ORDER BY ord
             )
             FROM pg_catalog.jsonb_array_elements(
               CASE WHEN pg_catalog.jsonb_typeof(l.steps) = 'array' THEN l.steps ELSE '[]'::pg_catalog.jsonb END
             ) WITH ORDINALITY AS s(step, ord)
             WHERE NULLIF(COALESCE(step->'interactiveQuestion', step->'interactive_question')->>'id', '') IS NOT NULL
           ), '[]'::pg_catalog.jsonb),
           NULLIF(l.alternate_exercise->>'id', ''),
           COALESCE(NULLIF(COALESCE(l.alternate_exercise->>'skillId', l.alternate_exercise->>'skill_id'), ''), l.skill_id)
    INTO v_course, v_required_items, v_alt_qid, v_alt_skill
    FROM public.lessons l
    WHERE l.id = p_lesson_id AND l.is_published AND NOT l.is_archived;

    IF v_course IS NOT NULL AND pg_catalog.jsonb_array_length(v_required_items) = 0 THEN
      SELECT COALESCE(
        CASE
          WHEN NULLIF(l.reinforcement_exercise->>'id', '') IS NOT NULL THEN
            pg_catalog.jsonb_build_array(
              pg_catalog.jsonb_build_object(
                'qid', l.reinforcement_exercise->>'id',
                'skill_id', COALESCE(
                  NULLIF(COALESCE(l.reinforcement_exercise->>'skillId', l.reinforcement_exercise->>'skill_id'), ''),
                  l.skill_id
                )
              )
            )
        END,
        '[]'::pg_catalog.jsonb
      )
      INTO v_required_items
      FROM public.lessons l
      WHERE l.id = p_lesson_id;
    END IF;

    IF v_course IS NULL THEN
      SELECT gl.course_id,
             CASE
               WHEN NULLIF(gl.questions->0->>'id', '') IS NOT NULL THEN
                 pg_catalog.jsonb_build_array(
                   pg_catalog.jsonb_build_object(
                     'qid', gl.questions->0->>'id',
                     'skill_id', COALESCE(
                       NULLIF(COALESCE(gl.questions->0->>'skillId', gl.questions->0->>'skill_id'), ''),
                       gl.skill_id
                     )
                   )
                 )
               ELSE '[]'::pg_catalog.jsonb
             END
      INTO v_course, v_required_items
      FROM public.generated_lessons gl
      WHERE gl.id = p_lesson_id;
    END IF;

    IF v_course IS NULL OR v_course IS DISTINCT FROM p_course_id THEN
      RAISE EXCEPTION 'Dars kursda topilmadi.' USING ERRCODE = '22023';
    END IF;

    v_required_count := pg_catalog.jsonb_array_length(v_required_items);
    IF v_required_count = 0 THEN
      RAISE EXCEPTION 'Darsning baholanadigan savollari topilmadi.' USING ERRCODE = '22023';
    END IF;

    SELECT pg_catalog.count(*)::INT
    INTO v_passed_count
    FROM pg_catalog.jsonb_array_elements(v_required_items) AS req
    WHERE COALESCE((
      SELECT aa.is_correct
      FROM public.answer_attempts aa
      WHERE aa.user_id = v_uid
        AND aa.course_id = v_course
        AND aa.skill_id = req->>'skill_id'
        AND aa.lesson_id = p_lesson_id
        AND aa.question_id = req->>'qid'
      ORDER BY aa.created_at DESC, aa.id DESC
      LIMIT 1
    ), false) = true;

    IF v_passed_count < v_required_count THEN
      IF v_passed_count = v_required_count - 1 AND v_alt_qid IS NOT NULL THEN
        SELECT COALESCE((
          SELECT aa.is_correct
          FROM public.answer_attempts aa
          WHERE aa.user_id = v_uid
            AND aa.course_id = v_course
            AND aa.skill_id = v_alt_skill
            AND aa.lesson_id = p_lesson_id
            AND aa.question_id = v_alt_qid
          ORDER BY aa.created_at DESC, aa.id DESC
          LIMIT 1
        ), false)
        INTO v_alt_passed;
      END IF;

      IF NOT v_alt_passed THEN
        RAISE EXCEPTION 'Dars javoblari serverda tasdiqlanmagan.' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  INSERT INTO public.lesson_progress (
    user_id, lesson_id, course_id, status, progress_percent, completed_at, updated_at
  )
  VALUES (v_uid, p_lesson_id, v_course, 'completed', 100, pg_catalog.now(), pg_catalog.now())
  ON CONFLICT (user_id, lesson_id) DO UPDATE SET
    status = 'completed',
    progress_percent = 100,
    completed_at = COALESCE(public.lesson_progress.completed_at, pg_catalog.now()),
    updated_at = pg_catalog.now();

  v_award := bilimyol_private.award_xp(v_uid, 20, 'lesson_completed_' || p_lesson_id);
  PERFORM public.record_learning_activity();

  RETURN pg_catalog.jsonb_build_object(
    'completed', true,
    'xp_awarded', CASE WHEN (v_award->>'awarded')::BOOLEAN THEN 20 ELSE 0 END
  );
END;
$$;

REVOKE ALL ON FUNCTION public.complete_lesson(TEXT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.complete_lesson(TEXT, TEXT) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 8. Lift <28% skills to >=50% on canonical reinforcement completion (FIX-P1-40)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.complete_reinforcement(
  p_reinforcement_node_id TEXT,
  p_course_id TEXT,
  p_skill_id TEXT,
  p_question_id TEXT,
  p_xp_awarded INT DEFAULT 30
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_target RECORD;
  v_existing RECORD;
  v_origin_alias TEXT;
  v_unique_total INT := 0;
  v_unique_correct INT := 0;
  v_before INT := 0;
  v_parent_skill_id TEXT;
  v_parent_total INT := 0;
  v_parent_correct INT := 0;
  v_parent_lss_score INT;
  v_parent_before INT := 0;
  v_parent_needs_remediation BOOLEAN := false;
  v_current_raw INT := 0;
  v_after INT := 50;
  v_server_xp_awarded CONSTANT INT := 30;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autentifikatsiya talab qilinadi.' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(pg_catalog.btrim(p_reinforcement_node_id), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_course_id), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_skill_id), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_question_id), '') IS NULL THEN
    RAISE EXCEPTION 'Mustahkamlash ma’lumotlari noto‘g‘ri.' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('learning:' || v_uid::TEXT, 0)
  );

  SELECT rt.canonical_reinf_id, rt.target_lesson_id, rt.required_score
  INTO v_target
  FROM bilimyol_private.resolve_reinforcement_target(p_course_id, p_skill_id, p_reinforcement_node_id) rt
  LIMIT 1;

  IF v_target.target_lesson_id IS NULL THEN
    RAISE EXCEPTION 'Mustahkamlash mashqi kurs va ko‘nikmaga mos emas.' USING ERRCODE = '22023';
  END IF;

  IF p_course_id = 'course_math_01' AND NOT public.can_open_math_lesson(v_target.target_lesson_id) THEN
    RAISE EXCEPTION 'Avval tayanch mavzularni o‘zlashtiring.' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.lessons l
    CROSS JOIN LATERAL (
      SELECT l.reinforcement_exercise AS elem
      WHERE pg_catalog.jsonb_typeof(l.reinforcement_exercise) = 'object'
      UNION ALL
      SELECT l.alternate_exercise AS elem
      WHERE pg_catalog.jsonb_typeof(l.alternate_exercise) = 'object'
    ) cand
    WHERE l.id = v_target.target_lesson_id
      AND l.course_id = p_course_id
      AND l.is_published
      AND NOT l.is_archived
      AND cand.elem->>'id' = p_question_id
      AND COALESCE(NULLIF(COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id'), ''), l.skill_id) = p_skill_id
    UNION ALL
    SELECT 1
    FROM public.generated_lessons gl
    CROSS JOIN LATERAL (
      SELECT elem
      FROM pg_catalog.jsonb_array_elements(
        CASE WHEN pg_catalog.jsonb_typeof(gl.questions) = 'array' THEN gl.questions ELSE '[]'::pg_catalog.jsonb END
      ) AS elem
      UNION ALL
      SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
      FROM pg_catalog.jsonb_array_elements(
        CASE WHEN pg_catalog.jsonb_typeof(gl.steps) = 'array' THEN gl.steps ELSE '[]'::pg_catalog.jsonb END
      ) AS step_elem
    ) cand
    WHERE gl.id = v_target.target_lesson_id
      AND gl.course_id = p_course_id
      AND gl.course_id <> 'course_math_01'
      AND (
        gl.skill_id = p_skill_id
        OR COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id') = p_skill_id
      )
      AND NOT EXISTS (SELECT 1 FROM public.lessons existing_l WHERE existing_l.id = v_target.target_lesson_id)
      AND pg_catalog.jsonb_typeof(cand.elem) = 'object'
      AND cand.elem->>'id' = p_question_id
  ) THEN
    RAISE EXCEPTION 'Mustahkamlash savoli darsning ruxsat etilgan mashqiga mos emas.' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.reinforcement_attempts ra
  WHERE ra.user_id = v_uid
    AND ra.course_id = p_course_id
    AND (
      ra.reinforcement_node_id = v_target.canonical_reinf_id
      OR (
        ra.skill_id = p_skill_id
        AND (
          ra.reinforcement_node_id = p_reinforcement_node_id
          OR ra.reinforcement_node_id = 'reinf_lesson_' || v_target.target_lesson_id
          OR ra.reinforcement_node_id = 'reinf_' || p_course_id || '_' || p_skill_id
          OR EXISTS (
            SELECT 1
            FROM bilimyol_private.resolve_reinforcement_target(
              p_course_id, p_skill_id, ra.reinforcement_node_id
            ) existing_t
            WHERE existing_t.target_lesson_id = v_target.target_lesson_id
          )
        )
      )
    )
  ORDER BY ra.created_at ASC, ra.id ASC
  LIMIT 1;

  IF FOUND THEN
    SELECT aa.lesson_id
    INTO v_origin_alias
    FROM public.answer_attempts aa
    WHERE aa.user_id = v_uid
      AND aa.course_id = p_course_id
      AND aa.skill_id = v_existing.skill_id
      AND aa.is_correct = true
      AND aa.created_at <= v_existing.created_at
      AND aa.lesson_id IN (
        v_existing.reinforcement_node_id,
        v_target.canonical_reinf_id,
        'reinf_lesson_' || v_target.target_lesson_id,
        'reinf_' || p_course_id || '_' || v_existing.skill_id
      )
    ORDER BY aa.created_at DESC, aa.id DESC
    LIMIT 1;

    IF v_existing.skill_id = p_skill_id
       AND COALESCE(v_origin_alias, v_existing.reinforcement_node_id) = p_reinforcement_node_id THEN
      RETURN pg_catalog.jsonb_build_object(
        'already_processed', true,
        'old_score', v_existing.before_score,
        'new_score', v_existing.after_score,
        'xp_awarded', 0
      );
    END IF;

    RAISE EXCEPTION 'Ushbu dars bo‘yicha mustahkamlash mashqi allaqachon yakunlangan.' USING ERRCODE = '42501';
  END IF;

  IF NOT COALESCE((
    SELECT aa.is_correct
    FROM public.answer_attempts aa
    WHERE aa.user_id = v_uid
      AND aa.course_id = p_course_id
      AND aa.skill_id = p_skill_id
      AND aa.lesson_id = p_reinforcement_node_id
      AND aa.question_id = p_question_id
    ORDER BY aa.created_at DESC, aa.id DESC
    LIMIT 1
  ), false) THEN
    RAISE EXCEPTION 'Mustahkamlash javobi serverda to‘g‘ri deb tasdiqlanmagan.'
      USING ERRCODE = '42501';
  END IF;

  SELECT pg_catalog.count(*)::INT,
         pg_catalog.count(*) FILTER (WHERE latest.is_correct)::INT
  INTO v_unique_total, v_unique_correct
  FROM (
    SELECT DISTINCT ON (aa.question_id) aa.is_correct
    FROM public.answer_attempts aa
    WHERE aa.user_id = v_uid
      AND aa.course_id = p_course_id
      AND aa.skill_id = p_skill_id
      AND aa.lesson_id NOT IN (
        p_reinforcement_node_id,
        v_target.canonical_reinf_id,
        'reinf_lesson_' || v_target.target_lesson_id
      )
    ORDER BY aa.question_id, aa.created_at DESC, aa.id DESC
  ) latest;

  v_before := COALESCE(
    pg_catalog.round((v_unique_correct::NUMERIC / NULLIF(v_unique_total, 0)::NUMERIC) * 100)::INT,
    0
  );

  SELECT GREATEST(v_before, COALESCE(pg_catalog.max(ra.after_score), 0))
  INTO v_before
  FROM public.reinforcement_attempts ra
  WHERE ra.user_id = v_uid
    AND ra.course_id = p_course_id
    AND ra.skill_id = p_skill_id
    AND ra.is_correct = true
    AND NOT EXISTS (
      SELECT 1 FROM public.answer_attempts newer_wrong
      WHERE newer_wrong.user_id = v_uid
        AND newer_wrong.course_id = p_course_id
        AND newer_wrong.skill_id = p_skill_id
        AND newer_wrong.is_correct = false
        AND newer_wrong.created_at > ra.created_at
    );

  SELECT COALESCE(
    (SELECT rn.skill_id
     FROM public.roadmap_nodes rn
     WHERE rn.course_id = p_course_id
       AND rn.is_active
       AND (
         v_target.canonical_reinf_id = 'reinf_' || rn.id
         OR (rn.is_reinforcement AND v_target.canonical_reinf_id = rn.id)
       )
     ORDER BY rn.order_index ASC, rn.id ASC
     LIMIT 1),
    (SELECT l.skill_id FROM public.lessons l WHERE l.id = v_target.target_lesson_id LIMIT 1),
    p_skill_id
  )
  INTO v_parent_skill_id;

  IF v_parent_skill_id IS DISTINCT FROM p_skill_id THEN
    SELECT pg_catalog.count(*)::INT,
           pg_catalog.count(*) FILTER (WHERE latest.is_correct)::INT
    INTO v_parent_total, v_parent_correct
    FROM (
      SELECT DISTINCT ON (aa.question_id) aa.is_correct
      FROM public.answer_attempts aa
      WHERE aa.user_id = v_uid
        AND aa.course_id = p_course_id
        AND aa.skill_id = v_parent_skill_id
        AND aa.lesson_id NOT IN (
          p_reinforcement_node_id,
          v_target.canonical_reinf_id,
          'reinf_lesson_' || v_target.target_lesson_id
        )
      ORDER BY aa.question_id, aa.created_at DESC, aa.id DESC
    ) latest;

    SELECT lss.score
    INTO v_parent_lss_score
    FROM public.learner_skill_scores lss
    WHERE lss.user_id = v_uid
      AND lss.course_id = p_course_id
      AND lss.skill_id = v_parent_skill_id;

    IF v_parent_total > 0 OR v_parent_lss_score IS NOT NULL THEN
      v_parent_before := CASE
        WHEN v_parent_total > 0 THEN
          pg_catalog.round((v_parent_correct::NUMERIC / v_parent_total::NUMERIC) * 100)::INT
        ELSE
          v_parent_lss_score
      END;

      SELECT GREATEST(v_parent_before, COALESCE(pg_catalog.max(ra.after_score), 0))
      INTO v_parent_before
      FROM public.reinforcement_attempts ra
      WHERE ra.user_id = v_uid
        AND ra.course_id = p_course_id
        AND ra.skill_id = v_parent_skill_id
        AND ra.is_correct = true
        AND NOT EXISTS (
          SELECT 1 FROM public.answer_attempts newer_wrong
          WHERE newer_wrong.user_id = v_uid
            AND newer_wrong.course_id = p_course_id
            AND newer_wrong.skill_id = v_parent_skill_id
            AND newer_wrong.is_correct = false
            AND newer_wrong.created_at > ra.created_at
        );

      v_parent_needs_remediation := (v_parent_before < v_target.required_score);
    ELSE
      v_parent_needs_remediation := false;
    END IF;
  END IF;

  IF v_before >= v_target.required_score AND NOT v_parent_needs_remediation THEN
    RAISE EXCEPTION 'Ushbu ko‘nikma allaqachon yetarli darajada o‘zlashtirilgan.' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(lss.score, 0)
  INTO v_current_raw
  FROM public.learner_skill_scores lss
  WHERE lss.user_id = v_uid AND lss.course_id = p_course_id AND lss.skill_id = p_skill_id;

  v_after := LEAST(100, GREATEST(50, COALESCE(v_current_raw, 0), v_before + 22));

  INSERT INTO public.reinforcement_attempts (
    user_id, course_id, skill_id, reinforcement_node_id,
    before_score, after_score, is_correct, xp_awarded, created_at
  )
  VALUES (
    v_uid, p_course_id, p_skill_id, v_target.canonical_reinf_id,
    v_before, v_after, true, v_server_xp_awarded,
    GREATEST(
      pg_catalog.clock_timestamp(),
      COALESCE(
        (SELECT pg_catalog.max(aa_prev.created_at) + interval '1 microsecond'
         FROM public.answer_attempts aa_prev
         WHERE aa_prev.user_id = v_uid),
        pg_catalog.clock_timestamp()
      ),
      COALESCE(
        (SELECT pg_catalog.max(ra_prev.created_at) + interval '1 microsecond'
         FROM public.reinforcement_attempts ra_prev
         WHERE ra_prev.user_id = v_uid),
        pg_catalog.clock_timestamp()
      )
    )
  );

  INSERT INTO public.learner_skill_scores (
    user_id, course_id, skill_id, score, mastery_level, attempt_count, last_updated
  )
  VALUES (
    v_uid, p_course_id, p_skill_id, v_after,
    CASE
      WHEN v_after < 40 THEN 'needs_remediation'
      WHEN v_after < 60 THEN 'developing'
      WHEN v_after < 80 THEN 'proficient'
      ELSE 'mastered'
    END,
    1, pg_catalog.now()
  )
  ON CONFLICT (user_id, course_id, skill_id) DO UPDATE SET
    score = EXCLUDED.score,
    mastery_level = EXCLUDED.mastery_level,
    last_updated = pg_catalog.now();

  PERFORM bilimyol_private.award_xp(
    v_uid,
    v_server_xp_awarded,
    'reinforcement_completed_' || v_target.canonical_reinf_id
  );
  PERFORM public.record_learning_activity();

  RETURN pg_catalog.jsonb_build_object(
    'already_processed', false,
    'old_score', v_before,
    'new_score', v_after,
    'xp_awarded', v_server_xp_awarded
  );
END;
$$;

REVOKE ALL ON FUNCTION public.complete_reinforcement(TEXT, TEXT, TEXT, TEXT, INT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_reinforcement(TEXT, TEXT, TEXT, TEXT, INT)
  TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 9. Rich 9-mode mistake feedback in bilimyol_private.resolve_mistake_context,
--    public.tutor_mistake_context, and public.get_mistake_feedback (FIX-P1-40)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION bilimyol_private.resolve_mistake_context(
  p_user_id UUID,
  p_course_id TEXT,
  p_skill_id TEXT,
  p_question_id TEXT,
  p_expose_non_choice_answer BOOLEAN
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_lesson_id TEXT;
  v_selected_index INT;
  v_selected_answer TEXT;
  v_q_body JSONB;
  v_q_type TEXT;
  v_question_text TEXT;
  v_selected_option TEXT;
  v_correct_index INT;
  v_correct_option TEXT;
  v_explanation TEXT;
  v_parsed JSONB;
  v_wrong_count INT := 0;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT aa.lesson_id, aa.selected_index, aa.selected_answer
  INTO v_lesson_id, v_selected_index, v_selected_answer
  FROM public.answer_attempts aa
  WHERE aa.user_id = p_user_id
    AND aa.course_id = p_course_id
    AND aa.skill_id = p_skill_id
    AND aa.question_id = p_question_id
    AND NOT aa.is_correct
  ORDER BY aa.created_at DESC, aa.id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT q_cand.body
  INTO v_q_body
  FROM (
    SELECT pg_catalog.to_jsonb(q) AS body
    FROM public.questions q
    WHERE q.id = p_question_id
      AND q.course_id = p_course_id
      AND q.skill_id = p_skill_id
      AND NOT q.is_placement
    UNION ALL
    SELECT cand.elem AS body
    FROM public.generated_lessons gl
    CROSS JOIN LATERAL (
      SELECT elem
      FROM pg_catalog.jsonb_array_elements(
        CASE WHEN pg_catalog.jsonb_typeof(gl.questions) = 'array' THEN gl.questions ELSE '[]'::pg_catalog.jsonb END
      ) AS elem
      UNION ALL
      SELECT COALESCE(step_elem->'interactiveQuestion', step_elem->'interactive_question') AS elem
      FROM pg_catalog.jsonb_array_elements(
        CASE WHEN pg_catalog.jsonb_typeof(gl.steps) = 'array' THEN gl.steps ELSE '[]'::pg_catalog.jsonb END
      ) AS step_elem
    ) cand
    WHERE (
        gl.id = v_lesson_id
        OR (
          pg_catalog.starts_with(v_lesson_id, 'reinf_lesson_')
          AND gl.id = pg_catalog.substr(v_lesson_id, 14)
          AND gl.course_id <> 'course_math_01'
        )
      )
      AND gl.course_id = p_course_id
      AND (
        gl.skill_id = p_skill_id
        OR COALESCE(cand.elem->>'skillId', cand.elem->>'skill_id') = p_skill_id
      )
      AND pg_catalog.jsonb_typeof(cand.elem) = 'object'
      AND cand.elem->>'id' = p_question_id
    UNION ALL
    SELECT items.item AS body
    FROM public.lessons l
    CROSS JOIN LATERAL (
      SELECT COALESCE(step->'interactiveQuestion', step->'interactive_question') AS item
      FROM pg_catalog.jsonb_array_elements(
        CASE WHEN pg_catalog.jsonb_typeof(l.steps) = 'array' THEN l.steps ELSE '[]'::pg_catalog.jsonb END
      ) AS step
      UNION ALL
      SELECT l.reinforcement_exercise AS item
      WHERE pg_catalog.jsonb_typeof(l.reinforcement_exercise) = 'object'
      UNION ALL
      SELECT l.alternate_exercise AS item
      WHERE pg_catalog.jsonb_typeof(l.alternate_exercise) = 'object'
    ) AS items
    WHERE (
        l.id = v_lesson_id
        OR (
          pg_catalog.starts_with(v_lesson_id, 'reinf_')
          AND l.id = (
            SELECT rt.target_lesson_id
            FROM bilimyol_private.resolve_reinforcement_target(p_course_id, p_skill_id, v_lesson_id) rt
            LIMIT 1
          )
        )
      )
      AND l.course_id = p_course_id
      AND (
        l.skill_id = p_skill_id
        OR COALESCE(items.item->>'skillId', items.item->>'skill_id') = p_skill_id
      )
      AND l.is_published
      AND NOT l.is_archived
      AND pg_catalog.jsonb_typeof(items.item) = 'object'
      AND items.item->>'id' = p_question_id
  ) q_cand
  LIMIT 1;

  IF v_q_body IS NULL THEN
    RETURN NULL;
  END IF;

  v_question_text := v_q_body->>'text';
  v_q_type := COALESCE(
    NULLIF(pg_catalog.btrim(COALESCE(v_q_body->>'questionType', v_q_body->>'question_type', v_q_body->>'mode', '')), ''),
    'multiple_choice'
  );

  IF v_q_type IN ('text_input', 'fill_blank') THEN
    v_selected_option := COALESCE(NULLIF(pg_catalog.btrim(COALESCE(v_selected_answer, '')), ''), '—');
    v_correct_option := COALESCE(v_q_body->'acceptedAnswers'->>0, v_q_body->'accepted_answers'->>0);
  ELSIF v_q_type = 'sentence_order' THEN
    v_selected_option := COALESCE(NULLIF(pg_catalog.btrim(COALESCE(v_selected_answer, '')), ''), '—');
    IF pg_catalog.starts_with(v_selected_option, '[') THEN
      BEGIN
        v_parsed := v_selected_option::pg_catalog.jsonb;
        IF pg_catalog.jsonb_typeof(v_parsed) = 'array' THEN
          SELECT COALESCE(NULLIF(pg_catalog.string_agg(tok, ' ' ORDER BY ord), ''), '—')
          INTO v_selected_option
          FROM pg_catalog.jsonb_array_elements_text(v_parsed) WITH ORDINALITY AS t(tok, ord);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
    SELECT pg_catalog.string_agg(tok, ' ' ORDER BY ord)
    INTO v_correct_option
    FROM pg_catalog.jsonb_array_elements_text(
      COALESCE(v_q_body->'orderedTokens', v_q_body->'ordered_tokens', '[]'::pg_catalog.jsonb)
    ) WITH ORDINALITY AS t(tok, ord);
    v_correct_option := COALESCE(NULLIF(v_correct_option, ''), v_q_body->'acceptedAnswers'->>0, v_q_body->'accepted_answers'->>0);
  ELSIF v_q_type = 'word_match' THEN
    v_selected_option := COALESCE(NULLIF(pg_catalog.btrim(COALESCE(v_selected_answer, '')), ''), '—');
    IF pg_catalog.starts_with(v_selected_option, '{') THEN
      BEGIN
        v_parsed := v_selected_option::pg_catalog.jsonb;
        IF pg_catalog.jsonb_typeof(v_parsed) = 'object' THEN
          SELECT COALESCE(
            NULLIF(pg_catalog.string_agg(
              (pair->>'left') || ' -> ' || COALESCE(NULLIF(pg_catalog.btrim(COALESCE(v_parsed->>(pair->>'id'), '')), ''), '—'),
              ', ' ORDER BY ord
            ), ''),
            v_selected_option
          )
          INTO v_selected_option
          FROM pg_catalog.jsonb_array_elements(
            COALESCE(v_q_body->'matchPairs', v_q_body->'match_pairs', '[]'::pg_catalog.jsonb)
          ) WITH ORDINALITY AS mp(pair, ord);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
    SELECT pg_catalog.string_agg((pair->>'left') || ' -> ' || (pair->>'right'), ', ' ORDER BY ord)
    INTO v_correct_option
    FROM pg_catalog.jsonb_array_elements(
      COALESCE(v_q_body->'matchPairs', v_q_body->'match_pairs', '[]'::pg_catalog.jsonb)
    ) WITH ORDINALITY AS mp(pair, ord);
  ELSIF v_q_type IN ('speaking_prompt', 'writing_prompt') THEN
    v_selected_option := COALESCE(NULLIF(pg_catalog.btrim(COALESCE(v_selected_answer, '')), ''), '—');
    IF pg_catalog.starts_with(v_selected_option, '{') THEN
      BEGIN
        v_parsed := v_selected_option::pg_catalog.jsonb;
        IF pg_catalog.jsonb_typeof(v_parsed) = 'object' AND v_parsed ? 'response' THEN
          v_selected_option := COALESCE(NULLIF(pg_catalog.btrim(COALESCE(v_parsed->>'response', '')), ''), '—');
        END IF;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
    v_correct_option := COALESCE(v_q_body->>'sampleResponse', v_q_body->>'sample_response');
  ELSE
    v_selected_option := v_q_body->'options'->>v_selected_index;
    v_correct_index := CASE
      WHEN COALESCE(v_q_body->>'correct_index', v_q_body->>'correctIndex') ~ '^[0-9]{1,3}$'
      THEN COALESCE(v_q_body->>'correct_index', v_q_body->>'correctIndex')::INT
    END;
    v_correct_option := CASE
      WHEN v_correct_index IS NOT NULL THEN v_q_body->'options'->>v_correct_index
    END;
  END IF;

  v_explanation := COALESCE(
    CASE
      WHEN v_selected_option IS NOT NULL THEN
        NULLIF(pg_catalog.btrim(COALESCE(
          COALESCE(v_q_body->'mistakeFeedbackByOption', v_q_body->'mistake_feedback_by_option')->v_selected_option->>'uz',
          ''
        )), '')
    END,
    NULLIF(pg_catalog.btrim(COALESCE(v_q_body->>'wrongFeedback', v_q_body->>'wrong_feedback', '')), ''),
    NULLIF(pg_catalog.btrim(COALESCE(v_q_body->>'explanation', '')), '')
  );

  IF v_question_text IS NULL
     OR v_selected_option IS NULL
     OR v_correct_option IS NULL
     OR v_selected_option = v_correct_option THEN
    RETURN NULL;
  END IF;

  IF p_course_id = 'course_math_01' AND EXISTS (
    SELECT 1 FROM bilimyol_private.math_pilot_items mpi
    WHERE mpi.lesson_id = v_lesson_id AND mpi.question_id = p_question_id
  ) THEN
    SELECT pg_catalog.count(*)::INT
    INTO v_wrong_count
    FROM public.answer_attempts aa
    WHERE aa.user_id = p_user_id
      AND aa.course_id = p_course_id
      AND aa.skill_id = p_skill_id
      AND aa.lesson_id = v_lesson_id
      AND aa.question_id = p_question_id
      AND aa.is_correct = false;

    IF v_wrong_count < 2 AND NOT EXISTS (
      SELECT 1 FROM bilimyol_private.math_progression(p_user_id) mp
      WHERE mp.target_lesson_id = v_lesson_id
        AND mp.mastery_state IN ('needs_review', 'mastered')
    ) THEN
      RETURN pg_catalog.jsonb_build_object(
        'questionText', v_question_text,
        'selectedOption', v_selected_option,
        'correctOption', NULL,
        'explanation', 'Ishlangan misolni ko‘rib chiqing va qayta urinib ko‘ring.'
      );
    END IF;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'questionText', v_question_text,
    'selectedOption', v_selected_option,
    'correctOption', CASE
      WHEN p_expose_non_choice_answer
           OR v_q_type IN ('multiple_choice', 'error_correction', 'conversation_completion')
      THEN v_correct_option
      ELSE NULL
    END,
    'explanation', v_explanation
  );
END;
$$;

REVOKE ALL ON FUNCTION bilimyol_private.resolve_mistake_context(UUID, TEXT, TEXT, TEXT, BOOLEAN)
  FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.tutor_mistake_context(
  p_user_id UUID, p_course_id TEXT, p_skill_id TEXT, p_question_id TEXT
)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT bilimyol_private.resolve_mistake_context(p_user_id, p_course_id, p_skill_id, p_question_id, true);
$$;

REVOKE ALL ON FUNCTION public.tutor_mistake_context(UUID, TEXT, TEXT, TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tutor_mistake_context(UUID, TEXT, TEXT, TEXT)
  TO service_role;

CREATE OR REPLACE FUNCTION public.get_mistake_feedback(
  p_course_id TEXT, p_skill_id TEXT, p_question_id TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN bilimyol_private.resolve_mistake_context(v_uid, p_course_id, p_skill_id, p_question_id, false);
END;
$$;

REVOKE ALL ON FUNCTION public.get_mistake_feedback(TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_mistake_feedback(TEXT, TEXT, TEXT)
  TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';
COMMIT;
